sources.Intro = [====[
local Intro = {}

function Intro.Play()
    local gui
    local watchdog
    local tweens = {}
    local closed = false

    local function close()
        if closed then return end
        closed = true
        for _, tween in ipairs(tweens) do
            pcall(function() tween:Cancel() end)
        end
        if gui then pcall(function() gui:Destroy() end) end
    end

    local ok, message = xpcall(function()
        local TweenService = game:GetService("TweenService")
        local Players = game:GetService("Players")
        gui = Instance.new("ScreenGui")
        gui.Name = "KozmozIntro"
        gui.ResetOnSpawn = false
        gui.IgnoreGuiInset = true
        gui.DisplayOrder = 2147483000
        gui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
        pcall(function() gui.ScreenInsets = Enum.ScreenInsets.None end)

        local protect = protect_gui or protectgui or (syn and syn.protect_gui)
        if type(protect) == "function" then pcall(protect, gui) end
        local parented = false
        local getRoot = gethui or get_hidden_gui
        if type(getRoot) == "function" then
            parented = pcall(function()
                local parent = getRoot()
                assert(parent, "GUI root unavailable")
                gui.Parent = parent
            end)
        end
        if not parented then
            parented = pcall(function() gui.Parent = game:GetService("CoreGui") end)
        end
        if not parented then
            local player = Players.LocalPlayer
            local parent = player and player:WaitForChild("PlayerGui", 3)
            assert(parent, "Intro GUI parent unavailable")
            gui.Parent = parent
        end

        watchdog = task.delay(12, function()
            watchdog = nil
            close()
        end)

        local shade = Instance.new("Frame")
        shade.Name = "Shade"
        shade.Size = UDim2.fromScale(1, 1)
        shade.BackgroundColor3 = Color3.fromRGB(3, 4, 10)
        shade.BackgroundTransparency = 1
        shade.BorderSizePixel = 0
        shade.Active = true
        shade.Parent = gui

        -- Main Title Row (Text + Kozmoz Logo to the right as circled in png 4)
        local center = Instance.new("Frame")
        center.Name = "TitleHolder"
        center.AnchorPoint = Vector2.new(0.5, 0.5)
        center.Position = UDim2.new(0.5, 0, 0.48, 14)
        center.Size = UDim2.new(0, 560, 0, 95)
        center.BackgroundTransparency = 1
        center.Parent = shade

        local rowLayout = Instance.new("UIListLayout")
        rowLayout.FillDirection = Enum.FillDirection.Horizontal
        rowLayout.HorizontalAlignment = Enum.HorizontalAlignment.Center
        rowLayout.VerticalAlignment = Enum.VerticalAlignment.Center
        rowLayout.Padding = UDim.new(0, 18)
        rowLayout.Parent = center

        -- Text frame containing multi-layered glowing strokes
        local textFrame = Instance.new("Frame")
        textFrame.Name = "TextFrame"
        textFrame.Size = UDim2.new(0, 410, 0, 80)
        textFrame.BackgroundTransparency = 1
        textFrame.Parent = center

        local function animate(object, duration, properties)
            if closed then return end
            local tween = TweenService:Create(object, TweenInfo.new(duration, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut), properties)
            tweens[#tweens + 1] = tween
            tween:Play()
            return tween
        end

        local function label(name, zindex)
            local text = Instance.new("TextLabel")
            text.Name = name
            text.Size = UDim2.fromScale(1, 1)
            text.BackgroundTransparency = 1
            text.Text = "KOZMOZ crack by 3667"
            text.Font = Enum.Font.GothamBold
            text.TextScaled = true
            text.TextWrapped = true
            text.TextColor3 = Color3.fromRGB(255, 255, 255)
            text.TextTransparency = 1
            text.TextStrokeTransparency = 1
            text.ZIndex = zindex
            text.Parent = textFrame
            local limit = Instance.new("UITextSizeConstraint")
            limit.MinTextSize = 18
            limit.MaxTextSize = 48
            limit.Parent = text
            return text
        end

        local strokes = {}
        local softGlow = {0.995, 0.985, 0.97, 0.945, 0.905, 0.84, 0.73, 0.48, 0.2}
        local brightGlow = {0.987, 0.975, 0.955, 0.925, 0.87, 0.78, 0.64, 0.36, 0.08}
        for i, width in ipairs({30, 24, 19, 15, 11, 8, 5, 3, 1}) do
            local glow = label("Glow" .. i, i)
            local stroke = Instance.new("UIStroke")
            stroke.Color = Color3.fromRGB(100 + i * 13, 122 + i * 14, 255)
            stroke.Thickness = width
            stroke.Transparency = 1
            stroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Contextual
            stroke.Parent = glow
            strokes[#strokes + 1] = stroke
        end

        local title = label("Text", 12)
        local gradient = Instance.new("UIGradient")
        gradient.Color = ColorSequence.new({
            ColorSequenceKeypoint.new(0, Color3.fromRGB(156, 217, 255)),
            ColorSequenceKeypoint.new(0.5, Color3.fromRGB(255, 255, 255)),
            ColorSequenceKeypoint.new(1, Color3.fromRGB(186, 164, 255)),
        })
        gradient.Parent = title

        -- KOZMOZ Logo (positioned in the exact circle marked in png 4)
        local logo = Instance.new("ImageLabel")
        logo.Name = "KozmozLogo"
        logo.Size = UDim2.fromOffset(76, 76)
        logo.BackgroundTransparency = 1
        logo.Image = "rbxassetid://109796428128440"
        logo.ImageColor3 = Color3.fromRGB(195, 230, 255)
        logo.ImageTransparency = 1
        logo.ScaleType = Enum.ScaleType.Fit
        logo.ZIndex = 14
        logo.Parent = center

        local logoGlow = Instance.new("UIStroke")
        logoGlow.Color = Color3.fromRGB(156, 217, 255)
        logoGlow.Thickness = 2
        logoGlow.Transparency = 1
        logoGlow.Parent = logo

        -- Loading Progress Bar at the bottom (exact location where line was drawn in png 4)
        local loadBarBack = Instance.new("Frame")
        loadBarBack.Name = "LoadBarBack"
        loadBarBack.AnchorPoint = Vector2.new(0.5, 0.5)
        loadBarBack.Position = UDim2.new(0.5, 0, 0.82, 0)
        loadBarBack.Size = UDim2.new(0, 460, 0, 7)
        loadBarBack.BackgroundColor3 = Color3.fromRGB(15, 20, 36)
        loadBarBack.BackgroundTransparency = 1
        loadBarBack.BorderSizePixel = 0
        loadBarBack.Parent = shade

        local barCorner = Instance.new("UICorner")
        barCorner.CornerRadius = UDim.new(1, 0)
        barCorner.Parent = loadBarBack

        local barStroke = Instance.new("UIStroke")
        barStroke.Color = Color3.fromRGB(80, 110, 200)
        barStroke.Thickness = 1
        barStroke.Transparency = 1
        barStroke.Parent = loadBarBack

        local loadBarFill = Instance.new("Frame")
        loadBarFill.Name = "LoadBarFill"
        loadBarFill.Size = UDim2.new(0, 0, 1, 0)
        loadBarFill.BackgroundColor3 = Color3.fromRGB(156, 217, 255)
        loadBarFill.BackgroundTransparency = 1
        loadBarFill.BorderSizePixel = 0
        loadBarFill.Parent = loadBarBack

        local fillCorner = Instance.new("UICorner")
        fillCorner.CornerRadius = UDim.new(1, 0)
        fillCorner.Parent = loadBarFill

        local fillGradient = Instance.new("UIGradient")
        fillGradient.Color = ColorSequence.new({
            ColorSequenceKeypoint.new(0, Color3.fromRGB(130, 210, 255)),
            ColorSequenceKeypoint.new(0.5, Color3.fromRGB(255, 255, 255)),
            ColorSequenceKeypoint.new(1, Color3.fromRGB(186, 164, 255)),
        })
        fillGradient.Parent = loadBarFill

        -- KOZMOZ: donme yok (logo sabit durur), toplam acilis suresi ~6.6 saniye.
        -- Bekleme sirasinda hicbir is yapilmaz -> FPS'e hicbir etkisi yok.
        animate(shade, 0.45, {BackgroundTransparency = 0.05})
        task.wait(0.25)
        if closed then return end

        animate(title, 0.6, {TextTransparency = 0})
        animate(logo, 0.6, {ImageTransparency = 0})
        animate(logoGlow, 0.6, {Transparency = 0.4})
        animate(center, 0.8, {Position = UDim2.fromScale(0.5, 0.48)})
        animate(loadBarBack, 0.45, {BackgroundTransparency = 0.2})
        animate(barStroke, 0.45, {Transparency = 0.4})
        animate(loadBarFill, 0.45, {BackgroundTransparency = 0})

        for i, stroke in ipairs(strokes) do
            animate(stroke, 0.6, {Transparency = softGlow[i]})
        end

        -- KOZMOZ: yavas ama akici dolum (4.2 s) - donme yok, sadece tween
        animate(loadBarFill, 4.2, {Size = UDim2.new(1, 0, 1, 0)})
        task.wait(4.2)
        if closed then return end

        -- dolum bittikten sonra kisa bir "hazir" beklemesi
        task.wait(0.8)
        if closed then return end

        -- Subtle bright pulse at completion
        for i, stroke in ipairs(strokes) do
            animate(stroke, 0.25, {Transparency = brightGlow[i]})
        end
        animate(logoGlow, 0.25, {Transparency = 0.1})
        task.wait(0.25)
        if closed then return end

        -- Fade-out
        animate(title, 0.45, {TextTransparency = 1})
        animate(logo, 0.45, {ImageTransparency = 1})
        animate(logoGlow, 0.45, {Transparency = 1})
        animate(loadBarBack, 0.45, {BackgroundTransparency = 1})
        animate(loadBarFill, 0.45, {BackgroundTransparency = 1})
        animate(barStroke, 0.45, {Transparency = 1})
        for _, stroke in ipairs(strokes) do animate(stroke, 0.45, {Transparency = 1}) end
        animate(shade, 0.45, {BackgroundTransparency = 1})
        task.wait(0.45)
    end, function(err) return tostring(err) end)

    if watchdog then pcall(task.cancel, watchdog) end
    close()
    return ok, message
end

return Intro
]====]
