local function decodeBase64(data)
    local b64 = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
    local t = {}
    for i = 1, #b64 do
        t[b64:sub(i, i)] = i - 1
    end
    t["="] = 0

    local out = {}
    local len = #data
    local i = 1
    while i <= len do
        local c1 = t[data:sub(i, i)] or 0
        local c2 = t[data:sub(i + 1, i + 1)] or 0
        local c3 = t[data:sub(i + 2, i + 2)] or 0
        local c4 = t[data:sub(i + 3, i + 3)] or 0

        local b1 = bit32.bor(bit32.lshift(c1, 2), bit32.rshift(c2, 4))
        table.insert(out, string.char(b1))

        if data:sub(i + 2, i + 2) ~= "=" then
            local b2 = bit32.band(bit32.bor(bit32.lshift(c2, 4), bit32.rshift(c3, 2)), 0xFF)
            table.insert(out, string.char(b2))
        end

        if data:sub(i + 3, i + 3) ~= "=" then
            local b3 = bit32.band(bit32.bor(bit32.lshift(c3, 6), c4), 0xFF)
            table.insert(out, string.char(b3))
        end

        i = i + 4
    end

    return table.concat(out)
end

--==== KOZMOZ (kullanici istegi): HELLO KITTY GORSELLERI DISKE YAZILMIYOR ====--
-- Eskiden hk_logo_clean.png / hk_text_clean.png base64'ten cozulup diske
-- yaziliyor, sonra getcustomasset ile yukleniyordu. Bu KALDIRILDI.
-- Iki gorsel zaten Roblox'ta yuklu asset ID olarak duruyor (asagidaki
-- HK_LOGO_ASSET / HK_TEXT_ASSET satirlari) -> diskte dosya olusmuyor.

function Library:ApplyPredefinedTheme(ThemeName: string)
    if not Library.DefaultSchemeSnapshot then
        Library.DefaultSchemeSnapshot = {
            FontColor = Library.Scheme.FontColor or Color3.fromRGB(240, 240, 240),
            MainColor = Library.Scheme.MainColor or Color3.fromRGB(25, 25, 25),
            AccentColor = Library.Scheme.AccentColor or Color3.fromRGB(255, 255, 255),
            BackgroundColor = Library.Scheme.BackgroundColor or Color3.fromRGB(25, 25, 25),
            OutlineColor = Library.Scheme.OutlineColor or Color3.fromRGB(60, 60, 60),
            BarColor = Library.Scheme.BarColor or Color3.fromRGB(25, 25, 25),
        }
    end

    Library.CurrentThemeName = ThemeName

    if ThemeName == "Hello Kitty" then
        local hkColors = {
            BackgroundColor = Color3.fromRGB(255, 200, 248),
            MainColor = Color3.fromRGB(25, 25, 25),
            AccentColor = Color3.fromRGB(225, 33, 33),
            OutlineColor = Color3.fromRGB(232, 156, 156),
            FontColor = Color3.fromRGB(212, 126, 203),
            BarColor = Color3.fromRGB(255, 177, 243),
        }
        for k, v in pairs(hkColors) do
            Library.Scheme[k] = v
            if Library.Options and Library.Options[k] then
                pcall(function() Library.Options[k]:SetValue(v) end)
            end
        end
        Library:UpdateColorsUsingRegistry()

        if Library.WindowTitle then
            Library.WindowTitle.Visible = false
        end
        if Library.HelloKittyTitleImage then
            Library.HelloKittyTitleImage.Visible = true
            Library.HelloKittyTitleImage.BackgroundTransparency = 1
            Library.HelloKittyTitleImage.BorderSizePixel = 0
            Library.HelloKittyTitleImage.Image = HK_TEXT_ASSET
            Library.HelloKittyTitleImage.Size = UDim2.new(0, 105, 0, 38)
            Library.HelloKittyTitleImage.ScaleType = Enum.ScaleType.Fit
        end
        if Library.WindowIcon then
            Library.WindowIcon.Image = HK_LOGO_ASSET
            Library.WindowIcon.ImageRectOffset = Vector2.zero
            Library.WindowIcon.ImageRectSize = Vector2.zero
            Library.WindowIcon.ImageColor3 = Color3.fromRGB(255, 255, 255)
            Library.WindowIcon.BackgroundTransparency = 1
            Library.WindowIcon.BorderSizePixel = 0
            Library.WindowIcon.Size = UDim2.fromOffset(42, 42)
            Library.WindowIcon.ScaleType = Enum.ScaleType.Fit
        end

        -- Hello Kitty theme: GUI Transparency = 0 (image-1.png)
        if Library.Options and Library.Options.GUITransparencySlider then
            pcall(function() Library.Options.GUITransparencySlider:SetValue(0) end)
        end
        if Library.TopBarBgImage then
            Library.TopBarBgImage.Visible = true
            Library.TopBarBgImage.Image = "rbxassetid://104419581099944"
        end
        if Library.Window then
            Library.Window:SetBackgroundImage("")
        end
    else
        for k, v in pairs(Library.DefaultSchemeSnapshot) do
            Library.Scheme[k] = v
            if Library.Options and Library.Options[k] then
                pcall(function() Library.Options[k]:SetValue(v) end)
            end
        end
        Library:UpdateColorsUsingRegistry()

        if Library.HelloKittyTitleImage then
            Library.HelloKittyTitleImage.Visible = false
        end
        if Library.WindowTitle then
            Library.WindowTitle.Visible = true
        end
        if Library.WindowIcon then
            Library.WindowIcon.Image = "rbxassetid://109796428128440"
            Library.WindowIcon.ImageRectOffset = Vector2.zero
            Library.WindowIcon.ImageRectSize = Vector2.zero
            Library.WindowIcon.ImageColor3 = Library.Scheme.FontColor or Color3.fromRGB(240, 240, 240)
            Library.WindowIcon.BackgroundTransparency = 1
            Library.WindowIcon.BorderSizePixel = 0
            Library.WindowIcon.Size = UDim2.fromOffset(32, 32)
        end

        -- KOZMOZ USER DEFAULT: the Default theme keeps the user's transparency (46)
        if Library.Options and Library.Options.GUITransparencySlider then
            pcall(function() Library.Options.GUITransparencySlider:SetValue(46) end)
        end
        if Library.TopBarBgImage then
            Library.TopBarBgImage.Visible = false
        end
        if Library.Window then
            Library.Window:SetBackgroundImage("")
        end
    end
end

function Library:Validate(Table: { [string]: any }, Template: { [string]: any }): { [string]: any }
    if typeof(Table) ~= "table" then
        return Template
    end

    for k, v in Template do
        if typeof(k) == "number" then
            continue
        end

        if typeof(v) == "table" then
            Table[k] = Library:Validate(Table[k], v)
        elseif Table[k] == nil then
            Table[k] = v
        end
    end

    return Table
end

local function FillInstance(Table: { [string]: any }, Instance: GuiObject)
    local ThemeProperties = Library.Registry[Instance] or {}

    for key, value in Table do
        if key ~= "Text" then
            local SchemeValue = GetSchemeValue(value)

            if SchemeValue or typeof(value) == "function" then
                ThemeProperties[key] = value
                value = SchemeValue or value()
            else
                ThemeProperties[key] = nil
            end
        end

        -- Bulletproof guard for Color3 properties: NEVER let a raw string reach a Color3 property!
        if (string.find(key, "Color") or key == "Color") and typeof(value) ~= "ColorSequence" then
            if typeof(value) == "string" then
                local resolved = GetSchemeValue(value)
                if typeof(resolved) == "Color3" then
                    value = resolved
                else
                    local s, hexColor = pcall(Color3.fromHex, value)
                    if s and typeof(hexColor) == "Color3" then
                        value = hexColor
                    else
                        value = (typeof(Library.Scheme.AccentColor) == "Color3" and Library.Scheme.AccentColor)
                             or (typeof(Library.Scheme.MainColor) == "Color3" and Library.Scheme.MainColor)
                             or Color3.fromRGB(255, 255, 255)
                    end
                end
            elseif typeof(value) ~= "Color3" and typeof(value) ~= "function" then
                value = Color3.fromRGB(255, 255, 255)
            end
        end

        local ok = pcall(function()
            Instance[key] = value
        end)
        if not ok and (string.find(key, "Color") or key == "Color") and typeof(value) ~= "ColorSequence" then
            pcall(function()
                Instance[key] = Color3.fromRGB(255, 255, 255)
            end)
        end
    end

    if GetTableSize(ThemeProperties) > 0 then
        Library.Registry[Instance] = ThemeProperties
    end
end

local function New(ClassName: string, Properties: { [string]: any }): any
    local Instance = Instance.new(ClassName)

    if Templates[ClassName] then
        FillInstance(Templates[ClassName], Instance)
    end
    FillInstance(Properties, Instance)

    if Properties["Parent"] and not Properties["ZIndex"] then
        pcall(function()
            Instance.ZIndex = Properties.Parent.ZIndex
        end)
    end

    return Instance
end

local function SafeParentUI(Instance: Instance, Parent: Instance | () -> Instance)
    local success, _error = pcall(function()
        if not Parent then
            Parent = CoreGui
        end

        local DestinationParent
        if typeof(Parent) == "function" then
            DestinationParent = Parent()
        else
            DestinationParent = Parent
        end

        Instance.Parent = DestinationParent
    end)

    if not (success and Instance.Parent) then
        Instance.Parent = Library.LocalPlayer:WaitForChild("PlayerGui", math.huge)
    end
end

local function ParentUI(UI: Instance, SkipHiddenUI: boolean?)
    if SkipHiddenUI then
        SafeParentUI(UI, CoreGui)
        return
    end

    pcall(protectgui, UI)
    SafeParentUI(UI, gethui)
end

local function SetAlwaysOnTop(Gui: ScreenGui, Enabled: boolean)
    if not Gui then
        return
    end

    pcall(function()
        if sethiddenproperty then
            sethiddenproperty(Gui, "OnTopOfCoreBlur", Enabled)
        elseif setscriptable then
            setscriptable(Gui, "OnTopOfCoreBlur", true)
            Gui.OnTopOfCoreBlur = Enabled
            setscriptable(Gui, "OnTopOfCoreBlur", false)
        end
    end)
end

