					end

					task.wait(0.15)
					if not v25.Parent then
						return
					end

					if flag12 then
						tbl12.Grab(v25)
						task.wait()

						for _, v27 in children, nil, nil do
							if v27.Parent then
								tbl12.ResetVelocity(v27)
							end
						end

						tbl11.RagdollRemote:FireServer(v25, 0)
					else
						workspace.FallenPartsDestroyHeight = -10000
						tbl12.Teleport(v25, CFrame.new(0, -11000, 0))
						task.wait()
						local v27 = workspace
						local fallenPartsDestroyHeight2

						if tbl8.DestroyVoid then
							fallenPartsDestroyHeight2 = -10000
						else
							fallenPartsDestroyHeight2 = -100
						end

						v27.FallenPartsDestroyHeight = fallenPartsDestroyHeight2

						if v25.Parent then
							tbl12.Teleport(v25, cFrame2)

							for _, v28 in children, nil, nil do
								if v28.Parent then
									tbl12.ResetVelocity(v28)
								end
							end

							RunService.Heartbeat:Wait()

							for _, v28 in children, nil, nil do
								if v28.Parent then
									tbl12.ResetVelocity(v28)
								end
							end

							if v25.Parent then
								tbl12.RNO(v25)
							end
						end
					end
				end

				tbl12.UpdateWalkSpeed = function(arg)
					local v24, v25, v26 = tbl12.Char()
					local humanoidCreature = parent and parent:FindFirstChild("HumanoidCreature")

					if v26 and v26.Parent and v26.Health > 0 then
						if humanoidCreature then
							humanoidCreature.WalkSpeed = tbl9.WalkSpeed
							return
						end

						if v26.MoveDirection.Magnitude > 0 then
							v24:TranslateBy(v26.MoveDirection * tbl9.WalkSpeed * arg)
						end
					end
				end

				tbl12.UpdateFlight = function()
					local v24, v25, v26 = tbl12.Char()

					if not (v24 and v25 and v26 and v26.Health > 0) then
						if bodyVelocity or bodyGyro then
							tbl12.StopFly()
						end

						return
					end

					if not bodyVelocity or bodyVelocity.Parent ~= v25 or not bodyGyro or bodyGyro.Parent ~= v25 then
						tbl12.StopFly()
						tbl12.StartFly(v25)
					end

					if not v26.Sit then
						v26.PlatformStand = true
					end

					local n36 = 0

					if UserInputService:IsKeyDown(Enum.KeyCode.W) then
						n36 = 1
					end

					if UserInputService:IsKeyDown(Enum.KeyCode.S) then
						n36 -= 1
					end

					local n37 = 0

					if UserInputService:IsKeyDown(Enum.KeyCode.A) then
						n37 = -1
					end

					if UserInputService:IsKeyDown(Enum.KeyCode.D) then
						n37 += 1
					end

					local n38 = 0

					if UserInputService:IsKeyDown(Enum.KeyCode.Space) then
						n38 = 2
					end

					if UserInputService:IsKeyDown(Enum.KeyCode.LeftControl) or UserInputService:IsKeyDown(Enum.KeyCode.LeftShift) then
						n38 -= 2
					end

					if UserInputService.TouchEnabled and not UserInputService.KeyboardEnabled then
						local v27 = v23
						local ControlModule

						if v23 then
							ControlModule = v27
						else
							ControlModule = require(localPlayer.PlayerScripts:WaitForChild("PlayerModule"):WaitForChild("ControlModule"))
						end

						v23 = ControlModule
						local moveVector = v23:GetMoveVector()
						n37 += moveVector.X
						n36 -= moveVector.Z

						if v26.Jump then
							n38 += 2
						end
					end

					local n39 = currentCamera.CFrame.RightVector * n37 + currentCamera.CFrame.LookVector * n36 + Vector3.new(0, n38, 0)

					if n39.Magnitude > 1 then
						n39 = n39.Unit
					end

					local v27 = bodyVelocity
					local velocity = bodyVelocity.Velocity
					local lerp = velocity.Lerp
					local n40 = n39 * tbl9.FlightSpeed * 50
					local n41

					if n39.Magnitude > 0 then
						n41 = 0.22
					else
						n41 = 0.12
					end

					v27.Velocity = lerp(velocity, n40, n41)
					bodyGyro.CFrame = currentCamera.CFrame
				end

				do
					local v24 = nil
					local flag12 = nil
					local n36 = nil
					local num = nil
					local n37 = nil
					local n38 = 0
					-- KOZMOZ FIX: eskiden sethiddenproperty + setfflag + getfflag UCU birden
					-- gerekiyordu. Cogu executor'da setfflag/getfflag yok -> Desync hic
					-- acilmiyordu (toggle kendini kapatiyordu). Artik ana sart sadece
					-- sethiddenproperty (+ set_hidden_property alternatifi). fflag varsa
					-- ek olarak paket hizi da 1000'e cekilir, yoksa flicker tek basina calisir.
					-- (bayrak yukarida, tbl12 olusurken hesaplandi; burada sadece tazeliyoruz)
					tbl12.DesyncHasFflag = type(setfflag) == "function" and type(getfflag) == "function"
					if type(tbl12.DesyncProbe) == "function" then
						tbl12.DesyncSupported = tbl12.DesyncProbe()
					else
						tbl12.DesyncSupported = (type(sethiddenproperty) == "function" or type(set_hidden_property) == "function")
					end

					-- KOZMOZ FIX: executor'da sethiddenproperty yoksa Roblox'un kendi
					-- set_hidden_property API'sine dusuyoruz. Ikisi de yoksa desync
					-- kendini kapatiyor ve net bildirim veriyor (eski davranis).
					local function desyncSetRep(obj, val)
						if obj == nil then
							return false
						end
						if type(sethiddenproperty) == "function" then
							if pcall(sethiddenproperty, obj, "PhysicsRepRootPart", val) then
								return true
							end
						end
						if type(set_hidden_property) == "function" then
							return (pcall(set_hidden_property, obj, "PhysicsRepRootPart", val))
						end
						return false
					end
					tbl12.DesyncSetRep = desyncSetRep

					-- KOZMOZ: Fakepos ile Desync AYNI ANDA calisabilsin. Fakepos acikken
					-- "dogru" hedef kok root degil, sahte koktur. Aksi halde Desync'in
					-- her 0.14 sn'lik geri yuklemesi Fakepos'u ezer ve desync olmez.
					local function desyncRepTarget(root)
						if tbl12.FakePosActive == true then
							local fp = tbl12.FakePosPart
							if fp and fp.Parent then
								return fp
							end
						end
						return root
					end
					tbl12.DesyncRepTarget = desyncRepTarget

					local function fn21(arg)
						if type(setfflag) ~= "function" or type(getfflag) ~= "function" then
							-- fflag destegi yok: flicker tek basina devam etsin (kill etme)
							return true
						end
						for _, v25 in ipairs({ tostring(arg), arg }) do
							pcall(setfflag, "S2PhysicsSenderRate", v25)
							local ok, result = pcall(getfflag, "S2PhysicsSenderRate")
							if ok and tonumber(result) == arg then
								return true
							end
						end

						-- yazamadik ama flicker yine de calisir
						return true
					end

					local function fn22()
						n38 += 1

						if v24 and v24.Parent then
							desyncSetRep(v24, nil)
						end

						v24 = nil
						flag12 = false
						n36 = 0
					end

					-- KOZMOZ: kar'daki desync motorunun "spin" parcasi.
					local desyncSpinConn = nil
					local function desyncStartSpin()
						if desyncSpinConn then return end
						desyncSpinConn = RunService.Heartbeat:Connect(function()
							if flag11 or not tbl8.Desync then return end
							local _, root = tbl12.Char()
							if root and root.Parent then
								pcall(function() root.AssemblyAngularVelocity = Vector3.new(0, 0.01, 0) end)
							end
						end)
					end
					local function desyncStopSpin()
						if desyncSpinConn then
							desyncSpinConn:Disconnect()
							desyncSpinConn = nil
						end
					end

					local function fn23()
						desyncStopSpin()
						tbl12.SetDesync(false)
						local desyncT = toggles.DesyncT or toggles.KozDesync -- v39

						if desyncT then
							desyncT:SetValue(false)
						end
					end

					tbl12.UpdateDesync = function()
						if flag11 or not tbl8.Desync then
							return
						end
						local now3 = os.clock()

						if n37 <= now3 then
							n37 = now3 + 1
							-- KOZMOZ FIX: fflag tutmuyorsa desync'i KAPATMA, sadece ayari
							-- tekrar dene. Boylece player'lar desync'i kaybetmiyor.
							if type(getfflag) == "function" then
								local ok, result = pcall(getfflag, "S2PhysicsSenderRate")
								if not ok or tonumber(result) ~= 1000 then
									fn21(1000)
								end
							end
						end

						local v25, v26, v27 = tbl12.Char()
						local flag13 = v25 ~= localPlayer.Character
						local flag14

						if flag13 then
							flag14 = flag13
						else
							flag14 = not (v25 and v25.Parent and v26 and v27 and v27.Health > 0)
						end

						if flag14 then
							if v24 then
								fn22()
							end

							return
						end

						if v26 ~= v24 then
							fn22()
							v24 = v26
							n36 = now3 + 0.14
						end

						if flag12 then
							return
						end

						if now3 < n36 then
						if not desyncSetRep(v24, desyncRepTarget(v24)) then
								return fn23()
							end
							return
						end

						flag12 = true
						local v28 = v24
						local v29 = n38
						if not desyncSetRep(v28, nil) then
							return fn23()
						end
						task.wait(0.1)
						if v29 ~= n38 or flag11 or not tbl8.Desync or v28 ~= v24 then
							return
						end

						if not v28.Parent or v25 ~= localPlayer.Character or v27.Health <= 0 then
							return fn22()
						end

						if not desyncSetRep(v28, desyncRepTarget(v28)) then
							return fn23()
						end
						flag12 = false
						n36 = os.clock() + 0.14
					end

					tbl12.SetDesync = function(arg)
						local desync = arg == true and not flag11 and tbl12.DesyncSupported == true
						if tbl8.Desync == desync then
							return
						end
						tbl12.SetRuntimeConnection("Desync", nil, false)
						tbl8.Desync = desync
						if not desync then desyncStopSpin() end

						if desync then
							-- KOZMOZ FIX: fflag okunamasa bile desync ACILIR; sadece paket
							-- hizi ayari atlanir (flicker + spin yine calisir).
							if type(getfflag) == "function" then
								local ok, result = pcall(getfflag, "S2PhysicsSenderRate")

								if ok and tonumber(result) then
									num = tonumber(result)
								end
							end

							n37 = os.clock() + 1
							fn21(1000)
						else
							fn22()

							if num ~= nil then
								fn21(num)
							end
						end

						if desync then desyncStartSpin() end
						tbl12.SetRuntimeConnection("Desync", RunService.Heartbeat, desync, tbl12.UpdateDesync)
					end
				end
			end

			do
				do
					do
						local lookFigures = {
							Enabled = false,
							Preview = true,
							Figure = "Sideways",
							Clock = 0,
							Cycle = 0,
						}

						local look = ReplicatedStorage.CharacterEvents.Look
						tbl7.LookFigures = lookFigures

						tbl12.ClearLookFigureCharacter = function()
							if lookFigures.Root and lookFigures.Root.Parent then
								lookFigures.Root.C0 = lookFigures.Saved[2]
							end

							local v23 = lookFigures
							local v24 = lookFigures
							lookFigures.Character = nil
							v23.Root = nil
							v24.Saved = nil
						end

						tbl12.UpdateLookFigures = function(arg)
							if flag11 or not lookFigures.Enabled then
								return
							end
							local v23, rootJoint, v24 = tbl12.Char()
							local torso = v23 and v23:FindFirstChild("Torso")
							local neck = torso and torso:FindFirstChild("Neck")
							rootJoint = rootJoint and rootJoint:FindFirstChild("RootJoint")
							torso = torso and torso:FindFirstChild("Right Shoulder")
							if not (v24 and v24.Health > 0 and neck and rootJoint and torso) then
								return tbl12.ClearLookFigureCharacter()
							end

							if lookFigures.Character ~= v23 or lookFigures.Root ~= rootJoint then
								tbl12.ClearLookFigureCharacter()
								local v25 = lookFigures
								local v26 = lookFigures
								local saved = { neck.C0, rootJoint.C0, torso.C0 }
								lookFigures.Character = v23
								v25.Root = rootJoint
								v26.Saved = saved
							end

							local cframe = CFrame.Angles
							local n36

							if lookFigures.Figure == "Upside Down" then
								n36 = 3.1415926535897931
							else
								n36 = 1.5707963267948966
							end

							local v25 = lookFigures.Saved[2]
							local n37 = cframe(0, 0, n36) * v25
							local v26

							if lookFigures.Preview then
								v26 = n37
							else
								v26 = lookFigures.Saved[2]
							end

							if rootJoint.C0 ~= v26 then
								rootJoint.C0 = v26
							end

							lookFigures.Clock = lookFigures.Clock + arg
							if lookFigures.Clock < 0.05 then
								return
							end
							local v27 = lookFigures
							local cycle = lookFigures.Cycle % 20 + 1
							lookFigures.Clock = lookFigures.Clock % 0.05
							v27.Cycle = cycle
							look:FireServer(lookFigures.Saved[1], n37, lookFigures.Saved[3], "high")

							if lookFigures.Cycle % 5 == 0 then
								look:FireServer(lookFigures.Saved[1], n37, lookFigures.Saved[3], "medium")
							end

							if lookFigures.Cycle % 10 == 0 then
								look:FireServer(lookFigures.Saved[1], n37, lookFigures.Saved[3], "low")
							end

							if lookFigures.Cycle == 20 then
								look:FireServer(lookFigures.Saved[1], n37, lookFigures.Saved[3], "lowest")
							end
						end

						tbl12.SetLookFigures = function(arg)
							local enabled = arg and not flag11
							if lookFigures.Enabled == enabled then
								return
							end
							lookFigures.Enabled = enabled
							local antiLag = toggles.AntiLag

							if enabled then
								lookFigures.AntiLag = antiLag.Value

								if not antiLag.Value then
									antiLag:SetValue(true)
								end

								antiLag:SetDisabled(true)
								tbl12.UpdateLookFigures(0)
							else
								local saved = lookFigures.Character == localPlayer.Character and lookFigures.Saved
								tbl12.ClearLookFigureCharacter()
								local v23 = lookFigures
								lookFigures.Clock = 0
								v23.Cycle = 0

								if saved then
									for _, v24 in ipairs({ "high", "medium", "low", "lowest" }) do
										look:FireServer(saved[1], saved[2], saved[3], v24)
									end
								end

								antiLag:SetDisabled(false)

								if antiLag.Value ~= lookFigures.AntiLag then
									antiLag:SetValue(lookFigures.AntiLag)
								end

								lookFigures.AntiLag = nil
							end

							tbl12.SetRuntimeConnection("LookFigures", RunService.Heartbeat, enabled, tbl12.UpdateLookFigures)
						end
					end

					do
					    -- Kar Anti Grab adapted to Kozmoz's existing services and option IDs.
					    -- Head / IsHeld / Heartbeat / Health / CharacterAdded connections are cleaned up on disable.
					    local agParts = { "Head", "Torso", "Left Arm", "Right Arm", "Left Leg", "Right Leg" }
					    local agHeartbeatConn, agHeadConn, agHeldConn, agHealthConn, agCharConn
					    local agChar, agRoot, agHumanoid
					    local agPinned, agSafe
					    local agOffsets = {}
					    local agCollisions = {}
					    local agGrabbed = false
					    local agJustStarted = false
					    local agFrameCounter = 0
					    local agLastStart = -math.huge
					    local agRestoreToken = 0
					    local agOnGrabStart, agBindCharacter

					    local function agDisconnect(conn)
					        if conn then
					            pcall(function() conn:Disconnect() end)
					        end
					    end

					    local function agCapture(char, root)
					        table.clear(agOffsets)
					        table.clear(agCollisions)
					        agCollisions[root] = root.CanCollide
					        for _, name in ipairs(agParts) do
					            local part = char:FindFirstChild(name)
					            if part and part:IsA("BasePart") then
					                agOffsets[part] = root.CFrame:ToObjectSpace(part.CFrame)
					                agCollisions[part] = part.CanCollide
					            end
					        end
					    end

					    local function agSnap(char, root, target)
					        if not (char and root and target) then return end
					        pcall(function()
					            root.CFrame = target
					            root.AssemblyLinearVelocity = Vector3.zero
					            root.AssemblyAngularVelocity = Vector3.zero
					            root.CanCollide = false
					        end)
					        for part, offset in pairs(agOffsets) do
					            if part.Parent == char then
					                pcall(function()
					                    part.CFrame = target * offset
					                    part.AssemblyLinearVelocity = Vector3.zero
					                    part.AssemblyAngularVelocity = Vector3.zero
					                    part.CanCollide = false
					                end)
					            end
					        end
					    end

					    local function agRestore()
					        local char, root, hum = agChar, agRoot, agHumanoid
					        local wasGrabbed, saved = agGrabbed, agPinned
					        agGrabbed, agPinned, agJustStarted = false, nil, false
					        agFrameCounter = 0
					        tbl7.States["Anti Grab"] = false
					        agRestoreToken += 1
					        local token = agRestoreToken
					        if wasGrabbed and char and root and root.Parent and saved then
					            agSnap(char, root, saved)
					        end
					        for part, collidable in pairs(agCollisions) do
					            if part and part.Parent then
					                pcall(function() part.CanCollide = collidable end)
					            end
					        end
					        table.clear(agOffsets)
					        table.clear(agCollisions)
					        if hum and hum.Parent then
					            pcall(function()
					                hum:SetStateEnabled(Enum.HumanoidStateType.Dead, true)
					                hum.AutoRotate = true
					                hum.PlatformStand = false
					                if not hum.SeatPart then hum.Sit = false end
					            end)
					        end
					        if char and char.Parent then
					            task.delay(0.05, function()
					                if token ~= agRestoreToken or agGrabbed then return end
					                local animate = char:FindFirstChild("Animate")
					                if animate then pcall(function() animate.Enabled = true end) end
					            end)
					        end
					    end

					    local function agStop()
					        agDisconnect(agHeartbeatConn)
					        agDisconnect(agHeadConn)
					        agDisconnect(agHeldConn)
					        agDisconnect(agHealthConn)
					        agDisconnect(agCharConn)
					        agHeartbeatConn, agHeadConn, agHeldConn, agHealthConn, agCharConn = nil, nil, nil, nil, nil
					        agRestore()
					        agChar, agRoot, agHumanoid, agSafe = nil, nil, nil, nil
					    end

					    agOnGrabStart = function()
					        if flag11 or not tbl8.AntiGrab or not (agChar and agRoot and agHumanoid) then return end
					        local now = os.clock()
					        if now - agLastStart < 0.02 then return end
					        agLastStart = now
					        if not agGrabbed then
					            agPinned = agSafe or agRoot.CFrame
					            agCapture(agChar, agRoot)
					            agGrabbed = true
					            agRestoreToken += 1
					        end
					        agJustStarted = true
					        tbl7.States["Anti Grab"] = true
					        pcall(function()
					            agHumanoid.Sit = false
					            agHumanoid:SetStateEnabled(Enum.HumanoidStateType.Dead, false)
					            agRoot.AssemblyLinearVelocity = Vector3.zero
					            agRoot.AssemblyAngularVelocity = Vector3.zero
					            local animate = agChar:FindFirstChild("Animate")
					            if animate then animate.Enabled = false end
					            local animator = agHumanoid:FindFirstChild("Animator")
					            if animator then
					                for _, track in ipairs(animator:GetPlayingAnimationTracks()) do
					                    pcall(function() track:Stop(0) end)
					                end
					            end
					            local ragdolled = agHumanoid:FindFirstChild("Ragdolled")
					            if ragdolled then ragdolled.Value = true end
					        end)
					        pcall(function() tbl11.Struggle:FireServer(localPlayer) end)
					    end

					    agBindCharacter = function(char, root, hum)
					        if flag11 or not tbl8.AntiGrab or not (char and root and hum) then return end
					        if agChar == char and agRoot == root and agHeartbeatConn then return end
					        agDisconnect(agHeartbeatConn)
					        agDisconnect(agHeadConn)
					        agDisconnect(agHeldConn)
					        agDisconnect(agHealthConn)
					        if agChar then agRestore() end
					        agChar, agRoot, agHumanoid = char, root, hum
					        agSafe = root.CFrame
					        agLastStart = -math.huge
					        local head = char:FindFirstChild("Head") or char:WaitForChild("Head", 5)
					        if not head or not tbl8.AntiGrab or flag11 then return end

					        agHeadConn = head.ChildAdded:Connect(function(child)
					            if child.Name == "PartOwner" then agOnGrabStart() end
					        end)
					        agHeldConn = isHeld.Changed:Connect(function()
					            if isHeld.Value then agOnGrabStart() end
					        end)
					        agHealthConn = hum.HealthChanged:Connect(function(health)
					            if agGrabbed and health <= 0 then
					                pcall(function() hum.Health = hum.MaxHealth end)
					            end
					        end)
					        agHeartbeatConn = RunService.Heartbeat:Connect(function(dt)
					            if flag11 or not tbl8.AntiGrab then agStop(); return end
					            if agChar ~= char or not root.Parent or not hum.Parent then return end
					            local beingGrabbed = isHeld.Value or head:FindFirstChild("PartOwner") ~= nil
					            if not beingGrabbed then
					                if agGrabbed then agRestore() end
					                agSafe = root.CFrame
					                return
					            end
					            if not agGrabbed then agOnGrabStart() end
					            if not agGrabbed or not agPinned then return end

					            -- Preserve kar's camera-relative WASD movement while held.
					            if not UserInputService:GetFocusedTextBox() then
					                local camera = workspace.CurrentCamera
					                if camera then
					                    local look = camera.CFrame.LookVector
					                    local right = camera.CFrame.RightVector
					                    local forward = Vector3.new(look.X, 0, look.Z)
					                    local side = Vector3.new(right.X, 0, right.Z)
					                    if forward.Magnitude > 0.001 then forward = forward.Unit end
					                    if side.Magnitude > 0.001 then side = side.Unit end
					                    local movement = Vector3.zero
					                    if UserInputService:IsKeyDown(Enum.KeyCode.W) then movement += forward end
					                    if UserInputService:IsKeyDown(Enum.KeyCode.S) then movement -= forward end
					                    if UserInputService:IsKeyDown(Enum.KeyCode.A) then movement -= side end
					                    if UserInputService:IsKeyDown(Enum.KeyCode.D) then movement += side end
					                    if movement.Magnitude > 0.01 then
					                        local direction = movement.Unit
					                        local alpha = math.min(0.15 * 60 / math.max(30, tonumber(_currentFPS) or 60), 1)
					                        agPinned = agPinned:Lerp(CFrame.lookAlong(agPinned.Position, direction), alpha)
					                        agPinned += direction * 22 * math.min(tonumber(dt) or 0.016, 0.05)
					                    end
					                end
					            end

					            pcall(function()
					                hum.Sit = false
					                hum:SetStateEnabled(Enum.HumanoidStateType.Dead, false)
					                if hum.Health <= 0 then hum.Health = hum.MaxHealth end
					                local animate = char:FindFirstChild("Animate")
					                if animate and animate.Enabled then animate.Enabled = false end
					                local animator = hum:FindFirstChild("Animator")
					                if animator then
					                    for _, track in ipairs(animator:GetPlayingAnimationTracks()) do
					                        if track.IsPlaying then pcall(function() track:Stop(0) end) end
					                    end
					                end
					            end)
					            if agJustStarted then
					                agJustStarted = false
					            else
					                agFrameCounter += 1
					                if agFrameCounter % 2 == 0 then
					                    pcall(function() tbl11.RagdollRemote:FireServer(root, 0) end)
					                elseif not tbl11.RagdollRemote then
					                    pcall(function() tbl11.Struggle:FireServer(localPlayer) end)
					                end
					            end
					            agSnap(char, root, agPinned)
					            tbl7.States["Anti Grab"] = true
					        end)
					        if isHeld.Value or head:FindFirstChild("PartOwner") then agOnGrabStart() end
					    end

					    -- Called both by the toggle and by Kozmoz's existing IsHeld.Value signal.
					    tbl12.AntiGrab = function()
					        if flag11 or not tbl8.AntiGrab then agStop(); return end
					        if not agCharConn then
					            agCharConn = localPlayer.CharacterAdded:Connect(function(char)
					                task.spawn(function()
					                    local root = char:WaitForChild("HumanoidRootPart", 10)
					                    local hum = char:WaitForChild("Humanoid", 10)
					                    if tbl8.AntiGrab and not flag11 and localPlayer.Character == char then
					                        agBindCharacter(char, root, hum)
					                    end
					                end)
					            end)
					        end
					        local char, root, hum = tbl12.Char()
					        if char and root and hum then
					            agBindCharacter(char, root, hum)
					            local head = char:FindFirstChild("Head")
					            if agHeartbeatConn and (isHeld.Value or (head and head:FindFirstChild("PartOwner"))) then
					                agOnGrabStart()
					            end
					        end
					    end
					end

						do
							-- KOZMOZ USER FIX: Anti Grab [GUCCI] powered by kar's NaN-seat + shuttle + probe engine.
							-- Adapts kar's Blobman / Train / Tractor selection to Kozmoz's vehicle model names.
							-- works both inside owned plots (PlotItems) and outside (SpawnedInToys), and auto-recovers.
							local gucciActive = false
							local gucciApplying = false
							local gucciReapplying = false
							local gucciVehicle = nil
							local gucciSeat = nil
							local gucciTrainOrigCF = nil
							local gucciAppliedType = nil
							local gucciSession = 0
							local ragLoopThread = nil
							local shuttleStop = nil
							local seatBlockThread = nil
							local probeThread = nil
							local probeToken = 0
							local detectConns = {}
							local windowFocused = true
							local applyGucci, startDetection, startProbe, cleanupGucci, reapplyGucci

							pcall(function()
								UserInputService.WindowFocused:Connect(function()
									windowFocused = true
								end)
								UserInputService.WindowUnfocused:Connect(function()
									windowFocused = false
								end)
							end)

							local function stopRagLoop()
								if ragLoopThread then
									pcall(task.cancel, ragLoopThread)
									ragLoopThread = nil
								end
							end

							local function stopShuttle()
								if shuttleStop then
									pcall(shuttleStop)
									shuttleStop = nil
								end
							end

							local function stopSeatBlock()
								if seatBlockThread then
									pcall(task.cancel, seatBlockThread)
									seatBlockThread = nil
								end
							end

							local function stopDetection()
								stopShuttle()
								stopSeatBlock()
								for _, conn in ipairs(detectConns) do
									pcall(function()
										conn:Disconnect()
									end)
								end
								table.clear(detectConns)
							end

							local function getOwnedPlotFolder()
								local plots = workspace:FindFirstChild("Plots")
								local plotItems = workspace:FindFirstChild("PlotItems")
								if plots and plotItems then
									for _, plot in ipairs(plots:GetChildren()) do
										local sign = plot:FindFirstChild("PlotSign")
										local owners = sign and sign:FindFirstChild("ThisPlotsOwners")
										if owners then
											for _, ownerVal in ipairs(owners:GetChildren()) do
												if ownerVal:IsA("StringValue") and ownerVal.Value == localPlayer.Name then
													local folder = plotItems:FindFirstChild(plot.Name)
													if folder then
														return folder
													end
												end
											end
										end
									end
								end
								return nil
							end

							local function findGucciToy(toyName)
								local myPlotFolder = getOwnedPlotFolder()
								if myPlotFolder then
									local found = myPlotFolder:FindFirstChild(toyName)
									if found and not tbl7.ToyAuraReserved[found] then
										return found
									end
								end
								local spawned = workspace:FindFirstChild(localPlayer.Name .. "SpawnedInToys")
								if spawned then
									local found = spawned:FindFirstChild(toyName)
									if found and not tbl7.ToyAuraReserved[found] then
										return found
									end
								end
								local plotItems = workspace:FindFirstChild("PlotItems")
								if plotItems then
									for _, child in ipairs(plotItems:GetChildren()) do
										if child:IsA("Folder") and child.Name ~= "PlayersInPlots" then
											local found = child:FindFirstChild(toyName)
											if found and not tbl7.ToyAuraReserved[found] then
												return found
											end
										end
									end
								end
								return nil
							end

							local function destroyGucciToy(model, isTrain)
								if not model then
									return
								end
								tbl7.ToyAuraReserved[model] = nil
								if isTrain then
									if gucciSeat and gucciTrainOrigCF then
										pcall(function()
											gucciSeat.CFrame = gucciTrainOrigCF
										end)
									end
									return
								end
								pcall(function()
									tbl11.DestroyToy:FireServer(model)
								end)
							end

							local function safeUnseat(hum)
								if not (hum and hum.Parent) then
									return
								end
								hum.Sit = false
								hum.PlatformStand = false
								local frames = 0
								while frames < 10 and hum.SeatPart ~= nil do
									RunService.Heartbeat:Wait()
									frames += 1
								end
								pcall(function()
									hum:ChangeState(Enum.HumanoidStateType.Jumping)
								end)
							end

							local function instantEscape()
								local char, hrp, hum = tbl12.Char()
								if not (char and hrp and hum) then
									return
								end
								local rag = hum:FindFirstChild("Ragdolled")
								pcall(function()
									for _, desc in ipairs(char:GetDescendants()) do
										if desc:IsA("BallSocketConstraint") then
											desc.Enabled = false
										elseif desc:IsA("Motor6D") then
											desc.Enabled = true
										elseif desc:IsA("WeldConstraint") and desc.Parent and desc.Parent.Name == "RagdollLimbPart" then
											desc.Enabled = false
										end
									end
								end)
								safeUnseat(hum)
								hum.Sit = false
								hum.PlatformStand = false
								hum.AutoRotate = true
								hrp.Anchored = true
								hrp.AssemblyLinearVelocity = Vector3.zero
								hrp.AssemblyAngularVelocity = Vector3.zero
								for _ = 1, 3 do
									pcall(function()
										tbl11.Struggle:FireServer(hrp)
									end)
									pcall(function()
										tbl11.RagdollRemote:FireServer(hrp, 0)
									end)
									pcall(function()
										local cam = workspace.CurrentCamera
										tbl11.SetNetworkOwner:FireServer(hrp, cam and cam.CFrame or hrp.CFrame)
									end)
									if rag then
										pcall(function()
											rag.Value = false
										end)
									end
									hrp.AssemblyLinearVelocity = Vector3.zero
									hrp.AssemblyAngularVelocity = Vector3.zero
									task.wait()
								end
								local rpc = char:FindFirstChild("RagdollPlayerCharacter")
								local unrag = rpc and rpc:FindFirstChild("UnragdollThisCharacter")
								if unrag then
									pcall(function()
										unrag:Fire()
									end)
								end
								pcall(function()
									hum:SetStateEnabled(Enum.HumanoidStateType.Jumping, true)
									hum:ChangeState(Enum.HumanoidStateType.GettingUp)
								end)
								task.wait()
								pcall(function()
									hum:ChangeState(Enum.HumanoidStateType.Running)
								end)
								hrp.Anchored = false
							end

							local function startShuttle(model)
								stopShuttle()
								if not (model and model.Parent) then
									return
								end
								local holdCF = CFrame.new(150, 307, 332)
								local primary = model.PrimaryPart
									or model:FindFirstChild("HumanoidRootPart")
									or model:FindFirstChild("SoundPart")
									or model:FindFirstChild("Head")
									or model:FindFirstChild("Torso")
									or model:FindFirstChildWhichIsA("BasePart")
								local alive = true
								local shuttleThread = task.spawn(function()
									while gucciActive and alive and model and model.Parent and model == gucciVehicle do
										pcall(function()
											local cam = workspace.CurrentCamera
											local camCF = (cam and cam.CFrame) or holdCF
											local part = (primary and primary.Parent and primary) or model:FindFirstChildWhichIsA("BasePart")
											if part then
												tbl11.SetNetworkOwner:FireServer(part, camCF)
												part.CFrame = holdCF
												part.AssemblyLinearVelocity = Vector3.zero
												part.AssemblyAngularVelocity = Vector3.zero
											end
										end)
										task.wait(0.1)
									end
									pcall(function()
										if model and model.Parent then
											for _, desc in ipairs(model:GetDescendants()) do
												if desc:IsA("BasePart") then
													desc.Anchored = true
													desc.AssemblyLinearVelocity = Vector3.zero
													desc.AssemblyAngularVelocity = Vector3.zero
												end
											end
										end
									end)
								end)
								shuttleStop = function()
									alive = false
									if shuttleThread then
										pcall(task.cancel, shuttleThread)
										shuttleThread = nil
									end
								end
							end

							local function startSeatBlock()
								stopSeatBlock()
								seatBlockThread = task.spawn(function()
									while gucciActive do
										RunService.Heartbeat:Wait()
										if not gucciApplying then
											local _, _, hum = tbl12.Char()
											if hum and hum.SeatPart ~= nil and hum.SeatPart ~= gucciSeat then
												hum.Sit = false
											end
										end
									end
									seatBlockThread = nil
								end)
							end

							local function isReallyRagdolled()
								if tbl8.AntiGrab then
									return false
								end
								local _, _, hum = tbl12.Char()
								local rag = hum and hum:FindFirstChild("Ragdolled")
								return rag ~= nil and rag.Value == true
							end

							reapplyGucci = function()
								if not gucciActive or gucciReapplying or flag11 then
									return
								end
								local session = gucciSession
								gucciReapplying = true
								local _, hrp0 = tbl12.Char()
								local savedSpot = hrp0 and hrp0.CFrame
								instantEscape()
								if not gucciActive or session ~= gucciSession or flag11 then
									return
								end
								stopDetection()
								stopRagLoop()
								if probeThread then
									pcall(task.cancel, probeThread)
									probeThread = nil
								end
								if gucciVehicle then
									destroyGucciToy(gucciVehicle, gucciAppliedType == "Train")
								end
								gucciVehicle = nil
								gucciSeat = nil
								gucciAppliedType = nil
								gucciTrainOrigCF = nil
								gucciApplying = false

								local _, _, hum = tbl12.Char()
								local rag = hum and hum:FindFirstChild("Ragdolled")
								if rag and rag.Value == true then
									local waited = 0
									while waited < 1 and rag.Parent and rag.Value == true do
										RunService.Heartbeat:Wait()
										waited += 0.016
									end
								end
								task.wait(0.25)
								if not gucciActive or flag11 or session ~= gucciSession then
									return
								end
								gucciReapplying = false
								if not gucciActive or flag11 then
									return
								end
								applyGucci()
								local spinWait = 0
								while session == gucciSession and gucciApplying and spinWait < 240 do
									RunService.Heartbeat:Wait()
									spinWait += 1
								end
								if session ~= gucciSession or not gucciActive or flag11 then
									return
								end
								if savedSpot then
									local _, hrpNow = tbl12.Char()
									if hrpNow and hrpNow.Parent then
										pcall(function()
											hrpNow.CFrame = savedSpot
											hrpNow.AssemblyLinearVelocity = Vector3.zero
											hrpNow.AssemblyAngularVelocity = Vector3.zero
										end)
									end
								end
								if gucciActive and session == gucciSession and not flag11 then
									startDetection()
									task.delay(1.5, function()
										if gucciActive and session == gucciSession then
											startProbe()
										end
									end)
								end
							end

							startDetection = function()
								stopDetection()
								local char, hrp, hum = tbl12.Char()
								if not (char and hrp and hum) then
									return
								end
								local rag = hum:FindFirstChild("Ragdolled") or hum:WaitForChild("Ragdolled", 3)
								if rag then
									table.insert(detectConns, rag.Changed:Connect(function()
										if not gucciActive or gucciApplying or gucciReapplying then
											return
										end
										if rag.Value == true then
											instantEscape()
											task.spawn(reapplyGucci)
										end
									end))
								end

								local headBusy = false
								table.insert(detectConns, RunService.Heartbeat:Connect(function()
									if not gucciActive or gucciApplying then
										return
									end
									local c, r, h = tbl12.Char()
									local head = c and c:FindFirstChild("Head")
									if not (head and r and h) then
										return
									end
									if not head:FindFirstChild("PartOwner") then
										headBusy = false
										return
									end
									if headBusy then
										return
									end
									headBusy = true
									task.spawn(function()
										for _ = 1, 3 do
											if not gucciActive then
												break
											end
											pcall(function()
												tbl11.Struggle:FireServer(r)
											end)
											pcall(function()
												tbl11.RagdollRemote:FireServer(r, 0)
											end)
											h.Sit = false
											h.PlatformStand = false
											local rg = h:FindFirstChild("Ragdolled")
											if rg then
												pcall(function()
													rg.Value = false
												end)
											end
											r.AssemblyLinearVelocity = Vector3.zero
											r.AssemblyAngularVelocity = Vector3.zero
											pcall(function()
												for _, desc in ipairs(c:GetDescendants()) do
													if desc:IsA("BallSocketConstraint") then
														desc.Enabled = false
													elseif desc:IsA("Motor6D") then
														desc.Enabled = true
													end
												end
											end)
											pcall(function()
												h:ChangeState(Enum.HumanoidStateType.GettingUp)
											end)
											task.wait()
										end
										pcall(function()
											h:ChangeState(Enum.HumanoidStateType.Running)
										end)
										headBusy = false
									end)
								end))

								table.insert(detectConns, hum:GetPropertyChangedSignal("SeatPart"):Connect(function()
									if not gucciActive or gucciApplying or gucciReapplying then
										return
									end
									if hum.SeatPart ~= gucciSeat and hum.SeatPart ~= nil then
										task.spawn(function()
											pcall(function()
												tbl11.RagdollRemote:FireServer(hrp, 0)
											end)
											safeUnseat(hum)
											task.spawn(reapplyGucci)
										end)
									end
								end))

								if gucciVehicle then
									local watched = gucciVehicle
									table.insert(detectConns, watched.AncestryChanged:Connect(function()
										if not watched:IsDescendantOf(workspace) then
											if not gucciActive or gucciApplying or gucciReapplying then
												return
											end
											task.spawn(reapplyGucci)
										end
									end))
									local vHum = watched:FindFirstChildOfClass("Humanoid")
									if vHum then
										table.insert(detectConns, vHum.HealthChanged:Connect(function(hp)
											if gucciActive and not gucciApplying and not gucciReapplying and hp < vHum.MaxHealth then
												task.spawn(reapplyGucci)
											end
										end))
									end
								end

								startSeatBlock()
							end

							startProbe = function()
								if probeThread then
									pcall(task.cancel, probeThread)
									probeThread = nil
								end
								probeToken += 1
								local myToken = probeToken
								probeThread = task.spawn(function()
									while gucciActive and probeToken == myToken and not flag11 do
										if not windowFocused or gucciApplying or gucciReapplying or isHeld.Value or isReallyRagdolled() then
											task.wait(0.25)
											continue
										end
										if gucciVehicle == nil or not gucciVehicle.Parent then
											task.spawn(reapplyGucci)
											task.wait(1)
											continue
										end
										local _, hrp = tbl12.Char()
										if hrp then
											pcall(function()
												tbl11.RagdollRemote:FireServer(hrp, 1e-134)
											end)
										end
										for _ = 1, 4 do
											RunService.Heartbeat:Wait()
										end
										if gucciActive and probeToken == myToken and not gucciApplying and not gucciReapplying and not isHeld.Value and isReallyRagdolled() then
											task.spawn(reapplyGucci)
											task.wait(2)
										else
											task.wait(0.6)
										end
									end
									probeThread = nil
								end)
							end

							applyGucci = function()
								local session = gucciSession
								gucciApplying = true
								while isHeld.Value == true and gucciActive and not flag11 do
									RunService.Heartbeat:Wait()
								end
								if not gucciActive or flag11 or session ~= gucciSession then
									if session == gucciSession then gucciApplying = false end
									return
								end

								local char, hrp, hum = tbl12.Char()
								if not (char and hrp and hum and hum.Health > 0) then
									if session == gucciSession then gucciApplying = false end
									return
								end

								local gType = tbl9.GucciType
								if gType == "SantaSleigh" or gType == "Santa Sleigh" then
									gType = "SantaSleigh"
								elseif gType == "Tractor" or gType == "TractorGreen" then
									gType = "TractorGreen"
								elseif gType ~= "Train" then
									gType = "CreatureBlobman"
								end
								local oldVehicle = gucciVehicle
								local vehicle = nil
								local seat = nil
								local isTrain = (gType == "Train")

								if isTrain then
									pcall(function()
										vehicle = train and train:FindFirstChild("Object") and train.Object:FindFirstChild("ObjectModel")
										seat = vehicle and (vehicle:FindFirstChild("Seat", true) or vehicle:FindFirstChildWhichIsA("Seat", true) or vehicle:FindFirstChildWhichIsA("VehicleSeat", true))
									end)
									if not (vehicle and seat) then
										if session == gucciSession then gucciApplying = false end
										return
									end
									gucciTrainOrigCF = seat.CFrame
								else
									local spawnCF = CFrame.new(150, 307, 332)
									local fastConn = workspace.DescendantAdded:Connect(function(desc)
										if gucciActive and session == gucciSession and not vehicle and desc:IsA("Model") and desc.Name == gType then
											vehicle = desc
											pcall(function()
												for _, part in ipairs(desc:GetDescendants()) do
													if part:IsA("BasePart") then
														part.Anchored = true
														part.CFrame = spawnCF
													end
												end
											end)
										end
									end)

									local attempts = 0
									while gucciActive and session == gucciSession and not flag11 and not vehicle and attempts < 6 do
										attempts += 1
										vehicle = findGucciToy(gType)
										if not vehicle then
											local canSpawnToy = localPlayer:FindFirstChild("CanSpawnToy")
											if canSpawnToy then
												local w = 0
												while not canSpawnToy.Value and w < 45 and gucciActive do
													RunService.Heartbeat:Wait()
													w += 1
												end
											end
											task.spawn(function()
												pcall(function()
													tbl11.SpawnToy:InvokeServer(gType, spawnCF, Vector3.zero)
												end)
											end)
											local ticks = 0
											while gucciActive and session == gucciSession and not vehicle and ticks < 65 do
												RunService.Heartbeat:Wait()
												ticks += 1
												vehicle = vehicle or findGucciToy(gType)
											end
										end
									end
									fastConn:Disconnect()

									if not gucciActive or session ~= gucciSession or not vehicle or not vehicle.Parent then
										if session == gucciSession then gucciApplying = false end
										return
									end

									tbl7.ToyAuraReserved[vehicle] = true
									if gType == "CreatureBlobman" then
										vehicle.Name = "GucciBlob"
									elseif gType == "SantaSleigh" then
										vehicle.Name = "GucciSleigh"
									else
										vehicle.Name = "GucciTractor"
									end

									task.wait(0.12)
									if not gucciActive or session ~= gucciSession or not vehicle.Parent then
										destroyGucciToy(vehicle, false)
										if session == gucciSession then gucciApplying = false end
										return
									end

									local hideParts = (gType ~= "CreatureBlobman")
									pcall(function()
										local cam = workspace.CurrentCamera
										local camCF = (cam and cam.CFrame) or spawnCF
										for _, desc in ipairs(vehicle:GetDescendants()) do
											if desc:IsA("BasePart") then
												if hideParts then
													tbl11.SetNetworkOwner:FireServer(desc, camCF)
													desc.Transparency = 1
													desc.CanCollide = false
												end
												desc.Anchored = true
												desc.AssemblyLinearVelocity = Vector3.zero
												desc.AssemblyAngularVelocity = Vector3.zero
											elseif hideParts and (desc:IsA("Decal") or desc:IsA("Texture")) then
												desc.Transparency = 1
											end
										end
									end)

									seat = vehicle:FindFirstChild("VehicleSeat")
										or vehicle:WaitForChild("VehicleSeat", 2)
										or vehicle:FindFirstChildWhichIsA("Seat", true)
									if not seat then
										destroyGucciToy(vehicle, false)
										if session == gucciSession then gucciApplying = false end
										return
									end
								end

								if not gucciActive or session ~= gucciSession then
									destroyGucciToy(vehicle, isTrain)
									if session == gucciSession then gucciApplying = false end
									return
								end
								gucciVehicle = vehicle
								gucciSeat = seat
								gucciAppliedType = gType
								tbl7.ToyAuraReserved[vehicle] = true

								stopRagLoop()
								ragLoopThread = task.spawn(function()
									while gucciActive and gucciApplying do
										pcall(function()
											tbl11.RagdollRemote:FireServer(hrp, 0)
										end)
										RunService.Heartbeat:Wait()
									end
								end)

								local savedCF = hrp.CFrame
								local savedVel = hrp.AssemblyLinearVelocity
								local animate = char:FindFirstChild("Animate")
								local holdingCF = true

								local holdCFThread = task.spawn(function()
									while holdingCF do
										RunService.Heartbeat:Wait()
										pcall(function()
											hrp.CFrame = savedCF
										end)
									end
								end)

								pcall(function()
									seat:Sit(hum)
								end)

								local retrySitThread = task.spawn(function()
									while holdingCF do
										for _ = 1, 10 do
											if not holdingCF then
												return
											end
											RunService.Heartbeat:Wait()
										end
										if holdingCF and hum.SeatPart == nil then
											pcall(function()
												seat:Sit(hum)
											end)
										end
									end
								end)

								local sitTicks = 0
								local seated = false
								while sitTicks <= 200 and gucciActive and session == gucciSession and not flag11 do
									RunService.Heartbeat:Wait()
									sitTicks += 1
									if seat.Occupant == hum or hum.SeatPart == seat or (hum.Sit == true and hum.SeatPart ~= nil) then
										seated = true
										break
									end
								end

								pcall(task.cancel, retrySitThread)
								if session ~= gucciSession or not gucciActive or flag11 then
									holdingCF = false
									pcall(task.cancel, holdCFThread)
									return
								end

								if not seated then
									holdingCF = false
									pcall(task.cancel, holdCFThread)
									if animate then
										animate.Enabled = true
									end
