							-- Local-only voice indicators: one shared state per player, never change
						-- another player's microphone or the game's voice audio routing.
						tbl12.SetupVoiceBadges = function()
							-- No audio analyzers, voice routing changes, polling, or Chat settings.
							-- Mic state is event-driven; CoreGui's own voice bubble is recolored in place.
							local micOnPng = [=[]=]
							local micOffPng = [=[]=]
							local function decode64(src)
								local alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
								local map, out = {}, {}
								for i = 1, #alphabet do map[alphabet:sub(i,i)] = i-1 end
								for i = 1, #src, 4 do
									local a,b,c,d=src:sub(i,i),src:sub(i+1,i+1),src:sub(i+2,i+2),src:sub(i+3,i+3)
									local n=(map[a] or 0)*262144+(map[b] or 0)*4096+(map[c] or 0)*64+(map[d] or 0)
									out[#out+1]=string.char(math.floor(n/65536)%256)
									if c~="=" then out[#out+1]=string.char(math.floor(n/256)%256) end
									if d~="=" then out[#out+1]=string.char(n%256) end
								end
								return table.concat(out)
							end
							-- KOZMOZ: DISKE YAZIM YOK (eski png->dosya yolu kaldirildi).
							-- Ikon yok -> arayuz kendi vektor/yazi yedegini kullanir.
							local function loadIcon(filename, data)
								return nil
							end
							local onIcon=loadIcon("voice_mic_red_v1.png",micOnPng)
							local offIcon=loadIcon("voice_mic_slash_red_v1.png",micOffPng)
							local states={}
							local function paint(frame,status)
							local image=frame:FindFirstChild("VoiceImage")
							local fallback=frame:FindFirstChild("VoiceFallback")
							local slash=frame:FindFirstChild("VoiceSlash")
							local icon=status=="off" and offIcon or onIcon
							-- KOZMOZ FIX: hide the badge entirely while the voice state is unknown
							-- (it used to render a red "?" above every player's head)
							if status=="unknown" then
								if image then image.Visible=false end
								if fallback then fallback.Visible=false; fallback.Text="" end
								if slash then slash.Visible=false end
								frame.Visible=false
								return
							end
							frame.Visible=true
							if image then
								image.Visible=icon~=nil
								if icon then image.Image=icon end
							end
							if fallback then
								fallback.Visible=icon==nil
								fallback.Text=icon==nil and "ðŸŽ™" or ""
							end
							if slash then slash.Visible=offIcon==nil and status=="off" end
							end
							local function makeBadge(parent)
							local frame=Instance.new("Frame")
							frame.Name="KozmozVoiceStatus"
							frame.Size=UDim2.fromOffset(26,26)
							frame.LayoutOrder=-20
							frame.BackgroundTransparency=1
							local image=Instance.new("ImageLabel")
							image.Name="VoiceImage"; image.BackgroundTransparency=1
							image.Size=UDim2.fromScale(1,1)
							image.ScaleType=Enum.ScaleType.Fit
							image.Parent=frame
							local txt=Instance.new("TextLabel")
							txt.Name="VoiceFallback"; txt.BackgroundTransparency=1
							txt.TextScaled=true; txt.Size=UDim2.fromScale(1,1)
							txt.TextColor3=Color3.fromRGB(190,23,42)
							txt.Parent=frame
							local slash=Instance.new("Frame")
							slash.Name="VoiceSlash"; slash.BackgroundColor3=Color3.fromRGB(220,18,40)
							slash.BorderSizePixel=0; slash.Size=UDim2.new(1,0,0,4)
							slash.AnchorPoint=Vector2.new(.5,.5)
							slash.Position=UDim2.fromScale(.5,.5)
							slash.Rotation=-45; slash.Parent=frame
							frame.Parent=parent
							return frame
							end
							local function updateState(st)
							if st.Connection then st.Connection:Disconnect(); st.Connection=nil end
							local input=st.Player:FindFirstChildOfClass("AudioDeviceInput")
							local function refresh()
								local status="unknown"
								if input and input.Parent then
									local ok, muted=pcall(function() return input.Muted end)
									if ok then status=muted and "off" or "on" end
								end
								st.Status=status
								if st.Badge and st.Badge.Parent then paint(st.Badge,status) end
							end
							if input then
								st.Connection=input:GetPropertyChangedSignal("Muted"):Connect(refresh)
							end
							refresh()
							end
							local function watchPlayer(player)
							if player==localPlayer or states[player] then return end
							local st={ Player=player }
							states[player]=st
							st.Added=player.ChildAdded:Connect(function(c)
								if c:IsA("AudioDeviceInput") then updateState(st) end
							end)
							st.Removed=player.ChildRemoved:Connect(function(c)
								if c:IsA("AudioDeviceInput") then updateState(st) end
							end)
							updateState(st)
							end
							local function unwatchPlayer(player)
							local st=states[player]; if not st then return end
							states[player]=nil
							if st.Connection then st.Connection:Disconnect() end
							if st.Added then st.Added:Disconnect() end
							if st.Removed then st.Removed:Disconnect() end
							if st.Badge then st.Badge:Destroy() end
							end
							local add=Players.PlayerAdded:Connect(watchPlayer)
							local remove=Players.PlayerRemoving:Connect(unwatchPlayer)
							for _, player in ipairs(Players:GetPlayers()) do watchPlayer(player) end
							-- The original Roblox white voice icon remains untouched. Put the red
							-- picture over its ImageLabel while Roblox shows the voice bubble.
							local overlays=setmetatable({}, { __mode="k" })
							local watched=setmetatable({}, { __mode="k" })
							local uiConnections={}
							local closed=false
							local function overlayInsert(insert)
								if not insert:IsA("GuiObject") or overlays[insert] then return end
								local red=Instance.new("ImageLabel")
								red.Name="KozmozRedVoiceMic"
								red.AnchorPoint=Vector2.new(.5,.5)
								red.Position=UDim2.fromScale(.5,.5)
								red.Size=UDim2.fromScale(.75,.75)
								red.BackgroundTransparency=1
								red.ScaleType=Enum.ScaleType.Fit
								red.ZIndex=math.min(insert.ZIndex+30,1000)
								if onIcon then red.Image=onIcon end
								red.Parent=insert
								if not onIcon then
									local fallback=Instance.new("TextLabel")
									fallback.BackgroundTransparency=1
									fallback.Size=UDim2.fromScale(1,1)
									fallback.Text="ðŸŽ™"; fallback.TextScaled=true
									fallback.TextColor3=Color3.fromRGB(190,23,42)
									fallback.Parent=red
								end
								overlays[insert]=red
							end
							local function watchBubble(bubble)
								if watched[bubble] then return end
								watched[bubble]=true
								-- Parent red art to the native bubble: visible only when it is,
								-- regardless of the current Roblox Insert image hierarchy.
								pcall(overlayInsert,bubble)
							end
							local coreOK,core=pcall(function() return game:GetService("CoreGui") end)
							if coreOK and core then
							local function checkAdded(item)
								if not closed and item.Name=="VoiceBubble" then pcall(watchBubble,item) end
							end
							table.insert(uiConnections,core.DescendantAdded:Connect(checkAdded))
							-- Include already-existing native bubbles (often nested in RobloxGui).
							task.delay(2, function()
