				tbl12.SetChinaHat = function(chinaHat)
					tbl8.ChinaHat = chinaHat

					tbl12.SetRuntimeConnection("ChinaHatRespawn", localPlayer.CharacterAdded, chinaHat, function(arg)
						task.defer(tbl12.CreateChinaHat, arg)
