				do
					local groundLogoPart = nil
					local groundLogoDecal = nil
					local spawnCoverPart = nil
					local groundLogoAngle = 0
					local customGroundPos = nil
					local originalEmblemPos = nil
					local hiddenOriginalInstances = {}
					local lastEmblemScan = 0
					local groundLogoState = {}
					local spawnDescConn = nil

					local function GetSpawnPart()
						local sp = workspace:FindFirstChild("SpawnLocation")
						if not sp then
							for _, child in ipairs(workspace:GetChildren()) do
								if child:IsA("SpawnLocation") then
									sp = child
									break
								end
							end
						end
						if not sp then
							sp = workspace:FindFirstChildWhichIsA("SpawnLocation", true)
						end
						return sp
					end

					local function RaycastGround(origin)
						local rayOrigin = Vector3.new(origin.X, 40, origin.Z)
						local rayDir = Vector3.new(0, -90, 0)
						local params = RaycastParams.new()
						params.FilterType = Enum.RaycastFilterType.Exclude
						local filter = { localPlayer.Character, groundLogoPart, spawnCoverPart }
						if alwaysHereTweenedObjects then
							table.insert(filter, alwaysHereTweenedObjects)
						end
						local mapObj = workspace:FindFirstChild("Map")
						if mapObj then
							local ahto = mapObj:FindFirstChild("AlwaysHereTweenedObjects")
							if ahto then table.insert(filter, ahto) end
							local u1 = mapObj:FindFirstChild("InnerUFO") or mapObj:FindFirstChild("OuterUFO")
							if u1 then table.insert(filter, u1) end
						end
						for _, child in ipairs(workspace:GetChildren()) do
							local cName = string.lower(child.Name)
							if string.find(cName, "ufo") then
								table.insert(filter, child)
							end
						end
						params.FilterDescendantsInstances = filter
						local res = workspace:Raycast(rayOrigin, rayDir, params)
						if res then
							return res.Position + Vector3.new(0, 0.005, 0)
						end
						local sp = GetSpawnPart()
						if sp then
							return Vector3.new(sp.Position.X, sp.Position.Y + (sp.Size.Y / 2) + 0.005, sp.Position.Z)
						end
						return Vector3.new(origin.X, -2.485, origin.Z)
					end

					tbl12.RemoveOriginalCenterEmblem = function(force)
						local now = os.clock()
						if not force and #hiddenOriginalInstances > 0 and (now - lastEmblemScan < 30) then
							return
						end
						if not force and (now - lastEmblemScan < 10) then
							return
						end
						lastEmblemScan = now

						pcall(function()
							local sp = GetSpawnPart()
							if sp then
								for _, desc in ipairs(sp:GetDescendants()) do
									if (desc:IsA("Decal") or desc:IsA("Texture")) and desc ~= groundLogoDecal then
										if desc.Transparency < 1 then
											table.insert(hiddenOriginalInstances, { inst = desc, origTrans = desc.Transparency })
											desc.Transparency = 1
										end
									end
								end

								if not spawnDescConn then
									spawnDescConn = sp.DescendantAdded:Connect(function(desc)
										if (desc:IsA("Decal") or desc:IsA("Texture")) and desc ~= groundLogoDecal then
											pcall(function()
												desc.Transparency = 1
											end)
										end
									end)
								end
							end

							if alwaysHereTweenedObjects then
								for _, ufoName in ipairs({ "InnerUFO", "OuterUFO" }) do
									local ufo = alwaysHereTweenedObjects:FindFirstChild(ufoName)
									if ufo then
										for _, desc in ipairs(ufo:GetDescendants()) do
											if desc:IsA("BasePart") then
												if desc.Transparency < 1 then
													table.insert(hiddenOriginalInstances, { inst = desc, origTrans = desc.Transparency, origCollide = desc.CanCollide })
													desc.Transparency = 1
													desc.LocalTransparencyModifier = 1
													desc.CanCollide = false
												end
											elseif desc:IsA("Decal") or desc:IsA("Texture") then
												if desc.Transparency < 1 then
													table.insert(hiddenOriginalInstances, { inst = desc, origTrans = desc.Transparency })
													desc.Transparency = 1
												end
											end
										end
									end
								end
							end

							local searchScopes = { workspace }
							local spPos = sp and sp.Position
							for _, scope in ipairs(searchScopes) do
								if scope then
									for _, inst in ipairs(scope:GetDescendants()) do
										if (inst:IsA("Decal") or inst:IsA("Texture")) and inst ~= groundLogoDecal then
											local iName = string.lower(inst.Name)
											local pName = inst.Parent and string.lower(inst.Parent.Name) or ""
											local tex = string.lower(tostring(inst.Texture))
											local isSunMatch = string.find(iName, "sun") or string.find(iName, "star") or string.find(iName, "emblem")
												or string.find(iName, "pattern") or string.find(iName, "symbol") or string.find(iName, "circle")
												or string.find(iName, "spawn") or string.find(iName, "center") or string.find(iName, "ufo")
												or string.find(pName, "sun") or string.find(pName, "star") or string.find(pName, "emblem")
												or string.find(pName, "symbol") or string.find(pName, "pattern") or string.find(pName, "spawn")
												or string.find(pName, "center") or string.find(pName, "ufo")
												or string.find(tex, "sun") or string.find(tex, "star") or string.find(tex, "emblem")
												or string.find(tex, "spawn") or string.find(tex, "ufo")

											local isTopDecalNearCenter = false
											local isNearSpawn = false
											if inst.Face == Enum.NormalId.Top and inst.Parent and inst.Parent:IsA("BasePart") then
												local pos = inst.Parent.Position
												if math.abs(pos.X) < 180 and math.abs(pos.Z) < 180 and pos.Y > -30 and pos.Y < 30 then
													isTopDecalNearCenter = true
												end
												if spPos and (pos - spPos).Magnitude < 100 then
													isNearSpawn = true
												end
											end

											if isSunMatch or isTopDecalNearCenter or isNearSpawn then
												if inst.Parent and inst.Parent:IsA("BasePart") and not originalEmblemPos then
													originalEmblemPos = inst.Parent.Position
												end
												if inst.Transparency < 1 then
													table.insert(hiddenOriginalInstances, { inst = inst, origTrans = inst.Transparency })
													inst.Transparency = 1
												end
											end
										elseif inst:IsA("BasePart") and inst ~= groundLogoPart and inst ~= spawnCoverPart then
											local bName = string.lower(inst.Name)
											local pName = inst.Parent and string.lower(inst.Parent.Name) or ""
											local isNameMatch = string.find(bName, "sun") or string.find(bName, "star") or string.find(bName, "emblem")
												or string.find(bName, "centerlogo") or string.find(bName, "groundlogo")
												or string.find(pName, "sun") or string.find(pName, "star") or string.find(pName, "emblem")

											local isFlatCenterPart = false
											local pos = inst.Position
											if math.abs(pos.X) < 180 and math.abs(pos.Z) < 180 and pos.Y > -30 and pos.Y < 30 then
												if inst.Size.Y <= 2 and (inst.Size.X > 15 or inst.Size.Z > 15) and not inst.CanCollide then
													isFlatCenterPart = true
												end
											end

											if isNameMatch or isFlatCenterPart then
												if not originalEmblemPos then
													originalEmblemPos = inst.Position
												end
												if inst.Transparency < 1 then
													table.insert(hiddenOriginalInstances, { inst = inst, origTrans = inst.Transparency })
													inst.Transparency = 1
													inst.LocalTransparencyModifier = 1
												end
											end
										end
									end
								end
							end
						end)
					end

					tbl12.RestoreOriginalCenterEmblem = function()
						pcall(function()
							if spawnDescConn then
								spawnDescConn:Disconnect()
								spawnDescConn = nil
							end
							for _, record in ipairs(hiddenOriginalInstances) do
								if record.inst and record.inst.Parent then
									record.inst.Transparency = record.origTrans
									if record.inst:IsA("BasePart") then
										record.inst.LocalTransparencyModifier = record.origTrans
										if record.origCollide ~= nil then
											record.inst.CanCollide = record.origCollide
										end
									end
								end
							end
							table.clear(hiddenOriginalInstances)
						end)
					end

					local function GetPlayfieldCenter()
						if alwaysHereTweenedObjects and alwaysHereTweenedObjects:FindFirstChild("InnerUFO") then
							local ufo = alwaysHereTweenedObjects.InnerUFO
							local ufoObj = (ufo:FindFirstChild("Object") and ufo.Object:FindFirstChild("ObjectModel")) or ufo:FindFirstChildWhichIsA("BasePart", true)
							if ufoObj then
								return RaycastGround(ufoObj.Position)
							end
						end
						if originalEmblemPos then
							return RaycastGround(originalEmblemPos)
						end
						local plots = workspace:FindFirstChild("Plots")
						if plots and #plots:GetChildren() >= 3 then
							local sum = Vector3.zero
							local count = 0
							for _, pl in ipairs(plots:GetChildren()) do
								local pv = pl:GetPivot()
								sum = sum + pv.Position
								count = count + 1
							end
							if count > 0 then
								local avg = sum / count
								return RaycastGround(Vector3.new(avg.X, avg.Y, avg.Z))
							end
						end
						local sp = GetSpawnPart()
						if sp then
							return RaycastGround(sp.Position)
						end
						return RaycastGround(Vector3.new(0, -2.5, 0))
					end

					tbl12.ClearKozmozGroundLogo = function()
						tbl12.SetRuntimeConnection("KozmozGroundLogoLoop", nil, false)
						if groundLogoPart and groundLogoPart.Parent then
							groundLogoPart:Destroy()
						end
						if spawnCoverPart and spawnCoverPart.Parent then
							spawnCoverPart:Destroy()
						end
						groundLogoPart = nil
						groundLogoDecal = nil
						spawnCoverPart = nil
					end

					tbl12.SetKozmozGroundLogoCustomPos = function(pos)
						customGroundPos = pos
						if tbl8.KozmozGroundLogo then
							tbl12.UpdateKozmozGroundLogo(0)
						end
					end

					tbl12.UpdateKozmozGroundLogo = function(dt)
						dt = dt or 0
						if flag11 or not tbl8.KozmozGroundLogo then
							tbl12.ClearKozmozGroundLogo()
							return
						end

						-- KOZMOZ FIX: the emblem scan used to run from this per-frame update and
						-- walked every workspace descendant; it now runs once when the logo is enabled.
						-- New decals are still caught by spawnDescConn.

						if spawnCoverPart and spawnCoverPart.Parent then
							spawnCoverPart:Destroy()
							spawnCoverPart = nil
						end

						local mode = tbl9.KozmozGroundLogoMode or "Map Center"
						local sp = GetSpawnPart()

						if not (groundLogoPart and groundLogoPart.Parent) then
							local p = Instance.new("Part")
							p.Name = "KozmozGroundLogo"
							p.Anchored = true
							p.CanCollide = false
							p.CanTouch = false
							p.CanQuery = false
							p.CastShadow = false
							p.Material = Enum.Material.SmoothPlastic
							p.Transparency = 1
							p.Parent = workspace

							local d = Instance.new("Decal")
							d.Name = "LogoDecal"
							d.Face = Enum.NormalId.Top
							d.Parent = p

							groundLogoPart = p
							groundLogoDecal = d
						end

						local size = tbl9.KozmozGroundLogoSize or 94
						local texture = tbl9.KozmozGroundLogoAsset or "rbxassetid://109796428128440"
						local transparency = tbl9.KozmozGroundLogoTransparency or 0.9
						local color = tbl9.KozmozGroundLogoColor or Color3.fromRGB(255, 255, 255)
						-- KOZMOZ FIX: only write the properties when they actually change.
						if groundLogoState.Size ~= size then
							groundLogoPart.Size = Vector3.new(size, 0.002, size)
							groundLogoState.Size = size
						end
						if groundLogoState.Texture ~= texture then
							groundLogoDecal.Texture = texture
							groundLogoState.Texture = texture
						end
						if groundLogoState.Transparency ~= transparency then
							groundLogoDecal.Transparency = transparency
							groundLogoState.Transparency = transparency
						end
						if groundLogoState.Color ~= color then
							groundLogoDecal.Color3 = color
							groundLogoState.Color = color
						end

						if tbl8.KozmozGroundLogoAutoRotate then
							groundLogoAngle = (groundLogoAngle + (tbl9.KozmozGroundLogoRotSpeed or 2.9) * dt * 45) % 360
						end

						local targetCF
						if mode == "Spawn Location" and sp then
							local topY = sp.Position.Y + (sp.Size.Y / 2)
							targetCF = (sp.CFrame - sp.Position) * CFrame.Angles(0, math.rad(groundLogoAngle), 0) + Vector3.new(sp.Position.X, topY + 0.003, sp.Position.Z)
						elseif mode == "Follow Player" then
							local char = localPlayer.Character
							local root = char and char:FindFirstChild("HumanoidRootPart")
							if root then
