							local v22 = math.sqrt((math.floor((arg - 1) / n37) + 0.5) / (math.floor((arg2 - n38 - 1) / n37) + 1))
							local n39 = v22 * 3.1415926535897931 * 2 * arg4 + n38 / n37 * 3.1415926535897931 * 2
