				tbl12.LoadACEditorPose = function(arg)
					if not arg then
						return
					end

					if not options.ACCSecXO or not options.ACRSecXOTorso then
						return
					end
					local bodyOffset = arg.BodyOffset

					if not bodyOffset and arg.BodyPos then
						bodyOffset = CFrame.new(tonumber(arg.BodyPos[1]) or 0, tonumber(arg.BodyPos[2]) or 0, tonumber(arg.BodyPos[3]) or -5)
					end

					if bodyOffset then
						local accSecXO = options.ACCSecXO
						local setValue = accSecXO.SetValue
						local v22 = table.pack(tonumber(string.format("%.1f", bodyOffset.X)))
						setValue(accSecXO, table.unpack(v22, 1, v22.n))
						local accSecYO = options.ACCSecYO
						local setValue2 = accSecYO.SetValue
						local v23 = table.pack(tonumber(string.format("%.1f", bodyOffset.Y)))
						setValue2(accSecYO, table.unpack(v23, 1, v23.n))
						local accSecZO = options.ACCSecZO
						local setValue3 = accSecZO.SetValue
						local v24 = table.pack(tonumber(string.format("%.1f", bodyOffset.Z)))
						setValue3(accSecZO, table.unpack(v24, 1, v24.n))
					end

					local rotation = arg.Rotation or arg

					for k in tbl7.ACRotation, nil, nil do
						local v22 = rotation[k]

						if v22 then
							local x

							if typeof(v22) == "Vector3" then
								x = v22.X
							else
								x = v22[1]
							end

							local y

							if typeof(v22) == "Vector3" then
								y = v22.Y
							else
								y = v22[2]
							end

							local z

							if typeof(v22) == "Vector3" then
								z = v22.Z
							else
								z = v22[3]
							end

							local v23 = options["ACRSecXO" .. k]
							local setValue = v23.SetValue
							local v24 = table.pack(tonumber(string.format("%.1f", tonumber(x) or 0)))
							setValue(v23, table.unpack(v24, 1, v24.n))
							local v25 = options["ACRSecYO" .. k]
							local setValue2 = v25.SetValue
							local v26 = table.pack(tonumber(string.format("%.1f", tonumber(y) or 0)))
							setValue2(v25, table.unpack(v26, 1, v26.n))
							local v27 = options["ACRSecZO" .. k]
							local setValue3 = v27.SetValue
							local v28 = table.pack(tonumber(string.format("%.1f", tonumber(z) or 0)))
							setValue3(v27, table.unpack(v28, 1, v28.n))
						end
					end

					if arg.LimbOffsets then
						for k in tbl7.ACOffset, nil, nil do
							local v22 = arg.LimbOffsets[k]

							if v22 then
								local x

								if typeof(v22) == "Vector3" then
									x = v22.X
								else
									x = v22[1]
								end

								local y

								if typeof(v22) == "Vector3" then
									y = v22.Y
								else
									y = v22[2]
								end

								local z

								if typeof(v22) == "Vector3" then
									z = v22.Z
								else
									z = v22[3]
								end

								local v23 = options["ACOSecXO" .. k]
								local setValue = v23.SetValue
								local v24 = table.pack(tonumber(string.format("%.1f", tonumber(x) or 0)))
								setValue(v23, table.unpack(v24, 1, v24.n))
								local v25 = options["ACOSecYO" .. k]
								local setValue2 = v25.SetValue
								local v26 = table.pack(tonumber(string.format("%.1f", tonumber(y) or 0)))
								setValue2(v25, table.unpack(v26, 1, v26.n))
								local v27 = options["ACOSecZO" .. k]
								local setValue3 = v27.SetValue
								local v28 = table.pack(tonumber(string.format("%.1f", tonumber(z) or 0)))
								setValue3(v27, table.unpack(v28, 1, v28.n))
							end
						end
					else
						for k in tbl7.ACOffset, nil, nil do
							options["ACOSecXO" .. k]:SetValue(options["ACOSecXO" .. k].Default)
							options["ACOSecYO" .. k]:SetValue(options["ACOSecYO" .. k].Default)
							options["ACOSecZO" .. k]:SetValue(options["ACOSecZO" .. k].Default)
						end
					end

					return true
				end

				tbl12.BringPlayer = function(arg)
					local v22, v23, v24 = tbl12.Char(arg)
					local v25, v26, v27 = tbl12.Char()
					local flag12 = arg == localPlayer or tbl12.IsProtectedPlayer(arg)

					if not flag12 then
						flag12 = not (v23 and v24 and v24.Health > 0 and v26 and v27 and v27.Health > 0)
					end

					if flag12 then
						return
					end

					if not tbl12.IsNetworkOwner(v23) and not tbl12.SNO(v23) then
						return
					end
					local n36 = v26.CFrame * CFrame.new(0, 0, -5)
					local BasePart = v22:QueryDescendants("BasePart")
					local tbl16 = {}

					for i = 1, 3 do
						local flag13 = flag11

						if not flag11 then
							flag13 = not (v23.Parent and v22.Parent)
						end

						if not (flag13 or v24.Health <= 0) then
							tbl12.PivotTo(v22, n36 * v23.CFrame:Inverse() * v22:GetPivot(), BasePart, tbl16)

							for _, v28 in BasePart, nil, nil do
								tbl12.ResetVelocity(v28)
							end

							RunService.Heartbeat:Wait()
							continue
						end

						break
					end

					for _, v28 in BasePart, nil, nil do
						if v28.Parent then
							tbl12.ResetVelocity(v28)
						end
					end

					if v23.Parent then
						tbl12.RNO(v23)
					end

					return v23.Parent ~= nil and v24.Health > 0
				end

				do
					local tbl16 = {}

					tbl12.Kill = function(arg)
						local v22, v23, v24 = tbl12.Char(arg)

						if v24 and v24.Health ~= 0 and v23 and tbl12.GetMagnitude(workspace.SpawnLocation, v23) < 15000 and not tbl16[v22] then
							v24.BreakJointsOnDeath = false
							v24:ChangeState(Enum.HumanoidStateType.Dead)
							tbl12.DestroyObject(v22, v23)
							tbl16[v22] = true

							task.delay(1, function()
								tbl16[v22] = nil
							end)
						end
					end
				end
			end

			-- KOZMOZ: Target > Methods > Kill bu fonksiyonu cagirir (reso akisi).
			-- KOZMOZ: reso'nun Kill akisi BIREBIR (reso (12).txt, tbl14.Kill / 30342).
			-- Once Release (CreatureGrab/Release + RightWeld) denenir; basarili olursa
			-- BreakJointsOnDeath=false + Dead state uygulanir. Oturan hedefte once
			-- Bring yapilir, sonra reso'nun kendi tbl12.Kill'i cagrilir.
			-- (Eski sÃ¼rÃ¼m burada sahiplik (SNO) kapisi ariyordu; sahiplik alinamayinca
			--  hicbir sey yapmiyor ve UI'da "no valid target/network ownership" cikiyordu.)
			tbl12.KillReso = function(arg)
				if not parent then
					return
				end
				local v22, v23, v24 = tbl12.Char()
				if not (v23 and v24 and v24.Health > 0) then
					return
				end
				local v25, v26, v27 = tbl12.Char(arg)
				if not (v26 and v27 and v27.Health > 0) then
					return
				end

				if not (v27.Sit and v27.SeatPart) and tbl14.Release(arg) then
					v27.BreakJointsOnDeath = false
					v27:ChangeState(Enum.HumanoidStateType.Dead)
					task.wait()
					return true
				end

				if v27.Sit and v27.SeatPart and tbl14.Bring(arg) then
					tbl12.Kill(arg)
					return true
				end
			end

			-- KOZMOZ: Blacklist / auto modÃ¼ller bunlari kullanir (Target tarafi).
			tbl12.RunTargetOnce = function(player, method)
				if flag11 or not (player and player.Parent) then return false end
				if tbl12.IsProtectedPlayer and tbl12.IsProtectedPlayer(player) then return false end
				tbl7.TargetMethods = { [method] = true }
				if options and options.MethodSettingsTargets then
					pcall(options.MethodSettingsTargets.SetValue, options.MethodSettingsTargets, method)
				end
				pcall(function() tbl12.ProcessPlayer(player, false, false, false, nil) end)
				return true
			end

			-- KOZMOZ: Target > Method Settings > Methods kutusunu bul (iki yol: kayitli
			-- referans ya da kutuphanenin kendi Options kaydi). Blok yukarida tanimlandigi
			-- icin bu yardimci cagri aninda arar, tanim aninda degil.
			tbl12.GetTargetMethodsDropdown = function()
				local dd = options and options.MethodSettingsTargets
				if dd and dd.SetValue then
					return dd
				end
				local stored = tbl12.LibraryOptions
				if stored and stored.MethodSettingsTargets then
					return stored.MethodSettingsTargets
				end
				return nil
			end

			-- KOZMOZ: Target > Method Settings > Methods degeri (UI'da gorunur)
			tbl12.SetTargetMethod = function(method)
				if method ~= "Kick" and method ~= "Kill" then
					return false
				end
				if tbl7 and tbl7.TargetMethods then
					tbl7.TargetMethods = { [method] = true }
				end
				local dd = tbl12.GetTargetMethodsDropdown()
				if dd then
					pcall(dd.SetValue, dd, method)
				end
				return true
			end

			-- KOZMOZ: "Loop Apply Method Selected"i gercekten actan/kapatan yardimci.
			-- SetValue tek basina callback'i calistirmadigi icin callback'i da cagirir.
			tbl12.SetTargetLoopKick = function(on)
				-- KOZMOZ: once UI id'si (LoopApplyMethodTSel), yoksa runtime id'si
				local t = toggles and (toggles.LoopApplyMethodTSel or toggles.LoopApplyMethodT)
				if not (t and t.SetValue) then
					return false
				end
				on = on == true
				task.spawn(function()
					if (t.Value == true) ~= on then
						pcall(t.SetValue, t, on)
						if t.Disabled ~= true then
							if type(t.Callback) == "function" then
								pcall(t.Callback, on)
							end
							if type(t.Changed) == "function" then
								pcall(t.Changed, on)
							end
						end
					end
				end)
				return true
			end

			-- KOZMOZ: tek bir oyuncuya Target metodunu uygula (Kill icin kullanilir).
			tbl12.RunTargetOnce = function(player, method)
				if flag11 or not (player and player.Parent) then
					return false
				end
				if tbl12.IsProtectedPlayer and tbl12.IsProtectedPlayer(player) then
					return false
				end
				tbl12.SetTargetMethod(method)
				pcall(function()
					tbl12.ProcessPlayer(player, false, false, false, nil)
				end)
				return true
			end

			-- KOZMOZ: Blacklist motoru. Target sekmesindeki Target kutusuna ismi yazar,
			-- Method Settings > Methods'u Kick/Kill yapar. Kick'te "Loop Apply Method
			-- Selected" acilir (sunucudaki gercek dongu budur), Kill'de dongu kapali
			-- tutulup kill ayrica tekrar tekrar uygulanir. Blobman kullanilmaz.
			tbl12.RunTargetDrive = function(want, method)
				if flag11 or type(want) ~= "table" then
					return false
				end
				if not (options and options.TargetDropdown and options.TargetDropdown.SetValue) then
					return false
				end

				tbl12.SetTargetMethod(method)

				local current = {}
				if type(options.TargetDropdown.Value) == "table" then
					for player in pairs(options.TargetDropdown.Value) do
						if player and player.Parent and player ~= me then
							current[player] = true
						end
					end
				end
				for player in pairs(want) do
					if player and player.Parent and player ~= me then
						current[player] = true
					end
				end
				pcall(options.TargetDropdown.SetValue, options.TargetDropdown, current)

				if method == "Kick" then
					tbl12.SetTargetLoopKick(true)
				else
					tbl12.SetTargetLoopKick(false)
				end

				return true
			end

			tbl12.Void = function(arg)
				local v22, v23, v24 = tbl12.Char(arg)

				if v24 and v24.Health ~= 0 and v23 and tbl12.GetMagnitude(workspace.SpawnLocation, v23) < 15000 and tbl12.SNO(v23) then
					local cframe = CFrame.new(0, 9e9, 0)
					tbl12.PivotTo(v22, cframe * v23.CFrame:Inverse() * v22:GetPivot())
					tbl12.Teleport(v23, cframe)
					v23.Velocity = Vector3.new(0, 9e9, 0)
					task.delay(0.35, tbl12.RNO, v23)
				end
			end

			-- Shared Food cleanup (Target > Destroy Food and Blobman > Remove Food).
			-- Only real Players and Food* Models are eligible. Return values describe
			-- local requests/observations, never a server-authoritative deletion.
			local foodHeldAttempts = setmetatable({}, { __mode = "k" })
			local foodInventoryAttempts = setmetatable({}, { __mode = "k" })

			local function foodOwnFolder()
				local folder = workspace:FindFirstChild(localPlayer.Name .. "SpawnedInToys")
				if folder and folder.Parent then return folder end
				return v17 and v17.Parent and v17 or nil
			end

			tbl12.IsFoodModel = function(model, ownFolder)
				if not (model and model.Parent and model:IsA("Model") and model.Name:sub(1, 4) == "Food") then
					return false
				end
				ownFolder = ownFolder or foodOwnFolder()
				return not (ownFolder and model:IsDescendantOf(ownFolder))
			end

			local function foodTargetValid(player)
				return typeof(player) == "Instance" and player:IsA("Player") and player.Parent
					and player ~= localPlayer and not tbl12.IsProtectedPlayer(player) and not flag11
			end

			-- Exactly one non-empty StringValue owner, and it must be this player.
			-- Shared, empty, unknown or still-loading ownership is deliberately skipped.
			tbl12.GetSoleOwnedPlotInventory = function(player)
				if not (player and player.Parent) then return nil end
				local plots = workspace:FindFirstChild("Plots")
				local items = workspace:FindFirstChild("PlotItems")
				if not (plots and items) then return nil end
				local found = nil
				local matches = 0
				for _, plot in ipairs(plots:GetChildren()) do
					local sign = plot:FindFirstChild("PlotSign")
					local owners = sign and sign:FindFirstChild("ThisPlotsOwners")
					if owners then
						local count, soleName = 0, nil
						for _, entry in ipairs(owners:GetChildren()) do
							if entry:IsA("StringValue") and entry.Value ~= "" then
								count += 1
								soleName = entry.Value
							end
						end
						if count == 1 and soleName == player.Name then
							matches += 1
							if matches > 1 then return nil end -- more than one matching plot: ambiguous
							found = items:FindFirstChild(plot.Name)
						end
					end
				end
				return found
			end

			-- Serialize the whole DestroyObject/SNO request, including its delayed
			-- grab-line release, against Target/Extra Defense Anti Vehicle work.
			tbl12.WithAntiVehicleLock = function(callback, stillValid, noSettle)
				local deadline = os.clock() + 1.1
				while tbl7.AntiVehicleBusy and not flag11 and os.clock() < deadline do
					task.wait()
				end
				if flag11 or tbl7.AntiVehicleBusy or (stillValid and not stillValid()) then
					return true, nil, "skipped"
				end
				local token = {}
				tbl7.AntiVehicleBusy = token
				local ok, result = pcall(callback)
				local skipSettle = noSettle
				if type(skipSettle) == "function" then
					local okS, v = pcall(skipSettle)
					skipSettle = okS and v
				end
				if ok and result == true and not skipSettle then
					-- DestroyObject schedules RNO at 0.5 s; do not let the next
					-- Food/Anti Vehicle SNO start before that request has fired.
					local settle = os.clock() + 0.55
					while not flag11 and os.clock() < settle do task.wait(0.05) end
				end
				if tbl7.AntiVehicleBusy == token then tbl7.AntiVehicleBusy = nil end
				return ok, result
			end

			-- Shared vehicle drop. Extra Defense and Target Anti Vehicle both use this.
			-- v33: TP + SIT + DELETE (Remove Gucci style), zero idle waits.
			--   Same frame: teleport onto the vehicle seat and Seat:Sit(). Every heartbeat until the
			--   server hands us the SeatWeld: stay glued to the seat and Sit() again. The SeatWeld and
			--   the vehicle control LocalScript are disabled instantly (destroyed one deferred step
			--   later = no "set parent to NULL" warning). Seated server-side and right next to it we
			--   own the vehicle -> SNO + void it every heartbeat until the server deletes it, then
			--   stand up and teleport straight back.
			--   Fallback: the Destroy Food pipeline (tbl12.DestroyObject: SNO -> void -> RNO).
			--   Occupied seats stay protected. Our root is never anchored.
			tbl12.ApelVehicleDrop = function(item, stillValid)
				if flag11 or not item or not item.Parent or (stillValid and not stillValid()) then return false end
				local myChar, myRoot, myHum = tbl12.Char()
				if not (myChar and myChar.Parent and myRoot and myRoot.Parent and myHum and myHum.Parent and myHum.Health > 0) then
					return false
				end
				if myRoot.Anchored or tbl8.GucciAntiGrab or tbl8.ControllingSomeone or tbl7.States.Owning then
					return false
				end
				if tbl14.KickTargetsBusy then return false end
				for _, state in pairs(tbl14.LoopKickStates or {}) do
					if state.active then return false end
				end
				local seat = item:FindFirstChildOfClass("VehicleSeat") or item:FindFirstChildWhichIsA("VehicleSeat", true)
					or item:FindFirstChildWhichIsA("Seat", true)
				if seat and seat.Occupant and seat.Occupant ~= myHum then return false end
				if seat and myHum.SeatPart and myHum.SeatPart ~= seat then return false end

				-- DestroyObject schedules an RNO at 0.5 s; only then keep the lock's settle window.
				local usedDestroyObject = false
				local ok, result = tbl12.WithAntiVehicleLock(function()
					if stillValid and not stillValid() then return false end
					if seat and seat.Occupant and seat.Occupant ~= myHum then return false end
					local savedCF = myRoot.CFrame
					local fallenY = workspace.FallenPartsDestroyHeight
					local dropY = -11111
					if typeof(fallenY) == "number" and fallenY == fallenY then
						dropY = math.min(-11111, fallenY - 500)
					end
					local dropPos = CFrame.new(0, dropY, 9999)

					local function drivePart()
						return (item.PrimaryPart and item.PrimaryPart.Parent and item.PrimaryPart)
							or (seat and seat.Parent and seat) or item:FindFirstChildWhichIsA("BasePart", true)
					end
					local function claim()
						local part = drivePart()
						if not part then return end
						pcall(function()
							if tbl11 and tbl11.SetNetworkOwner then
								tbl11.SetNetworkOwner:FireServer(part, part.CFrame)
							end
						end)
					end
					local function pushDown()
						if not item.Parent then return false end
						claim()
						local moved = false
						if item.PrimaryPart then
							moved = pcall(function() item:SetPrimaryPartCFrame(dropPos) end)
						end
						if not moved then
							moved = pcall(function() item:PivotTo(dropPos) end)
						end
						pcall(function()
							local part = drivePart()
							if part then
								part.AssemblyLinearVelocity = Vector3.new(0, -750, 0)
								part.AssemblyAngularVelocity = Vector3.zero
							end
						end)
						return moved
					end
					local function zeroVel()
						pcall(function()
							myRoot.AssemblyLinearVelocity = Vector3.zero
							myRoot.AssemblyAngularVelocity = Vector3.zero
						end)
					end
					local function tpTo(cf)
						pcall(function()
							if myRoot.Parent then
								myRoot.CFrame = cf
							end
						end)
						zeroVel()
					end
					local function goHome()
						tpTo(savedCF)
						pcall(function() tbl12.ResetVelocity(myRoot) end)
					end
					local function killLater(inst)
						pcall(function() inst.Enabled = false end)
						task.defer(function()
							pcall(function() inst:Destroy() end)
						end)
					end

					local destroyed = not item.Parent
					local watchPart = seat or drivePart()
					local ancestryConn = watchPart and watchPart.AncestryChanged:Connect(function()
						if not watchPart.Parent then destroyed = true end
					end)
					local itemConn = item.AncestryChanged:Connect(function()
						if not item.Parent then destroyed = true end
					end)
					local function gone()
						return destroyed or not item.Parent
					end
					local function occupiedByOther()
						return seat and seat.Parent and seat.Occupant and seat.Occupant ~= myHum
					end
					local function invalid()
						return flag11 or myHum.Health <= 0 or not myRoot.Parent or (stillValid and not stillValid())
					end
					local function dropConns()
						pcall(function() if ancestryConn then ancestryConn:Disconnect() end end)
						pcall(function() itemConn:Disconnect() end)
					end

					-- ===== Route 1: TP onto the seat + Sit in the same frame (Remove Gucci style) =====
					if seat and seat.Parent and seat:IsA("VehicleSeat") and not occupiedByOther() then
						local seatSpot = nil
						local function onSeatCF()
							if seat.Parent then
								seatSpot = seat.CFrame * CFrame.new(0, 2, 0)
							end
							return seatSpot
						end
						local gotWeld = false
						local ctrlConn = myChar.ChildAdded:Connect(function(child)
							if child:IsA("LocalScript") and child.Name:lower():find("control") then
								killLater(child)
							end
						end)
						local weldConn = seat.ChildAdded:Connect(function(child)
							if child.Name == "SeatWeld" then
								killLater(child)
								gotWeld = true
							end
						end)
						local function seatConns()
							pcall(function() ctrlConn:Disconnect() end)
							pcall(function() weldConn:Disconnect() end)
						end

						if myHum.Sit and myHum.SeatPart ~= seat then
							pcall(function() myHum.Sit = false end)
						end
						-- same frame: teleport + sit
						tpTo(onSeatCF())
						pcall(seat.Sit, seat, myHum)
						local sitStart = os.clock()
						while not gotWeld do
							task.wait()
							if gotWeld or gone() or occupiedByOther() or invalid() or os.clock() - sitStart > 0.6 then break end
							if seat.Parent then
								tpTo(onSeatCF())
								pcall(seat.Sit, seat, myHum)
							end
						end

						if gotWeld and not gone() then
							-- seated (weldless) owner right next to it: void every heartbeat
							local spot = seatSpot or savedCF
							local holdDeadline = os.clock() + 2.5
							while not gone() and not invalid() and os.clock() < holdDeadline do
								if occupiedByOther() then break end
								pushDown()
								tpTo(spot)
								task.wait()
							end
						end
						seatConns()
						pcall(function() if myHum.Parent then myHum.Sit = false end end)
						goHome()
						if gone() then
							dropConns()
							warn("[KOZMOZ] Anti Vehicle removed " .. item.Name .. " (tp+sit)")
							return true
						end
					end

					-- ===== Route 2 (fallback): Destroy Food pipeline (SNO -> void -> RNO) =====
					if invalid() or occupiedByOther() then
						dropConns()
						goHome()
						return gone()
					end
					local nicePart = tbl12.FindNicePart and tbl12.FindNicePart(item)
					if nicePart and not nicePart.Anchored then
						local okD, voided = pcall(tbl12.DestroyObject, item, nicePart)
						if okD and voided == true then
							usedDestroyObject = true
							local deadline = os.clock() + 1.0
							while not flag11 and not gone() and os.clock() < deadline do
								if occupiedByOther() then break end
								if tbl12.IsNetworkOwner(nicePart) or tbl12.IsPartOwner(nicePart) then
									pcall(function()
										if tbl12.PivotTo then
											tbl12.PivotTo(item, CFrame.new(0, -11111, 0))
										else
											item:PivotTo(CFrame.new(0, -11111, 0))
										end
									end)
									pcall(function()
										nicePart.AssemblyLinearVelocity = Vector3.new(0, -750, 0)
										nicePart.AssemblyAngularVelocity = Vector3.zero
									end)
								end
								task.wait()
							end
						elseif not okD then
							warn("[KOZMOZ] Anti Vehicle DestroyObject: " .. tostring(voided))
						end
					end
					dropConns()
					pcall(function()
						if myRoot.Parent and (myRoot.Position - savedCF.Position).Magnitude > 3 then goHome() end
					end)
					if gone() then
						warn("[KOZMOZ] Anti Vehicle removed " .. item.Name .. " (void)")
						return true
					end
					return false
				end, stillValid, function() return not usedDestroyObject end)
				return ok and result == true
			end

			tbl12.GetHeldFood = function(player)
				local result = {}
				if not foodTargetValid(player) then return result end
				local char, root, hum = tbl12.Char(player)
				if not (char and char.Parent and root and root.Parent and hum and hum.Parent and hum.Health > 0) then
					return result
				end
				local ownFolder = foodOwnFolder()
				if not ownFolder then return result end
				local seen = {}
				for _, armName in ipairs({ "Left Arm", "Right Arm", "LeftHand", "RightHand" }) do
					local arm = char:FindFirstChild(armName)
					if arm and arm:IsA("BasePart") then
						local ok, connected = pcall(arm.GetConnectedParts, arm, false)
						if ok then
							for _, hold in ipairs(connected) do
								local model = hold.Parent
								if hold.Name == "HoldPart" and hold:IsA("BasePart")
									and tbl12.IsFoodModel(model, ownFolder) and not seen[model] then
									seen[model] = true
									result[#result + 1] = { Model = model, HoldPart = hold, Arm = arm }
								end
							end
						end
					end
				end
				return result
			end

			tbl12.CleanTargetFood = function(player, options)
				options = options or {}
				local result = { Scanned = false, Found = 0, HeldAttempts = 0, InventoryAttempts = 0, Attempted = false }
				if not foodTargetValid(player) then return result end
				local myChar, myRoot, myHum = tbl12.Char()
				if not (myChar and myChar.Parent and myRoot and myRoot.Parent and myHum and myHum.Parent and myHum.Health > 0) then
					return result
				end
				local ownFolder = foodOwnFolder()
				local seen = {}
				local targetChar = player.Character
				for _, entry in ipairs(tbl12.GetHeldFood(player)) do
					if flag11 or not foodTargetValid(player) then return result end
					local model = entry.Model
					if model.Parent and not seen[model] then
						seen[model] = true
						result.Found += 1
						local now = os.clock()
						if (options.ForceHandRetry or now - (foodHeldAttempts[model] or -math.huge) >= 1.5)
							and model.Parent and entry.HoldPart.Parent == model then
							foodHeldAttempts[model] = now
							result.HeldAttempts += 1
							result.Attempted = true
							local ok, released = pcall(tbl12.BreakHoldable, model, 0.30, true, targetChar)
							if not ok then
								warn("[KOZMOZ Food] held release attempt: " .. tostring(released))
							end
						end
					end
				end
				if options.HandsOnly then
					result.Scanned = true
					return result
				end

				local containers = {}
				local personal = workspace:FindFirstChild(player.Name .. "SpawnedInToys")
				if personal and personal.Parent then containers[#containers + 1] = personal end
				local okPlot, solePlot = pcall(tbl12.GetSoleOwnedPlotInventory, player)
				if okPlot and solePlot and solePlot.Parent and solePlot ~= personal then
					containers[#containers + 1] = solePlot
				elseif not okPlot then
					warn("[KOZMOZ Food] plot lookup: " .. tostring(solePlot))
				end
				for _, container in ipairs(containers) do
					for _, model in ipairs(container:GetChildren()) do
						if flag11 or not foodTargetValid(player) then return result end
						if tbl12.IsFoodModel(model, ownFolder) and not seen[model] and model.Parent == container then
							seen[model] = true
							result.Found += 1
							local part = model.PrimaryPart
							if not (part and part:IsA("BasePart") and part.Parent and part:IsDescendantOf(model) and not part.Anchored) then
								part = tbl12.FindNicePart(model)
							end
							if part and part:IsA("BasePart") and part.Parent and not part.Anchored and part.Position.Y > -500 then
								local function valid()
									return not flag11 and foodTargetValid(player) and model.Parent == container
										and part.Parent and part:IsDescendantOf(model) and not part.Anchored and part.Position.Y > -500
								end
								local ok, destroyed = tbl12.WithAntiVehicleLock(function()
									if not valid() or os.clock() - (foodInventoryAttempts[model] or -math.huge) < 1.25 then
										return false
									end
									foodInventoryAttempts[model] = os.clock()
									return tbl12.DestroyObject(model, part)
								end, valid)
								if not ok then
									warn("[KOZMOZ Food] inventory void attempt: " .. tostring(destroyed))
								elseif destroyed == true then
									result.InventoryAttempts += 1
									result.Attempted = true
								end
							end
						end
					end
				end
				result.Scanned = true
				return result
			end

			-- Preserve the existing Target methods key and routing name.
			tbl12.EatAntiInput = function(player)
				local result = tbl12.CleanTargetFood(player)
				-- A completed scan with no Food is not an ownership failure.
				return result.Scanned == true
			end

			do
				local obj = setmetatable({}, { __mode = "k" })
				local obj2 = setmetatable({}, { __mode = "k" })

				tbl12.ResetGucciSeat = function(arg)
					obj[arg] = nil
				end

				tbl12.RemoveGucci = function(arg)
					local v22, v23, v24 = tbl12.Char()
					local v25, v26, v27 = tbl12.Char(arg)
					local v28, v29 = tbl12.GetInventory(arg)
					local gucciAntiGrab = tbl8.GucciAntiGrab

					if not gucciAntiGrab then
						gucciAntiGrab = not (v24 and v24.Health > 0 and v23 and v28)
					end

					if gucciAntiGrab then
						return false
					end

					local function fn21(arg2)
						if not (arg2 and arg2.Parent) or obj2[arg2] then
							return
						end

						if obj[arg2] then
							return
						end

						if (arg2:IsA("VehicleSeat") or arg2:IsA("Seat")) and not arg2.Occupant then
							obj2[arg2] = true

							if tbl8.RagdollInRG and v26 then
								tbl12.SNO(v26, 1.5)
							end

							if v24.Sit then
								v24.Sit = false
								task.wait(0.1)
							end

							local now3 = tick()
							local flag12 = false
							local flag13 = false

							tbl12.SetRuntimeConnection(arg2, v22.ChildAdded, true, function(arg3)
								if arg3:IsA("LocalScript") and arg3.Name:lower():find("control") then
									arg3.Enabled = false
									arg3:Destroy()
									flag13 = true
								end
							end)

							local connection = arg2.ChildAdded:Connect(function(child)
								if child.Name == "SeatWeld" then
									child.Enabled = false
									child:Destroy()
									flag12 = true
								end
							end)

							while true do
								arg2:Sit(v24)
								fn20()
								if not (flag12 or tick() - now3 > 0.5 or not arg2.Parent or v24.Health <= 0 or flag11) then
									continue
								end
								break
							end

							v24.Sit = false

							if flag12 then
								local now4 = tick()

								while not flag13 and not flag11 and v22.Parent and v24.Health > 0 and tick() - now4 < 0.5 do
									task.wait()
								end
							end

							tbl12.SetRuntimeConnection(arg2, nil, false)
							obj2[arg2] = nil

							if not flag12 then
								v24.Sit = true
								task.wait(0.05)
								v24.Sit = false
								return connection:Disconnect()
							end

							obj[arg2] = true
							connection:Disconnect()

							connection = arg2.ChildAdded:Connect(function(child)
								local v30
								v30, v30 = tbl12.Char()

								if child.Name == "SeatWeld" and child.Part1 ~= v30 then
									obj[arg2] = nil
									connection:Disconnect()
								end
							end)
						end
					end

					local seatPart = v27 and v27.SeatPart
					if seatPart and not v27.Sit then
						obj[seatPart] = nil
						return fn21(seatPart)
					end

					for _, v30 in v28:GetChildren() do
						if v30:IsA("Model") then
							local vehicleSeat = v30:FindFirstChildWhichIsA("VehicleSeat") or v30:FindFirstChildWhichIsA("Seat")

							if vehicleSeat then
								fn21(vehicleSeat)
							end
						end
					end

					if v29 then
						for _, v30 in v29:GetChildren() do
							if v30:IsA("Model") then
								local vehicleSeat = v30:FindFirstChildWhichIsA("VehicleSeat") or v30:FindFirstChildWhichIsA("Seat")

								if vehicleSeat then
									fn21(vehicleSeat)
								end
							end
						end
					end
				end
			end
		end

		-- Target > Methods > Anti Vehicle: SELECTED PLAYER ONLY.
		-- Even if Server Apply is used, this method skips anyone not in Target selection.
		local targetAntiVehicleAttempts = setmetatable({}, { __mode = "k" })
		local targetAntiVehicleNames = { "CreatureBlobman", "TractorRed", "TractorOrange", "TractorGreen", "SantaSleigh" }
		-- v31: occupied vehicles stay protected, but the instant the rider leaves the seat
		-- the drop fires (Occupant signal, no polling delay).
		local targetAntiVehicleVacate = setmetatable({}, { __mode = "k" })
		local targetAntiVehicleWarned = setmetatable({}, { __mode = "k" })
		local function targetAntiVehicleWatchVacate(seat, model, valid)
			if not seat or targetAntiVehicleVacate[seat] then return end
			local conn
			local busy = false
			conn = seat:GetPropertyChangedSignal("Occupant"):Connect(function()
				if flag11 or not seat.Parent or not model.Parent then
					conn:Disconnect()
					targetAntiVehicleVacate[seat] = nil
					return
				end
				if seat.Occupant ~= nil or busy then return end
				if not valid() then
					conn:Disconnect()
					targetAntiVehicleVacate[seat] = nil
					return
				end
				busy = true
				task.spawn(function()
					local removed = false
					for _ = 1, 3 do
						if not valid() then break end
						removed = tbl12.ApelVehicleDrop(model, valid)
						if removed or not valid() then break end
						task.wait()
					end
					busy = false
					if removed or not model.Parent then
						conn:Disconnect()
						targetAntiVehicleVacate[seat] = nil
					end
				end)
			end)
			targetAntiVehicleVacate[seat] = conn
		end
		tbl12.AntiVehicleMethod = function(player)
			if flag11 or not player or not player.Parent or player == localPlayer or tbl12.IsProtectedPlayer(player) then return false end
			if tbl7.SelectedPlayers[player] ~= true then return false end
			local myChar, _, myHum = tbl12.Char()
			if not (myChar and myChar.Parent and myHum and myHum.Parent and myHum.Health > 0) then return false end

			local containers = {}
			local personal = workspace:FindFirstChild(player.Name .. "SpawnedInToys")
			if personal and personal.Parent and personal.Name == player.Name .. "SpawnedInToys" then
				containers[#containers + 1] = personal
			end
			local okPlot, plotInv = pcall(tbl12.GetSoleOwnedPlotInventory, player)
			if not okPlot then
				warn("[KOZMOZ Anti Vehicle Target] plot lookup: " .. tostring(plotInv))
			elseif plotInv and plotInv.Parent and plotInv ~= personal then
				containers[#containers + 1] = plotInv
			end

			local anyFound = false
			local anyRemoved = false
			for _, container in ipairs(containers) do
				for _, model in ipairs(container:GetChildren()) do
					if flag11 or not player.Parent or tbl12.IsProtectedPlayer(player) or tbl7.SelectedPlayers[player] ~= true then
						return anyRemoved or not anyFound
					end
					if model:IsA("Model") and model.Parent == container and table.find(targetAntiVehicleNames, model.Name) then
						anyFound = true
						if os.clock() - (targetAntiVehicleAttempts[model] or -math.huge) >= 0.25 then
							local seat = model:FindFirstChildOfClass("VehicleSeat") or model:FindFirstChildWhichIsA("VehicleSeat", true)
							if seat and seat.Occupant and seat.Occupant ~= myHum then
								targetAntiVehicleWatchVacate(seat, model, function()
									return not flag11 and player.Parent and not tbl12.IsProtectedPlayer(player)
										and tbl7.SelectedPlayers[player] == true and model.Parent == container
										and seat.Parent and (not seat.Occupant or seat.Occupant == myHum)
								end)
								if not targetAntiVehicleWarned[model] then
									targetAntiVehicleWarned[model] = true
									warn("[KOZMOZ Anti Vehicle Target] " .. model.Name .. " occupied (protected): removes the instant the rider leaves")
								end
							else
								local function valid()
									return not flag11 and player.Parent and not tbl12.IsProtectedPlayer(player)
										and tbl7.SelectedPlayers[player] == true and model.Parent == container
										and table.find(targetAntiVehicleNames, model.Name)
										and (not seat or not seat.Parent or not seat.Occupant or seat.Occupant == myHum)
								end
								local removed = false
								for attempt = 1, 3 do
									if not valid() then break end
									targetAntiVehicleAttempts[model] = os.clock()
									removed = tbl12.ApelVehicleDrop(model, valid)
									if removed then break end
									if not valid() then break end
									task.wait()
								end
								if removed then
									anyRemoved = true
								else
									warn("[KOZMOZ Anti Vehicle Target] " .. model.Name .. " not removed for selected player " .. player.Name)
								end
							end
						end
					end
				end
			end
			-- No vehicle found is a completed scan, not an ownership failure.
			return anyRemoved or not anyFound
		end

		tbl12.DeleteSeatables = function(arg)
			local v22, v23, v24 = tbl12.Char()
			local v25 = tbl12.GetInventory(arg)
			if not (v24 and v24.Health > 0 and v23 and v25) then
				return false
			end

			local function fn21(arg2)
				if arg2:IsA("Model") then
					local primaryPart = arg2.PrimaryPart or tbl12.FindNicePart(arg2)
					if not primaryPart or not primaryPart:IsA("BasePart") or primaryPart.Velocity.Magnitude > 100 then
						return
