		-- Per-method pacing for non-Kick Blobman actions. These are request/
		-- confirmation windows, not guaranteed server results. KickTiming and
		-- cleanup/cancellation delays are intentionally separate.
		tbl14.MethodTiming = {
			SitConfirm = 0.65, SitPoll = 0.025,
			GrabTimeout = 0.55, GrabPoll = 0.025, NearGrabConfirm = 0.10,
			AcquireNear = 0.30, AcquireFar = 0.55, AcquireConfirm = 0.08, AcquirePoll = 0.02,
			BringConfirm = 0.08, BringPoll = 0.02,
			DeathPoll = 0.015, DeathChecks = 2,
			GucciCooldown = 0.55, GucciSitMax = 0.12, GucciPoll = 0.02,
			LockPrepare = 0.08, LockSeatMax = 0.24, LockPoll = 0.02,
			FollowStep = 0.08, FollowTeleport = 0.55,
			LoopLockStep = 0.03,
			-- KOZMOZ: eski degerler cok agirdi, blobman "yavas/yapismis" hissi veriyordu
			LockSeatMax2 = 0.24,
			RemoveFoodCooldown = 1.5, RemoveFoodGrab = 0.55,
		}
		tbl14.Sit = function()
			local v22, v23, v24 = tbl12.Char()
			if parent and not parent.Parent then parent = nil end
			local nowTrace = os.clock()
			if nowTrace - (tbl14.LastSitTrace or 0) > 5 then
				tbl14.LastSitTrace = nowTrace
				warn("[BLOBMAN TRACE] Sit invoked; inventory=" .. tostring(v17)
					.. ", parent=" .. tostring(parent)
					.. ", mySeat=" .. tostring(v24 and v24.SeatPart)
					.. ", GucciAntiGrab=" .. tostring(tbl8.GucciAntiGrab))
			end
			local seated = v24 and v24.SeatPart
			if seated and seated.Parent and seated.Parent.Name == "CreatureBlobman" then
				parent = seated.Parent
				return true
			end
			if not (v24 and v24.Health > 0 and v23 and v23.Parent) then return false end
			if parent or (v24.Sit and v24.SeatPart) or tbl8.GucciAntiGrab then return false end
			local creatureBlobman = v17 and v17:FindFirstChild("CreatureBlobman")
			local vehicleSeat = creatureBlobman and creatureBlobman:FindFirstChild("VehicleSeat")
			if vehicleSeat and vehicleSeat.Occupant and vehicleSeat.Occupant ~= v24 then
				-- Never spam Sit() into an occupied seat or replace it every frame.
				return false
			end
			if not creatureBlobman then
				creatureBlobman = tbl12.SpawnToy("CreatureBlobman")
			end
			if not (creatureBlobman and creatureBlobman.Parent) then return false end
			if not vehicleSeat then
				vehicleSeat = creatureBlobman:WaitForChild("VehicleSeat", 0.5)
			end
			if not (vehicleSeat and vehicleSeat.Parent) then return false end
			if vehicleSeat.Occupant == v24 or v24.SeatPart == vehicleSeat then
				parent = creatureBlobman
				return true
			end
			if vehicleSeat.Occupant then return false end
			local cFrame2 = v23.CFrame
			-- One actual Sit request, then a bounded confirmation wait.
			pcall(vehicleSeat.Sit, vehicleSeat, v24)
			local deadline = tick() + tbl14.MethodTiming.SitConfirm
			while not flag11 and tick() < deadline do
				if vehicleSeat.Occupant and vehicleSeat.Occupant ~= v24 then return false end
				if vehicleSeat.Occupant == v24 or v24.SeatPart == vehicleSeat then
					parent = creatureBlobman
					break
				end
				task.wait(tbl14.MethodTiming.SitPoll)
			end
			if parent == creatureBlobman then
				tbl12.Teleport(v23, cFrame2)
				return true
			end
			return false
		end

		tbl14.Grab = function(arg, arg2)
			if not parent then
				return
			end
			local v22 = tbl14.GetBlobmanComponents()
			if not (v22.CreatureGrab and v22.RightWeld) then
				return
			end
			local v23, v24, v25 = tbl12.Char()
			if not (v24 and v25 and v25.Health > 0) or not parent then
				return
			end
			local v26, v27, v28 = tbl12.Char(arg)
			local rootAttachment = v27 and v27:FindFirstChild("RootAttachment")
			if not (rootAttachment and v28 and v28.Health > 0) or not parent then
				return
			end
			local now3 = tick()

			if tbl12.GetMagnitude(v24, v27) > 40 then
				local cFrame2 = v24.CFrame
				currentCamera.CameraType = Enum.CameraType.Scriptable

				while true do
					local flag12 = parent and v27 and v27.Parent and v25.Health > 0 and v28.Health > 0 and rootAttachment and v22.RightWeld.Attachment0 ~= rootAttachment

					if flag12 then
						flag12 = tick() - now3 < (arg2 or tbl14.MethodTiming.GrabTimeout)
					end

					if flag12 then
						tbl12.Teleport(v24, tbl12.PredictCFrame(v27) - Vector3.new(0, 15, 0))
						task.wait(tbl14.MethodTiming.GrabPoll)
						v22.CreatureGrab:FireServer(nil, v27, v22.RightWeld)
						if v22.RightWeld.Attachment0 == rootAttachment then break end
						continue
					end

					break
				end

				tbl12.Teleport(v24, cFrame2, CFrame.new(0, 5, 0))
				currentCamera.CameraType = Enum.CameraType.Custom
			else
				v22.CreatureGrab:FireServer(nil, v27, v22.RightWeld)
				local deadline = os.clock() + tbl14.MethodTiming.NearGrabConfirm
				while not flag11 and parent and v27.Parent and os.clock() < deadline do
					if v22.RightWeld and v22.RightWeld.Attachment0 == rootAttachment then return true end
					task.wait(tbl14.MethodTiming.GrabPoll)
				end
			end

			if v22.RightWeld and v22.RightWeld.Attachment0 == rootAttachment then
				return true
			end
		end

		tbl14.Release = function(arg, arg2)
			if not parent then
				return
			end
			local v22 = tbl14.GetBlobmanComponents()
			if not (v22.CreatureGrab and v22.CreatureRelease and v22.RightWeld) then
				return
			end
			local v23, v24, v25 = tbl12.Char()
			if not (v24 and v25 and v25.Health > 0) or not parent then
				return
			end
			local v26, v27, v28 = tbl12.Char(arg)
			if not (v27 and v28 and v28.Health > 0) or not parent then
				return
			end

			if tbl12.IsNetworkOwner(v27) then
				return true
			end
			local now3 = tick()
			local flag12 = tbl12.GetMagnitude(v24, v27) >= 40
			if flag12 and tbl7.States.Owning then
				return
			end
			v22.RightWeld.Enabled = false
			local cframe = CFrame.new()
			local cframe2 = CFrame.new()
			local connection = nil
			tbl7.States.Owning = true

			local function fn21()
				cframe = v24.CFrame
				cframe2 = v24.CFrame

				RunService:BindToRenderStep("ClientVision", Enum.RenderPriority.Camera.Value - 1, function()
					v24.CFrame = cframe
				end)

				connection = RunService.Heartbeat:Connect(function()
					cframe = v24.CFrame
					v24.CFrame = cframe2
				end)
			end

			local function fn22()
				RunService:UnbindFromRenderStep("ClientVision")

				if connection then
					connection:Disconnect()
					connection = nil
				end

				if v24 then
					v24.CFrame = cframe
				end
			end

			if tbl12.GetMagnitude(workspace.SpawnLocation, v27) < 15000 then
				pcall(function()
					if flag12 then
						fn21()
					end

					while true do
						local flag13 = parent and v27 and v27.Parent and v25.Health > 0 and v28.Health > 0 and not tbl12.IsNetworkOwner(v27)

						if flag13 then
							flag13 = tick() - now3 < (arg2 or tbl14.MethodTiming.AcquireFar)
						end

						if flag13 then
							local v29 = tbl12.PredictCFrame(v27)
							v22.RightWeld.Enabled = false

							if flag12 then
								cframe2 = v29 - Vector3.new(0, 15, 0)
							end

							task.wait(0.011111111111111112)
							v22.CreatureGrab:FireServer(nil, v27, v22.RightWeld)
							task.wait(0.011111111111111112)
							v22.CreatureRelease:FireServer(v22.RightWeld)
							continue
						end

						break
					end
				end)

				if flag12 then
					pcall(fn22)
				end
			end

			task.delay(0.1, function()
				v22.RightWeld.Attachment0 = nil
				v22.RightWeld.Enabled = true
			end)

			tbl7.States.Owning = false
			if v27 and tbl12.IsNetworkOwner(v27) then return true end
			task.wait()
			if v27 and tbl12.IsNetworkOwner(v27) then
				return true
			end
		end

		-- Request pacing only; these are not guaranteed kicks/second.
		tbl14.KickTiming = {
			Alignment = 0.16, Hold = 0.75, ServerCooldown = 2.5,
			ServerSuccess = 0.35, ServerNoAction = 0.65,
			SelectedPrep = 0.10, SelectedFirstDrop = 0.03, SelectedRound = 0.055,
			ExtraOwner = 0.15, Sticky = 0.55,
		}
		tbl14.KickServerCooldowns = setmetatable({}, { __mode = "k" })

		-- Adapted from kar.txt > Miscellaneous > Auras > Blobman Kick.
		-- Unlike the older Kozmoz kick, the aura uses the left detector as the
		-- FIRST remote argument and drops with (detector, root), not (weld).
		-- Run only for explicitly selected targets, never as an implicit aura.
		tbl14.KarAuraKickTargets = function(targets, server)
			local _, ownRoot, ownHum = tbl12.Char()
			local seat = ownHum and ownHum.SeatPart
			local blob = seat and seat.Parent
			if not (ownRoot and ownHum and ownHum.Health > 0 and blob and blob.Name == "CreatureBlobman") then
				return false
			end
			local detector = blob:FindFirstChild("LeftDetector")
			local weld = detector and detector:FindFirstChild("LeftWeld")
			local ownerScript = blob:FindFirstChild("BlobmanSeatAndOwnerScript", true)
				or blob:FindFirstChild("BlobmanSeatAndOwnerScript[old]", true)
			local grab = ownerScript and ownerScript:FindFirstChild("CreatureGrab")
			local drop = ownerScript and ownerScript:FindFirstChild("CreatureDrop")
			if not (detector and weld and grab and drop and tbl11.SetNetworkOwner) then return false end
			local succeeded = false
			for _, player in ipairs(targets) do
				if flag11 or not blob.Parent or ownHum.SeatPart ~= seat then break end
				local now = os.clock()
				if player and player ~= localPlayer and not tbl12.IsProtectedPlayer(player, server)
					and now - (tbl14.KickServerCooldowns[player] or -math.huge) >= 1.5 then
					local _, targetRoot, targetHum = tbl12.Char(player)
					if targetRoot and targetRoot.Parent and targetHum and targetHum.Health > 0
						and (targetRoot.Position - ownRoot.Position).Magnitude <= 35 then
						-- kar: grab our root, request ownership facing the target,
						-- raise the target, then grab/drop it with the LEFT hand.
						local ok = pcall(function()
							ownRoot.AssemblyLinearVelocity = Vector3.zero
							grab:FireServer(detector, ownRoot, weld)
							task.wait(0.03)
							local aim = targetRoot.Position - ownRoot.Position
							if aim.Magnitude > 0.01 then
								tbl11.SetNetworkOwner:FireServer(targetRoot, CFrame.lookAt(ownRoot.Position, targetRoot.Position))
							else
								tbl11.SetNetworkOwner:FireServer(targetRoot, targetRoot.CFrame)
							end
							task.wait(0.03)
							targetRoot.CFrame += Vector3.new(0, 20, 0)
							task.wait(0.03)
							if tbl11.DestroyGrabLine then tbl11.DestroyGrabLine:FireServer(targetRoot) end
							task.wait(0.03)
							grab:FireServer(detector, targetRoot, weld)
							task.wait(0.03)
							drop:FireServer(detector, targetRoot)
							if tbl11.DestroyGrabLine then tbl11.DestroyGrabLine:FireServer(targetRoot) end
						end)
						if ok then
							tbl14.KickServerCooldowns[player] = now
							succeeded = true
						else
							warn("[KOZMOZ] Kar Blobman Kick remote failed for " .. player.Name)
						end
					end
				end
			end
			return succeeded
		end

		tbl14.KickTargets = function(targets, server)
			if tbl14.KickTargetsBusy or not targets or #targets == 0 or flag11 then return false end
			local busyToken = {}
			tbl14.KickTargetsBusy = busyToken
			local parts, ownRoot, ownChar
			local temporary = {}
			local eligible = {}
			local savedWeldEnabled, savedOriEnabled
			local function cleanup()
				if parts then
					pcall(function()
						local weld = parts.RightWeld
						if weld and weld.Parent then
							local a0 = weld.Attachment0
							local ours = a0 and ownChar and a0:IsDescendantOf(ownChar)
							if not ours and a0 then
								for _, entry in ipairs(eligible) do
									if entry.Character and a0:IsDescendantOf(entry.Character) then ours = true break end
								end
							end
							if ours then weld.Attachment0 = nil end
							if savedWeldEnabled ~= nil then weld.Enabled = savedWeldEnabled end
						end
					end)
					pcall(function()
						if parts.RightOri and parts.RightOri.Parent and savedOriEnabled ~= nil then
							parts.RightOri.Enabled = savedOriEnabled
						end
					end)
				end
				for _, object in ipairs(temporary) do
					pcall(function() if object and object.Parent then object:Destroy() end end)
				end
			end
			local function run()
				if not targets or #targets == 0 or flag11 then return false end
				if server then
					local now = os.clock()
					local due = false
					for _, player in ipairs(targets) do
						if player and now - (tbl14.KickServerCooldowns[player] or -math.huge) >= tbl14.KickTiming.ServerCooldown then
							due = true
							break
						end
					end
					if not due then return false end
				end
				local _, _, initialHum = tbl12.Char()
				local initialSeat = initialHum and initialHum.SeatPart
				if not (initialSeat and initialSeat.Parent and initialSeat.Parent.Name == "CreatureBlobman") then
					if not tbl12.EnsureBlobmanReady() then return false end
				end
				parts = tbl14.GetBlobmanComponents()
				ownChar, ownRoot, initialHum = tbl12.Char()
				local releaseSelected = tbl9.BKMethod == 2
				local finishRemote
				if parts then
					finishRemote = releaseSelected and parts.CreatureRelease or (not releaseSelected and parts.CreatureDrop or nil)
				end
				if not (parts and parts.CreatureGrab and finishRemote and parts.RightWeld
					and ownRoot and ownRoot.Parent and initialHum and initialHum.Health > 0
					and initialHum.SeatPart and initialHum.SeatPart.Parent == parts.Blobman) then
					return false
				end
				local blob = parts.Blobman
				savedWeldEnabled = parts.RightWeld.Enabled
				savedOriEnabled = parts.RightOri and parts.RightOri.Enabled or nil
				if parts.CreatureDrop then parts.CreatureDrop:FireServer(parts.RightWeld) end
				for _, player in ipairs(targets) do
					if flag11 or not blob.Parent then break end
					local cooldown = server and os.clock() - (tbl14.KickServerCooldowns[player] or -math.huge) < tbl14.KickTiming.ServerCooldown
					if not cooldown then
						local char, root, hum = tbl12.Char(player)
						if player and player ~= localPlayer and not tbl12.IsProtectedPlayer(player, server)
							and char and char.Parent and root and root.Parent and hum and hum.Health > 0
							and not (root.AssemblyRootPart or root).Massless and not hum.SeatPart then
							if server then tbl14.KickServerCooldowns[player] = os.clock() end
							-- Fundamental ownership acquisition is independent of Net Owner Spam.
							local acquired
							if tbl12.IsNetworkOwner(root) then
								acquired = true
							elseif parts.CreatureRelease then
								acquired = tbl14.Release(player, 0.38) == true
							else
								acquired = tbl12.SNO(root, 0.38) == true
							end
							if acquired and root.Parent and not hum.SeatPart then
								eligible[#eligible + 1] = { Player = player, Character = char, Root = root }
							end
						end
					end
				end
				if #eligible == 0 then return false end

				local x = options.BlobKickX
				local y = options.BlobKickY
				local z = options.BlobKickZ
				local dx = (tonumber(x and x.Value) or 0) - (tonumber(x and x.Default) or 0)
				local dy = (tonumber(y and y.Value) or 25) - (tonumber(y and y.Default) or 25)
				local dz = (tonumber(z and z.Value) or 0) - (tonumber(z and z.Default) or 0)
				parts.RightWeld.Enabled = false
				for i, entry in ipairs(eligible) do
					if flag11 or not blob.Parent or not entry.Root.Parent then break end
					-- Legacy circle is exactly unchanged at X=0/Y=25/Z=0.
					local cf = ownRoot.CFrame * CFrame.Angles(0, i / #eligible * math.pi * 2, 0)
						* CFrame.new(dx, 5 + dy, -20 + dz)
					entry.CFrame = cf
					tbl12.Teleport(entry.Root, cf)
					local pos, ori = tbl12.CreateAlign(entry.Root, true)
					if pos then
						temporary[#temporary + 1] = pos
						if pos.Attachment0 then temporary[#temporary + 1] = pos.Attachment0 end
						pos.Position = cf.Position
					end
					if ori then
						temporary[#temporary + 1] = ori
						if ori.Attachment0 and ori.Attachment0 ~= (pos and pos.Attachment0) then
							temporary[#temporary + 1] = ori.Attachment0
						end
						ori.CFrame = cf - cf.Position
					end
				end
				task.wait(tbl14.KickTiming.Alignment)
				for _, entry in ipairs(eligible) do
					if flag11 or not blob.Parent then break end
					if entry.Root.Parent then
						parts.CreatureGrab:FireServer(nil, entry.Root, parts.RightWeld)
						if not releaseSelected and tbl8.NetworkOwnerInKick then
							-- Optional extra ownership pulse; the base Release/SNO above is always kept.
							pcall(tbl12.Grab, entry.Root)
							pcall(tbl12.RNO, entry.Root)
						end
						if tbl8.DeleteShurInBlobK then
							local char = entry.Character
							task.spawn(function() pcall(tbl12.RemoveSticky, char) end)
						end
						task.wait()
					end
				end
				if flag11 or not blob.Parent then return false end
				parts.CreatureGrab:FireServer(nil, ownRoot, parts.RightWeld)
				local deadline = os.clock() + tbl14.KickTiming.Hold
				while not flag11 and blob.Parent and os.clock() < deadline do
					for _, entry in ipairs(eligible) do
						if entry.Root.Parent then
							entry.Root.CFrame = entry.CFrame
							tbl12.ResetVelocity(entry.Root)
						end
					end
					RunService.Heartbeat:Wait()
				end
				if flag11 or not blob.Parent then return false end
				if releaseSelected then
					parts.CreatureRelease:FireServer(parts.RightWeld)
				else
					parts.CreatureDrop:FireServer(parts.RightWeld)
				end
				return true
			end
			local ok, result = pcall(run)
			cleanup()
			if tbl14.KickTargetsBusy == busyToken then tbl14.KickTargetsBusy = nil end
			if not ok then
				warn("[BLOBMAN Kick] temporary alignment/remote failed; cleaned: " .. tostring(result))
				return false
			end
			return result == true
		end

		tbl14.Kick = function(arg)
			return tbl14.KickTargets({ arg })
		end

		tbl14.KickServer = function()
			return tbl14.KickTargets(tbl12.GetTargets(true, tbl7.SelectedPlayersBlob), true)
		end

		tbl12.KickServer = function(arg)
			local kickServerState = tbl7.KickServerState
			local tbl16 = {}
			if kickServerState.Running then
				return false
			end
			local now3 = os.clock()

			for _, v22 in ipairs(tbl12.GetTargets(true, tbl7.SelectedPlayers)) do
				local v23, v24, v25 = tbl12.Char(v22)
				local flag12 = v24 and v25 and v25.Health > 0

				if flag12 then
					flag12 = not arg

					if not flag12 then
						flag12 = now3 - (tbl7.KickServerCooldowns[v22] or -math.huge) >= 15
					end
				end

				if flag12 then
					tbl16[#tbl16 + 1] = v22
				end
			end

			if #tbl16 == 0 then
				return false
			end
			kickServerState.Running = true
			local tbl17 = {}
			local tbl18 = {}
			local connection = nil

			local ok, result = pcall(function()
				options.LineLagSSlider:SetValue(11)

				if not toggles.LineLagToggle.Value then
					toggles.LineLagToggle:SetValue(true)
				end

				toggles.LineLagToggle:SetDisabled(true)
				local v22, v23, v24 = tbl12.Char()
				if not (v23 and v24 and v24.Health > 0) then
					return
				end
				local position = v23.Position

				connection = RunService.Heartbeat:Connect(function()
					for k, v25 in tbl18, nil, nil do
						if k.Parent then
							k.CFrame = v25
							tbl12.ResetVelocity(k)
						else
							tbl18[k] = nil
						end
					end
				end)

				for i, v25 in ipairs(tbl16) do
					if not flag11 then
						local v26, v27, v28 = tbl12.Char(v25)

						if v27 and v28 and v28.Health > 0 then
							if arg then
								tbl7.KickServerCooldowns[v25] = os.clock()
							end

							if tbl12.SNO(v27) then
								local n36 = i / #tbl16 * 3.1415926535897931 * 2
								local v29 = tbl17
								local n37 = #tbl17 + 1
								local v30 = tbl18
								local cframe = CFrame.new(position + Vector3.new(math.cos(n36) * 15, 15, math.sin(n36) * 15))
								v29[n37] = v27
								v30[v27] = cframe
								tbl12.Teleport(v27, tbl18[v27])
							end
						end

						continue
					end

					break
				end

				for i, v25 in ipairs(tbl17) do
					local n36 = i / #tbl17 * 3.1415926535897931 * 2
					tbl18[v25] = CFrame.new(position + Vector3.new(math.cos(n36) * 15, 15, math.sin(n36) * 15))
				end

				RunService.Heartbeat:Wait()
			end)

			task.spawn(function()
				local n36 = os.clock() + 3

				while not flag11 and os.clock() < n36 do
					RunService.Heartbeat:Wait()
				end

				if connection then
					connection:Disconnect()
					connection = nil
				end
			end)

			task.wait(0.15)

			for _, v22 in ipairs(tbl17) do
				if v22.Parent then
					tbl12.RNO(v22)
				end
			end

			for _, v22 in ipairs(tbl17) do
				if not flag11 and v22.Parent then
					task.spawn(tbl12.RemoveSticky, v22.Parent)
				end
			end

			task.wait(6)

			if not flag11 then
				toggles.LineLagToggle:SetDisabled(false)
				toggles.LineLagToggle:SetValue(false)
			end

			kickServerState.Running = false

			if not ok then
				warn("[KOZMOZ] Target Kick Server failed: " .. tostring(result))
			end

			return ok and #tbl17 > 0
		end

		-- Blobman method safeguards. Non-Kick methods share these helpers;
		-- Kick/Target routes retain their existing behaviour and KickTiming.
		do
			local lastFailure = {}
			local followStates = setmetatable({}, { __mode = "k" })
			local lastGucciPulse = setmetatable({}, { __mode = "k" })

			tbl14.MethodFailure = function(method, player, reason)
				local key = method .. ":" .. tostring(player)
				local now = os.clock()
				if now - (lastFailure[key] or -math.huge) >= 3 then
					lastFailure[key] = now
					warn(("[BLOBMAN %s] %s: %s"):format(method, player and player.Name or "?", tostring(reason)))
				end
				return false
			end

			tbl14.MethodTarget = function(method, player, requireStanding)
				if flag11 or not (player and player.Parent) or player == localPlayer or tbl12.IsProtectedPlayer(player) then
					return tbl14.MethodFailure(method, player, "invalid or protected target")
				end
				local _, ownRoot, ownHum = tbl12.Char()
				local targetChar, targetRoot, targetHum = tbl12.Char(player)
				if not (ownRoot and ownRoot.Parent and ownHum and ownHum.Health > 0
					and targetChar and targetChar.Parent and targetRoot and targetRoot.Parent
					and targetHum and targetHum.Health > 0) then
					return tbl14.MethodFailure(method, player, "character/root/humanoid unavailable")
				end
				if requireStanding and targetHum.SeatPart then
					return tbl14.MethodFailure(method, player, "target is seated")
				end
				local seat = ownHum.SeatPart
				if not (seat and seat.Parent and seat.Parent.Name == "CreatureBlobman") then
					-- One bounded sit attempt; do not spawn a new Blobman on each loop frame.
					if not tbl12.EnsureBlobmanReady or not tbl12.EnsureBlobmanReady() then
						return tbl14.MethodFailure(method, player, "not seated in Blobman")
					end
					_, ownRoot, ownHum = tbl12.Char()
					seat = ownHum and ownHum.SeatPart
				end
				if not (seat and seat.Parent and seat.Parent.Name == "CreatureBlobman" and ownRoot and ownRoot.Parent) then
					return tbl14.MethodFailure(method, player, "Blobman seat not confirmed")
				end
				parent = seat.Parent
				return ownRoot, ownHum, targetChar, targetRoot, targetHum
			end

			tbl14.MethodAcquire = function(method, player, root)
				if root and root.Parent and tbl12.IsNetworkOwner(root) then return true end
				local _, ownRoot = tbl12.Char()
			local nearby = ownRoot and root and root.Parent and (root.Position - ownRoot.Position).Magnitude < 40
			if not (root and root.Parent and tbl14.Release(player, nearby and tbl14.MethodTiming.AcquireNear or tbl14.MethodTiming.AcquireFar)) then
					return tbl14.MethodFailure(method, player, "Release/network ownership failed")
				end
				local deadline = os.clock() + tbl14.MethodTiming.AcquireConfirm
				repeat
					if flag11 or not root.Parent then break end
					if tbl12.IsNetworkOwner(root) then return true end
					task.wait(tbl14.MethodTiming.AcquirePoll)
				until os.clock() >= deadline
				return tbl14.MethodFailure(method, player, "network ownership not confirmed")
			end

			tbl14.StopAllFollow = function()
				for player, state in pairs(followStates) do
					state.active = false
					followStates[player] = nil
				end
			end

			tbl14.Bring = function(player)
				local ownRoot, _, char, root = tbl14.MethodTarget("Bring", player)
				if not ownRoot or not tbl14.MethodAcquire("Bring", player, root) then return false end
				local ok, result = pcall(tbl12.BringPlayer, player)
				if not ok or not result then
					return tbl14.MethodFailure("Bring", player, ok and "BringPlayer did not complete" or result)
				end
				-- BringPlayer releases ownership after moving. Confirm the local position;
				-- this is NOT a promise that the server has accepted the movement.
			local bringDeadline = os.clock() + tbl14.MethodTiming.BringConfirm
				repeat
					if flag11 or not (char.Parent and root.Parent and ownRoot.Parent) then break end
					if (root.Position - ownRoot.Position).Magnitude <= 12 then return true end
					task.wait(tbl14.MethodTiming.BringPoll)
				until os.clock() >= bringDeadline
				return tbl14.MethodFailure("Bring", player, "target not observed near player")
			end

			tbl14.Kill = function(player)
				local ownRoot, _, char, root, hum = tbl14.MethodTarget("Kill", player)
				if not ownRoot then return false end
				if hum.SeatPart then
					if not tbl14.Bring(player) then return false end
					if flag11 or not char.Parent or not root.Parent or not hum.Parent or hum.Health <= 0 then
						return tbl14.MethodFailure("Kill", player, "target changed during Bring")
					end
					-- BringPlayer returns network ownership. Reacquire before the
					-- existing seated-target Kill action; no additional fallback damage.
					if not tbl14.MethodAcquire("Kill", player, root) then return false end
					local ok, err = pcall(tbl12.Kill, player)
					if not ok then return tbl14.MethodFailure("Kill", player, err) end
				else
					if not tbl14.MethodAcquire("Kill", player, root) then return false end
					local ok, err = pcall(function()
						hum.BreakJointsOnDeath = false
						hum:ChangeState(Enum.HumanoidStateType.Dead)
					end)
					if not ok then return tbl14.MethodFailure("Kill", player, err) end
				end
				if hum.Parent and (hum.Health <= 0 or hum:GetState() == Enum.HumanoidStateType.Dead) then return true end
				-- Give a pending local state transition at most two short frames to land.
				for _ = 1, tbl14.MethodTiming.DeathChecks do
					task.wait(tbl14.MethodTiming.DeathPoll)
					if hum.Parent and (hum.Health <= 0 or hum:GetState() == Enum.HumanoidStateType.Dead) then return true end
				end
				return tbl14.MethodFailure("Kill", player, "Dead state not locally observed")
			end

			tbl14.RemoveGucci = function(player)
				local ownRoot, _, _, root, hum = tbl14.MethodTarget("Remove Gucci", player, true)
				if not ownRoot then return false end
				local now = os.clock()
				if now - (lastGucciPulse[player] or -math.huge) < tbl14.MethodTiming.GucciCooldown then return true end
				if not tbl14.MethodAcquire("Remove Gucci", player, root) then return false end
				lastGucciPulse[player] = os.clock()
				local ok, err = pcall(function()
					hum.Sit = true
					local gucciDeadline = os.clock() + tbl14.MethodTiming.GucciSitMax
					while not flag11 and hum.Parent and not hum.SeatPart and os.clock() < gucciDeadline do
						task.wait(tbl14.MethodTiming.GucciPoll)
					end
					-- Do not alter a respawned/replaced humanoid or a newly occupied seat.
					if hum.Parent and not hum.SeatPart then hum.Sit = false end
				end)
				if not ok then return tbl14.MethodFailure("Remove Gucci", player, err) end
				-- A Sit pulse is an attempt, not proof that Gucci protection was removed.
				return true
			end

			local removeFoodBusy = setmetatable({}, { __mode = "k" })
			local removeFoodLast = setmetatable({}, { __mode = "k" })
			tbl14.RemoveFood = function(player)
				if flag11 or not (player and player.Parent) or player == localPlayer or tbl12.IsProtectedPlayer(player) then
					return false
				end
				if removeFoodBusy[player] then return true end
				local now = os.clock()
				if now - (removeFoodLast[player] or -math.huge) < tbl14.MethodTiming.RemoveFoodCooldown then return true end
				local token = {}
				removeFoodBusy[player] = token
				removeFoodLast[player] = now
				local ok, result = pcall(function()
					-- Shared Target cleanup first; never Grab a player with no held Food.
					local clean = tbl12.CleanTargetFood(player)
					if not clean.Scanned then return false end
					local held = tbl12.GetHeldFood(player)
					if #held == 0 then return true end
					local ownRoot, ownHum, char, root, hum = tbl14.MethodTarget("Remove Food", player)
					if not ownRoot then return false end
					local parts = tbl14.GetBlobmanComponents()
					if not (parts and parts.CreatureGrab and parts.RightWeld and parts.Blobman and parts.Blobman.Parent) then
						return tbl14.MethodFailure("Remove Food", player, "Blobman grab components missing")
					end
					local savedWeldEnabled = parts.RightWeld.Enabled
					local cameraType = currentCamera and currentCamera.CameraType
					local grabOK, grabbed = pcall(tbl14.Grab, player, tbl14.MethodTiming.RemoveFoodGrab)
					-- Always try to release/clear, even when Grab failed or retry threw.
					pcall(function()
						if parts.CreatureRelease then
							parts.CreatureRelease:FireServer(parts.RightWeld)
						elseif parts.CreatureDrop then
							parts.CreatureDrop:FireServer(parts.RightWeld)
						end
					end)
					pcall(function()
						local weld = parts.RightWeld
						if weld and weld.Parent then
							local a0 = weld.Attachment0
							if a0 and char and a0:IsDescendantOf(char) then weld.Attachment0 = nil end
							weld.Enabled = savedWeldEnabled
						end
					end)
					if currentCamera and cameraType and currentCamera.CameraType == Enum.CameraType.Scriptable and cameraType ~= Enum.CameraType.Scriptable then
						pcall(function() currentCamera.CameraType = cameraType end)
					end
					if not grabOK then return tbl14.MethodFailure("Remove Food", player, grabbed) end
					if grabbed ~= true then return tbl14.MethodFailure("Remove Food", player, "limited Grab did not attach") end
					-- One forced held-food retry after the bounded Grab; inventory is
					-- not rescanned here and no Kick/Kill path is used.
					tbl12.CleanTargetFood(player, { HandsOnly = true, ForceHandRetry = true })
					return true
				end)
				if removeFoodBusy[player] == token then removeFoodBusy[player] = nil end
				if not ok then return tbl14.MethodFailure("Remove Food", player, result) end
				return result == true
			end

			-- =====================================================================
			-- KOZMOZ: "Kick + Remove Food" ayni anda.
			-- Kick dongusu blobman weld'ini ve Grab'i surekli kullandigi icin
			-- tam RemoveFood (Grab + weld) ayni anda calisirsa kick'i bozar.
			-- Bu yuzden pasif surum sadece yemek temizligi yapar:
			--   * elde tutulan yemek -> BreakHoldable
			--   * envanter/plot yemegi -> temizlenir
			-- Grab, RNO, weld, kamera ve ragdoll'a DOKUNMAZ.
			local removeFoodPassiveLast = setmetatable({}, { __mode = "k" })
			tbl14.RemoveFoodPassive = function(player)
				if flag11 or not (player and player.Parent) or player == localPlayer then return false end
				if tbl12.IsProtectedPlayer(player) then return true end
				local now = os.clock()
				if now - (removeFoodPassiveLast[player] or -math.huge) < 1.2 then return true end
				removeFoodPassiveLast[player] = now
				pcall(function() tbl12.CleanTargetFood(player) end)
				return true
			end

			tbl14.Lock = function(player)
				local ownRoot, ownHum, _, root, hum = tbl14.MethodTarget("Lock", player)
				if not ownRoot then return false end
				local parts = tbl14.GetBlobmanComponents()
				local weld = parts and parts.RightWeld
			local attachment = root:FindFirstChild("RootAttachment")
			if not (weld and weld.Parent and attachment and attachment.Parent) then
				return tbl14.MethodFailure("Lock", player, "RightWeld or RootAttachment missing")
			end
			local previous = weld.Attachment0
			local cameraType = currentCamera and currentCamera.CameraType
			local grabOK, grabbed = pcall(tbl14.Grab, player)
			if not grabOK and currentCamera and cameraType then
				pcall(function() currentCamera.CameraType = cameraType end)
			end
			if not grabOK or not grabbed then
				return tbl14.MethodFailure("Lock", player, grabOK and "Grab failed" or grabbed)
			end
			local blob = parent
				local oldSeat = ownHum.SeatPart
				local ok, result = pcall(function()
					weld.Attachment0 = nil
					task.wait(tbl14.MethodTiming.LockPrepare)
					if flag11 or not (weld.Parent and root.Parent and hum.Parent and hum.Health > 0 and blob == parent) then return false end
					ownHum.Sit = false
					-- Continue as soon as the seat releases, never wait a full fixed 0.45s.
					local deadline = os.clock() + tbl14.MethodTiming.LockSeatMax
					while ownHum.SeatPart and os.clock() < deadline and not flag11 do task.wait(tbl14.MethodTiming.LockPoll) end
					if flag11 or not (weld.Parent and root.Parent and attachment.Parent == root
						and hum.Parent and hum.Health > 0 and blob.Parent) or ownHum.SeatPart then return false end
					weld.Attachment0 = attachment
					return weld.Attachment0 == attachment
				end)
				if ok and result then return true end
			if weld.Parent and weld.Attachment0 == nil then pcall(function() weld.Attachment0 = previous end) end
			if oldSeat and oldSeat.Parent and not oldSeat.Occupant and not ownHum.SeatPart
				and ownHum.Parent and ownHum.Health > 0 then
				pcall(oldSeat.Sit, oldSeat, ownHum)
			end
			return tbl14.MethodFailure("Lock", player, ok and "target/Blobman changed during Lock" or result)
			end

			tbl14.Follow = function(player, loopKey)
			local existing = followStates[player]
			if existing and existing.active then
				local _, currentRoot = tbl12.Char(player)
				if currentRoot == existing.root and existing.root.Parent then
					-- Loop callbacks re-enter this function; one task per target only.
					if loopKey then
						existing.loopKey = loopKey
						existing.generation = tbl10.LoopTokens[loopKey]
					end
					return true
				end
				existing.active = false
			end
			local ownRoot, ownHum, char, root, hum = tbl14.MethodTarget("Follow", player)
				if not ownRoot or not tbl14.MethodAcquire("Follow", player, root) then return false end
				local blob = parent
				local state = { active = true, loopKey = loopKey,
					generation = loopKey and tbl10.LoopTokens[loopKey], root = root }
				followStates[player] = state
			task.spawn(function()
					local ok, err = pcall(function()
						local lastTeleport = -math.huge
						while state.active and not flag11 and tbl9.BlobMethod == "Follow"
							and player.Parent and not tbl12.IsProtectedPlayer(player)
							and parent == blob and blob.Parent and ownRoot.Parent and ownHum.Parent and ownHum.Health > 0
							and char.Parent and root.Parent and hum.Parent and hum.Health > 0
							and select(2, tbl12.Char(player)) == root and tbl12.IsNetworkOwner(root)
							and (not state.loopKey or (tbl8[state.loopKey] and tbl10.LoopTokens[state.loopKey] == state.generation
								and (state.loopKey ~= "LoopApplyMethod" or tbl7.SelectedPlayersBlob[player]))) do
							if tbl12.GetMagnitude(root, ownRoot) > 50 and os.clock() - lastTeleport >= tbl14.MethodTiming.FollowTeleport then
							lastTeleport = os.clock()
							tbl12.Teleport(root, ownRoot, CFrame.new(0, 10, 0))
						end
							hum.WalkToPoint = ownRoot.Position
							task.wait(tbl14.MethodTiming.FollowStep)
						end
					end)
					if not ok then tbl14.MethodFailure("Follow", player, err) end
					state.active = false
					if followStates[player] == state then followStates[player] = nil end
				end)
				return true
			end
		end

		tbl14.LoopKickStates = setmetatable({}, { __mode = "k" })
		tbl14.StopLoopKick = function(player)
			for target, state in pairs(tbl14.LoopKickStates) do
				if not player or target == player then
					state.active = false
					if player then tbl14.LoopKickStates[target] = nil end
				end
			end
		end

		tbl14.LoopKick = function(player, loopKey)
			if flag11 or not player or player == localPlayer or tbl12.IsProtectedPlayer(player) then return false end
			local existing = tbl14.LoopKickStates[player]
			if existing and existing.active then return true end
			if existing then existing.active = false end
			local ownChar, ownRoot, ownHum = tbl12.Char()
			if not (ownRoot and ownRoot.Parent and ownHum and ownHum.Health > 0 and ownHum.SeatPart) then return false end
			local char, root, hum = tbl12.Char(player)
			local rootAttachment = root and root:FindFirstChild("RootAttachment")
			if not (char and char.Parent and root and root.Parent and hum and hum.Parent and hum.Health > 0
				and rootAttachment and not (root.AssemblyRootPart or root).Massless) then return false end
			local firePlayerPart = root:FindFirstChild("FirePlayerPart")
			local weldConstraint = firePlayerPart and firePlayerPart:FindFirstChild("WeldConstraint")
			if not (firePlayerPart and weldConstraint and weldConstraint.Enabled) then return false end
			local parts = tbl14.GetBlobmanComponents()
			local releaseSelected = tbl9.BKMethod == 2
			local finishRemote
			if parts then
				finishRemote = releaseSelected and parts.CreatureRelease or (not releaseSelected and parts.CreatureDrop or nil)
			end
			if not (parts and parts.CreatureGrab and finishRemote and parts.RightWeld and parts.RightOri
				and parts.Blobman and parts.Blobman.Parent and ownHum.SeatPart.Parent == parts.Blobman) then return false end

			-- KOZMOZ FIX: kozmoz used to run this loop with fixed slow waits
			-- (0.10 + 0.03 + 0.03 + 0.055 ~= 0.12 s per cycle), which felt much
			-- slower than reso's one-frame loop. The waits are now divided by a
			-- Kick Speed factor (default 8 = reso speed, 1 = very safe / slow).
			local kickSpeed = 8
			pcall(function()
				if tbl9.BKDelayMode == "Normal" then
					kickSpeed = 4
				elseif options and options.BlobKickSpeed and options.BlobKickSpeed.Value then
					kickSpeed = tonumber(options.BlobKickSpeed.Value) or 8
				end
			end)
			local kickMult = math.clamp(kickSpeed, 1, 10) / 4
			local function kwait(base)
				return task.wait((base or 0) / kickMult)
			end

			-- KOZMOZ: png 2 mantigi. "Faster but worse" = hizli ama daha az guvenli:
			-- ekstra network-owner pulse'lari her turda yapilir. "Normal" = yavas ama
			-- oturakli: ekstra pulse yok, sadece ana sahiplik alma kalir.
			local extraOwner = tbl8.NetworkOwnerInKick or tbl9.BKDelayMode ~= "Normal"

			local originalBlob = parts.Blobman
			local savedWeldEnabled = parts.RightWeld.Enabled
			local savedOriEnabled = parts.RightOri.Enabled
			local temporary = {}
			local alignPos
			local state = { active = true, loopKey = loopKey, epoch = tbl10.Epoch,
				generation = loopKey and tbl10.LoopTokens[loopKey] or nil }
			tbl14.LoopKickStates[player] = state
			local ran = false
			local function live()
				if not (state.active and not flag11 and tbl9.BlobMethod == "Kick"
					and player.Parent and not tbl12.IsProtectedPlayer(player)
					and player.Character == char and char.Parent and root.Parent and hum.Parent and hum.Health > 0
					and ownRoot.Parent and ownHum.Parent and ownHum.Health > 0
					and parent == originalBlob and originalBlob.Parent) then return false end
				if loopKey then
					return tbl8[loopKey] == true and tbl10.LoopTokens[loopKey] == state.generation
						and tbl10.Epoch == state.epoch and tbl7.SelectedPlayersBlob[player] == true
				end
				return tbl8.LoopApplyMethod == true and tbl7.SelectedPlayersBlob[player] == true and tbl10.Epoch == state.epoch
			end
			local ok, err = pcall(function()
				parts.RightWeld.Enabled = false
				parts.RightOri.Enabled = false
				-- Basic ownership check remains on even when Net Owner Spam is off.
				if not (tbl12.SNO(root, 0.38 / kickMult) or tbl14.Release(player, 0.38 / kickMult)) then return end
				if not live() then return end
				hum.Sit = true
				task.delay(0.5, function()
					if not flag11 and hum.Parent and player.Character == char then pcall(function() hum.Sit = false end) end
				end)
				local function kickCFrame()
					return ownRoot.CFrame * CFrame.new(options.BlobKickX.Value, options.BlobKickY.Value, options.BlobKickZ.Value)
				end
				local cf = kickCFrame()
				tbl12.Teleport(root, cf)
				local pos, ori = tbl12.CreateAlign(root, true)
				alignPos = pos
				if pos then
					temporary[#temporary + 1] = pos
					if pos.Attachment0 then temporary[#temporary + 1] = pos.Attachment0 end
					pos.Position = cf.Position
				end
				if ori then
					temporary[#temporary + 1] = ori
					if ori.Attachment0 and ori.Attachment0 ~= (pos and pos.Attachment0) then
						temporary[#temporary + 1] = ori.Attachment0
					end
				end
				task.wait(tbl14.KickTiming.SelectedPrep)
				if not live() then return end
				local lastExtraOwner = -math.huge
				local lastSticky = -math.huge
				if tbl9.BKMethod == 1 and extraOwner then
					pcall(tbl12.Grab, root)
					pcall(tbl12.RNO, root)
					lastExtraOwner = os.clock()
				end
				if parts.CreatureDrop then
					parts.CreatureDrop:FireServer(parts.RightWeld)
					if parts.LeftWeld then parts.CreatureDrop:FireServer(parts.LeftWeld) end
				end
				kwait(tbl14.KickTiming.SelectedFirstDrop)
				if not live() then return end
				rootAttachment.Parent = char
				ran = true
				while live() and tbl12.GetMagnitude(ownRoot, root) <= 41 and not hum.SeatPart and ownHum.Sit do
					task.spawn(function()
						if not live() then return end
						pcall(function()
							hum.RequiresNeck = false
							tbl12.ToggleMotor6D(char, false, true)
							tbl12.RepositionLimbs(char)
						end)
					end)
					task.spawn(function() if live() then pcall(tbl12.ToggleCollisions, char, false) end end)
					parts.RightOri.Enabled = false
					parts.RightWeld.Enabled = false
					parts.RightOri.Attachment0 = nil
					parts.RightWeld.Attachment0 = nil
					if alignPos and alignPos.Parent then alignPos.Position = kickCFrame().Position end
					tbl12.ResetVelocity(root)
					if tbl8.DeleteShurInBlobK and os.clock() - lastSticky >= tbl14.KickTiming.Sticky then
						lastSticky = os.clock()
						task.spawn(function() if live() then pcall(tbl12.RemoveSticky, char) end end)
					end
					if tbl9.BKMethod == 1 then
						parts.CreatureGrab:FireServer(nil, root, parts.RightWeld)
						kwait(tbl14.KickTiming.SelectedFirstDrop)
						if not live() then break end
						parts.CreatureDrop:FireServer(parts.RightWeld)
						if parts.LeftWeld then parts.CreatureDrop:FireServer(parts.LeftWeld) end
						-- Grab-Drop: birakma sonrasi ragdoll YOK -> dongu en hizli halinde kalir.
						kwait(tbl14.KickTiming.SelectedFirstDrop)
						-- KOZMOZ: "Net Owner Spam" artik gercekten spam: her turda
						-- sahiplik zorlanir (0.15 s beklemek yok), boylece kick kaymaz.
						if extraOwner then
							lastExtraOwner = os.clock()
							pcall(tbl12.Grab, root)
							pcall(tbl12.RNO, root)
						end
					else
						parts.CreatureGrab:FireServer(nil, root, parts.RightWeld)
						kwait(tbl14.KickTiming.SelectedFirstDrop)
						if not live() then break end
						parts.CreatureRelease:FireServer(parts.RightWeld)
						-- Grab-Release: ragdoll + sahiplik ayni anda; adam yigilir ve kacmaz.
						task.spawn(function() if live() then pcall(tbl12.Ragdoll, char) end end)
						pcall(tbl12.Grab, root)
						pcall(tbl12.RNO, root)
						lastExtraOwner = os.clock()
					end
					kwait(tbl14.KickTiming.SelectedRound)
				end
			end)
			state.active = false
			if tbl14.LoopKickStates[player] == state then tbl14.LoopKickStates[player] = nil end
			pcall(function()
				if rootAttachment.Parent == char then
					if root.Parent then rootAttachment.Parent = root else rootAttachment:Destroy() end
				end
			end)
			if ran and char.Parent then
				task.spawn(function() pcall(tbl12.ToggleMotor6D, char, true) end)
				task.spawn(function() pcall(tbl12.ToggleCollisions, char, true) end)
			end
			for _, object in ipairs(temporary) do
				pcall(function() if object and object.Parent then object:Destroy() end end)
			end
			if parent == originalBlob and originalBlob.Parent then
				pcall(function()
					local a0 = parts.RightWeld.Attachment0
					if a0 and (a0:IsDescendantOf(char) or a0:IsDescendantOf(ownChar)) then parts.RightWeld.Attachment0 = nil end
					parts.RightWeld.Enabled = savedWeldEnabled
				end)
				pcall(function() parts.RightOri.Enabled = savedOriEnabled end)
			end
			if not ok then
				warn("[BLOBMAN LoopKick] stopped after error; temporary parts restored: " .. tostring(err))
				return false
			end
			return ran
		end

		tbl14.LoopLock = function(player, loopKey)
			local ownRoot, ownHum, _, root, hum = tbl14.MethodTarget("Loop Lock", player)
			if not ownRoot then return false end
			local parts = tbl14.GetBlobmanComponents()
			local grab = parts and parts.CreatureGrab
			local release = parts and parts.CreatureRelease
			local weld = parts and parts.LeftWeld
			if not (grab and release and weld and weld.Parent) then
				return tbl14.MethodFailure("Loop Lock", player, "left grab/release/weld missing")
			end
			if root.Massless and not hum.SeatPart then
				return tbl14.MethodFailure("Loop Lock", player, "massless target")
			end
			if not tbl14.MethodAcquire("Loop Lock", player, root) then return false end
			local blob = parent
			local generation = tbl10.LoopTokens[loopKey]
			local originalEnabled = weld.Enabled
			local bodyPosition
			local ok, err = pcall(function()
				tbl12.Teleport(root, ownRoot, CFrame.new(0, 0, -5))
				bodyPosition = Instance.new("BodyPosition")
				bodyPosition.Name = "BlobLockBP"
				bodyPosition.MaxForce = Vector3.new(1e6, 1e6, 1e6)
				bodyPosition.D = 250
				bodyPosition.Position = (ownRoot.CFrame * CFrame.new(0, 0, -5)).Position
				bodyPosition.Parent = root
				tbl12.ResetVelocity(root)
				weld.Enabled = false
				while not flag11 and player.Parent and root.Parent and hum.Parent and hum.Health > 0
					and ownRoot.Parent and ownHum.Parent and ownHum.Health > 0
					and tbl8[loopKey] and tbl10.LoopTokens[loopKey] == generation
					and parent == blob and blob.Parent and tbl9.BlobMethod == "Lock"
					and (loopKey ~= "LoopApplyMethod" or tbl7.SelectedPlayersBlob[player])
					and tbl12.GetMagnitude(ownRoot, root) < 45 do
					bodyPosition.Position = (ownRoot.CFrame * CFrame.new(0, 0, -5)).Position
					tbl12.ResetVelocity(root)
					grab:FireServer(nil, root, weld)
					task.wait(tbl14.MethodTiming.LoopLockStep)
					if flag11 or not (weld.Parent and tbl8[loopKey] and root.Parent) then break end
					release:FireServer(weld)
					task.wait(tbl14.MethodTiming.LoopLockStep)
				end
			end)
			if bodyPosition then pcall(bodyPosition.Destroy, bodyPosition) end
			if weld.Parent and parent == blob then pcall(function() weld.Enabled = originalEnabled end) end
			if not ok then return tbl14.MethodFailure("Loop Lock", player, err) end
			return true
		end

		tbl12.NormalizeServerHopServer = function(arg)
			if typeof(arg) ~= "table" then
				return
			end
			local id = arg.Id or arg.id
			local num = tonumber(arg.Playing or arg.playing)
			local num2 = tonumber(arg.MaxPlayers or arg.maxPlayers)
			if type(id) ~= "string" or not num or not num2 or num2 <= 0 then
				return
			end

			return {
				Id = id,
				Playing = math.max(0, num),
				MaxPlayers = num2,
				Ping = tonumber(arg.Ping or arg.ping),
				FPS = tonumber(arg.FPS or arg.fps),
			}
		end

		tbl12.IsServerHopCandidate = function(arg, arg2)
			if arg.Id == jobId or tbl7.ServerHop.Rejected[arg.Id] then
				return false
			end

			if arg2 and not arg2[arg.Id] then
				return false
			end
			local n36 = math.min(tbl9.ServerHopMinPlayers, tbl9.ServerHopMaxPlayers)
			local n37 = math.max(tbl9.ServerHopMinPlayers, tbl9.ServerHopMaxPlayers)
			if arg.Playing < n36 or arg.Playing > n37 then
				return false
			end

			if not tbl8.ServerHopIncludeFull and arg.Playing >= arg.MaxPlayers then
				return false
			end
			return true
		end

		--==== KOZMOZ: SERVER-HOP CACHE ARTIK DISKTE DEGIL BELLEKTE ====--
		-- Eskiden KozmozServerHop_<placeId>.json yaziliyordu (her sunucu taramasinda).
		-- Artik cache sadece bellekte tutulur: diske tek bayt yazilmaz.
		tbl12.LoadServerHopCache = function()
			local cached = tbl7.ServerHop.MemoryCache
			if typeof(cached) ~= "table" or cached.PlaceId ~= placeId then
				return {}, nil, false, {}
			end
			local tbl16 = {}
			local tbl17 = {}
			for _, server in ipairs(cached.Servers or {}) do
				local v23 = tbl12.NormalizeServerHopServer(server)
				if v23 and v23.Id ~= jobId then
					tbl16[#tbl16 + 1] = v23
				end
			end
			for k, region in pairs(cached.Regions or {}) do
				if type(k) == "string" and typeof(region) == "table" then
					tbl17[k] = {}
					for k2, v24 in pairs(region) do
						if type(k2) == "string" and v24 == true then
							tbl17[k][k2] = true
						end
					end
				end
			end
			local n36 = tonumber(cached.CachedAt) or 0
			local n37 = os.time() - n36
			return tbl16, n36, n37 >= 0 and n37 <= 120, tbl17
		end

		tbl12.SaveServerHopCache = function(arg, arg2)
			tbl7.ServerHop.LastCacheError = nil
			tbl7.ServerHop.MemoryCache = {
				PlaceId = placeId,
				CachedAt = arg2 or os.time(),
				Servers = arg,
				Regions = tbl7.ServerHop.CachedRegions,
			}
			return true
		end

		tbl12.FetchServerHopPage = function(arg, arg2, arg3)
			local str5 = arg3 or "Roblox"
			local ok, result = pcall(game.HttpGet, game, arg, true)
			if not ok then
				return nil, tostring(result)
			end

			if type(result) ~= "string" or result == "" then
				return nil, str5 .. " returned an empty response"
			end
			local ok2, result2 = pcall(HttpService.JSONDecode, HttpService, result)
			if not ok2 or typeof(result2) ~= "table" then
				return nil, str5 .. " returned an invalid JSON response"
			end

			if arg2 and typeof(result2[arg2]) ~= "table" then
				local errors = result2.errors and result2.errors[1]
				local str6

				if errors then
					str6 = tostring(errors.message)
				else
					str6 = str5 .. " returned no server data"
				end

				return nil, str6
			end

			return result2
		end

		tbl12.GetServerHopContinent = function(arg)
			if type(arg) ~= "string" then
				return
			end
			local str5 = " " .. arg:upper() .. " "

			for _, regionName in ipairs(tbl7.ServerHop.RegionNames) do
				local v22 = tbl7.ServerHop.ContinentCountries[regionName]
				if v22 and v22:find(str5, 1, true) then
					return regionName
				end
			end
		end

		tbl12.RefreshServerHopRegions = function()
			local list, v22 = tbl12.FetchServerHopPage("https://apis.rovalra.com/v1/datacenters/list", nil, "RoValra")
			if not list then
				return false, v22
			end
			local serverHop = tbl7.ServerHop
			local regionNames = tbl7.ServerHop.RegionNames
			local tbl16 = {}
			local regions = {}

			for i = 2, #regionNames do
				regions[regionNames[i]] = {}
			end

			for _, v23 in ipairs(list) do
				local location = v23.location
				local country = location and location.country
				local city = location and location.city
				local str5

				if type(country) == "string" then
					str5 = country:upper()
				else
					str5 = nil
				end

				local str6 = str5 and city and str5 .. "\0" .. city
				local v24 = tbl12.GetServerHopContinent(str5)

				if v23.inactive ~= true and str6 and v24 and not tbl16[str6] then
					tbl16[str6] = true

					regions[v24][#regions[v24] + 1] = {
						Country = str5,
						City = city,
						Latitude = tonumber(location.latLong and location.latLong[1]),
						Longitude = tonumber(location.latLong and location.latLong[2]),
					}
				end
			end

			if not next(tbl16) then
				return false, "RoValra returned no active datacenters"
			end
			serverHop.Regions = regions
			serverHop.AutomaticCountry = nil
			serverHop.PlayerCoordinates = nil
			table.clear(serverHop.ResolvedRegions)
			return true
		end

		tbl12.GetServerHopPlayerCoordinates = function()
			local serverHop = tbl7.ServerHop
			local LocalizationService = game:GetService("LocalizationService")
			local ok, result = pcall(LocalizationService.GetCountryRegionForPlayerAsync, LocalizationService, localPlayer)
			if not ok or type(result) ~= "string" or result == "" then
				return
			end
			local automaticCountry = result:upper()
			if serverHop.AutomaticCountry == automaticCountry then
				local playerCoordinates = serverHop.PlayerCoordinates
				return playerCoordinates and playerCoordinates.X, playerCoordinates and playerCoordinates.Y, automaticCountry
			end
			local match = nil
			local v22 = nil

			for _, v23 in ipairs({
				"https://cdn.jsdelivr.net/gh/google/dspl@master/samples/google/canonical/countries.csv",
				"https://raw.githubusercontent.com/google/dspl/master/samples/google/canonical/countries.csv",
			}) do
				local ok2, result2 = pcall(game.HttpGet, game, v23, true)

				if ok2 and type(result2) == "string" then
					match, v22 = result2:match("\n" .. automaticCountry .. ",([%d%.%-]+),([%d%.%-]+),")
					if not match then
						continue
					end
				else
					continue
				end

				break
