			local seat = hum and hum.SeatPart
			if seat and seat.Parent and seat.Parent.Name == "CreatureBlobman" then
				parent = seat.Parent
				local parts = tbl14.GetBlobmanComponents()
				if parts and parts.Blobman == seat.Parent and parts.CreatureGrab then return true end
			else
				-- A cached model without its seated humanoid is not a ready Blobman.
				parent = nil
			end
			local ok, err = pcall(tbl14.Sit)
			if not ok then warn("[KOZMOZ] Blobman sit failed: " .. tostring(err)) end
			local deadline = os.clock() + tbl14.MethodTiming.SitConfirm
			repeat
				local _, _, currentHum = tbl12.Char()
				local currentSeat = currentHum and currentHum.SeatPart
				if currentSeat and currentSeat.Parent and currentSeat.Parent.Name == "CreatureBlobman" then
					parent = currentSeat.Parent
					local parts = tbl14.GetBlobmanComponents()
					if parts and parts.Blobman == currentSeat.Parent and parts.CreatureGrab then return true end
				end
				task.wait(tbl14.MethodTiming.SitPoll)
			until flag11 or os.clock() >= deadline
			fn18("Could not sit in CreatureBlobman. Spawn one or use Auto Sit Blobman, then retry.", "Blobman")
			return false
		end

