		-- KOZMOZ USER FEATURE: "Auto Anti Explosion" - the instant a bomb goes off next to you
		-- the Anti Explosion switch is flipped on AND that same explosion is blocked, so you
		-- never have to react in time yourself. After the hold time the switch is handed back
		-- (hold 0 leaves it on). Anything you touch by hand is never reverted.
		local autoAE = { token = 0, ours = false, onAt = 0, manualAt = 0 }
		tbl12.AutoAntiExplosion = autoAE

		task.spawn(function()
			-- watch the switch so a manual flip is never undone by the auto revert
			for _ = 1, 200 do
				local toggle = toggles and toggles.AntiExplosion
				if toggle and toggle.OnChanged then
					local previous = toggle.Changed
					toggle:OnChanged(function(value)
						if previous then
							previous(value)
						end

						if not autoAE.ours then
							autoAE.manualAt = os.clock()
						end
					end)
					return
				end
				task.wait(0.1)
			end
		end)

		workspace.ChildAdded:Connect(function(child)
			if flag11 or not tbl8.AutoAntiExplosion then
				return
			end

			if not explosionPartNear(child) then
				return
			end

			local toggle = toggles and toggles.AntiExplosion
			local hold = tonumber(tbl9.AutoAntiExplosionHold) or 7

			local function scheduleRevert()
				if not toggle or hold <= 0 then
					return
				end

				autoAE.token += 1
				local token = autoAE.token
				task.delay(hold, function()
					if flag11 or token ~= autoAE.token or autoAE.manualAt > autoAE.onAt then
						return
					end

					if toggle.Value == true then
						autoAE.ours = true
						pcall(function()
							toggle:SetValue(false)
						end)
						autoAE.ours = false
					end
				end)
			end

			if tbl8.AntiExplosion then
				-- the switch is already on and this bomb was just handled by the guard above.
				-- if WE are the one who turned it on, push the hand-back to the last explosion
				-- instead of dropping the shield in the middle of a bomb spam.
				if autoAE.onAt > autoAE.manualAt then
					scheduleRevert()
				end

				return
			end

			if toggle then
				autoAE.ours = true
				pcall(function()
					toggle:SetValue(true)
				end)
				autoAE.ours = false
				autoAE.onAt = os.clock()
			end

			-- the bomb is exploding right now: block it, don't wait for the switch to propagate
			guardExplosionPart()
			scheduleRevert()
		end)

