		tbl12.SetupManualSlotClick = function()
			local cooldown = {}
			local conn = UserInputService.InputBegan:Connect(function(input, processed)
				if flag11 or tbl8.AutoSlot or input.UserInputType ~= Enum.UserInputType.MouseButton1 then return end
				local main = lib.Window and lib.Window.MainFrame
				if processed and main and main.Visible
					and lib:MouseIsOverFrame(main, UserInputService:GetMouseLocation()) then return end
				local slots = workspace:FindFirstChild("Slots")
				local target = localPlayer:GetMouse().Target
				if not (slots and target and target:IsDescendantOf(slots)) then return end
				local slotHandle = target:FindFirstAncestor("SlotHandle")
				local machine = slotHandle and slotHandle.Parent
				local handle = slotHandle and slotHandle:FindFirstChild("Handle")
				local screen = machine and machine:FindFirstChild("Screen")
				local gui = screen and screen:FindFirstChild("SlotGui")
				local frame = gui and gui:FindFirstChild("TimeLeftFrame")
				local timeText = frame and frame:FindFirstChild("TimeText")
				if not (handle and handle:IsA("BasePart") and timeText and timeText.Text == "0:00") then return end
				local now = os.clock()
				if cooldown[handle] and now - cooldown[handle] < 2 then return end
				cooldown[handle] = now
			task.delay(.6, function()
					if flag11 or tbl8.AutoSlot or not handle.Parent or not timeText.Parent or timeText.Text ~= "0:00" then return end
					pcall(tbl12.SNO, handle)
				end)
			end)
			lib:OnUnload(function() conn:Disconnect() end)
		end
