		-- KOZMOZ CREATOR / KOZMOZ USER OVERHEAD TAGS + CREATOR JOIN NOTIFICATION
		-- creator        -> KOZMOZ CREATOR (red + crown)
		-- other KOZMOZers -> KOZMOZ USER (gray)
		-- Everyone else gets NO tag at all: the tag only shows on people who run
		-- this script (the list below), so random players stay clean.
		do
			local KOZMOZ_CREATOR_ID = 10677987819
			local notifiedCreators = {}

			-- UserIds that count as KOZMOZ users (besides the creator).
			local KOZMOZ_USER_IDS = {
				[11959171342] = true,
			}

			local function IsKozmozCreator(player)
				if not player then return false end
				return player.UserId == KOZMOZ_CREATOR_ID or tostring(player.UserId) == "10677987819"
			end

			local function IsKozmozUser(player)
				if not player then return false end
				if tostring(player.UserId) == "11959171342" then return true end
				return KOZMOZ_USER_IDS[player.UserId] == true
			end

			local function CreateKozmozTag(char, player)
				if not char or not player then return end
				local head = char:FindFirstChild("Head") or char:WaitForChild("Head", 5)
				if not head then return end

				local isCreator = IsKozmozCreator(player)
				local isUser = (not isCreator) and IsKozmozUser(player)

				for _, nm in ipairs({ "KozmozCreatorOverheadTag", "KozmozUserOverheadTag" }) do
					local old = head:FindFirstChild(nm)
					if old then old:Destroy() end
				end

				-- plain players: no tag
				if not isCreator and not isUser then
					return
				end

				local bbg = Instance.new("BillboardGui")
				bbg.Name = isCreator and "KozmozCreatorOverheadTag" or "KozmozUserOverheadTag"
				bbg.Adornee = head
				bbg.Size = UDim2.fromOffset(280, 50)
				bbg.StudsOffset = Vector3.new(0, 3.2, 0)
				bbg.AlwaysOnTop = true
				bbg.ResetOnSpawn = false

				local holder = Instance.new("Frame")
				holder.Name = "TagHolder"
				holder.Size = UDim2.fromScale(1, 1)
				holder.BackgroundTransparency = 1
				holder.Parent = bbg

				local layout = Instance.new("UIListLayout")
				layout.FillDirection = Enum.FillDirection.Horizontal
				layout.HorizontalAlignment = Enum.HorizontalAlignment.Center
				layout.VerticalAlignment = Enum.VerticalAlignment.Center
				layout.Padding = UDim.new(0, 6)
				layout.Parent = holder

				if isCreator then
					local crownLabel = Instance.new("TextLabel")
					crownLabel.Name = "Crown"
					crownLabel.Text = "\u{1F451}"
					crownLabel.TextSize = 28
					crownLabel.Size = UDim2.fromOffset(32, 34)
					crownLabel.BackgroundTransparency = 1
					crownLabel.Parent = holder
				end

				local titleLabel = Instance.new("TextLabel")
				titleLabel.Name = "Title"
				titleLabel.Text = isCreator and "KOZMOZ CREATOR" or "KOZMOZ USER"
				-- creator: red | normal user: gray
				titleLabel.TextColor3 = isCreator and Color3.fromRGB(255, 35, 35) or Color3.fromRGB(170, 170, 170)
				titleLabel.Font = Enum.Font.FredokaOne
				titleLabel.TextSize = isCreator and 24 or 20
				titleLabel.Size = UDim2.fromOffset(200, 34)
				titleLabel.BackgroundTransparency = 1
				titleLabel.Parent = holder

				local stroke = Instance.new("UIStroke")
				stroke.Color = Color3.fromRGB(0, 0, 0)
				stroke.Thickness = 3
				stroke.Parent = titleLabel

				bbg.Parent = head
			end

			local function CheckAndNotifyPlayer(player)
				if not player then return end

				local isCreator = IsKozmozCreator(player)

				if isCreator and not notifiedCreators[player] then
					notifiedCreators[player] = true
					task.defer(function()
						pcall(function()
							lib:Notify({
								Title = "KOZMOZ",
								Description = "\u{1F451} Kozmoz Creator (" .. (player.DisplayName or player.Name) .. ") joined the game!",
								Time = 8,
								SoundId = n34,
								BigIcon = "rbxassetid://109796428128440",
								Volume = n35,
								IconColor = Color3.fromRGB(255, 160, 0),
							})
						end)
					end)
				end

				if player.Character then
					task.defer(CreateKozmozTag, player.Character, player)
				end

				lib:GiveSignal(player.CharacterAdded:Connect(function(char)
					task.defer(CreateKozmozTag, char, player)
