				local driftTrigger = 7
				local driftHold = 0.45
				local releaseAfter = 1.0
				if stab >= 2 then
					driftTrigger, driftHold, releaseAfter = 5, 0.3, 1.5
				elseif stab <= 0 then
					driftTrigger, driftHold, releaseAfter = 7, 0.45, 1.25
				end

				-- Constraints cannot reliably hold another player's part without ownership.
				-- The original Grab/SNO branch in the main loop keeps trying to
				-- acquire it; we never fire extra remotes from here (no remote spam).
				if not tbl12.IsNetworkOwner(root) then
					if state.active then
						kzKickClearAlign(state)
						state.cooldownUntil = now + 1
					end
					state.badSince = nil
					return false
				end
				local drift = (root.Position - targetPosition).Magnitude

				-- ADAPTIVE CATCH-UP: ankor kurulu degilken bile hedef cok kaydiysa
				-- (>= 9 stud, 0.25 sn) ankoru erkenden kur. v39'daki 0.45 sn ve
				-- 7 stud esigi buyuk hedeflerde gec kaliyordu.
				if not state.active then
					if drift >= driftTrigger + 2 then
						state.ownedSince = state.ownedSince or now
						if now - state.ownedSince >= driftHold * 0.55 then
							state.badSince = state.badSince or now
						end
					else
						state.ownedSince = nil
					end
				end

				if state.active then
					if not (state.anchor and state.anchor.Parent and state.alignPosition and state.alignPosition.Parent) then
						kzKickClearAlign(state)
						state.cooldownUntil = now + 1
						return false
					end
					state.anchor.CFrame = CFrame.new(targetPosition)
					if drift <= 3 then
						state.goodSince = state.goodSince or now
					elseif drift > 4 then
						state.goodSince = nil
					end
					-- KOZMOZ IMPROVE: "birak" suresi 1.25 -> 1.0 sn.
					-- Daha hizli birakir => daha az "havada kilitli" bug.
					if state.goodSince and now - state.goodSince >= releaseAfter then
						kzKickClearAlign(state)
						state.cooldownUntil = now + 2.5
						return false
					end
					return true
				end

				if drift <= driftTrigger or now < state.cooldownUntil then
					state.badSince = nil
					state.ownedSince = nil
					return false
				end
				state.badSince = state.badSince or now
				if now - state.badSince < driftHold then
					return false
				end

				-- Build a Kar-style anchored AlignPosition/AlignOrientation fallback.
				local ok = pcall(function()
					local anchor = Instance.new("Part")
					state.anchor = anchor
					anchor.Name = "KozmozKickHoldAnchor_" .. tostring(player.UserId)
					anchor.Size = Vector3.new(0.1, 0.1, 0.1)
					anchor.Anchored = true
					anchor.CanCollide = false
					anchor.CanTouch = false
					anchor.CanQuery = false
					anchor.Transparency = 1
					anchor.CFrame = CFrame.new(targetPosition)
					anchor.Parent = workspace
					state.rootAttachment = Instance.new("Attachment")
					state.rootAttachment.Name = "KozmozKickHoldRootAttachment"
					state.rootAttachment.Parent = root
					state.anchorAttachment = Instance.new("Attachment")
					state.anchorAttachment.Parent = anchor
					local ap = Instance.new("AlignPosition")
					state.alignPosition = ap
					ap.Name = "KozmozKickHoldAlignAP"
					ap.MaxForce = math.huge
					-- KOZMOZ IMPROVE: hedef cok uzaga kactiysa rijit mod (kacis yok),
					-- yakin hedefte yumusak mod (titreme / firlama yok).
					ap.MaxVelocity = (drift >= 20) and 3000 or 1000
					ap.Responsiveness = (drift >= 20) and 200 or 120
					ap.RigidityEnabled = false
					ap.Attachment0 = state.rootAttachment
					ap.Attachment1 = state.anchorAttachment
					local ao = Instance.new("AlignOrientation")
					state.alignOrientation = ao
					ao.Name = "KozmozKickHoldAlignAO"
					ao.MaxTorque = math.huge
					ao.Responsiveness = 200
					ao.RigidityEnabled = false
					ao.Attachment0 = state.rootAttachment
					ao.Attachment1 = state.anchorAttachment
					-- Remove the old constraints BEFORE enabling the new ones.
					kzKickDestroy(root:FindFirstChild("KickAP"))
					kzKickDestroy(root:FindFirstChild("KickAO"))
					ap.Parent = root
					ao.Parent = root
				end)
			if not ok then
				kzKickClearAlign(state)
				state.cooldownUntil = now + 2.5
				state.failCount = (state.failCount or 0) + 1
				-- KOZMOZ IMPROVE: art arda 4 kez kurulamazsa state'i tamamen
				-- sifirla; yarim kalmis attachment/ankor birikmesin.
				if state.failCount >= 4 then
					kzKickClearPlayer(player)
				end
				return false
			end
			state.active = true
			state.badSince = nil
			state.failCount = 0
			return true
			end

			-- EKI is one guarded attempt plus at most two timed retries per root.
			-- Keep state per player so a respawn cannot leave the old root modified.
			local kzEKIStates = setmetatable({}, { __mode = "k" })

			local function kzEKIClear(player)
				local state = kzEKIStates[player]
				if not state then return end
				kzEKIStates[player] = nil
				if state.tried and state.root and typeof(sethiddenproperty) == "function" then
					pcall(sethiddenproperty, state.root, "PhysicsRepRootPart", nil)
				end
			end

			local function kzEKIStep(player, root)
				local state = kzEKIStates[player]
				if state and state.root ~= root then
					kzEKIClear(player)
					state = nil
				end
				if not tbl8.EKI or typeof(sethiddenproperty) ~= "function"
					or not root or not root.Parent then
					kzEKIClear(player)
					return
				end
				if not state then
					state = { root = root, attempts = 0, ownedSince = nil, nextTry = 0 }
					kzEKIStates[player] = state
				end
				if not tbl12.IsNetworkOwner(root) then
					state.ownedSince = nil -- must own it continuously before touching physics state
					if state.applied then
						state.lostSince = state.lostSince or os.clock()
						if os.clock() - state.lostSince >= 1 then kzEKIClear(player) end
					end
					return
				end
				state.lostSince = nil
				local now = os.clock()
				state.ownedSince = state.ownedSince or now
				-- KOZMOZ IMPROVE: v39'da kok basina EN FAZLA 3 deneme vardi; uzun
				-- kick sirasinda (hedef 10+ sn havada) sahiplik bir kez kaybolunca
				-- bir daha asla uygulanmiyordu. Artik: en az 3 sn arayla, sinirsiz
				-- deneme; uygulanmissa sadece sahiplik kaybinda yeniden dener.
				if now - state.ownedSince < 0.6 or now < state.nextTry then
					return
				end
				if state.applied and now < (state.refreshAt or 0) then
					return
				end
				state.attempts += 1
				state.tried = true
				local ok = pcall(sethiddenproperty, root, "PhysicsRepRootPart", root)
				-- Verify when the executor exposes a working getter; otherwise pcall is
				-- the best available indication (not a server-side guarantee).
				if ok and typeof(gethiddenproperty) == "function" then
					local readOK, value = pcall(gethiddenproperty, root, "PhysicsRepRootPart")
					if readOK then ok = value == root end
				end
				if ok then
					state.applied = true
					-- KOZMOZ IMPROVE: 4 sn'de bir tazele (bazi durumlarda Roblox
					-- hidden property'yi kendisi sifirliyor).
					state.refreshAt = now + (tonumber(tbl9.KickRefreshAfter) or 4)
					state.nextTry = now + (tonumber(tbl9.KickAttemptGap) or 3)
				else
					state.nextTry = now + 1
				end
			end

			local function fn22(arg)
				if not arg then
						return
				end
				kzKickClearPlayer(arg)
				kzEKIClear(arg)
				local v22, v23, v24 = tbl12.Char(arg)

				if v23 then
					local kickAP = v23:FindFirstChild("KickAP")
					local kickAO = v23:FindFirstChild("KickAO")
					local weldHRP = v23:FindFirstChild("WeldHRP")

					if kickAP then
						kickAP:Destroy()
					end

					if kickAO then
						kickAO:Destroy()
					end

					if weldHRP and v24:FindFirstChild("Ragdolled") and v24.Ragdolled.Value then
						weldHRP.Enabled = true
					end

				end

				if v22 then
					task.spawn(tbl12.ToggleMotor6D, v22, true, true)
					task.spawn(tbl12.ToggleCollisions, v22, true)
				end
			end

			local function fn23(arg, arg2, arg3)
				local n36 = 6.2831853071795862 / arg3 * (arg2 - 1)
				local nkOffset = tbl9.NKOffset
				return arg.Position + Vector3.new(math.cos(n36) * 10 + (tbl9.KickHoldOffsetX or 0), nkOffset, math.sin(n36) * 10 + (tbl9.KickHoldOffsetZ or 0))
			end

			while task.wait() do
				if flag11 then
					for k in tbl16, nil, nil do
						fn22(k)
					end
					for k in pairs(kzEKIStates) do kzEKIClear(k) end
					return
				end

				if not tbl8.EKI then
					for k in pairs(kzEKIStates) do kzEKIClear(k) end
				end

				if not tbl8.LoopApplyMethodT then
					for k in tbl16, nil, nil do
						fn22(k)
						tbl16[k] = nil
					end

					if not tbl12.WaitForRuntimeToggle("LoopApplyMethodT") then
