						fn22(k)
						tbl16[k] = nil
					end
				end

				if not (not loopApplyMethodT or not targetMethods.Kick or inPlot.Value) then
					local v22, v23, v24 = tbl12.Char()

					if v23 and v24 and v24.Health > 0 then
						local tbl17 = {}

						for k in selectedPlayers, nil, nil do
							if k and k.Parent and k:IsA("Player") then
								table.insert(tbl17, k)
								tbl16[k] = true
							end
						end

						if #tbl17 ~= 0 then
							for i, v25 in ipairs(tbl17) do
								if v23 and v24 and v24.Health > 0 and not inPlot.Value then
									local v26, v27, v28 = tbl12.Char(v25)
									local torso = v26 and v26:FindFirstChild("Torso")

									if not (v27 and v28 and torso and v28.Health > 0) then
										fn22(v25)
									else
											-- KOZMOZ USER: cooperate with Spin when both Kick and Spin are selected
											local spinCoop = targetMethods.Spin == true and not tbl12.IsProtectedPlayer(v25)
											local spinPin = spinCoop and v27:FindFirstChild("KozmozSpinHold")
											local v29 = (spinPin and spinPin.Position) or fn23(v23, i, #tbl17)
											local kickAP = v27:FindFirstChild("KickAP")
											local kickAO = v27:FindFirstChild("KickAO")
											local kzUseAlign = kzKickHoldStep(v25, v27, v29, spinCoop)
											-- Re-read: fallback may have destroyed the old BodyMovers.
											if not kzUseAlign then
												kickAP = v27:FindFirstChild("KickAP")
												kickAO = v27:FindFirstChild("KickAO")
											end
