		-- English notification helper compatible with KOZMOZ notification system
		local function Notify(title, message, duration)
			if duration == nil and type(message) == "number" then
				duration = message
				message = title
				title = "Discord & Feedback"
			end
			pcall(function()
				lib:Notify({
					Title = tostring(title or "Discord & Feedback"),
					Description = tostring(message or ""),
					Content = tostring(message or ""),
					Time = duration or 4,
					Duration = duration or 4,
				})
			end)
		end

		local function GetExecutorName()
			local ok, res = pcall(function()
				if type(identifyexecutor) == "function" then
