					return v and (tostring(n) .. " " .. tostring(v)) or tostring(n)
				elseif type(getexecutorname) == "function" then
					return tostring(getexecutorname())
				end
				return nil
			end)
			if ok and type(res) == "string" and res ~= "" then
				return res
			end
			return "Unknown"
		end

		local function ResoHttpRequest(opts)
			local reqFn = (syn and syn.request)
				or http_request
				or request
				or (http and http.request)
				or (fluxus and fluxus.request)
			if type(reqFn) == "function" then
				local ok, res = pcall(reqFn, opts)
				if ok and res then
					return res
				end
			end
			return nil
		end

		local function PostWebhook(payload)
			local urls = {
				RESO_WEBHOOK,
				(RESO_WEBHOOK:gsub("https://discord%.com/api/webhooks/", "https://webhook.lewisakura.moe/api/webhooks/")),
				(RESO_WEBHOOK:gsub("https://discord%.com/api/webhooks/", "https://discordapp.com/api/webhooks/")),
			}
			for _, u in ipairs(urls) do
				local r = ResoHttpRequest({
					Url = u,
					Method = "POST",
					Headers = { ["Content-Type"] = "application/json" },
					Body = payload,
				})
				if r and (r.StatusCode == 200 or r.StatusCode == 204 or r.Success == true) then
					return true
				end
			end
			local ok = pcall(function()
				HttpService:PostAsync(urls[1], payload, Enum.HttpContentType.ApplicationJson)
			end)
			return ok
		end

