		-- ==================================================================
		-- 4. 10-MINUTE COOLDOWN & LIVE COUNTDOWN TIMER (Anti-Spam Persisted)
		-- ==================================================================
		-- KOZMOZ: DISKE YAZIM YOK. Cooldown artik dosyada degil bellekte tutulur
		-- (script yeniden acilirsa cooldown sifirlanir - kabul edilebilir).
		local COOLDOWN_KEY = "KozmozFeedbackCooldown"
		local kozFeedbackCooldownUntil = 0
		local function GetSavedCooldown()
			local rem = 0
			pcall(function()
				if true then
					local savedExpire = tonumber(kozFeedbackCooldownUntil)
					if savedExpire and savedExpire > os.time() then
						rem = savedExpire - os.time()
					end
				end
			end)
			pcall(function()
				local genvTime = getgenv and getgenv().KozmozNextFeedbackTime
				if genvTime and genvTime > tick() then
					rem = math.max(rem, math.ceil(genvTime - tick()))
				end
			end)
			return rem
		end

		local nextSendTime = tick() + GetSavedCooldown()
		local sending = false

		local function FormatTime(seconds)
			seconds = math.max(0, math.floor(seconds))
			return string.format("%02d:%02d", math.floor(seconds / 60), seconds % 60)
		end

		local function CooldownRemaining()
			return math.max(0, math.ceil(nextSendTime - tick()))
		end

		local wasCoolingDown = CooldownRemaining() > 0
		task.spawn(function()
			while container.Parent and not flag11 do
				task.wait(1)
				local remaining = CooldownRemaining()
				if remaining > 0 then
					if not sending then
						sendBtn.Text = "â³ Wait " .. FormatTime(remaining)
					end
					timerLbl.Text = "â³ Next message available in " .. FormatTime(remaining)
					timerLbl.TextColor3 = AXUM_TEXT_DARK
					wasCoolingDown = true
				else
					if not sending then
						sendBtn.Text = "Send Feedback"
					end
					timerLbl.Text = "âœ… Ready to send"
					timerLbl.TextColor3 = AXUM_ACCENT
					if wasCoolingDown then
						wasCoolingDown = false
						Notify("Feedback Ready", "Cooldown finished â€” you can now send a new message!", 3)
					end
				end
			end
		end)

		-- ==================================================================
		-- 5. SEND FEEDBACK (Webhook Embed with 10-Min Cooldown & Anti-Spam)
		-- ==================================================================
		sendBtn.MouseButton1Click:Connect(function()
			if sending then return end
			local remaining = CooldownRemaining()
			if remaining > 0 then
				Notify("Cooldown Active", "Please wait " .. FormatTime(remaining) .. " before sending another message.", 3)
				return
			end
			local textMsg = tostring(msgBox.Text or ""):gsub("^%s+", ""):gsub("%s+$", "")
			if #textMsg < 5 then
				Notify("Feedback", "Please enter a message of at least 5 characters!", 3)
				return
			end
			if textMsg:match("^(.)%1+$") and #textMsg > 4 then
				Notify("Feedback", "Please enter a meaningful message!", 3)
				return
			end
			sending = true
			sendBtn.Text = "Sending..."

			task.spawn(function()
				local payload = HttpService:JSONEncode({
					username = "KOZMOZ | Feedback",
					embeds = {{
						title = "ðŸ“© KOZMOZ â€” New Feedback",
						color = 55551,
						fields = {
							{
								name = "ðŸ‘¤ Player",
								value = string.format("**%s** (@%s)\n[Roblox Profile](https://www.roblox.com/users/%d/profile)", tostring(localPlayer.DisplayName), tostring(localPlayer.Name), localPlayer.UserId),
								inline = true,
							},
							{
								name = "ðŸ†” User Info",
								value = string.format("**User ID:** `%d`\n**Account Age:** `%d days`\n**Executor:** `%s`", localPlayer.UserId, localPlayer.AccountAge, GetExecutorName()),
								inline = true,
							},
							{
								name = "ðŸ’¬ Message",
								value = "```" .. textMsg:sub(1, 1000) .. "```",
								inline = false,
							},
							{
								name = "ðŸŒ Server Info",
								value = string.format("PlaceId: `%s` | JobId: `%s`", tostring(game.PlaceId), tostring(game.JobId)),
								inline = false,
							},
						},
						footer = { text = "KOZMOZ Feedback System" },
						timestamp = os.date("!%Y-%m-%dT%H:%M:%SZ"),
					}},
				})

				local okSend = PostWebhook(payload)
				sending = false
				if okSend then
					nextSendTime = tick() + SEND_COOLDOWN
					pcall(function()
						if getgenv then getgenv().KozmozNextFeedbackTime = nextSendTime end
						if type(writefile) == "function" then
							kozFeedbackCooldownUntil = os.time() + SEND_COOLDOWN
						end
					end)
					msgBox.Text = ""
					sendBtn.Text = "Sent! âœ“"
					Notify("Feedback Sent", "Your message has been sent successfully! Next message in 10 minutes.", 4)
				else
					sendBtn.Text = "Failed!"
					Notify("Feedback Error", "Failed to send message. HTTP request was blocked by executor.", 4)
					task.delay(2, function()
						if sendBtn and sendBtn.Parent and CooldownRemaining() <= 0 then
							sendBtn.Text = "Send Feedback"
						end
					end)
				end
			end)
		end)

		pcall(function() DiscordBox:Resize() end)
	end


