			-- Cosmetics Implementation (Headless & Korblox)
			local FakeCosmeticsEnabled = false
			local RespawnPersist = false
			local CosmeticChoice = "Both"

			local KORBLOX_MESH_ID = "101851696"
			local KORBLOX_TEX_ID = "101851254"
			local HEADLESS_MESH_ID = "134082579"

			local savedHeadData = nil
			local savedLegData = nil

			local function SnapshotCharacter()
				local char = localPlayer.Character
				if not char then return end

				local head = char:FindFirstChild("Head")
				if head and not savedHeadData then
					local meshObj = head:FindFirstChildOfClass("SpecialMesh")
					savedHeadData = {
						Transparency = head.Transparency,
						MeshScale = meshObj and meshObj.Scale or Vector3.new(1.25, 1.25, 1.25),
						Decals = {},
					}
					for _, d in ipairs(head:GetChildren()) do
						if d:IsA("Decal") then
							table.insert(savedHeadData.Decals, {
								Instance = d,
								Transparency = d.Transparency,
							})
						end
					end
				end

				if not savedLegData then
					savedLegData = {}
					-- KOZMOZ FIX: Korblox SOL bacaga uygulaniyor, snapshot da SOL bacagi
					-- kaydetmeli; aksi halde kapatinca sol bacak gorunmez kaliyordu.
					local rleg = char:FindFirstChild("Left Leg")
					if rleg then
						savedLegData.R6 = {
							Part = rleg,
							Transparency = rleg.Transparency,
						}
					else
						local rUp = char:FindFirstChild("LeftUpperLeg")
						local rLow = char:FindFirstChild("LeftLowerLeg")
						local rFoot = char:FindFirstChild("LeftFoot")
						savedLegData.R15 = {
							Parts = { rUp, rLow, rFoot },
							Transparencies = {
								rUp and rUp.Transparency or 0,
								rLow and rLow.Transparency or 0,
								rFoot and rFoot.Transparency or 0,
							},
						}
					end
				end
			end

			local function WearHeadless()
				local char = localPlayer.Character
				if not char then return end
				local head = char:FindFirstChild("Head")
				if not head then return end

				SnapshotCharacter()

				head.Transparency = 1
				head:SetAttribute("KozHeadlessApplied", true)
				for _, child in ipairs(head:GetChildren()) do
					if child:IsA("Decal") then
						child.Transparency = 1
					elseif child:IsA("SpecialMesh") and child.Name ~= "PhantomHeadlessMesh" then
						-- KOZMOZ v27: remember the real head scale so unload restores it exactly
						if typeof(child:GetAttribute("KozOrigScale")) ~= "Vector3" then
							child:SetAttribute("KozOrigScale", child.Scale)
						end
						child.Scale = Vector3.new(0.001, 0.001, 0.001)
					end
				end

				local headlessMesh = head:FindFirstChild("PhantomHeadlessMesh")
				if not headlessMesh then
					headlessMesh = Instance.new("SpecialMesh")
					headlessMesh.Name = "PhantomHeadlessMesh"
					headlessMesh.MeshType = Enum.MeshType.FileMesh
					headlessMesh.MeshId = "rbxassetid://" .. HEADLESS_MESH_ID
					headlessMesh.Scale = Vector3.new(0.001, 0.001, 0.001)
					headlessMesh.Parent = head
				end
			end

			-- KOZMOZ: gercek Korblox bacagi (Roblox "Korblox Deathspeaker Left Leg",
			-- asset 139607673). Eski halde sol bacak sadece gizleniyordu ve Strip
			-- sirasinda SAG bacak kaydedildigi icin sol ayak kalici olarak kayboluyordu.
			local KORBLOX_LEG_ASSET = "139607673"
			-- KOZMOZ FIX (image-57): "Korblox geliyor ama bacagim gorunmez olmuyor".
			-- Sebep: gercek sol bacak yalnizca bir kez Transparency = 1 yapiyordu.
			-- Oyunun ragdoll / respawn / limb-sync kodu bunu tekrar 0'a cekiyor ve
			-- LocalTransparencyModifier hic kullanilmadigi icin bacak yeniden
			-- gorunuyordu. Cozum: cok katmanli gizleme + hafif koruma dongusu.
			local kozKorblox = { applied = false, parts = {}, saved = {}, fake = nil, loop = nil, lastRebuild = 0, lastCheck = 0 }
			-- Ileri bildirim: koruma dongusu WearKorblox'u yeniden cagirabilsin.
			local WearKorblox

			local function kozKorbloxCollect(char)
				local parts = {}
				local r6 = char:FindFirstChild("Left Leg")
				if r6 and r6:IsA("BasePart") then
					table.insert(parts, r6)
				else
					for _, n in ipairs({ "LeftUpperLeg", "LeftLowerLeg", "LeftFoot" }) do
						local p = char:FindFirstChild(n)
						if p and p:IsA("BasePart") then table.insert(parts, p) end
					end
				end
				return parts
			end

			local function kozKorbloxHideNow()
				for _, part in ipairs(kozKorblox.parts) do
					if part and part.Parent then
						if part.Transparency < 1 then pcall(function() part.Transparency = 1 end) end
						if part.LocalTransparencyModifier < 1 then pcall(function() part.LocalTransparencyModifier = 1 end) end
						for _, child in ipairs(part:GetChildren()) do
							if (child:IsA("Decal") or child:IsA("Texture")) and child.Transparency < 1 then
								pcall(function() child.Transparency = 1 end)
							end
						end
					end
				end
			end

			local function kozKorbloxApply(char)
				if not char then return end
				local parts = kozKorbloxCollect(char)
				if #parts == 0 then return end

				-- Orijinal degerleri SADECE bir kez kaydet (ust uste binmesin).
				if not kozKorblox.applied then
					kozKorblox.parts = parts
					kozKorblox.saved = {}
					for i, part in ipairs(parts) do
						local rec = { part = part, transparency = part.Transparency, ltm = part.LocalTransparencyModifier, children = {} }
						for _, child in ipairs(part:GetChildren()) do
							if child:IsA("Decal") or child:IsA("Texture") then
								table.insert(rec.children, { inst = child, transparency = child.Transparency })
								child:SetAttribute("KozOrigTransparency", child.Transparency)
								child:SetAttribute("KozHiddenByKorblox", true)
							end
						end
						kozKorblox.saved[i] = rec
					end
					kozKorblox.applied = true
				else
					kozKorblox.parts = parts
				end

				kozKorbloxHideNow()

				-- Koruma dongusu: oyun bacagi geri acarsa aninda tekrar gizle.
				-- (Sadece 1-3 parca icin ucuz karsilastirma; FPS etkisi yok.)
				if not kozKorblox.loop then
					-- KOZMOZ FPS: her frame yerine ~30 Hz kontrol (yariya indirir)
					kozKorblox.loop = RunService.Heartbeat:Connect(function()
						if not kozKorblox.applied or flag11 then
							return
						end
						local now30 = os.clock()
						if now30 - (kozKorblox.lastCheck or 0) < 1 / 30 then
							return
						end
						kozKorblox.lastCheck = now30
						local char2 = localPlayer.Character
						if not char2 then return end

						-- Karakter degistiyse parca listesini tazele
						local first = kozKorblox.parts[1]
						if not first or not first.Parent or first.Parent ~= char2 then
							local newParts = kozKorbloxCollect(char2)
							if #newParts > 0 then
								kozKorblox.parts = newParts
								kozKorbloxHideNow()
							end
							return
						end

						for _, part in ipairs(kozKorblox.parts) do
							if part and part.Parent and (part.Transparency < 1 or part.LocalTransparencyModifier < 1) then
								kozKorbloxHideNow()
								break
							end
						end

						-- Sahte bacak oyun tarafindan silindiyse yeniden kur (1 sn'de en fazla 1 kez)
						local fake = kozKorblox.fake
						if (not fake or not fake.Parent) and os.clock() - kozKorblox.lastRebuild > 1 then
							kozKorblox.lastRebuild = os.clock()
							if type(WearKorblox) == "function" then
								pcall(WearKorblox)
							end
						end
					end)
				end
			end

			local function kozKorbloxStrip()
				for _, rec in ipairs(kozKorblox.saved) do
					local part = rec.part
					if part and part.Parent then
						pcall(function()
							part.Transparency = rec.transparency or 0
							part.LocalTransparencyModifier = rec.ltm or 0
						end)
					end
					for _, childRec in ipairs(rec.children) do
						local child = childRec.inst
						if child and child.Parent then
							pcall(function() child.Transparency = childRec.transparency or 0 end)
							pcall(function() child:SetAttribute("KozHiddenByKorblox", nil) end)
						end
					end
				end
				kozKorblox.applied = false
				kozKorblox.parts = {}
				kozKorblox.saved = {}
				if kozKorblox.loop then
					pcall(function() kozKorblox.loop:Disconnect() end)
					kozKorblox.loop = nil
				end
				kozKorblox.fake = nil
			end

			WearKorblox = function()
				local char = localPlayer.Character
				if not char then return end

				SnapshotCharacter()

				-- Sol bacak parcalari (R6: "Left Leg" / R15: LeftUpperLeg..LeftFoot)
				local leftParts = {}
				-- R6 govdesi varsa "Left Leg", yoksa R15 parcalari
				local r6Leg = char:FindFirstChild("Left Leg")
				if r6Leg then
					table.insert(leftParts, r6Leg)
				else
					for _, partName in ipairs({ "LeftUpperLeg", "LeftLowerLeg", "LeftFoot" }) do
						local part = char:FindFirstChild(partName)
						if part and part:IsA("BasePart") then table.insert(leftParts, part) end
					end
				end
				if #leftParts == 0 then return end

				-- Onceki denemeden kalan parca varsa temizle
				local existingLeg = char:FindFirstChild("PhantomKorbloxLeg")
				if existingLeg then existingLeg:Destroy() end

				-- KOZMOZ FIX (image-57): gercek bacak cok katmanli gizlenir:
				-- Transparency + LocalTransparencyModifier + decal/doku + oyun
				-- geri acarsa aninda tekrar gizleyen koruma dongusu.
				pcall(kozKorbloxApply, char)
				-- Korblox bacak modeli (sol bacaga weld'li, gercek mesh + doku)
				local basePart = leftParts[1]
				local fakeLeg = Instance.new("Part")
				fakeLeg.Name = "PhantomKorbloxLeg"
				-- KOZMOZ FIX (image-57): sahte bacak gercek bacagin TAM ustune
				-- oturuyordu -> z-fighting / "bacak hala gorunuyor" izlenimi.
				-- Boyut bir tik kucuk, CFrame hafif iceri alindi.
				fakeLeg.Size = basePart.Size * 0.985
				fakeLeg.CFrame = basePart.CFrame * CFrame.new(0, 0, -0.02)
				fakeLeg.Anchored = false
				fakeLeg.CanCollide = false
				fakeLeg.CanTouch = false
				fakeLeg.CanQuery = false
				fakeLeg.Massless = true
				fakeLeg.Transparency = 0
				fakeLeg.CastShadow = false
				fakeLeg.BrickColor = BrickColor.new("Really black")
				fakeLeg.Material = Enum.Material.Plastic
				fakeLeg.Parent = char

				local mesh = Instance.new("SpecialMesh")
				mesh.Name = "KorbloxMesh"
				mesh.MeshType = Enum.MeshType.FileMesh
				mesh.MeshId = "rbxassetid://" .. KORBLOX_MESH_ID
				mesh.TextureId = "rbxassetid://" .. KORBLOX_TEX_ID
				mesh.Scale = Vector3.new(1, 1, 1)
				mesh.Parent = fakeLeg

				-- Gercek Korblox bacak asset referansi (gorsel dogrulama / komut dosyalari)
				local assetTag = Instance.new("StringValue")
				assetTag.Name = "KorbloxLegAssetId"
				assetTag.Value = KORBLOX_LEG_ASSET
				assetTag.Parent = fakeLeg

				kozKorblox.fake = fakeLeg

				local weld = Instance.new("WeldConstraint")
				weld.Part0 = basePart
				weld.Part1 = fakeLeg
				weld.Parent = fakeLeg
			end

			local function ApplyCosmetics()
				local char = localPlayer.Character
				if not char then return end
				if CosmeticChoice == "Headless" then
					WearHeadless()
				elseif CosmeticChoice == "Korblox" then
					WearKorblox()
				elseif CosmeticChoice == "Both" then
					WearHeadless()
					WearKorblox()
				end
			end

			local function StripCosmetics()
				local char = localPlayer.Character
				if not char then return end

				local head = char:FindFirstChild("Head")
				if head then
					local fakeMesh = head:FindFirstChild("PhantomHeadlessMesh")
					if fakeMesh then
						fakeMesh:Destroy()
					end

					-- KOZMOZ v27: only undo what Headless really changed (unload used to force every head mesh to 1.25 -> big head)
					local wasApplied = (savedHeadData ~= nil) or head:GetAttribute("KozHeadlessApplied") == true
					if savedHeadData then
						head.Transparency = savedHeadData.Transparency or 0
						for _, dInfo in ipairs(savedHeadData.Decals or {}) do
							if dInfo.Instance and dInfo.Instance.Parent == head then
								dInfo.Instance.Transparency = dInfo.Transparency or 0
							end
						end
					elseif wasApplied then
						head.Transparency = 0
						for _, d in ipairs(head:GetChildren()) do
							if d:IsA("Decal") then
								d.Transparency = 0
							end
						end
					end
					for _, d in ipairs(head:GetChildren()) do
						if d:IsA("SpecialMesh") then
							local orig = d:GetAttribute("KozOrigScale")
							if typeof(orig) == "Vector3" then
								d.Scale = orig
								d:SetAttribute("KozOrigScale", nil)
							elseif savedHeadData and savedHeadData.MeshScale and d.Scale.Magnitude < 0.01
								and savedHeadData.MeshScale.Magnitude >= 0.01 then
								d.Scale = savedHeadData.MeshScale
							end
						end
					end
					head:SetAttribute("KozHeadlessApplied", nil)
				end

				local fakeLeg = char:FindFirstChild("PhantomKorbloxLeg")
				local fakeLeg = char:FindFirstChild("PhantomKorbloxLeg")
				if fakeLeg then
					fakeLeg:Destroy()
				end

				-- KOZMOZ FIX (image-57): gizlemeyi KAYDEDILEN orijinal degerlerle geri al;
				-- LocalTransparencyModifier dahil (yoksa bacak gorunmez kaliyordu).
				if kozKorblox.applied or savedLegData ~= nil or fakeLeg ~= nil then
					pcall(kozKorbloxStrip)
				end

				savedHeadData = nil
				savedLegData = nil
			end

