			local RunService = game:GetService("RunService")
			local UIS = game:GetService("UserInputService")
			local Debris = game:GetService("Debris")

			local punchState = {
				activeAttack = nil, -- "punch_left", "punch_right", "kick_right", "kick_left"
				attackStart = 0,
				attackDuration = 0.38,
				lastAttackTime = 0,
			}

			local function CP_PunchOn()
				return toggles and toggles.PunchMode and toggles.PunchMode.Value
			end

			local function CP_KickOn()
				return toggles and toggles.KickEnabled and toggles.KickEnabled.Value
			end

			local function CP_LegOn(leg)
				if leg == "left" then
					return not toggles or not toggles.KickLeftLeg or toggles.KickLeftLeg.Value
				end
				return not toggles or not toggles.KickRightLeg or toggles.KickRightLeg.Value
			end

			local function CP_Active()
				return CP_PunchOn() or CP_KickOn()
			end

			local function CP_SetGrabbing(active)
				pcall(function()
					local char = localPlayer.Character
					local grabbingScript = char and char:FindFirstChild("GrabbingScript")
					if grabbingScript and grabbingScript:IsA("LocalScript") then
						grabbingScript.Enabled = not active
					end
					if not active then
						local torso = char and char:FindFirstChild("Torso")
						if torso then
							for _, jointName in ipairs({ "Right Shoulder", "Left Shoulder", "Right Hip", "Left Hip" }) do
								local joint = torso:FindFirstChild(jointName)
								if joint then
									joint.Transform = CFrame.new()
								end
							end
						end
					end
				end)
			end

			local CP_KickTrack = nil
			local CP_KickAnimator = nil

			local function CP_PlayKickAnimTrack()
				pcall(function()
					local char = localPlayer.Character
					local hum = char and char:FindFirstChildOfClass("Humanoid")
					local animator = hum and hum:FindFirstChildOfClass("Animator")
					if not animator then
						return
					end
					if CP_KickAnimator ~= animator or not CP_KickTrack then
						local anim = Instance.new("Animation")
						anim.Name = "KozmozKick"
						anim.AnimationId = "rbxassetid://2515090838"
						CP_KickTrack = animator:LoadAnimation(anim)
						CP_KickTrack.Priority = Enum.AnimationPriority.Action4
						CP_KickAnimator = animator
					end
					if CP_KickTrack and CP_KickTrack.Length > 0 then
						local duration = (options and options.PunchAnimSpeed and options.PunchAnimSpeed.Value) or 0.38
						local playbackSpeed = 1
						if duration > 0 then
							playbackSpeed = CP_KickTrack.Length / duration
						end
						CP_KickTrack:Play(0.05, 1, playbackSpeed)
					end
				end)
			end

			-- Clean any unwanted line/beam from character so png 1 line never appears
			local function CleanCharacterLines()
				pcall(function()
					local char = localPlayer.Character
					if not char then return end
					for _, part in ipairs({ char:FindFirstChild("Head"), char:FindFirstChild("Torso"), char:FindFirstChild("HumanoidRootPart") }) do
						if part then
							for _, child in ipairs(part:GetChildren()) do
								if child:IsA("Beam") or child.Name == "GrabBeam" or child.Name == "LineAttachment" then
									child:Destroy()
								end
							end
						end
					end
				end)
			end

			local function FindPunchTarget(maxReach, lookDir, rayOrigin)
				local myChar = localPlayer.Character
				local bestTarget = nil
				local bestDot = 0.30
				local bestDist = maxReach

				-- 1. Raycast for direct crosshair hit (players, clones, items)
				local rayParams = RaycastParams.new()
				rayParams.FilterType = Enum.RaycastFilterType.Exclude
				local filterList = {}
				if myChar then table.insert(filterList, myChar) end
				rayParams.FilterDescendantsInstances = filterList

				local rayResult = workspace:Raycast(rayOrigin, lookDir * (maxReach + 2.5), rayParams)
				if rayResult and rayResult.Instance then
					local hit = rayResult.Instance
					local charModel = hit:FindFirstAncestorOfClass("Model")
					local hum = charModel and charModel:FindFirstChildOfClass("Humanoid")
					local hrp = charModel and (charModel:FindFirstChild("HumanoidRootPart") or charModel:FindFirstChild("Torso") or charModel:FindFirstChildWhichIsA("BasePart"))

					if charModel and hum and hrp and charModel ~= myChar then
						local plr = Players:GetPlayerFromCharacter(charModel)
						if plr then
							return { type = "player", character = charModel, hrp = hrp, humanoid = hum, player = plr }
						else
							return { type = "clone", character = charModel, hrp = hrp, humanoid = hum }
						end
					elseif hit:IsA("BasePart") and not hit.Anchored and (not charModel or charModel ~= myChar) then
						local root = hit.AssemblyRootPart or hit
						return { type = "object", part = root }
					end
				end

				-- 2. Comprehensive search for all humanoid models in workspace (players and clones/NPCs)
				local searchedModels = {}
				if myChar then searchedModels[myChar] = true end

				local function checkCharCandidate(m, plrHint)
					if not (m and m:IsA("Model") and not searchedModels[m]) then
						return
					end
					searchedModels[m] = true
					local hum = m:FindFirstChildOfClass("Humanoid")
					if not hum then
						return
					end
					local root = m:FindFirstChild("HumanoidRootPart") or m:FindFirstChild("Torso") or m:FindFirstChildWhichIsA("BasePart")
					if root then
						local diff = root.Position - rayOrigin
						local dist = diff.Magnitude
						if dist > 1e-4 and dist <= bestDist then
							local dot = lookDir:Dot(diff.Unit)
							if dot > bestDot then
								bestDist = dist
								bestDot = dot
								local plr = plrHint or Players:GetPlayerFromCharacter(m)
								if plr then
									bestTarget = { type = "player", character = m, hrp = root, humanoid = hum, player = plr }
								else
									bestTarget = { type = "clone", character = m, hrp = root, humanoid = hum }
								end
							end
						end
					end
				end
				for _, p in ipairs(Players:GetPlayers()) do
					if p ~= localPlayer and p.Character then
						checkCharCandidate(p.Character, p)
					end
				end
				for _, child in ipairs(workspace:GetChildren()) do
					if child:IsA("Model") then
						checkCharCandidate(child, nil)
					end
				end

				-- 3. If no character found, check nearby unanchored objects / items / toys
				if not bestTarget then
					for _, item in ipairs(workspace:GetChildren()) do
						if item ~= myChar then
							local part = nil
							if item:IsA("BasePart") and not item.Anchored then
								part = item.AssemblyRootPart or item
							elseif item:IsA("Model") and not item:FindFirstChildOfClass("Humanoid") then
								local p = item.PrimaryPart or item:FindFirstChildWhichIsA("BasePart")
								if p and not p.Anchored then
									part = p.AssemblyRootPart or p
								end
							end

							if part and not part.Anchored then
								local diff = part.Position - rayOrigin
								local dist = diff.Magnitude
								if dist <= maxReach then
									local dot = lookDir:Dot(diff.Unit)
									if dot > 0.40 then
										return { type = "object", part = part }
									end
								end
							end
						end
					end
				end

				return bestTarget
			end

			local function ExecuteAttack(attackType, limb)
				if attackType == "punch" then
					if not CP_PunchOn() then
						return
					end
				elseif attackType == "kick" then
					if not CP_KickOn() then
						return
					end
					if not CP_LegOn(limb) then
						local otherLeg = (limb == "left") and "right" or "left"
						if CP_LegOn(otherLeg) then
							limb = otherLeg
						else
							return
						end
					end
				elseif not CP_Active() then
					return
				end
				local duration = (options and options.PunchAnimSpeed and options.PunchAnimSpeed.Value) or 0.38
				local now = os.clock()
				if now - punchState.lastAttackTime < (duration * 0.85) then return end

				punchState.activeAttack = attackType .. "_" .. limb
				punchState.attackStart = now
				punchState.attackDuration = duration
				punchState.lastAttackTime = now

				if attackType == "kick" then
					CP_PlayKickAnimTrack()
				end

				CleanCharacterLines()
				pcall(function()
					if tbl11 and tbl11.DestroyGrabLine then
						tbl11.DestroyGrabLine:FireServer()
					end
				end)

				-- Punch and kick sounds:
				-- Left: rbxassetid://109316755832781, Right: rbxassetid://139697578472716
				local soundId = (limb == "right") and "rbxassetid://139697578472716" or "rbxassetid://109316755832781"
				pcall(function()
					local s = Instance.new("Sound")
					s.SoundId = soundId
					s.Volume = (attackType == "kick") and 1.25 or 1.0
					s.PlaybackSpeed = (attackType == "kick") and 0.95 or 1.0
					s.Parent = workspace
					s:Play()
					Debris:AddItem(s, 2)
				end)

				local char = localPlayer.Character
				if not char then return end
				local myHrp = char:FindFirstChild("HumanoidRootPart") or char:FindFirstChild("Torso")
				if not myHrp then return end

				local cam = workspace.CurrentCamera
				local lookDir = cam and cam.CFrame.LookVector or myHrp.CFrame.LookVector
				local rayOrigin = cam and cam.CFrame.Position or (myHrp.Position + Vector3.new(0, 1.5, 0))
				-- Kick force and distance are the exact same as punch:
				local maxReach = (options and options.PunchReach and options.PunchReach.Value) or 12
				local force = (options and options.PunchForce and options.PunchForce.Value) or 70

				local target = FindPunchTarget(maxReach, lookDir, rayOrigin)

				if target then
					if target.type == "player" then
						local tHrp = target.hrp
						if force > 0 and tHrp then
							pcall(function()
								if tbl12.SNO and tbl12.SNO(tHrp) then
									tHrp.AssemblyLinearVelocity = lookDir * force + Vector3.new(0, math.max(16, force * 0.35), 0)
								end
							end)
						end

						task.spawn(function()
							if tbl11 and tbl11.RagdollRemote and tHrp then
								pcall(function() tbl11.RagdollRemote:FireServer(tHrp, 1.25) end)
								task.delay(1.25, function()
									pcall(function()
										if tbl11 and tbl11.RagdollRemote and tHrp and tHrp.Parent then
											tbl11.RagdollRemote:FireServer(tHrp, 0)
										end
									end)
								end)
							end
						end)

					elseif target.type == "clone" then
						local tHrp = target.hrp
						local tHum = target.humanoid
						local tChar = target.character
						local attackVel = lookDir * force + Vector3.new(0, math.max(18, force * 0.38), 0)

						task.spawn(function()
							pcall(function()
								if tbl12.SNO then tbl12.SNO(tHrp) end
							end)
							for _ = 1, 3 do
								pcall(function()
									if tHrp and tHrp.Parent then
										tHrp.AssemblyLinearVelocity = attackVel
										tHrp.Velocity = attackVel
									end
									if tChar then
										for _, p in ipairs(tChar:GetChildren()) do
											if p:IsA("BasePart") then
												p.AssemblyLinearVelocity = attackVel
												p.Velocity = attackVel
											end
										end
									end
								end)
								RunService.Heartbeat:Wait()
							end
						end)

						task.spawn(function()
							if tbl11 and tbl11.RagdollRemote and tHrp then
								pcall(function() tbl11.RagdollRemote:FireServer(tHrp, 1.25) end)
							end
							if tHum then
								pcall(function()
									tHum.Sit = true
									tHum:ChangeState(Enum.HumanoidStateType.Ragdoll)
								end)
							end
							task.delay(1.25, function()
								pcall(function()
									if tHum and tHum.Parent then
										tHum.Sit = false
										tHum:ChangeState(Enum.HumanoidStateType.GettingUp)
									end
									if tbl11 and tbl11.RagdollRemote and tHrp and tHrp.Parent then
										tbl11.RagdollRemote:FireServer(tHrp, 0)
									end
								end)
							end)
						end)

					elseif target.type == "object" then
						local root = target.part.AssemblyRootPart or target.part
						if root and not root.Anchored then
							pcall(function()
								if tbl12.SNO then tbl12.SNO(root) end
							end)
							pcall(function()
								root.AssemblyLinearVelocity = lookDir * (force * 1.5) + Vector3.new(0, math.max(20, force * 0.4), 0)
								root.AssemblyAngularVelocity = Vector3.new(math.random(-20, 20), math.random(-20, 20), math.random(-20, 20))
							end)
						end
					end
				end
			end

			local function ExecutePunch(arm)
				ExecuteAttack("punch", arm)
			end

			local function ExecuteKick(leg)
				ExecuteAttack("kick", leg or "right")
			end

			local function HandleAttackClick(button)
				if not CP_Active() then
					return
				end
				local mode = (options and options.AttackMode and options.AttackMode.Value) or "Left/Right Punch"
				local side = (button == "left") and "left" or "right"
				if mode == "Kick Only" then
					if CP_KickOn() then
						ExecuteKick(side)
					elseif CP_PunchOn() then
						ExecutePunch(side)
					end
				elseif mode == "Punch & Kick Combo" then
					if button == "left" then
						if CP_PunchOn() then
							ExecutePunch("left")
						elseif CP_KickOn() then
							ExecuteKick("left")
						end
					else
						if CP_KickOn() then
							ExecuteKick("right")
						elseif CP_PunchOn() then
							ExecutePunch("right")
						end
					end
				else
					if CP_PunchOn() then
						ExecutePunch(side)
					elseif CP_KickOn() then
						ExecuteKick(side)
					end
				end
			end
			-- Input connections (Mouse clicks, Middle click for Kick, and F hotkey for Kick)
			UIS.InputBegan:Connect(function(input, gameProcessed)
				if not CP_Active() then return end
				if input.UserInputType == Enum.UserInputType.MouseButton1 then
					HandleAttackClick("left")
				elseif input.UserInputType == Enum.UserInputType.MouseButton2 then
					HandleAttackClick("right")
				elseif input.UserInputType == Enum.UserInputType.MouseButton3 then
					ExecuteKick("right")
				elseif input.KeyCode == Enum.KeyCode.F then
					ExecuteKick("right")
				end
			end)

			local mouse = localPlayer:GetMouse()
			if mouse then
				mouse.Button1Down:Connect(function()
					HandleAttackClick("left")
				end)
				mouse.Button2Down:Connect(function()
					HandleAttackClick("right")
				end)
			end

			RunService.RenderStepped:Connect(function()
				-- KOZMOZ FPS: kontrol pesinde degilsek hicbir is yapma (erken cikis)
				if not CP_Active() then return end
				local char = localPlayer.Character
				if not char then return end
				local cam = workspace.CurrentCamera
				if not cam then return end
				local isFirstPerson = (cam.CFrame.Position - cam.Focus.Position).Magnitude < 1.5
				-- KOZMOZ FPS: birinci sahis degilse govde islemini atla
				if not isFirstPerson then return end

				do
					local lArm = char:FindFirstChild("Left Arm")
					local rArm = char:FindFirstChild("Right Arm")
					local lLeg = char:FindFirstChild("Left Leg")
					local rLeg = char:FindFirstChild("Right Leg")
					if lArm then lArm.LocalTransparencyModifier = 0 end
					if rArm then rArm.LocalTransparencyModifier = 0 end
					if lLeg then lLeg.LocalTransparencyModifier = 0 end
					if rLeg then rLeg.LocalTransparencyModifier = 0 end
					for _, limbName in ipairs({
						"LeftUpperArm", "LeftLowerArm", "LeftHand",
						"RightUpperArm", "RightLowerArm", "RightHand",
						"LeftUpperLeg", "LeftLowerLeg", "LeftFoot",
						"RightUpperLeg", "RightLowerLeg", "RightFoot"
					}) do
						local part = char:FindFirstChild(limbName)
						if part and part:IsA("BasePart") then
							part.LocalTransparencyModifier = 0
						end
					end
				end
			end)

			RunService.Stepped:Connect(function()
				-- KOZMOZ FPS: CP kapaliyken veya saldiri yokken motoru hic calistirma
				if not CP_Active() then return end
				if not punchState.activeAttack then return end
				local char = localPlayer.Character
				if not char then return end
				local torso = char:FindFirstChild("Torso")
				if not torso then return end

				local rShoulder = torso:FindFirstChild("Right Shoulder")
				local lShoulder = torso:FindFirstChild("Left Shoulder")
				local rHip = torso:FindFirstChild("Right Hip")
				local lHip = torso:FindFirstChild("Left Hip")
				if not (rShoulder and lShoulder) then return end

				local now = os.clock()
				local elapsed = now - punchState.attackStart
				local duration = punchState.attackDuration or 0.38
				local progress = 0
				local currentAttack = punchState.activeAttack
				if currentAttack and elapsed < duration then
					local t = elapsed / duration
					progress = math.sin(t * math.pi)
				else
					punchState.activeAttack = nil
					currentAttack = nil
				end

				local rGuardAngle = CFrame.Angles(math.rad(28), math.rad(-12), math.rad(72))
				local lGuardAngle = CFrame.Angles(math.rad(28), math.rad(12), math.rad(-72))

				local rPunchAngle = CFrame.new(0.6, 0, -0.35) * CFrame.Angles(math.rad(30), math.rad(-5), math.rad(88))
				local lPunchAngle = CFrame.new(-0.6, 0, -0.35) * CFrame.Angles(math.rad(30), math.rad(5), math.rad(-88))

				local rRecoilAngle = CFrame.new(-0.25, 0, 0.2) * CFrame.Angles(math.rad(36), math.rad(-22), math.rad(35))
				local lRecoilAngle = CFrame.new(0.25, 0, 0.2) * CFrame.Angles(math.rad(36), math.rad(22), math.rad(-35))

				-- Realistic martial arts high kick animation:
				local rKickAngle = CFrame.new(0, 0.45, -0.65) * CFrame.Angles(math.rad(12), math.rad(-8), math.rad(82))
				local lPlantAngle = CFrame.new(0, -0.08, 0.08) * CFrame.Angles(math.rad(-8), 0, 0)
				local rArmBalance = CFrame.Angles(math.rad(18), math.rad(-15), math.rad(40))
				local lArmGuard = CFrame.Angles(math.rad(32), math.rad(15), math.rad(-65))

				local lKickAngle = CFrame.new(0, 0.45, -0.65) * CFrame.Angles(math.rad(12), math.rad(8), math.rad(-82))
				local rPlantAngle = CFrame.new(0, -0.08, 0.08) * CFrame.Angles(math.rad(-8), 0, 0)
				local lArmBalance = CFrame.Angles(math.rad(18), math.rad(15), math.rad(-40))
				local rArmGuard = CFrame.Angles(math.rad(32), math.rad(-15), math.rad(65))

				if currentAttack == "punch_right" then
					rShoulder.Transform = rGuardAngle:Lerp(rPunchAngle, progress)
					lShoulder.Transform = lGuardAngle:Lerp(lRecoilAngle, progress)
					if rHip then rHip.Transform = CFrame.new() end
					if lHip then lHip.Transform = CFrame.new() end
				elseif currentAttack == "punch_left" then
					lShoulder.Transform = lGuardAngle:Lerp(lPunchAngle, progress)
					rShoulder.Transform = rGuardAngle:Lerp(rRecoilAngle, progress)
					if rHip then rHip.Transform = CFrame.new() end
					if lHip then lHip.Transform = CFrame.new() end
				elseif currentAttack == "kick_right" then
					if rHip then rHip.Transform = CFrame.new():Lerp(rKickAngle, progress) end
					if lHip then lHip.Transform = CFrame.new():Lerp(lPlantAngle, progress) end
					rShoulder.Transform = rGuardAngle:Lerp(rArmBalance, progress)
					lShoulder.Transform = lGuardAngle:Lerp(lArmGuard, progress)
				elseif currentAttack == "kick_left" then
					if lHip then lHip.Transform = CFrame.new():Lerp(lKickAngle, progress) end
					if rHip then rHip.Transform = CFrame.new():Lerp(rPlantAngle, progress) end
					lShoulder.Transform = lGuardAngle:Lerp(lArmBalance, progress)
					rShoulder.Transform = rGuardAngle:Lerp(rArmGuard, progress)
				else
					rShoulder.Transform = rGuardAngle
					lShoulder.Transform = lGuardAngle
					if rHip then rHip.Transform = CFrame.new() end
					if lHip then lHip.Transform = CFrame.new() end
				end
			end)

			CombatPunch:AddToggle("PunchMode", {
				Text = "Punch",
				Default = false,
				Tooltip = "Boxer guard stance + left/right click punches that ragdoll targets (no server kick)",
				Callback = function(val)
					if val then
						CleanCharacterLines()
					end
					CP_SetGrabbing(CP_Active())
				end,
			}):AddKeyPicker("PunchKey", {
				Text = "Punch",
				Default = nil,
				Mode = "Toggle",
				NoUI = false,
				SyncToggleState = true,
			})

			CombatPunch:AddToggle("KickEnabled", {
				Text = "Kick",
				Default = false,
				Tooltip = "Martial-arts kicks with the same range/power as punches (no server kick). Kick animation is FE - everyone can see it.",
				Callback = function(val)
					if val then
						CleanCharacterLines()
					end
					CP_SetGrabbing(CP_Active())
				end,
			}):AddKeyPicker("KickToggleKey", {
				Text = "Kick",
				Default = nil,
				Mode = "Toggle",
				NoUI = false,
				SyncToggleState = true,
			})

			CombatPunch:AddToggle("KickRightLeg", {
				Text = "Kick: Right Leg",
				Default = true,
				Tooltip = "Allow kicking with your right leg (F / middle-click / right-click in Kick Only mode)",
			}):AddKeyPicker("KickRightLegKey", { Text = "Kick: Right Leg", Mode = "Toggle", NoUI = true, SyncToggleState = true })

			CombatPunch:AddToggle("KickLeftLeg", {
				Text = "Kick: Left Leg",
				Default = true,
				Tooltip = "Allow kicking with your left leg (G / left-click in Kick Only mode)",
			}):AddKeyPicker("KickLeftLegKey", { Text = "Kick: Left Leg", Mode = "Toggle", NoUI = true, SyncToggleState = true })

			CombatPunch:AddLabel("Kick (Right Leg)"):AddKeyPicker("KickKey", {
				Text = "Right Kick Key",
				Default = "F",
				Mode = "Press",
				NoUI = false,
				Callback = function()
					if CP_KickOn() then
						ExecuteKick("right")
					end
				end,
			})

			CombatPunch:AddLabel("Kick (Left Leg)"):AddKeyPicker("LeftKickKey", {
				Text = "Left Kick Key",
				Default = "G",
				Mode = "Press",
				NoUI = false,
				Callback = function()
					if CP_KickOn() then
						ExecuteKick("left")
					end
				end,
			})

			CombatPunch:AddDropdown("AttackMode", {
				Values = { "Left/Right Punch", "Punch & Kick Combo", "Kick Only" },
				Default = 1,
				Multi = false,
				Text = "Click Mode",
			})

			CombatPunch:AddSlider("PunchReach", {
				Text = "Hit Range",
				Default = 12,
				Min = 4,
				Max = 35,
				Rounding = 0,
				Suffix = " studs",
				Compact = true,
			})

			CombatPunch:AddSlider("PunchForce", {
				Text = "Power",
				Default = 70,
				Min = 0,
				Max = 250,
				Rounding = 0,
				Compact = true,
			})

			CombatPunch:AddSlider("PunchAnimSpeed", {
				Text = "Animation Speed",
				Default = 0.38,
				Min = 0.2,
				Max = 0.7,
				Rounding = 2,
				Suffix = "s",
				Compact = true,
			})
		end
	end

	do
		local FunWeaponGroup = tbl15.Fun:AddLeftGroupbox("Weapon", "bow-arrow")
		local Players = game:GetService("Players")
		local RunService = game:GetService("RunService")
		local UIS = game:GetService("UserInputService")

		local FW = {
			Enabled = false,
			Selected = "NinjaKatana",
			Toy = nil,
			Root = nil,
			Sticky = nil,
			StickyWeld = nil,
			Parts = {},
			PartRels = {},
			RelBBoxRoot = CFrame.new(),
			RootToStickyRel = CFrame.new(),
			LongAxis = Vector3.new(1, 0, 0),
			UpAxis = Vector3.new(0, 1, 0),
			BladeSign = 1,
			LongLen = 3,
			Owned = false,
			Stuck = false,
			StickAccepted = false,
			StickBusy = false,
			StickInverse = false,
			LastGripSignature = "",
			Busy = false,
			Generation = 0,
			LastSpawnTry = 0,
			LastStickTry = 0,
			LastOwnerCheck = 0,
			SwingStart = 0,
			SwingDuration = 0.42,
			SwingType = nil,
			SwingSide = 1,
			LastSwing = 0,
		}
		local FW_HitBusy = setmetatable({}, { __mode = "k" })
		-- KOZMOZ: ayni kisiye kac kez vuruldu + son vurus zamani (2. kesiste kesin sonuc)
		local FW_HitCount = setmetatable({}, { __mode = "k" })
		local FW_HitAt = setmetatable({}, { __mode = "k" })
		local FW_FORCE_KILL_AT = 2 -- 2. vurus = kesin kill

		local function FW_Option(name, fallback)
			local opt = options and options[name]
			if opt and opt.Value ~= nil then
				return opt.Value
			end
			return fallback
		end

		local function FW_Range()
			local v = tonumber(FW_Option("FunWeaponRange", 20)) or 20
			-- KOZMOZ FIX: never let a broken/0 value disable every hit
			if v < 4 then v = 4 end
			return v
		end

		local function FW_MaxTargets()
			local v = tonumber(FW_Option("FunWeaponMaxTargets", 8)) or 8
			return math.clamp(math.floor(v), 1, 12)
		end

		local function FW_PosRight()
			return FW_Option("FunWeaponGripRight", 0)
		end

		local function FW_PosUp()
			return FW_Option("FunWeaponGripUp", 0)
		end

		local function FW_PosForward()
			return FW_Option("FunWeaponGripForward", 0)
		end

		local function FW_Yaw()
			return FW_Option("FunWeaponGripAngle", 0)
		end

		local function FW_Pitch()
			return FW_Option("FunWeaponGripPitch", 0)
		end

		local function FW_Roll()
			return FW_Option("FunWeaponGripRoll", 0)
		end

		local function FW_GripSignature()
			return string.format("%.3f|%.3f|%.3f|%.3f|%.3f|%.3f", FW_PosRight(), FW_PosUp(), FW_PosForward(), FW_Yaw(), FW_Pitch(), FW_Roll())
		end

		local function FW_MyChar()
			local char = localPlayer.Character
			local hrp = char and (char:FindFirstChild("HumanoidRootPart") or char:FindFirstChild("Torso"))
			local hum = char and char:FindFirstChildOfClass("Humanoid")
			return char, hrp, hum
		end

		local function FW_SetGrabbing(active)
			pcall(function()
				local char = localPlayer.Character
				local grabbingScript = char and char:FindFirstChild("GrabbingScript")
				if grabbingScript and grabbingScript:IsA("LocalScript") then
					if active then
						grabbingScript.Enabled = false
					else
						local cpActive = (toggles and toggles.PunchMode and toggles.PunchMode.Value) or (toggles and toggles.KickEnabled and toggles.KickEnabled.Value)
						if not cpActive then
							grabbingScript.Enabled = true
						end
					end
				end
			end)
		end

		local function FW_ResetShoulder()
			pcall(function()
				local cpActive = (toggles and toggles.PunchMode and toggles.PunchMode.Value) or (toggles and toggles.KickEnabled and toggles.KickEnabled.Value)
				if cpActive then
					return
				end
				local char = localPlayer.Character
				local torso = char and char:FindFirstChild("Torso")
				local shoulder = torso and torso:FindFirstChild("Right Shoulder")
				if shoulder then
					shoulder.Transform = CFrame.new()
				end
				local leftShoulder = torso and torso:FindFirstChild("Left Shoulder")
				if leftShoulder then
					leftShoulder.Transform = CFrame.new()
				end
			end)
		end

		local function FW_IsOwned(part)
			local targetPart = part or FW.Root
			if not targetPart then
				return false
			end
			local owned = false
			pcall(function()
				owned = (tbl12.IsPartOwner and tbl12.IsPartOwner(targetPart) == true) or false
			end)
			return owned
		end

		local function FW_ClearToyState()
			FW.Toy = nil
			FW.Root = nil
			FW.Sticky = nil
			FW.StickyWeld = nil
			FW.Parts = {}
			FW.PartRels = {}
			FW.Owned = false
			FW.Stuck = false
			FW.StickAccepted = false
			FW.LastGripSignature = ""
		end

		local function FW_DestroyToy()
			local toy = FW.Toy
			FW.Generation = FW.Generation + 1
			FW.Busy = false
			FW.StickBusy = false
			FW_ClearToyState()
			if toy and toy.Parent then
				pcall(function()
					tbl12.DestroyToy(toy)
				end)
			end
		end

		local function FW_MakeToyHarmless()
			pcall(function()
				local list = FW.Parts
				if FW.Toy and FW.Toy.Parent then
					list = FW.Toy:GetDescendants()
				end
				for _, part in ipairs(list) do
					if part and part:IsA("BasePart") and part.Parent then
						part.CanCollide = false
						part.CanTouch = false
						part.CanQuery = false
						part.Massless = true
					end
				end
			end)
		end

		local function FW_PrepareToy(model)
			if not model or not model:IsA("Model") then
				return false
			end
			local soundPart = model:FindFirstChild("SoundPart") or model:WaitForChild("SoundPart", 0.35)
			local sticky = model:FindFirstChild("StickyPart") or model:WaitForChild("StickyPart", 0.35) or model:FindFirstChild("StickyPart", true)
			if sticky and not sticky:IsA("BasePart") then
				sticky = nil
			end
			local root = soundPart or model.PrimaryPart or tbl12.FindNicePart(model) or model:FindFirstChildWhichIsA("BasePart", true)
			if not root then
				return false
			end
			local stickyWeld = nil
			if sticky then
				stickyWeld = sticky:FindFirstChild("StickyWeld") or sticky:WaitForChild("StickyWeld", 0.35)
			end
			local parts = {}
			for _, part in ipairs(model:GetDescendants()) do
				if part:IsA("BasePart") then
					table.insert(parts, part)
				end
			end
			if #parts == 0 then
				return false
			end
			local ok, bboxCF, bboxSize = pcall(function()
				return model:GetBoundingBox()
			end)
			if not ok or not bboxCF then
				bboxCF = root.CFrame
				bboxSize = root.Size
			end
			local dims = {
				{ Vector3.new(1, 0, 0), bboxSize.X },
				{ Vector3.new(0, 1, 0), bboxSize.Y },
				{ Vector3.new(0, 0, 1), bboxSize.Z },
			}
			table.sort(dims, function(a, b)
				return a[2] > b[2]
			end)
			local longAxis = dims[1][1]
			local longLen = math.max(dims[1][2], 1)
			local upAxis = Vector3.new(0, 1, 0)
			if longAxis == upAxis then
				upAxis = Vector3.new(0, 0, 1)
			end
			local sign = 1
			local stickyDot = nil
			if sticky then
				stickyDot = bboxCF:PointToObjectSpace(sticky.Position):Dot(longAxis)
			end
			if stickyDot and math.abs(stickyDot) > longLen * 0.12 then
				if stickyDot < 0 then
					sign = -1
				end
			else
				local rootLocal = bboxCF:PointToObjectSpace(root.Position)
				if rootLocal:Dot(longAxis) > 0 then
					sign = -1
				end
			end
			local rels = {}
			for _, part in ipairs(parts) do
				rels[part] = root.CFrame:ToObjectSpace(part.CFrame)
			end
			FW.Toy = model
			FW.Root = root
			FW.Sticky = sticky
			FW.StickyWeld = stickyWeld
			FW.Parts = parts
			FW.PartRels = rels
			FW.RelBBoxRoot = bboxCF:ToObjectSpace(root.CFrame)
			if sticky then
				FW.RootToStickyRel = root.CFrame:ToObjectSpace(sticky.CFrame)
			else
				FW.RootToStickyRel = CFrame.new()
			end
			FW.LongAxis = longAxis
			FW.UpAxis = upAxis
			FW.BladeSign = sign
			FW.LongLen = longLen
			FW.Owned = FW_IsOwned(root)
			FW.Stuck = false
			FW.StickAccepted = false
			FW.LastGripSignature = ""
			FW_MakeToyHarmless()
			return true
		end

		local function FW_Claim(model)
			local root = FW.Root
			local sticky = FW.Sticky
			if not root then
				return false
			end
			if FW_IsOwned(root) then
				FW.Owned = true
				return true
			end
			local setOwnerRemote = tbl11 and tbl11.SetNetworkOwner
			if not setOwnerRemote then
				local grabEvents = game:GetService("ReplicatedStorage"):FindFirstChild("GrabEvents")
				setOwnerRemote = grabEvents and grabEvents:FindFirstChild("SetNetworkOwner")
			end
			for _ = 1, 30 do
				if not FW.Enabled or FW.Toy ~= model or not model.Parent then
					return false
				end
				pcall(function()
					if setOwnerRemote then
						setOwnerRemote:FireServer(root, root.CFrame)
						if sticky and sticky ~= root then
							setOwnerRemote:FireServer(sticky, sticky.CFrame)
						end
					end
					if tbl12.Grab then
						tbl12.Grab(root)
						if sticky and sticky ~= root then
							tbl12.Grab(sticky)
						end
					end
				end)
				if FW_IsOwned(root) or (sticky and FW_IsOwned(sticky)) then
					FW.Owned = true
					return true
				end
				task.wait(0.05)
			end
			local claimed = false
			pcall(function()
				claimed = tbl12.SNO and tbl12.SNO(root, 0.8) == true
			end)
			if not claimed then
				claimed = FW_IsOwned(root)
			end
			FW.Owned = claimed
			return claimed
		end

		local function FW_GroundSpawnCFrame()
			local char, hrp = FW_MyChar()
			if not char or not hrp then
				return nil
			end
			local facing = hrp.CFrame.LookVector
			facing = Vector3.new(facing.X, 0, facing.Z)
			if facing.Magnitude < 0.01 then
				facing = Vector3.new(0, 0, -1)
			else
				facing = facing.Unit
			end
			local origin = hrp.Position + facing * 2.2 + Vector3.new(0, 2, 0)
			local rayParams = RaycastParams.new()
			rayParams.FilterType = Enum.RaycastFilterType.Exclude
			rayParams.FilterDescendantsInstances = { char }
			local hit = workspace:Raycast(origin, Vector3.new(0, -14, 0), rayParams)
			local pos
			if hit then
				pos = hit.Position + Vector3.new(0, 0.25, 0)
			else
				pos = hrp.Position + facing * 2.2 - Vector3.new(0, 2.7, 0)
			end
			return CFrame.new(pos, pos + facing)
		end

		local function FW_SpawnGround()
			if not tbl11 or not tbl11.SpawnToy then
				return nil
			end
			local canSpawn = localPlayer:FindFirstChild("CanSpawnToy")
			local t0 = os.clock()
			while FW.Enabled and canSpawn and canSpawn.Value == false and os.clock() - t0 < 5 do
				task.wait()
			end
			if not FW.Enabled then
				return nil
			end
			local inv = nil
			local plotInv = nil
			pcall(function()
				inv, plotInv = tbl12.GetInventory(localPlayer)
			end)
			if not inv then
				inv = workspace:FindFirstChild(localPlayer.Name .. "SpawnedInToys")
			end
			local spawned = nil
			local conns = {}
			local function watch(folder)
				if folder then
					table.insert(conns, folder.ChildAdded:Connect(function(child)
						if child.Name == FW.Selected then
							spawned = child
						end
					end))
				end
			end
			watch(inv)
			if plotInv and plotInv ~= inv then
				watch(plotInv)
			end
			local spawnCF = FW_GroundSpawnCFrame()
			if not spawnCF then
				for _, conn in ipairs(conns) do
					conn:Disconnect()
				end
				return nil
			end
			task.spawn(function()
				pcall(function()
					tbl11.SpawnToy:InvokeServer(FW.Selected, spawnCF, Vector3.zero)
				end)
			end)
			t0 = os.clock()
			while not spawned and FW.Enabled and os.clock() - t0 < 3 do
				if inv then
					spawned = inv:FindFirstChild(FW.Selected)
				end
				if not spawned and plotInv then
					spawned = plotInv:FindFirstChild(FW.Selected)
				end
				if not spawned then
					task.wait()
				end
			end
			for _, conn in ipairs(conns) do
				conn:Disconnect()
			end
			return spawned
		end

		local function FW_Acquire()
			if FW.Busy or not FW.Enabled then
				return
			end
			FW.Busy = true
			local gen = FW.Generation
			local function finish()
				if gen == FW.Generation then
					FW.Busy = false
				end
			end
			task.spawn(function()
				local inv = nil
				local plotInv = nil
				pcall(function()
					inv, plotInv = tbl12.GetInventory(localPlayer)
				end)
				if not inv then
					inv = workspace:FindFirstChild(localPlayer.Name .. "SpawnedInToys")
				end
				local model = (inv and inv:FindFirstChild(FW.Selected)) or (plotInv and plotInv:FindFirstChild(FW.Selected))
				local wasExisting = model ~= nil
				if not model and FW.Enabled and gen == FW.Generation then
					model = FW_SpawnGround()
				end
				if not model and FW.Enabled and gen == FW.Generation then
					pcall(function()
						local groundCF = FW_GroundSpawnCFrame()
						if groundCF then
							model = tbl12.SpawnToy(FW.Selected, CFrame.new(groundCF.Position - Vector3.new(0, 0, 20)), 1)
						else
							model = tbl12.SpawnToy(FW.Selected, nil, 1)
						end
					end)
				end
				if model and FW.Enabled and gen == FW.Generation and FW_PrepareToy(model) then
					if FW_Claim(model) then
						if FW.Enabled and gen == FW.Generation and FW.Toy == model then
							FW.LastStickTry = 0
						end
					elseif wasExisting and FW.Enabled and gen == FW.Generation and FW.Root then
						local _, myHrp = FW_MyChar()
						if myHrp and (FW.Root.Position - myHrp.Position).Magnitude > 25 then
							FW_DestroyToy()
						end
					end
				end
				finish()
			end)
		end

		local function FW_DesiredRootCFrame(arm, hrp)
			if not arm or not hrp then
				return nil, nil
			end
			local armRef = arm.CFrame
			local swingDelta = nil
			if FW.SwingType then
				pcall(function()
					local torso = arm.Parent and arm.Parent:FindFirstChild("Torso")
					local joint = torso and torso:FindFirstChild("Right Shoulder")
					if joint and joint:IsA("Motor6D") and joint.Part1 == arm then
						local restArm = torso.CFrame * joint.C0 * joint.C1:Inverse()
						swingDelta = arm.CFrame * restArm:Inverse()
						armRef = restArm
					end
				end)
			end
			local handPos = armRef * Vector3.new(0, -1, 0)
			local flatFacing = hrp.CFrame.LookVector
			flatFacing = Vector3.new(flatFacing.X, 0, flatFacing.Z)
			if flatFacing.Magnitude < 0.01 then
				flatFacing = Vector3.new(0, 0, -1)
			else
				flatFacing = flatFacing.Unit
			end
			local yawFacing = CFrame.Angles(0, math.rad(FW_Yaw()), 0) * flatFacing
			if yawFacing.Magnitude > 0.01 then
				yawFacing = yawFacing.Unit
			end
			local Right = yawFacing:Cross(Vector3.new(0, 1, 0))
			if Right.Magnitude < 0.01 then
				Right = Vector3.new(1, 0, 0)
			else
				Right = Right.Unit
			end
			local bladeDir = CFrame.fromAxisAngle(Right, math.rad(FW_Pitch())) * yawFacing
			if bladeDir.Magnitude > 0.01 then
				bladeDir = bladeDir.Unit
			end
			local upWorld = Vector3.new(0, 1, 0) - bladeDir * bladeDir.Y
			if upWorld.Magnitude < 0.05 then
				upWorld = Right
			else
				upWorld = upWorld.Unit
			end
			upWorld = CFrame.fromAxisAngle(bladeDir, math.rad(FW_Roll())) * upWorld
			local longWorld = bladeDir * FW.BladeSign
			local function axisIndex(v)
				if v.X == 1 then
					return 1
				elseif v.Y == 1 then
					return 2
				end
				return 3
			end
			local basis = {}
			basis[axisIndex(FW.LongAxis)] = longWorld
			basis[axisIndex(FW.UpAxis)] = upWorld
			if not basis[1] then
				basis[1] = basis[2]:Cross(basis[3])
			elseif not basis[2] then
				basis[2] = basis[3]:Cross(basis[1])
			else
				basis[3] = basis[1]:Cross(basis[2])
			end
			local center = handPos + bladeDir * (FW.LongLen * 0.5 - 0.35 + FW_PosForward()) + Right * FW_PosRight() + Vector3.new(0, 1, 0) * FW_PosUp()
			local desiredBBox = CFrame.fromMatrix(center, basis[1], basis[2], basis[3])
			if swingDelta then
				return swingDelta * (desiredBBox * FW.RelBBoxRoot), swingDelta * handPos
			end
			return desiredBBox * FW.RelBBoxRoot, handPos
		end

		local function FW_IsAssemblyWithCharacter()
			local char = localPlayer and localPlayer.Character
			if not char then
				return false
			end
			local same = false
			pcall(function()
				for _, part in ipairs({ FW.Root, FW.Sticky }) do
					local assemblyRoot = part and part.AssemblyRootPart
					if assemblyRoot and assemblyRoot:IsDescendantOf(char) then
						same = true
						return
					end
				end
			end)
			return same
		end

		local function FW_IsWeldedToCharacter()
			local char = localPlayer and localPlayer.Character
			if not char then
				return false
			end
			local welded = false
			pcall(function()
				local weld = FW.StickyWeld
				if not weld or not weld.Parent then
					weld = FW.Sticky and FW.Sticky:FindFirstChild("StickyWeld")
					FW.StickyWeld = weld
				end
				if weld and weld.Enabled ~= false and ((weld.Part0 and weld.Part0:IsDescendantOf(char)) or (weld.Part1 and weld.Part1:IsDescendantOf(char))) then
					welded = true
				end
			end)
			if welded then
				return true
			end
			return FW_IsAssemblyWithCharacter()
		end

		local function FW_ApplyLocalCFrame(desiredRoot, force)
			if not desiredRoot or (not FW.Owned and not force) or (FW_IsWeldedToCharacter() and not force) then
				return
			end
			pcall(function()
				for _, part in ipairs(FW.Parts) do
					local rel = FW.PartRels[part]
					if part.Parent and rel then
						part.CFrame = desiredRoot * rel
						part.AssemblyLinearVelocity = Vector3.zero
						part.AssemblyAngularVelocity = Vector3.zero
						part.Velocity = Vector3.zero
						part.RotVelocity = Vector3.zero
					end
				end
			end)
		end

		local function FW_WeldOk(arm)
			local weld = FW.StickyWeld
			if not weld or not weld.Parent then
				weld = FW.Sticky and FW.Sticky:FindFirstChild("StickyWeld")
				FW.StickyWeld = weld
			end
			if not weld or not arm then
				return false
			end
			local ok = false
			pcall(function()
				ok = weld.Part1 == arm and weld.Enabled ~= false
			end)
			return ok
		end

		local function FW_RotationError(a, b)
			local _, angle = (a.Rotation * b.Rotation:Inverse()):ToAxisAngle()
			return angle or 0
		end

		local function FW_AdjustGripLive(arm, desiredRoot)
			if not arm or not desiredRoot or not FW.Sticky then
				return false
			end
			local weld = FW.StickyWeld
			if not weld or not weld.Parent then
				weld = FW.Sticky:FindFirstChild("StickyWeld")
				FW.StickyWeld = weld
			end
			if not weld then
				return false
			end
			local adjusted = false
			pcall(function()
				local desiredSticky = desiredRoot * FW.RootToStickyRel
				if weld:IsA("WeldConstraint") then
					if weld.Part0 ~= arm and weld.Part1 ~= arm then
						return
					end
					weld.Enabled = false
					if FW_IsAssemblyWithCharacter() then
						return
					end
					FW_ApplyLocalCFrame(desiredRoot, true)
					weld.Enabled = true
					adjusted = true
				elseif weld:IsA("Motor6D") or weld:IsA("Weld") then
					if weld.Part1 == arm then
						weld.C1 = arm.CFrame:ToObjectSpace(desiredSticky * weld.C0)
						adjusted = true
					elseif weld.Part0 == arm then
						weld.C0 = arm.CFrame:ToObjectSpace(desiredSticky * weld.C1)
						adjusted = true
					end
				end
			end)
			return adjusted
		end

		local function FW_UnstickForRestick(arm)
			local weld = FW.StickyWeld
			if not weld or not weld.Parent then
				weld = FW.Sticky and FW.Sticky:FindFirstChild("StickyWeld")
				FW.StickyWeld = weld
			end
			if not weld then
				return
			end
			local wasWelded = false
			pcall(function()
				wasWelded = weld.Part0 == arm or weld.Part1 == arm
			end)
			if not wasWelded then
				return
			end
			pcall(function()
				if weld:IsA("WeldConstraint") then
					weld.Enabled = false
				end
			end)
			pcall(function()
				if tbl12.Grab then
					if FW.Root then
						tbl12.Grab(FW.Root)
					end
					if FW.Sticky and FW.Sticky ~= FW.Root then
						tbl12.Grab(FW.Sticky)
					end
				end
			end)
			local t0 = os.clock()
			while os.clock() - t0 < 0.3 do
				if not FW_IsWeldedToCharacter() then
					break
				end
				task.wait()
			end
			FW.Stuck = false
			FW.StickAccepted = false
		end

		local function FW_TryStick(arm, desiredRoot, useInverse, gen, model)
			local sticky = FW.Sticky
			if not sticky or not sticky.Parent or not arm or not desiredRoot then
				return false
			end
			local desiredSticky = desiredRoot * FW.RootToStickyRel
			local rel = arm.CFrame:ToObjectSpace(desiredSticky)
			local fireRel = rel
			if useInverse then
				fireRel = rel:Inverse()
			end
			FW_ApplyLocalCFrame(desiredRoot)
			local fired = false
			pcall(function()
				if tbl11 and tbl11.StickyPartEvent then
					tbl11.StickyPartEvent:FireServer(sticky, arm, fireRel)
					fired = true
				end
			end)
			if not fired then
				return false
			end
			local t0 = os.clock()
			while os.clock() - t0 < 0.45 do
				if not FW.Enabled or gen ~= FW.Generation or FW.Toy ~= model then
					return false
				end
				if FW_WeldOk(arm) then
					break
				end
				task.wait()
			end
			if not FW_WeldOk(arm) then
				return false
			end
			local actualRel = arm.CFrame:ToObjectSpace(sticky.CFrame)
			local posErr = (actualRel.Position - rel.Position).Magnitude
			local angErr = FW_RotationError(actualRel, rel)
			return posErr <= 2 and angErr <= 0.85
		end

		local function FW_StickNow()
			local model = FW.Toy
			local gen = FW.Generation
			if not model or not model.Parent then
				return false
			end
			if not FW.Owned and not FW_Claim(model) then
				return false
			end
			if not FW.Enabled or gen ~= FW.Generation or FW.Toy ~= model then
				return false
			end
			if not FW.Sticky then
				return FW.Owned
			end
			local char, hrp, hum = FW_MyChar()
			if not char or not hrp or not hum or hum.Health <= 0 then
				return false
			end
			local arm = char:FindFirstChild("Right Arm") or char:FindFirstChild("RightHand")
			if not arm then
				return false
			end
			if FW_WeldOk(arm) then
				FW_UnstickForRestick(arm)
				if not FW.Enabled or gen ~= FW.Generation or FW.Toy ~= model then
					return false
				end
			end
			local stickSig = FW_GripSignature()
			local desiredRoot = FW_DesiredRootCFrame(arm, hrp)
			if not desiredRoot then
				return false
			end
			local ok = FW_TryStick(arm, desiredRoot, FW.StickInverse, gen, model)
			if ok then
				FW.Stuck = true
				FW.HasStuckOnce = true
				FW_MakeToyHarmless()
				FW.StickAccepted = false
				FW.LastGripSignature = stickSig
				FW_SetGrabbing(true)
				return true
			end
			if not FW.Enabled or gen ~= FW.Generation or FW.Toy ~= model then
				return false
			end
			if not FW.HasStuckOnce then
				if FW_WeldOk(arm) then
					FW_UnstickForRestick(arm)
					if not FW.Enabled or gen ~= FW.Generation or FW.Toy ~= model then
						return false
					end
				end
				desiredRoot = FW_DesiredRootCFrame(arm, hrp)
				ok = desiredRoot and FW_TryStick(arm, desiredRoot, not FW.StickInverse, gen, model)
				if ok then
					FW.StickInverse = not FW.StickInverse
					FW.Stuck = true
					FW.HasStuckOnce = true
					FW_MakeToyHarmless()
					FW.StickAccepted = false
					FW.LastGripSignature = stickSig
					FW_SetGrabbing(true)
					return true
				end
				if not FW.Enabled or gen ~= FW.Generation or FW.Toy ~= model then
					return false
				end
			end
			if FW_WeldOk(arm) then
				FW.Stuck = true
				FW.HasStuckOnce = true
				FW_MakeToyHarmless()
				FW_SetGrabbing(true)
				local verified = false
				pcall(function()
					local freshRoot = FW_DesiredRootCFrame(arm, hrp)
					if freshRoot and FW.Sticky then
						local rel = arm.CFrame:ToObjectSpace(freshRoot * FW.RootToStickyRel)
						local actualRel = arm.CFrame:ToObjectSpace(FW.Sticky.CFrame)
						verified = (actualRel.Position - rel.Position).Magnitude <= 2 and FW_RotationError(actualRel, rel) <= 0.85
					end
				end)
				FW.StickAccepted = false
				if verified then
					FW.LastGripSignature = FW_GripSignature()
					return true
				end
				FW.LastStickTry = os.clock()
				return false
			end
			return false
		end

		local function FW_RequestStick()
			if FW.StickBusy or not FW.Enabled then
				return
			end
			FW.StickBusy = true
			task.spawn(function()
				pcall(FW_StickNow)
				FW.StickBusy = false
			end)
		end

		-- KOZMOZ FIX (FPS): "full" is passed in. The cheap part of the grip
		-- (writing the hand CFrame) still runs every frame so the weapon never
		-- lags behind, but the expensive part (ownership probes, weld checks and
		-- stick requests that fire remotes) now runs at ~20 Hz instead of 60 Hz.
		-- That is what used to make the game hitch while a weapon was held.
		local function FW_MaintainStep(full)
			local toy = FW.Toy
			local root = FW.Root
			if not toy or not toy.Parent or not root or not root.Parent then
				FW_ClearToyState()
				local now = os.clock()
				if now - FW.LastSpawnTry > 2 then
					FW.LastSpawnTry = now
					FW_Acquire()
				end
				return
			end
			local char, hrp, hum = FW_MyChar()
			if not char or not hrp or not hum or hum.Health <= 0 then
				return
			end
			local arm = char:FindFirstChild("Right Arm") or char:FindFirstChild("RightHand")
			if not arm then
				return
			end
			if not full then
				if FW.Owned then
					local cheapRoot = FW_DesiredRootCFrame(arm, hrp)
					if cheapRoot then
						FW_ApplyLocalCFrame(cheapRoot)
					end
				end
				return
			end
			local now = os.clock()
			if now - FW.LastOwnerCheck > 0.25 then
				FW.LastOwnerCheck = now
				FW.Owned = FW_IsOwned(root)
			end
			local desiredRoot = FW_DesiredRootCFrame(arm, hrp)
			local sig = FW_GripSignature()
			if sig ~= (FW.LastSeenGripSignature or "") then
				FW.LastSeenGripSignature = sig
				FW.LastGripChange = now
			end
			local gripDirty = sig ~= FW.LastGripSignature
			if gripDirty then
				FW.StickAccepted = false
			end
			if FW.Sticky then
				local weldOk = FW_WeldOk(arm)
				local rootFar = false
				if desiredRoot then
					rootFar = (root.Position - desiredRoot.Position).Magnitude > 9
				end
				if weldOk and not gripDirty and (FW.StickAccepted or not rootFar) then
					FW.Stuck = true
					return
				end
				if gripDirty and desiredRoot then
					FW_AdjustGripLive(arm, desiredRoot)
				end
				local settled = not gripDirty or (now - (FW.LastGripChange or 0) > 0.35)
				if (not weldOk or gripDirty or rootFar) and (settled or not FW.HasStuckOnce) and now - FW.LastStickTry > 0.75 then
					FW.LastStickTry = now
					FW.Stuck = false
					FW_RequestStick()
				end
			else
				if not FW.Owned and now - FW.LastStickTry > 0.75 then
					FW.LastStickTry = now
					FW_RequestStick()
				end
			end
			if FW.Owned and desiredRoot then
				FW_ApplyLocalCFrame(desiredRoot)
			end
		end

		-- KOZMOZ USER: per-weapon swing + per-weapon dismember profiles.
		-- Each weapon has its own swing (keyframed shoulder pose, interpolated by
		-- parameters so >180 deg wind-ups never take the short way round), its own
		-- hit timing and its own way of falling apart.
		local FWA = {
			Debris = game:GetService("Debris"),
			RemoteIds = { slash = "rbxassetid://129967390", lunge = "rbxassetid://129967478" },
			RemoteTracks = {},
			RemoteAnimator = nil,
			RemoteTrack = nil,
		}
		-- Cut = which limbs are removed (FE, same as Break Limbs), Style = how they fly.
		FWA.Profiles = {
			NinjaKatana = { Anim = "katana", Duration = 0.40, HitDelay = 0.18, Cooldown = 0.34, Cut = "All", Style = "slice", Remote = "slash", CorpseDelay = 1.5 },
			ToolCleaver = { Anim = "cleaver", Duration = 0.48, HitDelay = 0.25, Cooldown = 0.42, Cut = "Arms", Style = "chop", Remote = "slash", CorpseDelay = 1.6 },
			ToolDiggingForkRusty = { Anim = "fork", Duration = 0.44, HitDelay = 0.22, Cooldown = 0.40, Cut = "Legs", Style = "impale", Remote = "lunge", CorpseDelay = 1.6 },
			ToolPickaxe = { Anim = "pickaxe", Duration = 0.62, HitDelay = 0.37, Cooldown = 0.56, Cut = "All", Style = "smash", Remote = "slash", CorpseDelay = 1.4 },
		}
		FWA.Profile = function(name)
			return FWA.Profiles[name or FW.Selected] or FWA.Profiles.ToolCleaver
		end
		-- Keyframe = { t, sweep, raise, twist, tilt, forward, up, out, ease }
		-- raise: 0 arm down / 90 forward / 180 overhead. sweep: + across the body.
		-- forward/up/out: shoulder offset in studs (torso space, out = away from body).
		FWA.Anims = {
			katana = { R = {
				{ 0, 0, 0, 0, 0, 0, 0, 0 },
				{ 0.28, 5, 150, -30, 0, 0, 0.15, 0.1, "out" },
				{ 0.36, 3, 158, -30, -3, -0.05, 0.2, 0.1, "inout" },
				{ 0.52, 0, 50, 15, 5, 0.25, 0, 0, "in" },
				{ 0.66, 30, 25, 30, 0, 0.15, 0, 0, "out" },
				{ 1, 0, 0, 0, 0, 0, 0, 0, "inout" },
			} },
			katana_back = { R = {
				{ 0, 0, 0, 0, 0, 0, 0, 0 },
				{ 0.28, 5, 135, 30, -25, 0, 0.15, 0.1, "out" },
				{ 0.36, 5, 142, 30, -28, -0.05, 0.2, 0.1, "inout" },
				{ 0.52, 0, 45, 15, 10, 0.25, 0, 0, "in" },
				{ 0.66, -15, 15, -30, -15, 0.15, 0, 0.1, "out" },
				{ 1, 0, 0, 0, 0, 0, 0, 0, "inout" },
			} },
			cleaver = { Mirror = true, R = {
				{ 0, 0, 0, 0, 0, 0, 0, 0 },
				{ 0.34, 0, 155, 0, 0, -0.1, 0.2, 0, "out" },
				{ 0.42, 0, 162, 0, 0, -0.15, 0.25, 0, "inout" },
				{ 0.58, 0, 45, 0, 0, 0.2, -0.05, 0, "in" },
				{ 0.72, 5, 12, 0, 0, 0.15, -0.1, 0, "out" },
				{ 1, 0, 0, 0, 0, 0, 0, 0, "inout" },
			} },
			pickaxe = { Mirror = true, R = {
				{ 0, 0, 0, 0, 0, 0, 0, 0 },
				{ 0.40, -5, 185, 0, 0, -0.2, 0.3, 0, "out" },
				{ 0.50, -5, 192, 0, 2, -0.25, 0.35, 0, "inout" },
				{ 0.66, 10, 40, 0, 0, 0.25, -0.1, 0, "in" },
				{ 0.80, 5, -5, 0, 10, 0.2, -0.2, 0, "out" },
				{ 1, 0, 0, 0, 0, 0, 0, 0, "inout" },
			}, L = {
				{ 0, 0, 0, 0, 0, 0, 0, 0 },
				{ 0.40, 20, -175, 0, 0, -0.2, 0.3, 0, "out" },
				{ 0.50, 20, -180, 0, 0, -0.25, 0.35, 0, "inout" },
				{ 0.66, -20, -40, 0, 0, 0.25, -0.1, 0, "in" },
				{ 0.80, -25, 0, 0, 0, 0.2, -0.2, 0, "out" },
				{ 1, 0, 0, 0, 0, 0, 0, 0, "inout" },
			} },
			fork = { Mirror = true, R = {
				{ 0, 0, 0, 0, 0, 0, 0, 0 },
				{ 0.34, 5, 15, 0, 0, -0.55, 0.05, 0, "out" },
				{ 0.42, 5, 15, 0, 0, -0.6, 0.05, 0, "inout" },
				{ 0.54, 5, 30, 0, 0, 0.75, 0.1, -0.1, "in" },
				{ 0.70, 5, 28, 0, 0, 0.65, 0.1, -0.1, "out" },
				{ 1, 0, 0, 0, 0, 0, 0, 0, "inout" },
			}, L = {
				{ 0, 0, 0, 0, 0, 0, 0, 0 },
				{ 0.34, -55, -50, 0, 0, -0.4, 0, 0, "out" },
				{ 0.54, -35, -60, 0, 0, 0.6, 0.1, 0, "in" },
				{ 0.70, -35, -58, 0, 0, 0.5, 0.1, 0, "out" },
				{ 1, 0, 0, 0, 0, 0, 0, 0, "inout" },
			} },
		}
		FWA.Ease = function(kind, a)
			if kind == "out" then
				return 1 - (1 - a) * (1 - a)
			elseif kind == "in" then
				return a * a
			elseif kind == "inout" then
				return a * a * (3 - 2 * a)
			end
			return a
		end
		-- Parameter interpolation (not CFrame:Lerp) so a 0 -> 185 deg wind-up goes
		-- over the head instead of swinging backwards through the body.
		FWA.Sample = function(frames, t, mirror, left)
			if not frames or #frames == 0 then
				return nil
			end
			local a, b = frames[1], frames[#frames]
			for i = 1, #frames - 1 do
				if t >= frames[i][1] and t <= frames[i + 1][1] then
					a, b = frames[i], frames[i + 1]
					break
				end
			end
			local span = b[1] - a[1]
			local k = span > 0 and math.clamp((t - a[1]) / span, 0, 1) or 1
			k = FWA.Ease(b[9], k)
			local v = {}
			for i = 2, 8 do
				v[i] = a[i] + (b[i] - a[i]) * k
			end
			local s = mirror or 1
			local fwd = left and -v[6] or v[6]
			return CFrame.new(fwd, v[7], v[8] * s)
				* CFrame.Angles(math.rad(v[5] * s), 0, 0)
				* CFrame.Angles(0, math.rad(v[2] * s), 0)
				* CFrame.Angles(0, 0, math.rad(v[3]))
				* CFrame.Angles(0, math.rad(v[4] * s), 0)
		end
		-- FE layer: Roblox's own R6 tool slash / lunge animations replicate to every
		-- client (Shoulder.Transform does not). Locally the per-weapon pose overrides it.
		FWA.PlayRemote = function(kind, duration)
			pcall(function()
				local char = localPlayer.Character
				local hum = char and char:FindFirstChildOfClass("Humanoid")
				local animator = hum and (hum:FindFirstChildOfClass("Animator") or hum:WaitForChild("Animator", 0.2))
				local id = FWA.RemoteIds[kind]
				if not (animator and id) then
					return
				end
				if FWA.RemoteAnimator ~= animator then
					FWA.RemoteAnimator = animator
					FWA.RemoteTracks = {}
				end
				local track = FWA.RemoteTracks[kind]
				if not track then
					local anim = Instance.new("Animation")
					anim.AnimationId = id
					track = animator:LoadAnimation(anim)
					track.Priority = Enum.AnimationPriority.Action4
					track.Looped = false
					FWA.RemoteTracks[kind] = track
				end
				if FWA.RemoteTrack and FWA.RemoteTrack ~= track and FWA.RemoteTrack.IsPlaying then
					FWA.RemoteTrack:Stop(0.05)
				end
				FWA.RemoteTrack = track
				local speed = 1
				if track.Length and track.Length > 0 and duration and duration > 0 then
					speed = math.clamp(track.Length / duration, 0.5, 4)
				end
				track:Play(0.05, 1, speed)
			end)
		end
		FWA.StopRemote = function()
			pcall(function()
				if FWA.RemoteTrack and FWA.RemoteTrack.IsPlaying then
					FWA.RemoteTrack:Stop(0.1)
				end
			end)
		end

		-- Local gore (only you see these): flying copies of the cut limbs + blood.
		FWA.SpawnGib = function(limb, velocity, spin)
			pcall(function()
				if not (limb and limb.Parent and limb:IsA("BasePart")) or limb.Transparency >= 1 then
					return
				end
				local gib = Instance.new("Part")
				gib.Name = "KozmozWeaponGib"
				gib.Size = limb.Size
				gib.CFrame = limb.CFrame
				gib.Color = limb.Color
				gib.Material = limb.Material
				gib.Transparency = limb.Transparency
				gib.TopSurface = Enum.SurfaceType.Smooth
				gib.BottomSurface = Enum.SurfaceType.Smooth
				gib.Anchored = false
				gib.CanCollide = true
				gib.CanTouch = false
				gib.CanQuery = false
				for _, child in ipairs(limb:GetChildren()) do
					if child:IsA("DataModelMesh") or child:IsA("Decal") then
						pcall(function()
							child:Clone().Parent = gib
						end)
					end
				end
				local stump = Instance.new("Part")
				stump.Name = "Stump"
				stump.Size = Vector3.new(limb.Size.X * 0.92, 0.12, limb.Size.Z * 0.92)
				stump.Color = Color3.fromRGB(120, 0, 0)
				stump.Material = Enum.Material.SmoothPlastic
				stump.CanCollide = false
				stump.CanTouch = false
				stump.CanQuery = false
				stump.Massless = true
				stump.CFrame = limb.CFrame * CFrame.new(0, limb.Size.Y * 0.5, 0)
				local weld = Instance.new("WeldConstraint")
				weld.Part0 = gib
				weld.Part1 = stump
				weld.Parent = gib
				stump.Parent = gib
				gib.Parent = workspace
				gib.AssemblyLinearVelocity = velocity
				gib.AssemblyAngularVelocity = spin or Vector3.zero
				-- KOZMOZ FIX (image-46): eskiden burada sadece LocalTransparencyModifier = 1
				-- yapiliyordu. Bu, uzvu SADECE senin ekraninda gizler; parca yerinde,
				-- COLLIDE acik ve uzerindeki Highlight/SelectionBox ile birlikte kalir.
				-- Sonuc: icinde kimse olmayan mor "kutu" (hayalet govde) gorunur.
				-- Artik gercek temizlik FWA.StripPart ile yapiliyor (asagida).
				pcall(function()
					limb.LocalTransparencyModifier = 0
				end)
				FWA.Debris:AddItem(gib, 4)
			end)
		end
		FWA.Blood = function(position, amount)
			pcall(function()
				local holder = Instance.new("Part")
				holder.Name = "KozmozWeaponBlood"
				holder.Anchored = true
				holder.CanCollide = false
				holder.CanTouch = false
				holder.CanQuery = false
				holder.Transparency = 1
				holder.Size = Vector3.new(0.2, 0.2, 0.2)
				holder.CFrame = CFrame.new(position)
				local emitter = Instance.new("ParticleEmitter")
				emitter.Color = ColorSequence.new(Color3.fromRGB(150, 0, 0), Color3.fromRGB(70, 0, 0))
				emitter.LightEmission = 0
				emitter.Size = NumberSequence.new(0.35, 0.05)
				emitter.Transparency = NumberSequence.new(0, 0.6)
				emitter.Lifetime = NumberRange.new(0.35, 0.8)
				emitter.Speed = NumberRange.new(10, 22)
				emitter.SpreadAngle = Vector2.new(180, 180)
				emitter.Acceleration = Vector3.new(0, -workspace.Gravity * 0.35, 0)
				emitter.Rate = 0
				emitter.Parent = holder
				holder.Parent = workspace
				emitter:Emit(amount or 24)
				FWA.Debris:AddItem(holder, 1.5)
			end)
		end
		-- Per-style velocity for a cut limb (local gib) and for the body (owned -> FE).
		FWA.LimbVelocity = function(style, offset, look, side)
			local up = Vector3.new(0, 1, 0)
			local right = look:Cross(up)
			right = right.Magnitude > 0.01 and right.Unit or Vector3.new(1, 0, 0)
			local flat = Vector3.new(offset.X, 0, offset.Z)
			local radial = flat.Magnitude > 0.05 and flat.Unit or right
			local jitter = Vector3.new(math.random(-40, 40), math.random(-20, 20), math.random(-40, 40)) / 10
			if style == "slice" then
				return -right * side * 34 + up * 16 + radial * 8 + jitter
			elseif style == "chop" then
				return radial * 20 + look * 6 + up * 4 + jitter
			elseif style == "impale" then
				return look * 38 + up * 18 + radial * 6 + jitter
			elseif style == "smash" then
				return radial * 42 + up * 32 + jitter * 2
			end
			return radial * 20 + up * 12 + jitter
		end
		FWA.BodyVelocity = function(style, look, side)
			local up = Vector3.new(0, 1, 0)
			local right = look:Cross(up)
			right = right.Magnitude > 0.01 and right.Unit or Vector3.new(1, 0, 0)
			if style == "slice" then
				return -right * side * 24 + up * 10 + look * 6
			elseif style == "chop" then
				return look * 5 - up * 55
			elseif style == "impale" then
				return look * 55 + up * 28
			elseif style == "smash" then
				return look * 8 - up * 85
			end
			return look * 9 + up * 8
		end
		FWA.Spin = function(style)
			local m = (style == "slice" or style == "smash") and 18 or 9
			return Vector3.new(math.random(-m, m), math.random(-m, m), math.random(-m, m))
		end
		FWA.IsCutLimb = function(name, cut)
			-- KOZMOZ: R6 ("Left Arm") ve R15 ("LeftUpperArm", "LeftLowerLeg"...) ikisini de tani.
			local isArm = name:find("Arm") or name:find("Hand")
			local isLeg = name:find("Leg") or name:find("Foot")
			return (isArm and (cut == "Arms" or cut == "All")) or (isLeg and (cut == "Legs" or cut == "All")) or false
		end
		-- FE cut: the target is owned + ragdolled (limbs are their own assemblies),
		-- so voiding a limb removes it for everyone - same mechanism as Break Limbs.
		-- KOZMOZ FIX (image-46): kesilen uzvu GERCEKTEN sok.
		-- 1) gorunmez yap (Transparency), 2) carpismayi kapat (hayalet kutu yok),
		-- 3) uzerindeki Highlight / SelectionBox / kutu adornment'larini sil,
		-- 4) uzva bagli tum joint/weld'leri kapat (govdeyi arkasindan suruklemesin).
		FWA.StripPart = function(part)
			if not part then
				return
			end
			pcall(function() part.Transparency = 1 end)
			pcall(function() part.LocalTransparencyModifier = 0 end)
			pcall(function() part.CanCollide = false end)
			pcall(function() part.CanTouch = false end)
			pcall(function() part.CanQuery = false end)
			pcall(function() part.Massless = true end)
			pcall(function() part.CastShadow = false end)
			pcall(function()
				for _, child in ipairs(part:GetChildren()) do
					if child:IsA("Highlight") or child:IsA("SelectionBox") or child:IsA("BoxHandleAdornment")
						or child:IsA("SurfaceGui") or child:IsA("BillboardGui") or child:IsA("Beam") then
						child:Destroy()
					end
				end
			end)
			pcall(function()
				for _, child in ipairs(part:GetChildren()) do
					if child:IsA("JointInstance") or child:IsA("WeldConstraint") or child:IsA("Constraint") then
						child.Enabled = false
					end
				end
			end)
			pcall(function()
				part.AssemblyLinearVelocity = Vector3.zero
				part.AssemblyAngularVelocity = Vector3.zero
			end)
		end

		FWA.CutLimbs = function(char, hrp, profile, look, side)
			local limbs = {}
			local cutSet = {}
			for _, child in ipairs(char:GetChildren()) do
				if child:IsA("BasePart") and FWA.IsCutLimb(child.Name, profile.Cut) then
					limbs[#limbs + 1] = child
					cutSet[child] = true
				end
			end
			if #limbs == 0 then
				return false
			end
			local center = hrp.Position
			for _, limb in ipairs(limbs) do
				FWA.SpawnGib(limb, FWA.LimbVelocity(profile.Style, limb.Position - center, look, side), FWA.Spin(profile.Style))
			end
			FWA.Blood(center, profile.Style == "smash" and 40 or 26)
			-- SIRA ONEMLI: once ragdoll birakilir AMA kesilen uzvun Motor6D'si geri
			-- acilmaz. Eskiden once uzuv -100000'e atilip sonra Motor6D acildigi icin
			-- weld tum govdeyi void'e surukluyordu -> "kesince bugda kaliyor" goruntusu.
			FWA.ReleaseRagdoll(char, cutSet)
			for _, limb in ipairs(limbs) do
				FWA.StripPart(limb)
				pcall(function()
					if limb.Parent then
						tbl12.Teleport(limb, CFrame.new(0, -100000, 0))
					end
				end)
				-- sunucu void'i kabul etmediyse bile ekranda hayalet kutu kalmasin
				task.delay(0.45, function()
					pcall(function()
						if limb.Parent and limb:IsDescendantOf(char) then
							FWA.StripPart(limb)
							limb:Destroy()
						end
					end)
				end)
			end
			pcall(function()
				if hrp.Parent then
					hrp.AssemblyLinearVelocity = FWA.BodyVelocity(profile.Style, look, side)
					hrp.AssemblyAngularVelocity = FWA.Spin(profile.Style)
				end
			end)
			return true
		end

		-- KOZMOZ USER: ragdoll'u birak (kil/pose bug'i kalmasin).
		-- 1) BallSocketConstraint'ler kapatilir, 2) Motor6D'ler geri acilir,
		-- 3) Humanoid.Ragdolled = false, 4) humanoid durumu Running'e alinir.
		-- skip = kesilen uzuvlar (bu Motor6D'ler ASLA geri acilmaz)
		FWA.ReleaseRagdoll = function(char, skip)
			if not char or not char.Parent then
				return
			end
			skip = skip or {}
			pcall(function()
				for _, name in ipairs({ "Left Leg", "Right Leg", "Left Arm", "Right Arm", "Head" }) do
					local limb = char:FindFirstChild(name)
					if limb and not skip[limb] then
						local bsc = limb:FindFirstChild("BallSocketConstraint")
						if bsc then
							bsc.Enabled = false
						end
					end
				end
			end)
			pcall(function()
				-- KOZMOZ FIX (image-51): Torso yoksa (R15 / ozel rig) motorlar bulunamiyordu.
				-- Artik Torso + UpperTorso + HumanoidRootPart + tum karakter taranir.
				local seen = {}
				local function enableMotors(container)
					if not container then
						return
					end
					for _, m in ipairs(container:GetChildren()) do
						if m:IsA("Motor6D") and not seen[m] then
							seen[m] = true
							-- KOZMOZ FIX (image-46): kesilen uzvun motoru geri acilirsa hedef
							-- "kesilmis ama yapisik" bug'inda kalir. O motorlari atla.
							local part1 = m.Part1
							if not (part1 and skip[part1]) then
								m.Enabled = true
							end
						end
					end
				end
				enableMotors(char:FindFirstChild("Torso"))
				enableMotors(char:FindFirstChild("UpperTorso"))
				enableMotors(char:FindFirstChild("HumanoidRootPart"))
				enableMotors(char)
			end)
			pcall(function()
				local hum = char:FindFirstChildOfClass("Humanoid")
				local rag = hum and hum:FindFirstChild("Ragdolled")
				if rag then
					rag.Value = false
				end
			end)
			-- KOZMOZ FIX (image-46): yerde/uzanan govde de kalkmasin diye kisa bir
			-- toparlanma: kok yukari alinir, hiz sifirlanir (sadece ilk vurusta).
			-- StartRagdoll/anti-kick gibi sistemlerin de verdigi "kalk" durumuyla
			-- cakismamasi icin pcall + kosul kontrolu var.
			task.delay(0.12, function()
				pcall(function()
					local hum = char:FindFirstChildOfClass("Humanoid")
					local root = char:FindFirstChild("HumanoidRootPart") or char:FindFirstChild("Torso")
					if not (hum and root and root.Parent) then
						return
					end
					if hum.Health <= 0 then
						return
					end
					if hum:GetState() == Enum.HumanoidStateType.Dead then
						return
					end
					-- govde yere yapisip kalmasin: hafif yukari it + hiz sifirla
					root.AssemblyAngularVelocity = Vector3.zero
					if root.AssemblyLinearVelocity.Magnitude < 6 then
						root.AssemblyLinearVelocity = Vector3.new(0, 6, 0)
					end
					hum:ChangeState(Enum.HumanoidStateType.GettingUp)
					hum:ChangeState(Enum.HumanoidStateType.Running)
				end)
			end)
		end
		-- Fallback when the ragdoll did not take (or an NPC): the old local break,
		-- but every piece flies the weapon's own way.
		FWA.LocalShatter = function(char, hum, hrp, profile, look, side)
			pcall(function()
				hum.BreakJointsOnDeath = true
				hum.Health = 0
				char:BreakJoints()
			end)
			local center = hrp.Position
			for _, part in ipairs(char:GetChildren()) do
				if part:IsA("BasePart") and part.Name ~= "HumanoidRootPart" then
					pcall(function()
						local vel
						if FWA.IsCutLimb(part.Name, profile.Cut) or part.Name == "Head" then
							vel = FWA.LimbVelocity(profile.Style, part.Position - center, look, side)
						else
							vel = FWA.BodyVelocity(profile.Style, look, side) * 0.5
						end
						part.AssemblyLinearVelocity = vel
						part.AssemblyAngularVelocity = FWA.Spin(profile.Style)
					end)
				end
			end
			pcall(function()
				hrp.AssemblyLinearVelocity = FWA.BodyVelocity(profile.Style, look, side) * 0.5
			end)
			FWA.Blood(center, 22)
		end
		local function FW_PoseStep()
			if not FW.SwingType then
				return
			end
			local char = localPlayer.Character
			local torso = char and char:FindFirstChild("Torso")
			local shoulder = torso and torso:FindFirstChild("Right Shoulder")
			local leftShoulder = torso and torso:FindFirstChild("Left Shoulder")
			if not shoulder then
				return
			end
			local anim = FWA.Anims[FW.SwingType] or FWA.Anims.cleaver
			local t = (os.clock() - FW.SwingStart) / math.max(FW.SwingDuration, 0.05)
			if t >= 1 then
				FW.SwingType = nil
				shoulder.Transform = CFrame.new()
				if leftShoulder and anim.L then
					leftShoulder.Transform = CFrame.new()
				end
				return
			end
			local mirror = anim.Mirror and FW.SwingSide or 1
			local cf = FWA.Sample(anim.R, t, mirror, false)
			if cf then
				shoulder.Transform = cf
			end
			if leftShoulder and anim.L then
				local lcf = FWA.Sample(anim.L, t, mirror, true)
				if lcf then
					leftShoulder.Transform = lcf
				end
			end
		end

		local function FW_FindTarget(range)
			local char, hrp = FW_MyChar()
			if not char or not hrp then
				return nil
			end
			local cam = workspace.CurrentCamera
			local look = cam and cam.CFrame.LookVector or hrp.CFrame.LookVector
			local origin = cam and cam.CFrame.Position or hrp.Position
			local rayParams = RaycastParams.new()
			rayParams.FilterType = Enum.RaycastFilterType.Exclude
			local filterList = { char }
			if FW.Toy then
				table.insert(filterList, FW.Toy)
			end
			rayParams.FilterDescendantsInstances = filterList
			local rayResult = workspace:Raycast(origin, look * (range + 3), rayParams)
			if rayResult and rayResult.Instance then
				local model = rayResult.Instance:FindFirstAncestorOfClass("Model")
				local hum = model and model:FindFirstChildOfClass("Humanoid")
				if model and hum and hum.Health > 0 and model ~= char and model.Name ~= "CreatureBlobman" and model.Name ~= "Gucci" then
					local plr = Players:GetPlayerFromCharacter(model)
					local protected = plr and tbl12.IsProtectedPlayer and tbl12.IsProtectedPlayer(plr, true)
					if not protected and not FW_HitBusy[model] then
						local root = model:FindFirstChild("HumanoidRootPart") or model:FindFirstChild("Torso")
						return { character = model, humanoid = hum, player = plr, hrp = root }
					end
				end
			end
			local bestTarget = nil
			local bestScore = -math.huge
			for _, plr in ipairs(Players:GetPlayers()) do
				if plr ~= localPlayer and plr.Character and not FW_HitBusy[plr.Character] and not (tbl12.IsProtectedPlayer and tbl12.IsProtectedPlayer(plr, true)) then
					local model = plr.Character
					local hum = model:FindFirstChildOfClass("Humanoid")
					local root = model:FindFirstChild("HumanoidRootPart") or model:FindFirstChild("Torso")
					if hum and hum.Health > 0 and root then
						local diff = root.Position - hrp.Position
						local dist = diff.Magnitude
						if dist <= range and dist > 0.01 then
							local dot = look:Dot(diff.Unit)
							if dot > 0.35 then
								local score = dot - (dist / range) * 0.2
								if score > bestScore then
									bestScore = score
									bestTarget = { character = model, humanoid = hum, player = plr, hrp = root }
								end
							end
						end
					end
				end
			end
			return bestTarget
		end

		-- KOZMOZ FIX: one swing now hits EVERY player in range (it used to pick a
		-- single target - or nobody at all - which is why the weapon often cut
		-- nobody). Whitelist / protected flag no longer blocks a hit, and the
		-- angle window is wider so players around you are not skipped.
		local function FW_FindTargets(range, maxCount)
			local char, hrp = FW_MyChar()
			if not char or not hrp then
				return {}
			end
			local cam = workspace.CurrentCamera
			local look = cam and cam.CFrame.LookVector or hrp.CFrame.LookVector
			look = Vector3.new(look.X, 0, look.Z)
			if look.Magnitude < 0.01 then
				look = Vector3.new(0, 0, -1)
			else
				look = look.Unit
			end
			local out = {}
			local seen = {}
			local consider = function(model, plr)
				if not model or model == char or seen[model] then
					return
				end
				if model.Name == "CreatureBlobman" or model.Name == "Gucci" then
					return
				end
				local hum = model:FindFirstChildOfClass("Humanoid")
				local root = model:FindFirstChild("HumanoidRootPart") or model:FindFirstChild("Torso")
				if not hum or not root or hum.Health <= 0 or FW_HitBusy[model] then
					return
				end
				local dist = (root.Position - hrp.Position).Magnitude
				if dist > range or dist < 0.01 then
					return
				end
				seen[model] = true
				out[#out + 1] = { character = model, humanoid = hum, player = plr, hrp = root, dist = dist }
			end
			for _, plr in ipairs(Players:GetPlayers()) do
				if plr ~= localPlayer then
					consider(plr.Character, plr)
				end
			end
			if tbl10 and tbl10.Figures then
				pcall(function()
					for model in pairs(tbl10.Figures) do
						consider(model, nil)
					end
				end)
			end
			-- nearest first
			table.sort(out, function(a, b) return a.dist < b.dist end)
			if maxCount and #out > maxCount then
				for i = #out, maxCount + 1, -1 do
					out[i] = nil
				end
			end
			return out
		end

		local FW_WarnAt = {}
		local function FW_WarnThrottled(key, msg)
			if os.clock() - (FW_WarnAt[key] or -math.huge) >= 5 then
				FW_WarnAt[key] = os.clock()
				warn(msg)
			end
		end

		-- v34: hit = own -> ragdoll -> cut limbs (FE) -> fling torso -> KILL (FE).
		-- Before, a failed SNO silently returned and a failed ragdoll fell back to a
		-- local-only shatter, so the target never fell apart or died for anyone.
		local function FW_Dismember(target, profile, side)
			if not target or not target.character or not target.humanoid or target.humanoid.Health <= 0 then
				return
			end
			profile = profile or FWA.Profile()
			side = side or 1
			local char = target.character
			local hum = target.humanoid
			local hrp = target.hrp
			if not hrp or FW_HitBusy[char] then
				return
			end
			FW_HitBusy[char] = true
			-- KOZMOZ: 6 saniye vurulmadiysa sayac sifirlanir (yeni fight = yeniden 1,2)
			task.delay(6, function()
				if FW_HitAt[char] and os.clock() - FW_HitAt[char] >= 5.5 then
					FW_HitCount[char] = nil
					FW_HitAt[char] = nil
				end
			end)
			task.spawn(function()
				local function alive()
					return char.Parent and hum.Parent and hum.Health > 0 and hrp.Parent
				end
				local function owned()
					local okO, res = pcall(function()
						return (tbl12.IsPartOwner and tbl12.IsPartOwner(hrp) == true)
							or (tbl12.IsNetworkOwner and tbl12.IsNetworkOwner(hrp) == true)
					end)
					return okO and res == true
				end
				local name = target.player and target.player.Name or char.Name

				-- 1) ownership: let a running SNO (Anti Vehicle / kick ...) finish first
				local waitStart = os.clock()
				while tbl7.States.Owning and os.clock() - waitStart < 0.35 do
					task.wait()
				end
				if alive() and not owned() then
					pcall(function()
						if tbl12.SNO then
							tbl12.SNO(hrp, 0.9)
						end
					end)
				end
				if alive() and not owned() then
					for _ = 1, 8 do
						pcall(function()
							if tbl11 and tbl11.SetNetworkOwner then
								tbl11.SetNetworkOwner:FireServer(hrp, hrp.CFrame)
							end
							if tbl12.Grab then
								tbl12.Grab(hrp)
							end
						end)
						task.wait()
						if owned() or not alive() then
							break
						end
					end
				end
				if not alive() then
					FW_HitBusy[char] = nil
					return
				end
				if not owned() then
					FW_WarnThrottled("own" .. name, "[KOZMOZ Weapon] " .. name .. ": ownership rejected by the server (in plot / anti-grab?), hit not applied")
					FW_HitBusy[char] = nil
					return
				end

				local cam = workspace.CurrentCamera
				local look = cam and cam.CFrame.LookVector or Vector3.new(0, 0, -1)
				look = Vector3.new(look.X, 0, look.Z)
				look = look.Magnitude > 0.01 and look.Unit or Vector3.new(0, 0, -1)

				-- KOZMOZ USER: "kil" YOK. Eski akis once ragdoll yapiyordu; hedef kesilmis
				-- bir kil/corpse gibi ortada kaliyordu (bug'li pose). Artik ragdoll adimi
				-- tamamen atlandi: ilk vurusta uzuvlar kopyor, hedef ayakta kaliyor.
				local cut = false
				if alive() then
					cut = FWA.CutLimbs(char, hrp, profile, look, side)
				end
				if not cut and alive() then
					-- uzuv bulunamadi (Cut listesi bos / NPC): govdeyi dagit
					FWA.LocalShatter(char, hum, hrp, profile, look, side)
				end

				-- 4) let the torso fly for a moment, then 5) kill it for everyone
				local flyUntil = os.clock() + (cut and 0.3 or 0.15)
				while os.clock() < flyUntil and hrp.Parent do
					task.wait()
				end
				local killed = false
				local function killNow()
					if not char.Parent then
						return true
					end
					local part = (hrp and hrp.Parent and hrp) or char:FindFirstChild("Head") or char:FindFirstChild("Torso")
						or char:FindFirstChildWhichIsA("BasePart", true)
					if not part then
						return false
					end
					pcall(function()
						hum.BreakJointsOnDeath = false
						hum:ChangeState(Enum.HumanoidStateType.Dead)
					end)
					local done = false
					-- KOZMOZ: once reso'nun Kill akisi (sahiplik + Dead + void)
					pcall(function()
						if target.player and tbl12.KillReso then
							done = tbl12.KillReso(target.player) == true
						end
					end)
					pcall(function()
						if tbl12.DestroyObject then
							done = tbl12.DestroyObject(char, part) == true or done
						end
					end)
					-- KOZMOZ: FE kill tutmasa bile hedef kesinlikle devrilsin
					pcall(function()
						hum.Health = 0
						hum:ChangeState(Enum.HumanoidStateType.Dead)
					end)
					return done
				end
				-- KOZMOZ USER: 1. vurus = uzuvlar kopsun (kill YOK), 2. vurus = kesin kill
				FW_HitCount[char] = (FW_HitCount[char] or 0) + 1
				FW_HitAt[char] = os.clock()
				local hitNo = FW_HitCount[char]
				local finalHit = hitNo >= FW_FORCE_KILL_AT

				if finalHit then
					pcall(function()
						hum.BreakJointsOnDeath = true
						hum.Health = 0
						hum:ChangeState(Enum.HumanoidStateType.Dead)
					end)
					pcall(function()
						if char.Parent then char:BreakJoints() end
					end)
					killed = killNow()
					-- sayaci sifirla: ayni karakter respawn ederse yeniden 1. vurus sayilir
					FW_HitCount[char] = nil
					FW_HitAt[char] = nil
				else
					-- ilk vurus: sadece kesim. Hedef hayatta ve ayakta kalir.
					killed = false
				end

				-- retries if the void did not take (no long corpse delay any more)
				local function verify(attempt)
					if not char or not char.Parent then
						FW_HitBusy[char] = nil
						return
					end
					if target.player and target.player.Character ~= char then
						FW_HitBusy[char] = nil
						return
					end
					-- KOZMOZ: hala ayakta/ragdoll ise kill'i tekrar dene (bugda kalmasin)
					if attempt <= 6 then
						if hum.Parent and hum.Health > 0 then
							pcall(function()
								hum.BreakJointsOnDeath = true
								hum.Health = 0
								hum:ChangeState(Enum.HumanoidStateType.Dead)
							end)
							pcall(function()
								if char.Parent then
									char:BreakJoints()
								end
							end)
						end
						killNow()
						task.delay(0.35, function()
							verify(attempt + 1)
						end)
					else
						if hrp and hrp.Parent then
							pcall(function()
								if tbl12.RNO then
									tbl12.RNO(hrp)
								end
							end)
						end
						FW_WarnThrottled("kill" .. name, "[KOZMOZ Weapon] " .. name .. ": kill void did not take (server reset?)")
						FW_HitBusy[char] = nil
					end
				end
				if killed or finalHit then
					task.delay(killed and 0.35 or 0.15, function()
						verify(1)
					end)
				else
					-- KOZMOZ USER: ilk vurus sadece kesim. Kill denemesi YOK; boylece hedef
					-- ragdoll/kill dongusunde bug'da kalmiyor. Kisa sure sonra tekrar
					-- vurulabilmesi icin kilit acilir.
					task.delay(0.12, function()
						FW_HitBusy[char] = nil
					end)
				end
			end)
		end

		local function FW_Swing(side)
			if not FW.Enabled then
				return
			end
			local profile = FWA.Profile()
			local now = os.clock()
			if now - FW.LastSwing < (profile.Cooldown or 0.3) then
				return
			end
			FW_SetGrabbing(true)
			FW.LastSwing = now
			FW.SwingStart = now
			FW.SwingSide = side
			FW.SwingDuration = profile.Duration
			if profile.Anim == "katana" and side < 0 then
				FW.SwingType = "katana_back"
			else
				FW.SwingType = profile.Anim
			end
			FWA.PlayRemote(profile.Remote, profile.Duration)
			local swingId = now
			task.delay(profile.HitDelay, function()
				if not FW.Enabled or FW.SwingStart ~= swingId then
					return
				end
				local range = FW_Range()
				local targets = FW_FindTargets(range, FW_MaxTargets())
				if not targets or #targets == 0 then
					return
				end
				-- the closest one gets the full cut, the rest are hit on a short stagger
				for index, target in ipairs(targets) do
					if not FW.Enabled then
						break
					end
					if index == 1 then
						FW_Dismember(target, profile, side)
					else
						task.delay(0.03 * (index - 1), function()
							if FW.Enabled then
								FW_Dismember(target, profile, side)
							end
						end)
					end
				end
			end)
		end

		UIS.InputBegan:Connect(function(input, gameProcessed)
			if not FW.Enabled or gameProcessed then
				return
			end
			if input.UserInputType == Enum.UserInputType.MouseButton1 then
				FW_Swing(1)
			elseif input.UserInputType == Enum.UserInputType.MouseButton2 then
				FW_Swing(-1)
			elseif input.UserInputType == Enum.UserInputType.Touch then
				FW_Swing(1)
			end
		end)

		local funMouse = localPlayer:GetMouse()
		if funMouse then
			funMouse.Button1Down:Connect(function()
				FW_Swing(1)
			end)
			funMouse.Button2Down:Connect(function()
				FW_Swing(-1)
			end)
		end

		-- KOZMOZ FIX (FPS): the weapon used to run its full "maintain" pass on
		-- EVERY physics step (60x/s): GetBoundingBox-free but still CFrame math,
		-- weld checks and ownership probes. That is what made the game stutter
		-- while holding a weapon. Pose stays per-frame (it is smooth), the heavy
		-- maintenance now runs at ~20 Hz and the cheap grabbing guard at ~10 Hz.
		local fwNextMaintain = 0
		local fwNextGrab = 0
		RunService.Stepped:Connect(function()
			if not FW.Enabled then
				return
			end
			local nowClock = os.clock()
			if nowClock >= fwNextGrab then
				fwNextGrab = nowClock + 0.1
				if FW.Stuck or FW.Owned then
					FW_SetGrabbing(true)
				end
			end
			FW_PoseStep()
			local fullPass = nowClock >= fwNextMaintain
			if fullPass then
				fwNextMaintain = nowClock + 0.05
			end
			pcall(FW_MaintainStep, fullPass)
		end)

