		local function setProp(inst, prop, value)
			if typeof(inst) ~= "Instance" then
				return false
			end
			return (pcall(function()
				inst[prop] = value
			end))
		end

		local function connect(signal, fn)
			if not signal or type(signal.Connect) ~= "function" then
				return nil
			end
			local ok, c = pcall(function()
				return signal:Connect(fn)
			end)
			if ok and c then
				table.insert(Connections, c)
			end
			return c
		end

		local function getMyRoot()
			local ch = fcLP and fcLP.Character
			if not ch then
				return nil
			end
			return ch:FindFirstChild("HumanoidRootPart") or ch.PrimaryPart
		end

		local function guiParent()
			local ok, core = pcall(function()
				return game:GetService("CoreGui")
			end)
			if ok and core then
				return core
			end
			local pg = fcLP and fcLP:FindFirstChildOfClass("PlayerGui")
			if pg then
				return pg
			end
			return nil
		end

		local function angleDelta(a, b)
			return math.atan2(math.sin(a - b), math.cos(a - b))
		end

		local function normalizeAnimId(s)
			local d = tostring(s or ""):match("(%d+)")
			if not d then
				return nil
			end
			return "rbxassetid://" .. d
		end

		local function findGroundNear(pos, ignoreList)
			local okP, params = pcall(RaycastParams.new)
			if not okP or not params then
				return nil
			end
			params.FilterType = Enum.RaycastFilterType.Exclude
			local ignore = {}
			if fcLP and fcLP.Character then
				table.insert(ignore, fcLP.Character)
			end
			if ignoreList then
				for _, v in ipairs(ignoreList) do
					table.insert(ignore, v)
				end
			end
			params.FilterDescendantsInstances = ignore
			local ok, res = pcall(function()
				return workspace:Raycast(pos + Vector3.new(0, 40, 0), Vector3.new(0, -300, 0), params)
			end)
			if ok and res and res.Position then
				return res.Position
			end
			return nil
		end

		local function headshot(userId)
			userId = tonumber(userId) or 0
			local content = nil
			if userId > 0 then
				pcall(function()
					content = fcPlayers:GetUserThumbnailAsync(userId, Enum.ThumbnailType.HeadShot, Enum.ThumbnailSize.Size150x150)
				end)
				if type(content) ~= "string" or content == "" then
					pcall(function()
						content = fcPlayers:GetUserThumbnailAsync(userId, Enum.ThumbnailType.AvatarBust, Enum.ThumbnailSize.Size150x150)
					end)
				end
			end
			if type(content) == "string" and content ~= "" then
				return content
			end
			if userId <= 0 then
				return ""
			end
			return "rbxthumb://type=AvatarHeadShot&id=" .. tostring(userId) .. "&w=150&h=150"
		end

		-- v23: find the selected player's avatar (resolve by name when there is no id)
		local function resolveAvatarAsync(spec, imageLabel)
			if not spec or not imageLabel then
				return
			end
			task.spawn(function()
				local uid = tonumber(spec.id) or 0
				if uid <= 0 then
					pcall(function()
						uid = fcPlayers:GetUserIdFromNameAsync(tostring(spec.user or spec.display or ""))
					end)
				end
				if uid and uid > 0 then
					local url = headshot(uid)
					if type(url) == "string" and url ~= "" and imageLabel.Parent then
						pcall(function()
							imageLabel.Image = url
						end)
					end
				end
			end)
		end

		-- ============================================================================
		-- 1) Sync Spawned Bots into KOZMOZ's Figure Grab -> Target -> Targets Dropdown
		-- ============================================================================
		syncBotsIntoFigureGrab = function()
			local dd = options and options.AutoClickerDropdown
			local ddTarget = options and options.TargetsDropdown
			if not dd and not ddTarget then
				return
			end
			pcall(function()
				local vals = {}
				if fcPlayers and type(fcPlayers.GetPlayers) == "function" then
					for _, p in ipairs(fcPlayers:GetPlayers()) do
						if p ~= fcLP then
							vals[#vals + 1] = p
						end
					end
				end
				if type(dd.ValueImages) ~= "table" then
					dd.ValueImages = {}
				end
				for _, a in ipairs(actors) do
					if not a.dead and a.botProxy and a.rig and a.rig.Parent then
						vals[#vals + 1] = a.botProxy
						dd.ValueImages[a.botProxy] = "rbxthumb://type=AvatarHeadShot&id=" .. tostring(a.spec.id) .. "&w=48&h=48"
					end
				end
				if dd.SetValues then
					dd:SetValues(vals)
				end
				-- v25: also add the bots to the Target tab list
				if ddTarget and ddTarget.SetValues then
					local tvals = {}
					for _, pl in ipairs(fcPlayers:GetPlayers()) do
						if pl ~= fcLP then
							tvals[#tvals + 1] = pl
						end
					end
					for _, a in ipairs(actors) do
						if not a.dead and a.botProxy and a.rig and a.rig.Parent then
							tvals[#tvals + 1] = a.botProxy
							if type(ddTarget.ValueImages) == "table" then
								ddTarget.ValueImages[a.botProxy] = "rbxthumb://type=AvatarHeadShot&id=" .. tostring(a.spec.id) .. "&w=48&h=48"
							end
						end
					end
					pcall(function()
						ddTarget:SetValues(tvals)
					end)
				end
			end)
		end

		-- ============================================================================
		-- 2) Source Resolution (Friends / InGame / UserId + Automatic Live TextBox Read)
		-- ============================================================================
		local function readLiveManualText()
			local rawTxt = Config.ManualRaw or ""
			if options and options.FigureUserIdInput and type(options.FigureUserIdInput.Value) == "string" and options.FigureUserIdInput.Value ~= "" then
				rawTxt = options.FigureUserIdInput.Value
			end
			if userIdBoxInst and typeof(userIdBoxInst) == "Instance" then
				pcall(function()
					if type(userIdBoxInst.Text) == "string" then
						rawTxt = userIdBoxInst.Text
					end
				end)
			end
			rawTxt = tostring(rawTxt or ""):gsub("^%s+", ""):gsub("%s+$", "")
			return rawTxt
		end

		local function resolveUserIdentity(id, fallbackName)
			local userName = (type(fallbackName) == "string" and fallbackName ~= "") and fallbackName or nil
			local displayName = nil

			if fcPlayers and type(fcPlayers.GetPlayers) == "function" then
				for _, p in ipairs(fcPlayers:GetPlayers()) do
					if p.UserId == id then
						userName = p.Name
						displayName = p.DisplayName or p.Name
						break
					end
				end
			end

			if (not displayName or not userName) and fcUserService then
				pcall(function()
					local infos = fcUserService:GetUserInfosByUserIdsAsync({ id })
					if type(infos) == "table" and infos[1] then
						userName = infos[1].Username or userName
						displayName = infos[1].DisplayName or infos[1].Username or displayName
					end
				end)
			end

			if not userName and fcPlayers then
				pcall(function()
					local nm = fcPlayers:GetNameFromUserIdAsync(id)
					if type(nm) == "string" and nm ~= "" then
						userName = nm
					end
				end)
			end

			userName = userName or ("user_" .. tostring(id))
			displayName = (displayName and displayName ~= "" and displayName) or userName
			return displayName, userName
		end

		local function resolveManualSpec(rawTxt)
			local txt = tostring(rawTxt or ""):gsub("^%s+", ""):gsub("%s+$", "")
			if txt == "" then
				return nil
			end

			-- Support profile URLs like https://www.roblox.com/users/12345678/profile
			local urlId = txt:match("users/(%d+)")
			local num = tonumber(urlId or txt)
			if num and num > 0 then
				local uid = math.floor(num)
				local disp, usr = resolveUserIdentity(uid, nil)
				return {
					id = uid,
					display = disp,
					user = usr,
					source = "UserId",
				}
			end

			local cleanName = txt:gsub("^@", "")
			if cleanName == "" then
				return nil
			end

			-- Check in-server players first (case-insensitive username or display name)
			local lower = string.lower(cleanName)
			if fcPlayers and type(fcPlayers.GetPlayers) == "function" then
				for _, p in ipairs(fcPlayers:GetPlayers()) do
					if string.lower(p.Name) == lower or string.lower(p.DisplayName or "") == lower then
						return {
							id = p.UserId,
							display = p.DisplayName or p.Name,
							user = p.Name,
							source = "UserId",
						}
					end
				end
			end

			local resolvedId = nil
			pcall(function()
				resolvedId = fcPlayers:GetUserIdFromNameAsync(cleanName)
			end)
			if type(resolvedId) == "number" and resolvedId > 0 then
				local disp, usr = resolveUserIdentity(resolvedId, cleanName)
				return {
					id = resolvedId,
					display = disp,
					user = usr,
					source = "UserId",
				}
			end
			return nil
		end

		local function fetchOnlineFriends()
			if not fcLP then
				return nil
			end
			for _, methodName in ipairs({ "GetFriendsOnlineAsync", "GetFriendsOnline" }) do
				local f = nil
				pcall(function()
					f = fcLP[methodName]
				end)
				if type(f) == "function" then
					local ok, res = pcall(function()
						return f(fcLP, 200)
					end)
					if ok and type(res) == "table" then
						return res
					end
				end
			end
			return nil
		end

		local function buildFriendList()
			local list = {}
			local online = fetchOnlineFriends()
			if online then
				for _, fr in ipairs(online) do
					if type(fr) == "table" and type(fr.VisitorId) == "number" then
						table.insert(list, {
							id = fr.VisitorId,
							display = (type(fr.DisplayName) == "string" and fr.DisplayName ~= "" and fr.DisplayName)
								or fr.UserName
								or "Friend",
							user = fr.UserName or "friend",
							source = "Friends",
						})
					end
				end
			end
			if #list == 0 and fcLP and type(fcLP.UserId) == "number" then
				local ok, pages = pcall(function()
					return fcPlayers:GetFriendsAsync(fcLP.UserId)
				end)
				if ok and pages then
					for _ = 1, 3 do
						local okPage, items = pcall(function()
							return pages:GetCurrentPage()
						end)
						if not okPage or type(items) ~= "table" then
							break
						end
						for _, it in ipairs(items) do
							if type(it.Id) == "number" and it.Id > 0 then
								table.insert(list, {
									id = it.Id,
									display = (type(it.DisplayName) == "string" and it.DisplayName ~= "" and it.DisplayName)
										or it.Username
										or "Friend",
									user = it.Username or "friend",
									source = "Friends",
								})
							end
						end
						local fin = false
						pcall(function()
							fin = pages.IsFinished
						end)
						if fin then
							break
						end
						local advOk = pcall(function()
							pages:AdvanceToNextPageAsync()
						end)
						if not advOk then
							break
						end
					end
				end
			end
			return list
		end

		local function collectFriends(forceRefresh)
			local t = os.clock()
			if not forceRefresh and _friendPoolCache and (t - _friendPoolAt) < 90 then
				return _friendPoolCache
			end
			local ok, res = pcall(buildFriendList)
			if ok and type(res) == "table" and #res > 0 then
				_friendPoolCache, _friendPoolAt = res, t
				return res
			end
			return _friendPoolCache or {}
		end

		local function inGameList()
			local list = {}
			if fcPlayers and type(fcPlayers.GetPlayers) == "function" then
				for _, p in ipairs(fcPlayers:GetPlayers()) do
					if p ~= fcLP then
						table.insert(list, {
							id = p.UserId,
							display = p.DisplayName or p.Name,
							user = p.Name,
							source = "InGame",
						})
					end
				end
			end
			return list
		end

		local function sourceList(mode, forceRefresh)
			if mode == "InGame" then
				return inGameList()
			end
			if mode == "UserId" then
				local s = resolveManualSpec(readLiveManualText())
				return s and { s } or {}
			end
			return collectFriends(forceRefresh)
		end

		local function isRecentFriend(id)
			for _, v in ipairs(friendHistory) do
				if v == id then
					return true
				end
			end
			return false
		end

		local function rememberFriend(id)
			table.insert(friendHistory, 1, id)
			while #friendHistory > Config.FriendHistorySize do
				table.remove(friendHistory)
			end
		end

		local function pickSpec(mode)
			-- Whenever the User ID / @Username box has text, ALWAYS honor it directly!
			local liveTxt = readLiveManualText()
			if liveTxt ~= "" then
				local manual = resolveManualSpec(liveTxt)
				if manual then
					rememberFriend(manual.id)
					return manual
				end
				if mode == "UserId" then
					return nil
				end
			elseif mode == "UserId" then
				return nil
			end

			local lst = sourceList(mode)
			if #lst == 0 then
				return nil
			end
			if selectedSourceEntry and selectedSourceEntry.source == mode then
				for _, item in ipairs(lst) do
					if item.id == selectedSourceEntry.id then
						rememberFriend(item.id)
						return item
					end
				end
			end
			local pool = {}
			for _, f in ipairs(lst) do
				if not isRecentFriend(f.id) then
					table.insert(pool, f)
				end
			end
			if #pool == 0 then
				pool = lst
			end
			local s = pool[RNG:NextInteger(1, #pool)]
			rememberFriend(s.id)
			return s
		end

		-- ============================================================================
		-- 3) Top-Center Roblox Join Banner (png 3: "<DisplayName>,  joined the game") + Chat
		-- ============================================================================
		local function postJoinChatMessage(spec)
			if not Config.ChatJoinMessage then
				return
			end
			local plainMsg = tostring(spec.display) .. ",  joined the game"
			local richMsg = "<font color='#d4d4d4'>" .. plainMsg .. "</font>"
			local sent = false

			if fcTextChat then
				pcall(function()
					local channels = fcTextChat:FindFirstChild("TextChannels")
					local ch = channels and (channels:FindFirstChild("RBXSystem") or channels:FindFirstChild("RBXGeneral"))
					if ch and type(ch.DisplaySystemMessage) == "function" then
						ch:DisplaySystemMessage(richMsg)
						sent = true
					end
				end)
			end

			if not sent and fcStarterGui then
				pcall(function()
					fcStarterGui:SetCore("ChatMakeSystemMessage", {
						Text = plainMsg,
						Color = Color3.fromRGB(212, 212, 212),
					})
				end)
			end
		end

		local function showTopCenterJoinBanner(spec)
			local parent = guiParent()
			if not parent then
				return false
			end
			local okBanner = pcall(function()
				local existing = parent:FindFirstChild("FJNPC_JoinToast")
				if existing then
					pcall(function()
						existing:Destroy()
					end)
				end

				local gui = Instance.new("ScreenGui")
				gui.Name = "FJNPC_JoinToast"
				gui.ResetOnSpawn = false
				gui.IgnoreGuiInset = true
				gui.DisplayOrder = 2147483000
				gui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
				pcall(function()
					gui.ScreenInsets = Enum.ScreenInsets.None
				end)

				local joinText = tostring(spec.display) .. ",  joined the game"
				local cardWidth = math.clamp(115 + (#joinText * 8), 310, 440)

				local card = Instance.new("Frame")
				card.Name = "BannerCard"
				card.AnchorPoint = Vector2.new(0.5, 0)
				card.Position = UDim2.new(0.5, 0, 0, -76)
				card.Size = UDim2.new(0, cardWidth, 0, 56)
				card.BackgroundColor3 = Color3.fromRGB(39, 41, 48)
				card.BackgroundTransparency = 0.04
				card.BorderSizePixel = 0
				card.Parent = gui
				local cc = Instance.new("UICorner")
				cc.CornerRadius = UDim.new(0, 12)
				cc.Parent = card

				local av = Instance.new("ImageLabel")
				av.Name = "Avatar"
				av.Position = UDim2.new(0, 11, 0.5, -20)
				av.Size = UDim2.new(0, 40, 0, 40)
				av.BackgroundColor3 = Color3.fromRGB(58, 61, 69)
				av.BorderSizePixel = 0
				-- v23: fill instantly with rbxthumb, then upgrade to the real thumbnail
				local uid0 = tonumber(spec.id) or 0
				av.Image = uid0 > 0 and ("rbxthumb://type=AvatarHeadShot&id=" .. tostring(uid0) .. "&w=150&h=150") or ""
				av.ImageTransparency = 0
				av.BackgroundTransparency = 0
				av.ScaleType = Enum.ScaleType.Crop
				av.Parent = card
				resolveAvatarAsync(spec, av)
				local ac = Instance.new("UICorner")
				ac.CornerRadius = UDim.new(1, 0)
				ac.Parent = av
				local ring = Instance.new("UIStroke")
				ring.Color = Color3.fromRGB(55, 115, 245)
				ring.Thickness = 1.6
				ring.Transparency = 0.05
				ring.Parent = av

				local lbl = Instance.new("TextLabel")
				lbl.Name = "JoinText"
				lbl.Text = joinText
				lbl.Font = Enum.Font.GothamBold
				lbl.TextSize = 15
				lbl.TextColor3 = Color3.fromRGB(255, 255, 255)
				lbl.TextXAlignment = Enum.TextXAlignment.Left
				lbl.BackgroundTransparency = 1
				lbl.Position = UDim2.new(0, 62, 0, 0)
				lbl.Size = UDim2.new(1, -74, 1, 0)
				lbl.TextTruncate = Enum.TextTruncate.AtEnd
				lbl.Parent = card

				gui.Parent = parent
				fcTweenService:Create(
					card,
					TweenInfo.new(0.38, Enum.EasingStyle.Quart, Enum.EasingDirection.Out),
					{ Position = UDim2.new(0.5, 0, 0, 14) }
				):Play()
				task.delay(Config.ToastDuration, function()
					if not gui.Parent then
						return
					end
					local tw = fcTweenService:Create(
						card,
						TweenInfo.new(0.30, Enum.EasingStyle.Quad, Enum.EasingDirection.In),
						{ Position = UDim2.new(0.5, 0, 0, -76) }
					)
					tw:Play()
					pcall(function()
						tw.Completed:Wait()
					end)
					pcall(function()
						gui:Destroy()
					end)
				end)
			end)
			return okBanner
		end

		local function joinNotice(spec)
			showTopCenterJoinBanner(spec)
			postJoinChatMessage(spec)
		end

		-- ============================================================================
		-- 4) Authentic FTAP R6 Avatar Builder (4-Layer Executor-Safe Loader)
		-- ============================================================================
		local function minimalR6Rig()
			local model = Instance.new("Model")
			local function part(n, size, tr, color)
				local p = Instance.new("Part")
				p.Name = n
				p.Size = size
				p.Transparency = tr or 0
				if color then
					pcall(function()
						p.Color = color
					end)
				end
				p.CanCollide = (n == "Head" or n == "Torso")
				pcall(function()
					p.TopSurface = Enum.SurfaceType.Smooth
					p.BottomSurface = Enum.SurfaceType.Smooth
				end)
				p.Parent = model
				return p
			end
			local function addAtt(parentPart, nm, pos)
				local att = Instance.new("Attachment")
				att.Name = nm
				att.Position = pos
				att.Parent = parentPart
				return att
			end
			local function joint(n, p0, p1, c0, c1)
				local m = Instance.new("Motor6D")
				m.Name = n
				m.Part0, m.Part1 = p0, p1
				m.C0, m.C1 = c0, c1
				m.Parent = p0
			end
			local skin = Color3.fromRGB(234, 184, 146)
			local root = part("HumanoidRootPart", Vector3.new(2, 2, 1), 1)
			local torso = part("Torso", Vector3.new(2, 2, 1), 0, Color3.fromRGB(40, 127, 71))
			local head = part("Head", Vector3.new(2, 1, 1), 0, skin)
			pcall(function()
				local mesh = Instance.new("SpecialMesh")
				mesh.MeshType = Enum.MeshType.Head
				mesh.Scale = Vector3.new(1.25, 1.25, 1.25)
				mesh.Parent = head
				local face = Instance.new("Decal")
				face.Name = "face"
				face.Texture = "rbxasset://textures/face.png"
				face.Parent = head
			end)
			local la = part("Left Arm", Vector3.new(1, 2, 1), 0, skin)
			local ra = part("Right Arm", Vector3.new(1, 2, 1), 0, skin)
			local ll = part("Left Leg", Vector3.new(1, 2, 1), 0, Color3.fromRGB(13, 105, 172))
			local rl = part("Right Leg", Vector3.new(1, 2, 1), 0, Color3.fromRGB(13, 105, 172))

			addAtt(head, "HatAttachment", Vector3.new(0, 0.6, 0))
			addAtt(head, "HairAttachment", Vector3.new(0, 0.6, 0))
			addAtt(head, "FaceFrontAttachment", Vector3.new(0, 0, -0.6))
			addAtt(head, "FaceCenterAttachment", Vector3.new(0, 0, 0))
			addAtt(torso, "NeckAttachment", Vector3.new(0, 1, 0))
			addAtt(torso, "BodyFrontAttachment", Vector3.new(0, 0, -0.5))
			addAtt(torso, "BodyBackAttachment", Vector3.new(0, 0, 0.5))
			addAtt(torso, "LeftCollarAttachment", Vector3.new(-1, 1, 0))
			addAtt(torso, "RightCollarAttachment", Vector3.new(1, 1, 0))
			addAtt(torso, "WaistBackAttachment", Vector3.new(0, -1, 0.5))
			addAtt(torso, "WaistCenterAttachment", Vector3.new(0, -1, 0))
			addAtt(torso, "WaistFrontAttachment", Vector3.new(0, -1, -0.5))
			addAtt(la, "LeftShoulderAttachment", Vector3.new(0, 1, 0))
			addAtt(ra, "RightShoulderAttachment", Vector3.new(0, 1, 0))

			joint("RootJoint", root, torso, CFrame.new(0, 0, 0), CFrame.new(0, 0, 0))
			joint("Neck", torso, head, CFrame.new(0, 1, 0), CFrame.new(0, -0.5, 0))
			joint("Left Shoulder", torso, la, CFrame.new(-1, 0.5, 0), CFrame.new(0.5, 0.5, 0))
			joint("Right Shoulder", torso, ra, CFrame.new(1, 0.5, 0), CFrame.new(-0.5, 0.5, 0))
			joint("Left Hip", torso, ll, CFrame.new(-0.5, -1, 0), CFrame.new(0, 1, 0))
			joint("Right Hip", torso, rl, CFrame.new(0.5, -1, 0), CFrame.new(0, 1, 0))

			local hum = Instance.new("Humanoid")
			pcall(function()
				hum.RigType = Enum.HumanoidRigType.R6
			end)
			hum.Parent = model
			model.PrimaryPart = root
			return model
		end

		local function sanitizeClonedR6(cloned)
			if not (typeof(cloned) == "Instance" and cloned:IsA("Model")) then
				return nil
			end
			if not cloned:FindFirstChild("Torso") or not cloned:FindFirstChild("HumanoidRootPart") then
				pcall(function()
					cloned:Destroy()
				end)
				return nil
			end
			pcall(function()
				for _, d in ipairs(cloned:GetDescendants()) do
					if d:IsA("LuaSourceContainer")
						or d:IsA("ForceField")
						or d:IsA("AlignPosition")
						or d:IsA("AlignOrientation")
						or d:IsA("BodyMover")
						or d:IsA("BallSocketConstraint")
						or d:IsA("NoCollisionConstraint")
						or d.Name == "RagdollLimbPart"
						or d.Name == "Ragdolled"
						or d.Name == "IsGrabbed"
						or d.Name == "PartOwner"
						or d.Name == "FirePlayerPart"
						or d.Name == "CamPart"
						or d.Name == "RagdollTouchedHitbox"
					then
						pcall(function()
							d:Destroy()
						end)
					elseif d:IsA("Motor6D") then
						pcall(function()
							d.Enabled = true
						end)
					end
				end
			end)
			return cloned
		end

		local function cloneInServerR6(userId)
			if not fcPlayers or type(fcPlayers.GetPlayers) ~= "function" then
				return nil
			end
			for _, p in ipairs(fcPlayers:GetPlayers()) do
				if p.UserId == userId and p.Character then
					local srcChar = p.Character
					local cloned = nil
					pcall(function()
						local prev = srcChar.Archivable
						srcChar.Archivable = true
						cloned = srcChar:Clone()
						srcChar.Archivable = prev
					end)
					local clean = sanitizeClonedR6(cloned)
					if clean then
						return clean
					end
				end
			end
			return nil
		end

		local function weldAccessoryToR6(rig, acc)
			local handle = acc:FindFirstChild("Handle")
			if not (handle and handle:IsA("BasePart")) then
				return
			end
			handle.CanCollide = false
			handle.CanQuery = false
			handle.CanTouch = false
			handle.Massless = true
			handle.Anchored = false
			for _, d in ipairs(handle:GetChildren()) do
				if d:IsA("Weld") or d:IsA("WeldConstraint") or d:IsA("Motor6D") then
					pcall(function()
						d:Destroy()
					end)
				end
			end
			local accAtt = handle:FindFirstChildOfClass("Attachment")
			local targetPart = rig:FindFirstChild("Head")
			local rigAtt = nil
			if accAtt then
				for _, d in ipairs(rig:GetDescendants()) do
					if d:IsA("Attachment") and d.Name == accAtt.Name and d.Parent ~= handle then
						rigAtt = d
						targetPart = d.Parent
						break
					end
				end
			end
			if not targetPart then
				return
			end
			local w = Instance.new("Weld")
			w.Name = "AccessoryWeld"
			w.Part0 = handle
			w.Part1 = targetPart
			if accAtt and rigAtt then
				w.C0 = accAtt.CFrame
				w.C1 = rigAtt.CFrame
			else
				pcall(function()
					w.C0 = acc.AttachmentPoint or CFrame.new(0, -0.5, 0)
				end)
			end
			w.Parent = handle
			acc.Parent = rig
		end

		local function buildR6WithAppearance(userId)
			local rig = minimalR6Rig()
			local hum = rig:FindFirstChildOfClass("Humanoid")
			local head = rig:FindFirstChild("Head")
			local appliedAny = false

			-- Try HumanoidDescription first if available
			pcall(function()
				local getDesc = fcPlayers["GetHumanoidDescriptionFromUserIdAsync"] or fcPlayers["GetHumanoidDescriptionFromUserId"]
				if type(getDesc) == "function" and hum then
					local desc = getDesc(fcPlayers, userId)
					if desc then
						-- Apply body colors directly from HumanoidDescription (works on ALL executors!)
						pcall(function()
							local bc = rig:FindFirstChildOfClass("BodyColors") or Instance.new("BodyColors")
							bc.HeadColor3 = desc.HeadColor
							bc.TorsoColor3 = desc.TorsoColor
							bc.LeftArmColor3 = desc.LeftArmColor
							bc.RightArmColor3 = desc.RightArmColor
							bc.LeftLegColor3 = desc.LeftLegColor
							bc.RightLegColor3 = desc.RightLegColor
							bc.Parent = rig
							appliedAny = true
						end)
						for _, mName in ipairs({ "ApplyDescriptionClientServer", "ApplyDescriptionReset", "ApplyDescription" }) do
							local fn = hum[mName]
							if type(fn) == "function" and pcall(fn, hum, desc) then
								appliedAny = true
								break
							end
						end
					end
				end
			end)

			-- Also load GetCharacterAppearanceAsync (public client API: shirts, pants, face, hats, hair, meshes!)
			pcall(function()
				local getApp = fcPlayers["GetCharacterAppearanceAsync"]
				if type(getApp) == "function" then
					local appModel = getApp(fcPlayers, userId)
					if typeof(appModel) == "Instance" then
						for _, item in ipairs(appModel:GetChildren()) do
							if item:IsA("Shirt") or item:IsA("Pants") or item:IsA("ShirtGraphic") or item:IsA("CharacterMesh") then
								for _, old in ipairs(rig:GetChildren()) do
									if old.ClassName == item.ClassName and (not item:IsA("CharacterMesh")) then
										old:Destroy()
									end
								end
								item.Parent = rig
								appliedAny = true
							elseif item:IsA("BodyColors") then
								for _, old in ipairs(rig:GetChildren()) do
									if old:IsA("BodyColors") then
										old:Destroy()
									end
								end
								item.Parent = rig
								appliedAny = true
							elseif item:IsA("Decal") and head then
								local oldFace = head:FindFirstChild("face")
								if oldFace then
									oldFace:Destroy()
								end
								item.Name = "face"
								item.Parent = head
								appliedAny = true
							elseif item:IsA("SpecialMesh") and head then
								local oldMesh = head:FindFirstChildOfClass("SpecialMesh")
								if oldMesh then
									oldMesh:Destroy()
								end
								item.Parent = head
								appliedAny = true
							elseif item:IsA("Accessory") or item:IsA("Hat") then
								pcall(weldAccessoryToR6, rig, item)
								appliedAny = true
							end
						end
						pcall(function()
							appModel:Destroy()
						end)
					end
				end
			end)

			if appliedAny then
				return rig
			end
			pcall(function()
				rig:Destroy()
			end)
			return nil
		end

		local function makeRig(userId)
			local attempts = {
				-- 1) If target player is in this server, clone their exact FTAP R6 rig first!
				function()
					return cloneInServerR6(userId)
				end,
				-- 2) Native R6 HumanoidDescription model builder (produces authentic R6 rig!)
				function()
					local d = fcPlayers["GetHumanoidDescriptionFromUserIdAsync"] or fcPlayers["GetHumanoidDescriptionFromUserId"]
					local c = fcPlayers["CreateHumanoidModelFromDescriptionAsync"] or fcPlayers["CreateHumanoidModelFromDescription"]
					if type(d) == "function" and type(c) == "function" then
						local desc = d(fcPlayers, userId)
						if desc then
							return c(fcPlayers, desc, Enum.HumanoidRigType.R6)
						end
					end
					return nil
				end,
				-- 3) CreateHumanoidModelFromUserId* (accepted if R6, otherwise converted via appearance)
				function()
					for _, fnName in ipairs({ "CreateHumanoidModelFromUserIdAsync", "CreateHumanoidModelFromUserId" }) do
						local f = fcPlayers[fnName]
						if type(f) == "function" then
							local ok, m = pcall(f, fcPlayers, userId)
							if ok and typeof(m) == "Instance" and m:IsA("Model") then
								if m:FindFirstChild("Torso") then
									return m
								end
								pcall(function()
									m:Destroy()
								end)
							end
						end
					end
					return nil
				end,
				-- 4) Universal executor-safe R6 + GetCharacterAppearanceAsync + BodyColors/Clothes/Accessories
				function()
					return buildR6WithAppearance(userId)
				end,
				-- 5) Guaranteed R6 fallback rig
				function()
					return minimalR6Rig()
				end,
			}
			for _, fn in ipairs(attempts) do
				local ok, model = pcall(fn)
				if ok and typeof(model) == "Instance" and model:IsA("Model") then
					local hum = model:FindFirstChildOfClass("Humanoid")
					local root = model:FindFirstChild("HumanoidRootPart")
					local torso = model:FindFirstChild("Torso")
					if hum and root and torso then
						return model, hum, root
					end
					pcall(function()
						model:Destroy()
					end)
				end
			end
			return nil, nil, nil
		end

		local function findSpawnCF()
			local mr = getMyRoot()
			if mr then
				local look = mr.CFrame.LookVector
				local flat = Vector3.new(look.X, 0, look.Z)
				flat = flat.Magnitude > 1e-3 and flat.Unit or Vector3.new(0, 0, -1)
				local nearPos = mr.Position + flat * 8
				local g = findGroundNear(nearPos)
				if g then
					return CFrame.new(g + Vector3.new(0, 3.2, 0))
				end
				return CFrame.new(nearPos + Vector3.new(0, 1.5, 0))
			end
			return CFrame.new(0, 8, 0)
		end

		-- ============================================================================
		-- 5) R6 Animations & Procedural Limb Swing Fallback
		-- ============================================================================
		local function setupAnimations(a)
			a.tracks, a.idleNames = {}, {}
			a.currentTrackName = nil
			a.procedural = false
			a.procJoints = {}

			a.animator = a.hum:FindFirstChildOfClass("Animator")
			if not a.animator then
				pcall(function()
					local an = Instance.new("Animator")
					an.Parent = a.hum
					a.animator = an
				end)
			end
			a.animFolder = Instance.new("Folder")
			a.animFolder.Name = "FJNPC_Anims"
			a.animFolder.Parent = a.rig

			local function load(id, name, prio)
				if not a.animator or not id then
					return nil
				end
				local ok, track = pcall(function()
					local an = Instance.new("Animation")
					an.Name = "FJNPC_" .. name
					an.AnimationId = normalizeAnimId(id)
					an.Parent = a.animFolder
					local t = a.animator:LoadAnimation(an)
					pcall(function()
						t.Priority = prio
					end)
					return t
				end)
				if ok and track then
					a.tracks[name] = track
					return track
				end
				return nil
			end

			for i, id in ipairs(DEFAULT_R6_ANIMS.idle) do
				local nm = "idle" .. tostring(i)
				if load(id, nm, Enum.AnimationPriority and Enum.AnimationPriority.Idle) then
					table.insert(a.idleNames, nm)
				end
			end
			local movPrio = Enum.AnimationPriority and Enum.AnimationPriority.Movement
			load(DEFAULT_R6_ANIMS.walk, "walk", movPrio)
			load(DEFAULT_R6_ANIMS.run, "run", movPrio)
			load(DEFAULT_R6_ANIMS.jump, "jump", movPrio)
			load(DEFAULT_R6_ANIMS.fall, "fall", movPrio)

			if not a.tracks.walk then
				a.procedural = true
			end
			for _, d in ipairs(a.rig:GetDescendants()) do
				if d:IsA("Motor6D") and d.Part1 then
					local jn, pn = string.lower(d.Name), string.lower(d.Part1.Name)
					local limb = string.find(pn, "arm") or string.find(pn, "leg")
					local skip = string.find(jn, "neck") or string.find(jn, "root")
					if limb and not skip then
						local left = string.find(pn, "left") ~= nil
						local isLeg = string.find(pn, "leg") ~= nil
						table.insert(a.procJoints, {
							m = d,
							c0 = d.C0,
							sign = (left and 1 or -1) * (isLeg and 1 or -1),
							amp = isLeg and 0.65 or 0.45,
						})
					end
				end
			end
		end

		local function stopAnimations(a, fade)
			if not a.tracks then
				return
			end
			for _, t in pairs(a.tracks) do
				if t then
					pcall(function()
						t:Stop(fade or 0.1)
					end)
				end
			end
			a.currentTrackName = nil
		end

		local function playTrack(a, name, fade)
			if not name or a.currentTrackName == name then
				return
			end
			local t = a.tracks[name]
			if not t then
				return
			end
			for k, tr in pairs(a.tracks) do
				if tr and k ~= name then
					pcall(function()
						tr:Stop(fade or 0.15)
					end)
				end
			end
			pcall(function()
				t:Play(fade or 0.15)
			end)
			a.currentTrackName = name
		end

		local function updateAnimations(a, now, moving)
			local hum = a.hum
			if not hum then
				return
			end
			if a.ragdolled or a.heldByFigureGrab then
				stopAnimations(a, 0.06)
				return
			end
			if a.procedural then
				local v = a.root and a.root.AssemblyLinearVelocity.Magnitude or 0
				local amt = math.clamp(v / math.max(Config.WalkSpeed, 1), 0, 1)
				local ph = now * 9.5
				for _, j in ipairs(a.procJoints) do
					if j.m and j.m.Parent and j.m.Enabled then
						pcall(function()
							j.m.C0 = j.c0 * CFrame.Angles(0, 0, math.sin(ph) * j.amp * amt * j.sign)
						end)
					end
				end
				return
			end
			local desired
			local st = hum:GetState()
			local airborne = (Enum.Material and hum.FloorMaterial == Enum.Material.Air)
				or (Enum.HumanoidStateType and st == Enum.HumanoidStateType.Freefall)
			if Enum.HumanoidStateType and st == Enum.HumanoidStateType.Jumping then
				desired = a.tracks.jump and "jump" or "fall"
			elseif airborne then
				desired = "fall"
			elseif moving then
				desired = (a.curSpeed >= (Config.RunSpeed - 3) and a.tracks.run) and "run" or "walk"
			else
				if now >= a.nextIdleSwitch then
					a.nextIdleSwitch = now + RNG:NextNumber(4, 8)
					if #a.idleNames > 0 then
						a.idleIndex = RNG:NextInteger(1, #a.idleNames)
					end
				end
				desired = a.idleNames[a.idleIndex] or "idle1"
			end
			if not desired or not a.tracks[desired] then
				stopAnimations(a, 0.2)
				return
			end
			playTrack(a, desired, 0.16)
		end

		-- ============================================================================
		-- 6) Gaze & Body Orientation
		-- ============================================================================
		local function setupFacing(a)
			if not Config.UseFacingConstraint then
				a.useFaceOri = false
				return
			end
			local ok = pcall(function()
				local att = Instance.new("Attachment")
				att.Name = "FJNPC_FaceAtt"
				att.Parent = a.root
				local ao = Instance.new("AlignOrientation")
				ao.Name = "FJNPC_FaceOri"
				pcall(function()
					ao.Mode = Enum.OrientationAlignmentMode.OneAttachment
				end)
				ao.Attachment0 = att
				ao.RigidityEnabled = false
				if not pcall(function()
					ao.MaxTorque = 26000
				end) then
					pcall(function()
						ao.MaxTorque = Vector3.new(0, 26000, 0)
					end)
				end
				pcall(function()
					ao.MaxAxesTorque = Vector3.new(0, 26000, 0)
				end)
				pcall(function()
					ao.MaxAngularVelocity = 9
				end)
				ao.Responsiveness = 11
				setProp(ao, "ReactionTorqueEnabled", false)
				ao.Parent = a.root
				a.faceAtt, a.faceOri = att, ao
			end)
			a.useFaceOri = ok and a.faceOri ~= nil
		end

		local function setFacing(a, on)
			if a.faceOri then
				pcall(function()
					a.faceOri.Enabled = on
				end)
			end
		end

		local function applyFacing(a, dir, dt)
			local root = a.root
			if not (root and root.Parent) or dir.Magnitude < 0.01 then
				return
			end
			local rotated = CFrame.Angles(0, a.glanceYaw, 0) * dir
			local look = Vector3.new(rotated.X, 0, rotated.Z)
			if look.Magnitude < 0.01 then
				return
			end
			local targetCF = CFrame.lookAt(root.Position, root.Position + look)
			if a.useFaceOri and a.faceOri then
				pcall(function()
					a.faceOri.CFrame = targetCF
				end)
			else
				local lv = root.CFrame.LookVector
				local curYaw = math.atan2(-lv.X, -lv.Z)
				local tgtYaw = math.atan2(-look.X, -look.Z)
				local nYaw = curYaw + angleDelta(tgtYaw, curYaw) * math.min(dt * 4, 1)
				pcall(function()
					root.CFrame = CFrame.new(root.Position) * CFrame.Angles(0, nYaw, 0)
				end)
			end
		end
		local function updateLook(a, now, dt, target, walking)
			if not Config.LookAround or a.ragdolled or a.heldByFigureGrab then
				return
			end
			local root = a.root
			if not (root and root.Parent) then
				return
			end
			if now >= a.nextPitchChange then
				local lo, hi = walking and 1.2 or 1.9, walking and 2.6 or 4.2
				a.nextPitchChange = now + RNG:NextNumber(lo, hi)
				local rel = root.CFrame:Inverse() * target
				local horiz = math.max(math.sqrt(rel.X * rel.X + rel.Z * rel.Z), 0.001)
				if RNG:NextNumber() < 0.45 then
					a.lookPitchTarget = math.clamp(math.atan2(rel.Y, horiz), -Config.HeadPitchMax, Config.HeadPitchMax)
				else
					a.lookPitchTarget = math.rad(RNG:NextNumber(-10, 11))
				end
			end
			a.lookPitch = a.lookPitch + (a.lookPitchTarget - a.lookPitch) * math.min(dt * 3.4, 1)
			if a.neck and a.neck.Parent and a.neckC0 then
				-- R6 Neck C0 has a -90 deg X base rotation in standard R6, or identity in minimalRig
				pcall(function()
					a.neck.C0 = a.neckC0 * CFrame.Angles(a.lookPitch, 0, 0)
				end)
			end
			if now >= a.nextGlance then
				local gmin = walking and (Config.GlanceIntervalMin * 0.55) or Config.GlanceIntervalMin
				local gmax = walking and (Config.GlanceIntervalMax * 0.65) or Config.GlanceIntervalMax
				a.nextGlance = now + RNG:NextNumber(gmin, gmax)
				if RNG:NextNumber() < Config.GlanceChance then
					local side = RNG:NextNumber() < 0.5 and -1 or 1
					a.glanceYawTarget = side * RNG:NextNumber(Config.GlanceYawMax * 0.45, Config.GlanceYawMax)
					a.glanceUntil = now + RNG:NextNumber(Config.GlanceDuration * 0.6, Config.GlanceDuration * 1.4)
				else
					a.glanceYawTarget = 0
					a.glanceUntil = 0
				end
			end
			if now > a.glanceUntil then
				a.glanceYawTarget = 0
			end
			a.glanceYaw = a.glanceYaw + (a.glanceYawTarget - a.glanceYaw) * math.min(dt * 3.2, 1)
		end

				-- ============================================================================
		-- 7) True FTAP R6 Ragdoll (RagdollLimbPart + FTAP BallSocketConstraints)
		-- ============================================================================
		local function installFTAPRagdollRigging(a)
			local rig = a.rig
			local torso = rig and rig:FindFirstChild("Torso")
			if not torso then
				return
			end
			a.ftapLimbData = {}
			a.noCollides = {}

			local flag = a.hum:FindFirstChild("Ragdolled")
			if not flag then
				flag = Instance.new("BoolValue")
				flag.Name = "Ragdolled"
				flag.Value = false
				flag.Parent = a.hum
			end
			a.ragdollBool = flag

			for limbName, spec in pairs(FTAP_LIMB_SOCKETS) do
				local limb = rig:FindFirstChild(limbName)
				if limb and limb:IsA("BasePart") then
					-- 1) Invisible RagdollLimbPart welded to limb (defeats Roblox R6 Humanoid CanCollide reset!)
					local rlp = limb:FindFirstChild("RagdollLimbPart")
					if not rlp then
						rlp = Instance.new("Part")
						rlp.Name = "RagdollLimbPart"
						rlp.Size = Vector3.new(
							math.max(limb.Size.X * 0.78, 0.5),
							math.max(limb.Size.Y * 0.82, 0.5),
							math.max(limb.Size.Z * 0.78, 0.5)
						)
						rlp.CFrame = limb.CFrame
						rlp.Transparency = 1
						rlp.CanCollide = false
						rlp.CanQuery = false
						rlp.CanTouch = false
						rlp.Massless = true
						rlp.Anchored = false
						pcall(function()
							rlp.TopSurface = Enum.SurfaceType.Smooth
							rlp.BottomSurface = Enum.SurfaceType.Smooth
						end)
						rlp.Parent = limb
						local wc = Instance.new("WeldConstraint")
						wc.Name = "RagdollLimbWeld"
						wc.Part0 = limb
						wc.Part1 = rlp
						wc.Parent = rlp
					end

					-- 2) FTAP BallSocketConstraint inside the limb matching tbl7.ACOffset!
					local attTorso = Instance.new("Attachment")
					attTorso.Name = "FTAP_TorsoAtt_" .. limbName
					attTorso.Position = spec.torsoPos
					attTorso.Parent = torso

					local attLimb = Instance.new("Attachment")
					attLimb.Name = "FTAP_LimbAtt"
					attLimb.Position = spec.limbPos
					attLimb.Parent = limb

					local socket = Instance.new("BallSocketConstraint")
					socket.Name = "BallSocketConstraint"
					if spec.torsoFirst then
						socket.Attachment0 = attTorso
						socket.Attachment1 = attLimb
					else
						socket.Attachment0 = attLimb
						socket.Attachment1 = attTorso
					end
					socket.LimitsEnabled = true
					socket.UpperAngle = spec.upper
					socket.TwistLimitsEnabled = true
					socket.TwistLowerAngle = -spec.twist
					socket.TwistUpperAngle = spec.twist
					socket.Enabled = false
					socket.Parent = limb

					local nc = Instance.new("NoCollisionConstraint")
					nc.Name = "FTAP_LimbTorsoNC"
					pcall(function()
						nc.Part0 = torso
						nc.Part1 = limb
						nc.Enabled = true
						nc.Parent = limb
					end)
					table.insert(a.noCollides, nc)

					a.ftapLimbData[limbName] = {
						limb = limb,
						rlp = rlp,
						socket = socket,
						attTorso = attTorso,
						attLimb = attLimb,
						spec = spec,
					}
				end
			end

			-- Prevent Left/Right legs and arms from tangling inside each other during ragdoll
			local ll, rl = rig:FindFirstChild("Left Leg"), rig:FindFirstChild("Right Leg")
			if ll and rl then
				pcall(function()
					local nc = Instance.new("NoCollisionConstraint")
					nc.Part0 = ll
					nc.Part1 = rl
					nc.Enabled = true
					nc.Parent = ll
					table.insert(a.noCollides, nc)
				end)
			end
		end

		local function enableRagdoll(a, reason)
			if not a or a.dead then
				return
			end
			local rig, hum, root = a.rig, a.hum, a.root
			if not (rig and hum and root and rig.Parent) then
				return
			end
			if a.ragdolled then
				return
			end

			a.ragdolled = true
			a.waypoints = nil
			a.ragdollReason = reason or "manual"
			stopAnimations(a, 0.04)
			setFacing(a, false)

			if a.ragdollBool then
				a.ragdollBool.Value = true
			end

			hum.AutoRotate = false
			hum.PlatformStand = true
			hum.WalkSpeed = 0
			hum.JumpPower = 0
			pcall(function()
				hum:SetStateEnabled(Enum.HumanoidStateType.GettingUp, false)
				hum:SetStateEnabled(Enum.HumanoidStateType.FallingDown, false)
				hum:SetStateEnabled(Enum.HumanoidStateType.Running, false)
				hum:SetStateEnabled(Enum.HumanoidStateType.Jumping, false)
				hum:ChangeState(Enum.HumanoidStateType.Physics)
			end)

			pcall(function()
				root.CanCollide = false
				root.Anchored = false
			end)

			-- Keep RootJoint (HumanoidRootPart <-> Torso) ENABLED so Torso & HRP stay unified;
			-- disable only the 5 limb Motor6Ds and engage FTAP BallSockets + RagdollLimbParts!
			for _, m in ipairs(a.motors) do
				if m and m.Parent then
					local jn = string.lower(m.Name)
					local isRootJoint = string.find(jn, "root") ~= nil
					if not isRootJoint then
						pcall(function()
							m.C0 = a.origC0[m] or m.C0
							m.Enabled = false
						end)
					else
						pcall(function()
							m.Enabled = true
						end)
					end
				end
			end

			local collideOn = not a.heldByFigureGrab
			for _, info in pairs(a.ftapLimbData or {}) do
				if info.socket and info.socket.Parent then
					info.socket.Enabled = true
				end
				if info.rlp and info.rlp.Parent then
					info.rlp.CanCollide = collideOn
				end
			end
		end

		local function disableRagdoll(a)
			if not a or not a.ragdolled then
				return
			end
			if a.heldByFigureGrab then
				return
			end
			local rig, hum, root = a.rig, a.hum, a.root

			for _, info in pairs(a.ftapLimbData or {}) do
				pcall(function()
					if info.rlp and info.rlp.Parent then
						info.rlp.CanCollide = false
					end
					if info.socket and info.socket.Parent then
						info.socket.Enabled = false
						info.socket.LimitsEnabled = true
						info.socket.UpperAngle = info.spec.upper
						info.socket.TwistLimitsEnabled = true
					end
					if info.attTorso and info.attTorso.Parent then
						info.attTorso.Position = info.spec.torsoPos
					end
					if info.attLimb and info.attLimb.Parent then
						info.attLimb.Position = info.spec.limbPos
					end
				end)
			end

			for _, m in ipairs(a.motors) do
				if m and m.Parent then
					pcall(function()
						if a.origC0[m] then
							m.C0 = a.origC0[m]
						end
						m.Enabled = true
					end)
				end
			end

			a.ragdolled = false
			if a.ragdollBool then
				a.ragdollBool.Value = false
			end
			if not (rig and hum and root and rig.Parent) then
				return
			end

			a.lookPitch, a.glanceYaw = 0, 0
			pcall(function()
				hum:SetStateEnabled(Enum.HumanoidStateType.GettingUp, true)
				hum:SetStateEnabled(Enum.HumanoidStateType.FallingDown, true)
				hum:SetStateEnabled(Enum.HumanoidStateType.Running, true)
				hum:SetStateEnabled(Enum.HumanoidStateType.Jumping, true)
			end)
			hum.AutoRotate = false
			hum.PlatformStand = false
			hum.WalkSpeed = Config.WalkSpeed
			hum.JumpPower = Config.JumpPower
			pcall(function()
				hum:ChangeState(Enum.HumanoidStateType.GettingUp)
			end)
			setFacing(a, true)

			pcall(function()
				local lv = root.CFrame.LookVector
				local yaw = math.atan2(-lv.X, -lv.Z)
				local g = findGroundNear(root.Position, { rig })
				local y = g and (g.Y + 3.0) or (root.Position.Y + 2.2)
				local uprightCF = CFrame.new(root.Position.X, y, root.Position.Z) * CFrame.Angles(0, yaw, 0)
				if type(rig.PivotTo) == "function" then
					rig:PivotTo(uprightCF)
				else
					root.CFrame = uprightCF
				end
				for _, p in ipairs(a.parts) do
					if p and p.Parent then
						p.AssemblyLinearVelocity = Vector3.zero
						p.AssemblyAngularVelocity = Vector3.zero
					end
				end
			end)
			a.currentTrackName = nil
			a.nextRepath = 0
			a.pathDirty = true
			a.lastProgressTime = os.clock()
			a.lastProgressPos = root.Position
			a.prevVelY = 0
			a.wasAirborne = false
		end

		local function scheduleGetUp(a, seconds)
			-- v23: perm ragdoll - a clone that ragdolls from a hit/throw never gets up
			if Config.PermRagdoll and a and (a.ragdollReason == "manual" or a.ragdollReason == "fling" or a.ragdollReason == "figure_grab") then
				return
			end
			a.ragdollToken = a.ragdollToken + 1
			local token = a.ragdollToken
			task.delay(seconds, function()
				if M.Running and token == a.ragdollToken and not a.heldByFigureGrab and not a.dead then
					disableRagdoll(a)
					if refreshCloneDropdown then
						refreshCloneDropdown()
					end
				end
			end)
		end

		local function fling(a, dir, power)
			local root = a.root
			local torso = a.rig and a.rig:FindFirstChild("Torso")
			if not (root and root.Parent) then
				return
			end
			local base = dir * power + Vector3.new(0, Config.FlingLift, 0)
			local spin = Vector3.new(
				(RNG:NextNumber() - 0.5) * 18,
				(RNG:NextNumber() - 0.5) * 18,
				(RNG:NextNumber() - 0.5) * 18
			)
			pcall(function()
				root.AssemblyLinearVelocity = base
				root.AssemblyAngularVelocity = spin
				if torso then
					torso.AssemblyLinearVelocity = base
					torso.AssemblyAngularVelocity = spin
				end
			end)
			for _, p in ipairs(a.parts) do
				if p and p.Parent and p ~= root and p ~= torso then
					pcall(function()
						p.AssemblyLinearVelocity = base + Vector3.new(
							(RNG:NextNumber() - 0.5) * 8,
							(RNG:NextNumber() - 0.5) * 8,
							(RNG:NextNumber() - 0.5) * 8
						)
					end)
				end
			end
		end

		-- v23: the thrown bot explodes like a bomb
		local function explodeBot(a)
			if not Config.BombOnFling then
				return
			end
			local root = a and a.root
			if not (root and root.Parent) then
				return
			end
			local pos = root.Position
			local radius = Config.BombRadius or 26

			pcall(function()
				local ball = Instance.new("Part")
				ball.Shape = Enum.PartType.Ball
				ball.Material = Enum.Material.Neon
				ball.Color = Color3.fromRGB(255, 145, 20)
				ball.Size = Vector3.new(2, 2, 2)
				ball.Anchored = true
				ball.CanCollide = false
				pcall(function()
					ball.CanQuery = false
					ball.CanTouch = false
				end)
				ball.CFrame = CFrame.new(pos)
				ball.Parent = workspace

				local light = Instance.new("PointLight")
				light.Brightness = 6
				light.Range = radius
				light.Color = Color3.fromRGB(255, 170, 40)
				light.Parent = ball

				if fcTweenService then
					fcTweenService:Create(ball, TweenInfo.new(0.5, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
						Size = Vector3.new(radius * 1.7, radius * 1.7, radius * 1.7),
						Transparency = 1,
					}):Play()
					fcTweenService:Create(light, TweenInfo.new(0.5), { Brightness = 0 }):Play()
				end
				pcall(function()
					local snd = Instance.new("Sound")
					snd.SoundId = "rbxassetid://5801257793"
					snd.Volume = 1.4
					snd.Parent = ball
					snd:Play()
				end)
				pcall(function()
					game:GetService("Debris"):AddItem(ball, 0.9)
				end)
			end)

			for _, plr in ipairs(fcPlayers:GetPlayers()) do
				if plr ~= fcLP then
					local ch = plr.Character
					local hrp = ch and (ch:FindFirstChild("HumanoidRootPart") or ch:FindFirstChild("Torso"))
					local hum = ch and ch:FindFirstChildOfClass("Humanoid")
					if hrp and hum and hum.Health > 0 and (hrp.Position - pos).Magnitude <= radius then
						-- v23: the blast launches players away with high speed + spin
						pcall(function()
							local dir = hrp.Position - pos
							if dir.Magnitude < 0.1 then
								dir = Vector3.new(0, 1, 0)
							end
							local away = Vector3.new(dir.X, 0, dir.Z)
							if away.Magnitude < 0.1 then
								away = Vector3.new(math.random(-1, 1), 0, math.random(-1, 1))
							end
							away = away.Unit
							local power = Config.BombPower or 170
							local falloff = 1
							local d = (hrp.Position - pos).Magnitude
							if radius > 0 then
								falloff = math.clamp(1 - (d / radius) * 0.55, 0.45, 1)
							end
							hrp.AssemblyLinearVelocity = away * (power * falloff) + Vector3.new(0, power * 0.55, 0)
							hrp.AssemblyAngularVelocity = Vector3.new(math.random(-40, 40), math.random(-40, 40), math.random(-40, 40))
							task.delay(0.15, function()
								pcall(function()
									if hrp and hrp.Parent then
										hrp.AssemblyLinearVelocity = hrp.AssemblyLinearVelocity + Vector3.new(0, power * 0.25, 0)
									end
								end)
							end)
						end)
						if Config.BombKill then
							pcall(function()
								if tbl12 and tbl12.Kill then
									tbl12.Kill(plr)
								end
							end)
						end
					end
				end
			end
			fcNotify("Bomb", "Bot exploded - " .. tostring(math.floor(radius)) .. " studs cleared.", 2.5)
		end

		local function toggleRagdoll(a)
			if not M.Running or not a or a.heldByFigureGrab then
				return
			end
			if a.ragdolled then
				a.ragdollToken = a.ragdollToken + 1
				disableRagdoll(a)
			else
				enableRagdoll(a, "manual")
				local torso = a.rig and a.rig:FindFirstChild("Torso")
				if torso then
					pcall(function()
						torso.AssemblyAngularVelocity = Vector3.new((RNG:NextNumber() - 0.5) * 10, 0, (RNG:NextNumber() - 0.5) * 10)
						torso.AssemblyLinearVelocity = Vector3.new((RNG:NextNumber() - 0.5) * 6, -4, (RNG:NextNumber() - 0.5) * 6)
					end)
				end
			end
		end

		-- ============================================================================
		-- 8) Rig Prep, Spawn, Queue & Cleanup
		-- ============================================================================
		local function prepareRig(a, model, hum, root)
			model.Name = "FJClone_" .. tostring(a.spec.id) .. "_" .. tostring(a.seq)
			pcall(function()
				model:SetAttribute("FigureClone", true)
			end)
			if not setProp(hum, "DisplayName", tostring(a.spec.display)) then
				model.Name = tostring(a.spec.display)
			end
			setProp(hum, "NameDisplayDistance", 80)
			pcall(function()
				hum.DisplayDistanceType = Enum.HumanoidDisplayDistanceType.Viewer
			end)
			hum.BreakJointsOnDeath = false
			setProp(hum, "RequiresNeck", false)
			pcall(function()
				hum:SetStateEnabled(Enum.HumanoidStateType.Dead, false)
			end)
			hum.MaxHealth, hum.Health = 1000, 1000
			hum.AutoRotate = false
			pcall(function()
				hum.UseJumpPower = true
			end)
			hum.JumpPower = Config.JumpPower
			setProp(hum, "JumpHeight", 7.2)
			hum.WalkSpeed = Config.WalkSpeed

			a.motors, a.origC0, a.parts = {}, {}, {}
			a.neck, a.rootJoint = nil, nil
			a.neckC0, a.rootJointC0 = nil, nil
			for _, d in ipairs(model:GetDescendants()) do
				if d:IsA("LuaSourceContainer") then
					pcall(function()
						d:Destroy()
					end)
				elseif d:IsA("Motor6D") then
					table.insert(a.motors, d)
					a.origC0[d] = d.C0
					local jn = string.lower(d.Name)
					if string.find(jn, "neck") then
						a.neck, a.neckC0 = d, d.C0
					elseif string.find(jn, "root") then
						a.rootJoint, a.rootJointC0 = d, d.C0
					end
				elseif d:IsA("BasePart") then
					table.insert(a.parts, d)
					setProp(d, "Anchored", false)
					if d.Name == "HumanoidRootPart" then
						setProp(d, "CanCollide", false)
					elseif d.Name == "Head" or d.Name == "Torso" then
						setProp(d, "CanCollide", true)
					end
				end
			end
			model.PrimaryPart = root
			installFTAPRagdollRigging(a)
		end

		local function onTouched(a, hit)
			if a.heldByFigureGrab or a.ragdolled or not a.root then
				return
			end
			if not hit or not hit:IsA("BasePart") then
				return
			end
			if a.rig and hit:IsDescendantOf(a.rig) then
				return
			end
			local v = a.root.AssemblyLinearVelocity
			if v and v.Magnitude > Config.ImpactThreshold then
				enableRagdoll(a, "impact")
				scheduleGetUp(a, Config.RagdollTime)
			end
		end

		local function newActorState(spec, seq)
			local now = os.clock()
			local a = {
				seq = seq,
				spec = spec,
				botProxy = nil,
				rig = nil,
				hum = nil,
				root = nil,
				parts = {},
				motors = {},
				origC0 = {},
				ftapLimbData = {},
				noCollides = {},
				ragdollBool = nil,

				animator = nil,
				animFolder = nil,
				tracks = {},
				idleNames = {},
				currentTrackName = nil,
				procedural = false,
				procJoints = {},
				nextIdleSwitch = now + 3,
				idleIndex = 1,

				neck = nil,
				rootJoint = nil,
				neckC0 = nil,
				rootJointC0 = nil,
				lookPitch = 0,
				lookPitchTarget = 0,
				nextPitchChange = now + 1.2,
				glanceYaw = 0,
				glanceYawTarget = 0,
				glanceUntil = 0,
				nextGlance = now + 1.5,

				faceAtt = nil,
				faceOri = nil,
				useFaceOri = false,

				path = nil,
				computing = false,
				pathDirty = true,
				pathConn = nil,
				touchedConn = nil,
				waypoints = nil,
				wpIndex = 2,
				nextRepath = 0,
				lastJump = 0,
				moveVec = Vector3.zero,
				curSpeed = 0,
				lastProgressPos = nil,
				lastProgressTime = now,

				heldByFigureGrab = false,
				ragdolled = false,
				ragdollToken = 0,
				ragdollReason = nil,

				prevVelY = 0,
				wasAirborne = false,
				fallPeak = 0,
				landCooldown = 0,

				nextLOSTime = 0,
				lastLOSClear = false,
				lastLOSHit = nil,

				joinedAt = now,
				dead = false,
			}
			return a
		end

		local function cleanupActor(a)
			if not a then
				return
			end
			a.dead = true
			a.heldByFigureGrab = false
			a.ragdollToken = (a.ragdollToken or 0) + 1
			if a.botProxy then
				if tbl7 and tbl7.SelectedPlayersAC and tbl7.SelectedPlayersAC[a.botProxy] then
					tbl7.SelectedPlayersAC[a.botProxy] = nil
					if tbl12 and tbl12.SyncACPoseTargets then
						pcall(tbl12.SyncACPoseTargets)
					end
				end
				a.botProxy.Parent = nil
				a.botProxy.Character = nil
			end
			if a.touchedConn then
				pcall(function()
					a.touchedConn:Disconnect()
				end)
			end
			if a.pathConn then
				pcall(function()
					a.pathConn:Disconnect()
				end)
			end
			stopAnimations(a, 0)
			for _, o in pairs({ a.faceOri, a.faceAtt, a.animFolder, a.rig }) do
				if typeof(o) == "Instance" then
					pcall(function()
						o:Destroy()
					end)
				end
			end
			for k, _ in pairs(a) do
				if k ~= "spec" and k ~= "dead" and k ~= "botProxy" then
					a[k] = nil
				end
			end
		end

		local function removeActor(a)
			if not a then
				return
			end
			for i, v in ipairs(actors) do
				if v == a then
					table.remove(actors, i)
					break
				end
			end
			cleanupActor(a)
			if selected == a then
				selected = actors[#actors] or nil
			end
			if refreshCloneDropdown then
				refreshCloneDropdown()
			end
			if syncBotsIntoFigureGrab then
				syncBotsIntoFigureGrab()
			end
		end

		local function spawnActor(spec, withNotice)
			if not M.Running or not spec or flag11 then
				return nil
			end
			while #actors >= Config.MaxClones and #actors > 0 do
				removeActor(actors[1])
			end
			local model, hum, root = makeRig(spec.id)
			if not M.Running or flag11 then
				if model then
					pcall(function()
						model:Destroy()
					end)
				end
				return nil
			end
			if not (model and hum and root) then
				setStatus("Failed to load avatar: " .. tostring(spec.display))
				return nil
			end

			botCounter = botCounter + 1
			local a = newActorState(spec, botCounter)
			a.rig, a.hum, a.root = model, hum, root
			prepareRig(a, model, hum, root)
			model.Parent = workspace
			local spawnCF = findSpawnCF()
			if type(model.PivotTo) == "function" then
				pcall(function()
					model:PivotTo(spawnCF)
				end)
			else
				root.CFrame = spawnCF
			end
			setupAnimations(a)
			setupFacing(a)

			-- Create Figure Grab (AutoClicker) bot proxy: "DisplayName (@Username) (Bot)"
			a.botProxy = {
				__isFigureBot = true,
				Name = tostring(spec.user) .. "_Bot" .. tostring(a.seq),
				RealUserName = tostring(spec.user),
				DisplayName = tostring(spec.display),
				UserId = spec.id * 1000 + a.seq,
				__isFakeKickable = true,
				Character = model,
				Parent = fcPlayers,
				__ensureBotRagdoll = function()
					if a.dead then
						return
					end
					a.heldByFigureGrab = true
					a.ragdollToken = a.ragdollToken + 1
					if not a.ragdolled then
						enableRagdoll(a, "figure_grab")
					end
				end,
				__releaseBotRagdoll = function()
					if a.dead then
						return
					end
					a.heldByFigureGrab = false
					disableRagdoll(a)
					-- v23: firlatilarak birakildiysa bomba gibi patla
					task.delay(0.08, function()
						pcall(function()
							local rt = a.root
							if rt and rt.Parent and rt.AssemblyLinearVelocity.Magnitude > 45 then
								explodeBot(a)
							end
						end)
					end)
				end,
			}

			pcall(function()
				if root.Touched then
					a.touchedConn = root.Touched:Connect(function(hit)
						onTouched(a, hit)
					end)
				end
			end)
			pcall(function()
				if fcPathfinding and type(fcPathfinding.CreatePath) == "function" then
					a.path = fcPathfinding:CreatePath({
						AgentRadius = 2,
						AgentHeight = 5,
						AgentCanJump = true,
						AgentJumpHeight = 7.2,
						AgentMaxSlope = 50,
						WaypointSpacing = 4,
					})
					if a.path and a.path.Blocked then
						a.pathConn = a.path.Blocked:Connect(function()
							a.pathDirty = true
							a.nextRepath = 0
						end)
					end
				end
			end)
			a.lastProgressPos = root.Position
			table.insert(actors, a)
			selected = a
			if withNotice ~= false then
				joinNotice(spec)
			end
			if refreshCloneDropdown then
				refreshCloneDropdown()
			end
			if syncBotsIntoFigureGrab then
				syncBotsIntoFigureGrab()
			end
			setStatus(string.format("Active | %d/%d bots (%s)", #actors, Config.MaxClones, tostring(spec.display)))
			return a
		end

		local function queueJoin(spec, delaySec)
			local waitSec = tonumber(delaySec)
			if waitSec == nil then
				waitSec = Config.JoinDelay
			end
			if waitSec <= 0 then
				task.spawn(function()
					spawnActor(spec, true)
				end)
				return
			end
			local token = {}
			table.insert(joinQueue, token)
			setStatus(string.format("Joining in %.1fs: %s", waitSec, tostring(spec.display)))
			task.spawn(function()
				task.wait(waitSec)
				local found = false
				for i, t in ipairs(joinQueue) do
					if t == token then
						table.remove(joinQueue, i)
						found = true
						break
					end
				end
				if not found or not M.Running or flag11 then
					return
				end
				spawnActor(spec, true)
			end)
		end

		-- ============================================================================
		-- 9) Hybrid Raycast + Pathfinding Follower & Hard Landing
		-- ============================================================================
		local function lineOfSight(a, fromPos, toPos, now)
			if now and now < a.nextLOSTime then
				return a.lastLOSClear, a.lastLOSHit
			end
			if now then
				a.nextLOSTime = now + 0.12
			end
			local d = toPos - fromPos
			if d.Magnitude < 0.5 then
				a.lastLOSClear, a.lastLOSHit = true, nil
				return true, nil
			end
			if not _losParams then
				local okP, p = pcall(RaycastParams.new)
				if okP and p then
					p.FilterType = Enum.RaycastFilterType.Exclude
					_losParams = p
				end
			end
			if _losParams then
				pcall(function()
					local l = {}
					if fcLP and fcLP.Character then
						table.insert(l, fcLP.Character)
					end
					for _, other in ipairs(actors) do
						if other.rig then
							table.insert(l, other.rig)
						end
					end
					_losParams.FilterDescendantsInstances = l
				end)
			end
			local ok, hit = pcall(function()
				return workspace:Raycast(fromPos + Vector3.new(0, 0.6, 0), d, _losParams)
			end)
			if not ok then
				a.lastLOSClear, a.lastLOSHit = false, nil
				return false, nil
			end
			a.lastLOSClear, a.lastLOSHit = (hit == nil), hit
			return (hit == nil), hit
		end

		local function tryJump(a, now)
			if (now - a.lastJump) < 0.8 then
				return
			end
			local hum = a.hum
			if not hum or (Enum.Material and hum.FloorMaterial == Enum.Material.Air) then
				return
			end
			a.lastJump = now
			pcall(function()
				hum.Jump = true
			end)
		end

		local function computePath(a, start, goal)
			if not a.path or a.computing then
				return
			end
			a.computing = true
			task.spawn(function()
				local ok = pcall(function()
					a.path:ComputeAsync(start, goal)
				end)
				if a.dead then
					return
				end
				if ok and a.path and Enum.PathStatus and a.path.Status == Enum.PathStatus.Success then
					local wps = a.path:GetWaypoints()
					if type(wps) == "table" and #wps > 0 then
						a.waypoints, a.wpIndex = wps, math.min(2, #wps)
					else
						a.waypoints = nil
					end
				else
					a.waypoints = nil
				end
				a.pathDirty = false
				a.computing = false
			end)
		end

		local function pickGoal(a, root, target, dist, now)
			local clear, hit = lineOfSight(a, root.Position, target, now)
			if clear and dist < Config.DirectChaseRange then
				a.waypoints = nil
				return target, false
			end
			if hit and hit.Distance and hit.Distance < 5.5 then
				local rise = hit.Position.Y - root.Position.Y
				if rise > -1.5 and rise < 2.6 then
					tryJump(a, now)
					return target, false
				end
			end
			if a.path and (a.pathDirty or now >= a.nextRepath or not a.waypoints) then
				a.nextRepath = now + Config.RepathInterval
				computePath(a, root.Position, target)
			end
			if a.waypoints and a.waypoints[a.wpIndex] then
				local wp = a.waypoints[a.wpIndex]
				if (root.Position - wp.Position).Magnitude < 3.2 and a.wpIndex < #a.waypoints then
					a.wpIndex = a.wpIndex + 1
					wp = a.waypoints[a.wpIndex]
				end
				if wp and wp.Position then
					return wp.Position, (Enum.PathWaypointAction and wp.Action == Enum.PathWaypointAction.Jump)
				end
			end
			return target, (target.Y - root.Position.Y > 2.5)
		end

		local function updateStuck(a, target, now)
			local root = a.root
			if not a.lastProgressPos or (root.Position - a.lastProgressPos).Magnitude > 2.0 then
				a.lastProgressPos, a.lastProgressTime = root.Position, now
				return
			end
			if now - a.lastProgressTime < Config.StuckAfter then
				return
			end
			a.lastProgressTime, a.lastProgressPos = now, root.Position
			a.waypoints, a.pathDirty, a.nextRepath = nil, true, 0
			tryJump(a, now)
			pcall(function()
				local side = RNG:NextNumber() < 0.5 and -1 or 1
				root.CFrame = root.CFrame * CFrame.new(side * 3, 0.5, 0)
			end)
			if Config.StuckTeleport then
				task.delay(1.2, function()
					if a.dead or not a.rig or not a.root or not M.Running or a.heldByFigureGrab then
						return
					end
					local r = getMyRoot()
					if not r then
						return
					end
					if (a.root.Position - r.Position).Magnitude < Config.FollowDistance + 4 then
						return
					end
					local g = findGroundNear(target, { a.rig })
					if g then
						pcall(function()
							local lv = a.root.CFrame.LookVector
							local yaw = math.atan2(-lv.X, -lv.Z)
							local cf = CFrame.new(g + Vector3.new(0, 3.2, 0)) * CFrame.Angles(0, yaw, 0)
							if type(a.rig.PivotTo) == "function" then
								a.rig:PivotTo(cf)
							else
								a.root.CFrame = cf
							end
							a.root.AssemblyLinearVelocity = Vector3.zero
						end)
					end
				end)
			end
		end

		local function updateHardLanding(a, now)
			local root, hum = a.root, a.hum
			if not (root and hum and root.Parent) then
				return
			end
			if a.heldByFigureGrab or a.ragdolled then
				a.prevVelY = 0
				a.fallPeak = 0
				a.wasAirborne = false
				return
			end
			if now < a.landCooldown then
				return
			end
			local v = root.AssemblyLinearVelocity
			local vy = v and v.Y or 0
			local grounded = not (Enum.Material and hum.FloorMaterial == Enum.Material.Air)
			if not grounded and vy < -6 then
				a.wasAirborne = true
				a.fallPeak = math.min(a.fallPeak, vy)
			end
			if grounded and a.wasAirborne then
				local impact = math.abs(a.fallPeak)
				if impact >= Config.HardLandingVelocity then
					a.landCooldown = now + 1.2
					enableRagdoll(a, "hard landing (" .. math.floor(impact) .. ")")
					scheduleGetUp(a, Config.RagdollTime)
					if refreshCloneDropdown then
						refreshCloneDropdown()
					end
				end
				a.wasAirborne = false
				a.fallPeak = 0
			end
			if grounded then
				a.fallPeak = 0
			end
			a.prevVelY = vy
		end

		-- ============================================================================
		-- 10) Main Heartbeat & Stepped Collision Maintainer
		-- ============================================================================
		-- Keeps the bot limp (ragdoll) while it is held by Figure Grab
		local function enforceHeldRagdoll(a)
			if not (a and a.heldByFigureGrab) then
				return
			end
			local rig, hum, root = a.rig, a.hum, a.root
			if not (rig and rig.Parent and hum and root and root.Parent) then
				return
			end
			pcall(function()
				hum.AutoRotate = false
				hum.PlatformStand = true
				hum.WalkSpeed = 0
				hum.JumpPower = 0
				hum:ChangeState(Enum.HumanoidStateType.Physics)
			end)
			for _, m in ipairs(a.motors or {}) do
				if m and m.Parent then
					local jn = string.lower(m.Name)
					if not string.find(jn, "root") then
						pcall(function()
							m.Enabled = false
						end)
					end
				end
			end
			for _, info in pairs(a.ftapLimbData or {}) do
				if info.socket and info.socket.Parent then
					pcall(function()
						info.socket.Enabled = true
					end)
				end
				if info.rlp and info.rlp.Parent then
					pcall(function()
						info.rlp.CanCollide = false
					end)
				end
			end
			if a.faceOri then
				pcall(function()
					a.faceOri.Enabled = false
				end)
			end
		end

		local function updateActor(a, dt, now, myRoot)
			local rig, hum, root = a.rig, a.hum, a.root
			if not (rig and hum and root and root.Parent) then
				return
			end

			-- If Figure Grab was turned off manually without fn22 firing yet, release cleanly
			if a.heldByFigureGrab and (not tbl8 or not tbl8.AutoClicker or not (tbl7 and tbl7.SelectedPlayersAC and tbl7.SelectedPlayersAC[a.botProxy])) then
				a.heldByFigureGrab = false
				disableRagdoll(a)
			end

			updateHardLanding(a, now)

			if a.heldByFigureGrab then
				enforceHeldRagdoll(a)
			end

			if a.heldByFigureGrab or a.ragdolled or not myRoot then
				return
			end

			local target = myRoot.Position
			local dist = (root.Position - target).Magnitude
			updateLook(a, now, dt, target, dist > Config.FollowDistance)

			local goal, jumpNeeded = pickGoal(a, root, target, dist, now)
			local delta = goal - root.Position
			local flat = Vector3.new(delta.X, 0, delta.Z)
			local near = dist <= Config.FollowDistance
			local desired = Vector3.zero
			if flat.Magnitude > Config.ArrivalRadius and not near then
				desired = flat.Unit * math.clamp((dist - Config.FollowDistance) / 6, 0.28, 1)
			end
			local k = 1 - math.exp(-dt * Config.SteerResponsiveness)
			a.moveVec = a.moveVec + (desired - a.moveVec) * k
			if a.moveVec.Magnitude < 0.02 then
				a.moveVec = Vector3.zero
			end

			local targetSpeed = 0
			if not near then
				if dist > 32 then
					targetSpeed = Config.RunSpeed
				elseif dist > 11 then
					targetSpeed = Config.WalkSpeed
				else
					targetSpeed = Config.SlowSpeed
				end
			end
			a.curSpeed = a.curSpeed + (targetSpeed - a.curSpeed) * math.min(dt * 4, 1)
			hum.WalkSpeed = math.max(a.curSpeed, 4)
			hum.AutoRotate = false
			pcall(function()
				hum:Move(a.moveVec)
			end)
			if jumpNeeded then
				tryJump(a, now)
			end

			local faceDir
			if a.moveVec.Magnitude > 0.08 then
				faceDir = a.moveVec.Unit
			else
				local toP = Vector3.new(target.X - root.Position.X, 0, target.Z - root.Position.Z)
				faceDir = toP.Magnitude > 0.1 and toP.Unit or Vector3.new(0, 0, -1)
			end
			applyFacing(a, faceDir, dt)
			updateAnimations(a, now, a.moveVec.Magnitude > 0.08)
			if not near then
				updateStuck(a, target, now)
			end
		end

				local function onStepped()
			if not M.Running or flag11 or #actors == 0 then
				return
			end
			for _, a in ipairs(actors) do
				if a.ragdolled and not a.heldByFigureGrab and a.rig and a.rig.Parent then
					local torso = a.rig:FindFirstChild("Torso")
					local head = a.rig:FindFirstChild("Head")
					if torso then
						torso.CanCollide = true
					end
					if head then
						head.CanCollide = true
					end
					for _, info in pairs(a.ftapLimbData or {}) do
						if info.rlp and info.rlp.Parent and not info.rlp.CanCollide then
							info.rlp.CanCollide = true
						end
					end
				elseif a.heldByFigureGrab then
					enforceHeldRagdoll(a)
				end
			end
		end

		local lastActorError = 0
		local function onHeartbeat(dt)
			if not M.Running or flag11 or #actors == 0 then
				return
			end
			dt = math.min(tonumber(dt) or 0.016, 0.05)
			local now = os.clock()
			local myRoot = getMyRoot()

			local removedAny = false
			for i = #actors, 1, -1 do
				local a = actors[i]
				if a.dead or not a.rig or not a.rig.Parent or not a.root or not a.root.Parent then
					table.remove(actors, i)
					if not a.dead then
						cleanupActor(a)
					end
					if selected == a then
						selected = actors[#actors] or nil
					end
					removedAny = true
				end
			end
			if removedAny then
				if refreshCloneDropdown then
					refreshCloneDropdown()
				end
				if syncBotsIntoFigureGrab then
					syncBotsIntoFigureGrab()
				end
			end
			for _, a in ipairs(actors) do
				local ok, err = pcall(updateActor, a, dt, now, myRoot)
				if not ok and now - lastActorError > 5 then
					lastActorError = now
					warn("[BotJoin] " .. tostring(err))
				end
			end
		end

		-- v25: motor Kick/Kill'i bot proxy'sine uygularsa â†’ fake kick zinciri
		pcall(function()
			if tbl12 and tbl12.RunPlayerMethod and not tbl12.__fakeKickHooked then
				local origRunPlayerMethod = tbl12.RunPlayerMethod
				tbl12.RunPlayerMethod = function(name, fn, plr, instant, extra)
					if typeof(plr) == "table" and (plr.__isFigureBot or plr.__isFakeKickable) then
						local hostile = (name == "Kick" or name == "Blob_Kick" or name == "Kill" or name == "Blob_Kill")
						if hostile then
							local g = getgenv().KOZMOZ_FAKE_KICK_PROXY
							if type(g) == "function" then
								g(plr)
							end
							return
						end
					end
					return origRunPlayerMethod(name, fn, plr, instant, extra)
				end
				tbl12.__fakeKickHooked = true
			end
		end)

		-- ============================================================================
		-- 11) Actions & Engine Lifecycle
		-- ============================================================================
		local ACTIONS = {
			ragdoll = function(a)
				if a then
					toggleRagdoll(a)
				end
			end,
			getup = function(a)
				if a then
					a.ragdollToken = a.ragdollToken + 1
					disableRagdoll(a)
				end
			end,
			fling = function(a)
				if a and not a.heldByFigureGrab then
					if not a.ragdolled then
						enableRagdoll(a, "fling")
					end
					local cam = workspace.CurrentCamera
					local dir = (cam and cam.CFrame.LookVector) or Vector3.new(0, 0, -1)
					fling(a, dir, Config.FlingPower)
					explodeBot(a)
					scheduleGetUp(a, Config.RagdollTime)
				end
			end,
			remove = function(a)
				if a then
					removeActor(a)
				end
			end,
		}

		local function matchesKeyPicker(input, optName, fallbackCode)
			local kc = input and input.KeyCode
			if not kc then
				return false
			end
			local opt = options and options[optName]
			if not opt then
				-- v23: do not trigger the key if its keypicker was removed
				return false
			end
			local v = opt.Value
			if v == nil or v == "None" or v == "" then
				return false
			end
			if type(v) == "string" then
				return kc.Name == v or tostring(kc) == v
			end
			return kc == v
		end

		local function ensureRunning()
			if not M.Running then
				if toggles and toggles.FigureCloneToggle and not toggles.FigureCloneToggle.Value then
					toggles.FigureCloneToggle:SetValue(true)
				else
					M.Start()
				end
			end
		end

		local function triggerJoin(delayOverride)
			ensureRunning()
			if not M.Running then
				return
			end
			task.spawn(function()
				local spec = pickSpec(Config.SourceMode)
				if not spec then
					setStatus("No user found - check User ID / Source")
					fcNotify("Bot Join", "User not found. Enter a valid User ID or @username, or choose Friends / InGame.", 3)
					return
				end
				queueJoin(spec, delayOverride)
			end)
		end

		function M.Start()
			if M.Running or flag11 then
				return
			end
			if not fcLP then
				return
			end
			M.Running = true

			connect(fcUIS.InputBegan, function(input, gp)
				if gp or not M.Running then
					return
				end
				if fcUIS.GetFocusedTextBox and fcUIS:GetFocusedTextBox() then
					return
				end
				if matchesKeyPicker(input, "FigureRagdollKey", Enum.KeyCode and Enum.KeyCode.R) then
					if selected then
						toggleRagdoll(selected)
						if refreshCloneDropdown then
							refreshCloneDropdown()
						end
					end
				elseif matchesKeyPicker(input, "FigureSpawnKey", Enum.KeyCode and Enum.KeyCode.N) then
					triggerJoin(Config.JoinDelay)
				end
			end)

			if fcRunService.Stepped then
				connect(fcRunService.Stepped, onStepped)
			end
			connect(fcRunService.Heartbeat, onHeartbeat)
			setStatus(string.format("Active | %d/%d bots", #actors, Config.MaxClones))

			task.spawn(function()
				pcall(collectFriends, false)
				if refreshSourceDropdown then
					pcall(refreshSourceDropdown, false)
				end
			end)
		end

		function M.Stop()
			if not M.Running then
				return
			end
			M.Running = false
			joinQueue = {}
			for _, c in ipairs(Connections) do
				pcall(function()
					c:Disconnect()
				end)
			end
			Connections = {}
			for i = #actors, 1, -1 do
				cleanupActor(actors[i])
			end
			actors = {}
			selected = nil
			if refreshCloneDropdown then
				refreshCloneDropdown()
			end
			if syncBotsIntoFigureGrab then
				syncBotsIntoFigureGrab()
			end
			setStatus("Idle | 0 bots")
		end

		function M.RemoveAll()
			joinQueue = {}
			for i = #actors, 1, -1 do
				cleanupActor(actors[i])
			end
			actors = {}
			selected = nil
			if refreshCloneDropdown then
				refreshCloneDropdown()
			end
			if syncBotsIntoFigureGrab then
				syncBotsIntoFigureGrab()
			end
			setStatus(M.Running and ("Active | 0/" .. tostring(Config.MaxClones) .. " bots") or "Idle | 0 bots")
		end

		-- =====================================================================
		-- v25: FAKE KICK - when a joined bot is kicked via Target / Figure Grab
		--   realistic ragdoll + loop ragdoll for 5-6 seconds,
		--   then the selected blackhole + blackhole sound + KOZMOZ kick notification
		-- =====================================================================
		local function fkRandomRange(a, b)
			return a + RNG:NextNumber() * (b - a)
		end

		local function fkSpawnBlackhole(pos)
			local spawned = false
			pcall(function()
				local fn = getgenv().KOZMOZ_SPAWN_SELECTED_BH
				if type(fn) == "function" then
					spawned = fn(pos) and true or false
				end
			end)
			if not spawned then
				pcall(function()
					local fn = getenv and getenv().KOZMOZ_FAKE_BH or getgenv().KOZMOZ_FAKE_BH
					if type(fn) == "function" then
						fn(pos, nil)
						spawned = true
					end
				end)
			end
			return spawned
		end

		local function fkPlayBlackholeSound(pos)
			pcall(function()
				local id = (tbl9 and (tbl9.CustomBlackholeSound or tbl9.CustomBlackhole)) or "rbxassetid://9920612764"
				local anchor = Instance.new("Part")
				anchor.Name = "FakeKickSound"
				anchor.Anchored = true
				anchor.CanCollide = false
				anchor.CanQuery = false
				anchor.CanTouch = false
				anchor.Transparency = 1
				anchor.Size = Vector3.new(1, 1, 1)
				anchor.CFrame = CFrame.new(pos)
				anchor.Parent = workspace

				local snd = Instance.new("Sound")
				snd.SoundId = id
				snd.Volume = 2
				snd.RollOffMode = Enum.RollOffMode.InverseTapered
				snd.RollOffMaxDistance = 300
				snd.Parent = anchor
				snd:Play()
				game:GetService("Debris"):AddItem(anchor, 7)
			end)
		end

		local function fkNotifyKick(display)
			-- KOZMOZ'un kendi kick bildirimi
			pcall(function()
				if tbl12 and tbl12.NotifyEvent then
					tbl12.NotifyEvent("Kicked Player", { kickedPlayer = tostring(display) }, "Player Kicked")
					return
				end
			end)
			pcall(function()
				fcNotify("Kicked", tostring(display) .. " has been kicked.", 4)
			end)
		end

		-- realistic ragdoll: soft tumble, occasional small twitches
		local function fkRagdollTick(a, t)
			local rig = a.rig
			if not (rig and rig.Parent) then
				return
			end
			pcall(function()
				local torso = rig:FindFirstChild("Torso")
				local head = rig:FindFirstChild("Head")
				if torso then
					torso.CanCollide = true
				end
				if head then
					head.CanCollide = true
				end
				for _, info in pairs(a.ftapLimbData or {}) do
					if info.rlp and info.rlp.Parent then
						info.rlp.CanCollide = true
					end
				end
				-- light tipping in the first seconds, then only twitches
				local part = torso or (rig:FindFirstChildWhichIsA("BasePart"))
				if part and t < 0.6 then
					part.AssemblyAngularVelocity = Vector3.new(
						fkRandomRange(-3, 3), fkRandomRange(-2, 2), fkRandomRange(-3, 3))
				elseif part and RNG:NextNumber() < 0.35 then
					part.AssemblyAngularVelocity = Vector3.new(
						fkRandomRange(-1.2, 1.2), fkRandomRange(-0.8, 0.8), fkRandomRange(-1.2, 1.2))
				end
			end)
		end

		local fakeKickRegistry = {}
		getgenv().KOZMOZ_BOT_FAKEKICK = fakeKickRegistry

		local function fakeKickActor(a, opts)
			opts = opts or {}
			if not a or a.dead or a.fakeKicking then
				return
			end
			if not (a.rig and a.rig.Parent and a.root) then
				return
			end
			a.fakeKicking = true
			local display = a.spec and (a.spec.display or a.spec.user) or "Bot"
			local delay = opts.delay or fkRandomRange(5.0, 6.0)

			-- 1) ragdoll + realistic loop ragdoll
			if not a.ragdolled then
				pcall(enableRagdoll, a, "manual")
			end
			-- Bot is pinned in the air at the "Kick Height" value while it dangles
			local kickHeight = tonumber(tbl9 and tbl9.NKOffset) or 15
			local pinPart = nil
			pcall(function()
				local root = a.root
				if not (root and root.Parent) then
					return
				end
				local basePos = root.Position
				local params = RaycastParams.new()
				params.FilterType = Enum.RaycastFilterType.Exclude
				local ignore = { a.rig }
				local ch = LP.Character
				if ch then
					table.insert(ignore, ch)
				end
				params.FilterDescendantsInstances = ignore
				local hit = workspace:Raycast(basePos + Vector3.new(0, 6, 0), Vector3.new(0, -400, 0), params)
				local groundY = hit and hit.Position.Y or (basePos.Y - 3)
				local targetY = groundY + kickHeight

				local anchor = Instance.new("Part")
				anchor.Name = "KOZMOZ_KickPin"
				anchor.Size = Vector3.new(2, 2, 2)
				anchor.Transparency = 1
				anchor.Anchored = true
				anchor.CanCollide = false
				anchor.CanQuery = false
				anchor.CanTouch = false
				anchor.CFrame = CFrame.new(Vector3.new(basePos.X, targetY, basePos.Z))
				anchor.Parent = workspace
				pinPart = anchor

				pcall(function()
					a.rig:PivotTo(CFrame.new(Vector3.new(basePos.X, targetY, basePos.Z)))
				end)
			end)

			task.spawn(function()
				local t0 = os.clock()
				local pin = pinPart
				while (os.clock() - t0) < delay do
					if a.dead or not a.rig or not a.rig.Parent then
						break
					end
					-- hold the bot at the pinned height (soft, so it still dangles)
					pcall(function()
						local root = a.root
						if not (root and root.Parent and pin and pin.Parent) then
							return
						end
						local p = pin.Position
						local cur = root.Position
						local target = Vector3.new(p.X, p.Y, p.Z)
						root.CFrame = CFrame.new(target) * (root.CFrame - root.CFrame.Position)
						root.AssemblyLinearVelocity = Vector3.zero
					end)
					fkRagdollTick(a, os.clock() - t0)
					task.wait(0.1)
				end
				if pin then
					pcall(function()
						pin:Destroy()
					end)
				end

				-- 2) son konum
				local pos = nil
				pcall(function()
					pos = a.root and a.root.Position or (a.rig and a.rig:GetPivot().Position)
				end)
				pos = pos or Vector3.new(0, 20, 0)

				-- 3) selected blackhole + sound + KOZMOZ kick notification
				fkSpawnBlackhole(pos)
				fkPlayBlackholeSound(pos)
				fkNotifyKick(display)

				-- 4) remove the bot
