		refreshSourceDropdown = function(forceFriends)
			if forceFriends and Config.SourceMode == "Friends" then
				pcall(collectFriends, true)
			end
			local dd = nil
			if not dd then
				return
			end
			if Config.SourceMode == "UserId" then
				cachedSources = {}
				selectedSourceEntry = nil
				pcall(function()
					dd:SetValues({ "Use User ID / @Username box" })
				end)
				return
			end
			local lst = sourceList(Config.SourceMode, forceFriends)
			cachedSources = {}
			local labels = { "Random" }
			local maxItems = math.min(#lst, 50)
			for i = 1, maxItems do
				local s = lst[i]
				local lbl = string.format("%s (@%s)", tostring(s.display), tostring(s.user))
				cachedSources[lbl] = s
				labels[#labels + 1] = lbl
			end
			pcall(function()
				dd:SetValues(labels)
			end)
		end

		refreshCloneDropdown = function()
			local dd = options and options.FigureCloneSelect
			if not dd or syncingCloneDropdown then
				return
			end
			syncingCloneDropdown = true
			local labels = {}
			local activeLabel = nil
			for i, a in ipairs(actors) do
				local tag = a.heldByFigureGrab and " [FIGURE GRAB]" or (a.ragdolled and " [RAGDOLL]" or "")
				local lbl = string.format("#%d %s%s", i, tostring(a.spec.display), tag)
				labels[#labels + 1] = lbl
				if a == selected then
					activeLabel = lbl
				end
			end
			if #labels == 0 then
				labels[1] = "None"
				activeLabel = "None"
			end
			pcall(function()
				dd:SetValues(labels)
				if activeLabel and dd.SetValue then
					dd:SetValue(activeLabel)
				end
			end)
			syncingCloneDropdown = false
		end

