	do
		local InvincibilityTabbox = tbl15.Invincibility:AddLeftTabbox("Anti")
		local AntiTab = InvincibilityTabbox:AddTab("Anti", "shield-ban")
		local ExtraDefenseTab = InvincibilityTabbox:AddTab("Extra", "shield-check")
		local ConfigTab = InvincibilityTabbox:AddTab("Config", "settings-2")
		local AntiKickToyList2 = {
			["Japanese Lantern"] = "JapaneseLantern",
			["Spray Can"] = "SprayCanWD",
			["Spooky Candle"] = "SpookyCandle1",
			["Clock"] = "ClockAlarm",
		}
		local SelectedAntiKickToy = AntiKickToyList2["Japanese Lantern"] -- v36: default Japanese Lantern
		local AntiKickItemActive = false
		local MyPCLD = nil
		local pcldConn = nil

		local plr = game:GetService("Players").LocalPlayer
		local RS = game:GetService("ReplicatedStorage")
		local RunService = game:GetService("RunService")

		local function GetMagnitude(Part1, Part2)
			return (Part1.Position - Part2.Position).Magnitude
		end
		local function FWD(parent, part, timeOffset)
			return parent:FindFirstChild(part) or parent:WaitForChild(part, timeOffset or 1)
		end
		local function CheckNetworkOwnerOnPart(Part)
			local po = Part:FindFirstChild("PartOwner")
			return po and po.Value == plr.Name
		end
		local function sno(part)
			pcall(function()
				local grabEvents = RS:FindFirstChild("GrabEvents")
				local setNetOwner = grabEvents and grabEvents:FindFirstChild("SetNetworkOwner")
				if setNetOwner then
					setNetOwner:FireServer(part, part.CFrame)
				end
			end)
		end
		local function CheckForHome()
			local plotItems = workspace:FindFirstChild("PlotItems")
			local plots = workspace:FindFirstChild("Plots")
			if plots and plotItems then
				for i = 1, 5 do
					local Plot = plots:FindFirstChild("Plot" .. i)
					if Plot then
						local sign = Plot:FindFirstChild("PlotSign")
						local owners = sign and sign:FindFirstChild("ThisPlotsOwners")
						if owners then
							for _, v in pairs(owners:GetChildren()) do
								if v.Value == plr.Name then
									return plotItems:FindFirstChild("Plot" .. i)
								end
							end
						end
					end
				end
			end
			return nil
		end
		local function SpawnToy(ToyName)
			local InPlot = plr:FindFirstChild("InPlot")
			local InOwnedPlot = plr:FindFirstChild("InOwnedPlot")
			local CanSpawnToy = plr:FindFirstChild("CanSpawnToy")
			local inv = workspace:FindFirstChild(plr.Name .. "SpawnedInToys")

			if InPlot and InPlot.Value and InOwnedPlot and not InOwnedPlot.Value then
				InPlot:GetPropertyChangedSignal("Value"):Wait()
			end
			if CanSpawnToy and not CanSpawnToy.Value then
				CanSpawnToy:GetPropertyChangedSignal("Value"):Wait()
			end

			local hrp = plr.Character and plr.Character:FindFirstChild("HumanoidRootPart")
			if not hrp then
				return nil
			end

			local SpawnCF = (MyPCLD or hrp).CFrame * CFrame.new(0, 14, 20)
			local Container = (InOwnedPlot and InOwnedPlot.Value) and CheckForHome() or inv
			if not Container then
				return nil
			end

			local spawnedObject = nil
			local connection
			connection = Container.ChildAdded:Connect(function(child)
				if child.Name == ToyName then
					spawnedObject = child
				end
			end)

			task.spawn(function()
				pcall(function()
					local menuToys = RS:FindFirstChild("MenuToys")
					local spawnRemote = menuToys and menuToys:FindFirstChild("SpawnToyRemoteFunction")
					if spawnRemote then
						spawnRemote:InvokeServer(ToyName, SpawnCF, Vector3.zero)
					end
				end)
			end)

			local start = tick()
			repeat
				task.wait()
			until spawnedObject or (tick() - start) > 2.5

			if connection then
				connection:Disconnect()
			end
			return spawnedObject
		end
		local function FindPCLD(hrp)
			if pcldConn then
				pcldConn:Disconnect()
			end
			MyPCLD = nil
			pcldConn = RunService.Heartbeat:Connect(function()
				if MyPCLD or not hrp or not hrp.Parent then
					if pcldConn then
						pcldConn:Disconnect()
						pcldConn = nil
					end
					return
				end
				for _, v in pairs(workspace:GetChildren()) do
					if v.Name == "PlayerCharacterLocationDetector" and v:IsA("BasePart") then
						if GetMagnitude(v, hrp) <= 2 then
							MyPCLD = v
							break
						end
					end
				end
			end)
		end

		plr.CharacterAdded:Connect(function(char)
			if AntiKickItemActive then
				MyPCLD = nil
				local hrp = char:WaitForChild("HumanoidRootPart", 5)
				if hrp then
					FindPCLD(hrp)
				end
			end
		end)


		-- Anti Blobman Grab / Anti Vehicle / Auto Explode (from mumus.txt, adapted)
		local ABG_Enabled = false
		local ABG_Conn = nil

		local function ABG_CreateTruePosPart()
			local char = plr.Character
			if not char then
				return nil
			end
			local existing = char:FindFirstChild("TruePositionPart")
			if existing then
				return existing
			end
			local tp = Instance.new("Part")
			tp.Name = "TruePositionPart"
			tp.Anchored = true
			tp.CanCollide = false
			tp.CanTouch = false
			tp.CanQuery = false
			tp.Transparency = 1
			tp.Size = Vector3.new(1, 1, 1)
			tp.CFrame = CFrame.new(0, -100, 0)
			tp.Parent = char
			return tp
		end

		local function ABG_DropFromBlobs()
			local char = plr.Character
			if not char then
				return
			end
			local hrp = char:FindFirstChild("HumanoidRootPart")
			if not hrp then
				return
			end
			local function tryDrop(item)
				pcall(function()
					local scr = item:FindFirstChild("BlobmanSeatAndOwnerScript")
					local detector = item:FindFirstChild("RightDetector")
					if scr and detector then
						local drop = scr:FindFirstChild("CreatureDrop")
						local weld = detector:FindFirstChild("RightWeld")
						local isOurCharacterWeld = false
						if weld and char then
							pcall(function()
								isOurCharacterWeld = (weld.Part0 and weld.Part0:IsDescendantOf(char)) or (weld.Part1 and weld.Part1:IsDescendantOf(char))
							end)
						end
						if drop and weld and isOurCharacterWeld then
							drop:FireServer(weld, hrp)
							local charEvents = RS:FindFirstChild("CharacterEvents")
							local struggle = charEvents and charEvents:FindFirstChild("Struggle")
							if struggle then
								struggle:FireServer(plr)
							end
						end
					end
				end)
			end
			local plotItems = workspace:FindFirstChild("PlotItems")
			if plotItems then
				for _, plot in pairs(plotItems:GetChildren()) do
					if plot.Name ~= "PlayersInPlots" then
						for _, itm in pairs(plot:GetChildren()) do
							if itm.Name == "CreatureBlobman" then
								tryDrop(itm)
							end
						end
					end
				end
			end
			for _, other in pairs(game:GetService("Players"):GetPlayers()) do
				local toysFolder = workspace:FindFirstChild(other.Name .. "SpawnedInToys")
				if toysFolder then
					for _, itm in pairs(toysFolder:GetChildren()) do
						if itm.Name == "CreatureBlobman" then
							tryDrop(itm)
						end
					end
				end
			end
		end

		local function ABG_SetMassless()
			local char = plr.Character
			if not char then
				return
			end
			for _, prt in pairs(char:GetChildren()) do
				if prt:IsA("BasePart") and prt.Massless then
					prt.Massless = false
					ABG_DropFromBlobs()
				end
			end
		end

		local function ABG_MoveRootAttachment()
			local char = plr.Character
			if not char then
				return
			end
			local hrp = char:FindFirstChild("HumanoidRootPart")
			local truePart = char:FindFirstChild("TruePositionPart")
			if hrp and truePart then
				local rootAttachment = hrp:FindFirstChild("RootAttachment")
				if rootAttachment and rootAttachment:IsA("Attachment") then
					task.wait(0.2)
					rootAttachment.Parent = truePart
				end
			end
		end

		local function ABG_RestoreRootAttachment()
			local char = plr.Character
			if not char then
				return
			end
			local hrp = char:FindFirstChild("HumanoidRootPart")
			local truePart = char:FindFirstChild("TruePositionPart")
			if truePart then
				local rootAttachment = truePart:FindFirstChild("RootAttachment")
				if rootAttachment and rootAttachment:IsA("Attachment") and hrp then
					rootAttachment.Parent = hrp
				end
				truePart:Destroy()
			end
		end

		local function ABG_Loop()
			while ABG_Enabled do
				pcall(function()
					if plr.Character then
						ABG_CreateTruePosPart()
						ABG_SetMassless()
						local hrp = plr.Character:FindFirstChild("HumanoidRootPart")
						if hrp and hrp:FindFirstChild("RootAttachment") then
							local truePart = plr.Character:FindFirstChild("TruePositionPart")
							if truePart and not truePart:FindFirstChild("RootAttachment") then
								ABG_MoveRootAttachment()
							end
						end
					end
				end)
				task.wait(0.1)
			end
		end

		-- KOZMOZ USER LOCK: Anti Vehicle Method is always All.
		tbl9.AntiVehicleMethod = "All"
		local AV_Enabled = false
		-- apel.txt:7558-7809: same five target vehicles and seat/void/retry workflow.
		local AV_TargetItems = { "CreatureBlobman", "TractorRed", "TractorOrange", "TractorGreen", "SantaSleigh" }
		local function AV_MatchesMethod(name)
			if not table.find(AV_TargetItems, name) then return false end
			-- Locked to All by user request; the dropdown is display/confirmation only.
			local method = "All"
			return (method == "All")
				or (method == "Blobman" and name == "CreatureBlobman")
				or (method == "Tractor" and name:sub(1, 7) == "Tractor")
				or (method == "Sleigh" and name == "SantaSleigh")
		end
		local AV_Processed = setmetatable({}, { __mode = "k" })
		local AV_Retries = setmetatable({}, { __mode = "k" })
		local AV_Watched = setmetatable({}, { __mode = "k" })
		local AV_Conns = {}
		local AV_Generation = 0
		local AV_PlotItemsWatched = nil

		local function AV_GetMyPlotNumber()
			local plots = workspace:FindFirstChild("Plots")
			if plots then
				for i = 1, 5 do
					local plot = plots:FindFirstChild("Plot" .. i)
					local plotSign = plot and plot:FindFirstChild("PlotSign")
					local owners = plotSign and plotSign:FindFirstChild("ThisPlotsOwners")
					if owners then
						for _, ownerVal in ipairs(owners:GetChildren()) do
							if ownerVal:IsA("StringValue") and ownerVal.Value == plr.Name then
								return i
							end
						end
					end
				end
			end
			return nil
		end

		local function AV_IsWhitelistedPlayer(playerObj)
			return playerObj == plr or playerObj and tbl12.IsProtectedPlayer(playerObj, true)
		end

		local function AV_GetPlotOwner(plotNumber)
			local plots = workspace:FindFirstChild("Plots")
			local plot = plots and plots:FindFirstChild("Plot" .. tostring(plotNumber))
			local sign = plot and plot:FindFirstChild("PlotSign")
			local owners = sign and sign:FindFirstChild("ThisPlotsOwners")
			if not owners then return nil end
			for _, value in ipairs(owners:GetChildren()) do
				if value:IsA("StringValue") and value.Value ~= "" then
					return game:GetService("Players"):FindFirstChild(value.Value)
				end
			end
			return nil
		end

		local function AV_Allowed(isPlotFolder, plotNumber, ownerPlayer, item)
			if not isPlotFolder and not ownerPlayer and item and item.Parent then
				local folderName = item.Parent.Name
				if folderName:sub(-13) == "SpawnedInToys" then
					ownerPlayer = game:GetService("Players"):FindFirstChild(folderName:sub(1, -14))
				end
			end
			if isPlotFolder then
				local mine = AV_GetMyPlotNumber()
				-- Apel only skips YOUR plot. If you do not own a plot, other known plots
				-- are still eligible; unknown/protected owners are skipped below.
				if mine and mine == plotNumber then return false end
				local plots = workspace:FindFirstChild("Plots")
				local plot = plots and plots:FindFirstChild("Plot" .. tostring(plotNumber))
				local sign = plot and plot:FindFirstChild("PlotSign")
				local owners = sign and sign:FindFirstChild("ThisPlotsOwners")
				if not owners then return false end
				local anyOwner = false
				for _, entry in ipairs(owners:GetChildren()) do
					if entry:IsA("StringValue") and entry.Value ~= "" then
						local player = game:GetService("Players"):FindFirstChild(entry.Value)
						if not player or AV_IsWhitelistedPlayer(player) then return false end
						anyOwner = true
					end
				end
				return anyOwner
			end
			return ownerPlayer ~= nil and not AV_IsWhitelistedPlayer(ownerPlayer)
		end

		-- Apel port: seat the local Humanoid, anchor the local root, move the vehicle
		-- to Apel's drop point, then restore the local root. Kozmoz still skips own,
		-- protected/whitelisted, uncertain/shared plots and occupied seats.
		local function AV_ApelDropOnce(item, stillValid)
			return tbl12.ApelVehicleDrop(item, stillValid)
		end

		-- v31: occupied vehicles are protected, but an Occupant signal fires the drop the
		-- moment the rider leaves (no 3 s polling). Warnings are throttled per vehicle.
		local AV_VacateWatch = setmetatable({}, { __mode = "k" })
		local AV_LastWarn = setmetatable({}, { __mode = "k" })
		local function AV_WarnThrottled(item, msg)
			if os.clock() - (AV_LastWarn[item] or -math.huge) >= 10 then
				AV_LastWarn[item] = os.clock()
				warn(msg)
			end
		end
		local AV_WatchVacate

		local function AV_ProcessItem(item, isPlotFolder, plotNumber, ownerPlayer)
			if not item or not item.Parent or not AV_Enabled or AV_Retries[item] or AV_Processed[item]
				or not AV_MatchesMethod(item.Name) or not AV_Allowed(isPlotFolder, plotNumber, ownerPlayer, item) then return end
			local ticket = {}
			local generation = AV_Generation
			AV_Retries[item] = ticket
			task.spawn(function()
				local success = false
				local function stillValid()
					return AV_Enabled and not flag11 and generation == AV_Generation and AV_Retries[item] == ticket
						and item.Parent and AV_Allowed(isPlotFolder, plotNumber, ownerPlayer, item) and AV_MatchesMethod(item.Name)
				end
				local attempts = 0
				local occupied = false
				while stillValid() and attempts < 12 do
					attempts = attempts + 1
					local seat = item:FindFirstChildOfClass("VehicleSeat") or item:FindFirstChildWhichIsA("VehicleSeat", true)
					local _, _, myHum = tbl12.Char()
					if seat and seat.Occupant and seat.Occupant ~= myHum then
						occupied = true
						break
					end
					success = AV_ApelDropOnce(item, stillValid)
					if success then break end
					if not stillValid() then break end
					task.wait()
				end
				if AV_Retries[item] ~= ticket then return end
				AV_Retries[item] = nil
				if not AV_Enabled or not item.Parent then return end
				local seatNow = item:FindFirstChildOfClass("VehicleSeat") or item:FindFirstChildWhichIsA("VehicleSeat", true)
				if not success and seatNow and seatNow.Occupant then
					local _, _, myHumNow = tbl12.Char()
					if seatNow.Occupant ~= myHumNow then occupied = true end
				end
				if occupied and seatNow and seatNow.Parent then
					AV_WatchVacate(item, seatNow, isPlotFolder, plotNumber, ownerPlayer)
					if not seatNow.Occupant then
						-- rider left while we were checking: go again right now
						task.defer(AV_ProcessItem, item, isPlotFolder, plotNumber, ownerPlayer)
					else
						AV_WarnThrottled(item, "[KOZMOZ] Anti Vehicle " .. item.Name
							.. " occupied (protected): removes the instant the rider leaves.")
					end
					return
				end
				AV_Processed[item] = true
				if not success then
					local reason = "drop did not remove it (ownership/server rejection or missing seat)"
					if not AV_Allowed(isPlotFolder, plotNumber, ownerPlayer, item) then
						reason = "own/protected/whitelisted or uncertain plot"
					end
					AV_WarnThrottled(item, "[KOZMOZ] Anti Vehicle " .. item.Name .. " still present: " .. reason .. "; retrying while ON.")
				end
				task.delay(success and 1 or 0.25, function()
					if generation ~= AV_Generation then return end
					AV_Processed[item] = nil
					if AV_Enabled and item.Parent and AV_Allowed(isPlotFolder, plotNumber, ownerPlayer, item) and AV_MatchesMethod(item.Name) then
						AV_ProcessItem(item, isPlotFolder, plotNumber, ownerPlayer)
					end
				end)
			end)
		end

		AV_WatchVacate = function(item, seat, isPlotFolder, plotNumber, ownerPlayer)
			if not seat or AV_VacateWatch[seat] then return end
			local generation = AV_Generation
			local conn
			conn = seat:GetPropertyChangedSignal("Occupant"):Connect(function()
				if generation ~= AV_Generation or not AV_Enabled or flag11 or not item.Parent or not seat.Parent then
					conn:Disconnect()
					AV_VacateWatch[seat] = nil
					return
				end
				if seat.Occupant == nil then
					AV_Processed[item] = nil
					AV_ProcessItem(item, isPlotFolder, plotNumber, ownerPlayer)
				end
			end)
			AV_VacateWatch[seat] = conn
			table.insert(AV_Conns, conn)
		end

		local function AV_WatchFolder(folder, isPlotFolder, plotNumber, ownerPlayer)
			if not folder or not folder.Parent then return end
			if not isPlotFolder and not ownerPlayer then
				local name = folder.Name
				if name:sub(-13) == "SpawnedInToys" then
					ownerPlayer = game:GetService("Players"):FindFirstChild(name:sub(1, -14))
				end
				if not ownerPlayer then return end
			end
			if AV_Watched[folder] then return end
			AV_Watched[folder] = true
			for _, item in ipairs(folder:GetChildren()) do
				if item:IsA("Model") and AV_MatchesMethod(item.Name) then
					if AV_Allowed(isPlotFolder, plotNumber, ownerPlayer, item) then
						AV_ProcessItem(item, isPlotFolder, plotNumber, ownerPlayer)
					end
				end
			end
			local conn = folder.ChildAdded:Connect(function(item)
				if not AV_Enabled then return end
				if not item:IsA("Model") or not AV_MatchesMethod(item.Name) then return end
				if not AV_Allowed(isPlotFolder, plotNumber, ownerPlayer, item) then return end
				if item:FindFirstChildOfClass("VehicleSeat") or item:FindFirstChildWhichIsA("VehicleSeat", true) then
					AV_ProcessItem(item, isPlotFolder, plotNumber, ownerPlayer)
				else
					local seatConn
					seatConn = item.DescendantAdded:Connect(function(child)
						if child:IsA("VehicleSeat") then
							if seatConn then seatConn:Disconnect() end
							AV_ProcessItem(item, isPlotFolder, plotNumber, ownerPlayer)
						end
					end)
					table.insert(AV_Conns, seatConn)
				end
			end)
			table.insert(AV_Conns, conn)
		end

		local function AV_WatchPlotItems(plotItems)
			if not plotItems or not plotItems.Parent or AV_PlotItemsWatched == plotItems then return end
			AV_PlotItemsWatched = plotItems
			for i = 1, 5 do
				local plot = plotItems:FindFirstChild("Plot" .. i)
				if plot then AV_WatchFolder(plot, true, i, nil) end
			end
			table.insert(AV_Conns, plotItems.ChildAdded:Connect(function(child)
				if not AV_Enabled then return end
				local num = tonumber(child.Name:match("^Plot([1-5])$"))
				if num then AV_WatchFolder(child, true, num, nil) end
			end))
		end

		local function AV_Stop()
			AV_Generation = AV_Generation + 1
			for _, conn in ipairs(AV_Conns) do
				if conn then conn:Disconnect() end
			end
			AV_Conns = {}
			AV_Watched = setmetatable({}, { __mode = "k" })
			AV_Processed = setmetatable({}, { __mode = "k" })
			AV_Retries = setmetatable({}, { __mode = "k" })
			AV_VacateWatch = setmetatable({}, { __mode = "k" })
			AV_PlotItemsWatched = nil
		end

		local function AV_Start()
			AV_Stop()
			warn("[KOZMOZ] Anti Vehicle started: TP + sit + delete (gucci style), All, instant")
			local playersService = game:GetService("Players")
			for _, player in ipairs(playersService:GetPlayers()) do
				if player ~= plr then
					local folder = workspace:FindFirstChild(player.Name .. "SpawnedInToys")
					if folder then AV_WatchFolder(folder, false, nil, player) end
				end
			end
			AV_WatchPlotItems(workspace:FindFirstChild("PlotItems"))
			table.insert(AV_Conns, workspace.ChildAdded:Connect(function(child)
				if not AV_Enabled then return end
				if child.Name == "PlotItems" then
					AV_WatchPlotItems(child)
					return
				end
				if child.Name:sub(-13) == "SpawnedInToys" and child.Name ~= plr.Name .. "SpawnedInToys" then
					local ownerName = child.Name:sub(1, -14)
					local ownerPlayer = playersService:FindFirstChild(ownerName)
					AV_WatchFolder(child, false, nil, ownerPlayer)
				end
			end))
			table.insert(AV_Conns, playersService.PlayerAdded:Connect(function(player)
				task.wait(1)
				if not AV_Enabled or player == plr then return end
				local folder = workspace:FindFirstChild(player.Name .. "SpawnedInToys")
				if folder then AV_WatchFolder(folder, false, nil, player) end
			end))
		end

		lib:OnUnload(function()
			AV_Enabled = false
			AV_Stop()
		end)

		local AE_Active = false
		local AE_Resp = false
		local AE_Ready = false
		local AE_WasGrabbed = false
		local AE_TPLoop = nil
		local AE_Watch = nil
		local AE_TPLock = false
		local AE_SpawnDestroyExplosive = nil

		local function AE_StopTPLoop()
			if AE_TPLoop then
				AE_TPLoop:Disconnect()
				AE_TPLoop = nil
			end
		end

		local function AE_StartTPLoop(oven)
			AE_StopTPLoop()
			AE_TPLock = false
			AE_TPLoop = RunService.Heartbeat:Connect(function()
				if not AE_Active then
					return
				end
				if not (oven and oven.Parent) then
					return
				end
				for _, v in ipairs(oven:GetDescendants()) do
					if v:IsA("BasePart") then
						v.CanCollide = false
					end
				end
				if not AE_Ready then
					return
				end
				local grabbed = false
				for _, v in ipairs(oven:GetDescendants()) do
					local po = v:FindFirstChild("PartOwner")
					if po and po.Value == plr.Name then
						grabbed = true
						break
					end
				end
				if grabbed then
					if AE_TPLock then
						return
					end
					AE_TPLock = true
					AE_WasGrabbed = true
					task.wait(0.1)
					local bomb1, bomb2, bomb3, bomb4, bomb5 = nil, nil, nil, nil, nil
					for _, p in ipairs(game:GetService("Players"):GetPlayers()) do
						if p ~= plr then
							if tbl8.WhitelistedBypass and tbl7.Whitelisted and tbl7.Whitelisted[p] == true then
								-- skip whitelisted player bombs
							else
								local f = workspace:FindFirstChild(p.Name .. "SpawnedInToys")
								if f then
									bomb1 = bomb1 or f:FindFirstChild("BombMissile")
									bomb2 = bomb2 or f:FindFirstChild("BombDarkMatter")
									bomb3 = bomb3 or f:FindFirstChild("BombBalloon")
									bomb4 = bomb4 or f:FindFirstChild("BallSnowball")
									bomb5 = bomb5 or f:FindFirstChild("FireworkMissile")
								end
							end
						end
					end
					local targetPart = nil
					if bomb1 then
						targetPart = bomb1:FindFirstChild("PartHitDetector", true)
					elseif bomb2 then
						targetPart = bomb2:FindFirstChild("ParticlePart", true)
					elseif bomb3 then
						targetPart = bomb3:FindFirstChild("Balloon", true)
					elseif bomb4 then
						targetPart = bomb4:FindFirstChild("SnowRagdollPart", true)
					elseif bomb5 then
						targetPart = bomb5:FindFirstChild("PartHitDetector", true)
					end
					if targetPart and targetPart.Parent then
						for _, v in ipairs(oven:GetDescendants()) do
							if v:IsA("BasePart") and v.Name == "FirePlayerPart" then
								v.CFrame = targetPart.CFrame
								v.AssemblyLinearVelocity = v.AssemblyLinearVelocity + Vector3.new(0, 9000000000, 0)
							end
						end
					else
						for _, v in ipairs(oven:GetDescendants()) do
							if v:IsA("BasePart") and v.Name == "SoundPart" then
								v.CFrame = CFrame.new(0, 9000000000, 0)
							end
						end
					end
					AE_TPLock = false
				else
					if AE_WasGrabbed then
						local menuToys = RS:FindFirstChild("MenuToys")
						local destroyToy = menuToys and menuToys:FindFirstChild("DestroyToy")
						if destroyToy then
							pcall(function()
								destroyToy:FireServer(oven)
							end)
						end
					end
				end
			end)
		end

		AE_SpawnDestroyExplosive = function()
			if AE_Resp then
				return
			end
			AE_Resp = true
			AE_Ready = false
			AE_WasGrabbed = false
			task.wait(0.05)
			local char = plr.Character
			local root = char and char:FindFirstChild("HumanoidRootPart")
			if not root then
				AE_Resp = false
				return
			end
			local folder = workspace:FindFirstChild(plr.Name .. "SpawnedInToys")
			local existing = {}
			if folder then
				for _, obj in ipairs(folder:GetChildren()) do
					if obj.Name == "OvenDarkGray" then
						existing[obj] = true
					end
				end
			end
			task.spawn(function()
				pcall(function()
					local menuToys = RS:FindFirstChild("MenuToys")
					local spawnRemote = menuToys and menuToys:FindFirstChild("SpawnToyRemoteFunction")
					if spawnRemote then
						spawnRemote:InvokeServer("OvenDarkGray", root.CFrame * CFrame.new(0, 15, 20), Vector3.new(0, 97.69, 0))
					end
				end)
			end)
			local fw = 0
			while not folder and fw < 5 do
				if not AE_Active then
					AE_Resp = false
					return
				end
				task.wait(0.1)
				fw = fw + 0.1
				folder = workspace:FindFirstChild(plr.Name .. "SpawnedInToys")
			end
			if not folder then
				AE_Resp = false
				return
			end
			local newOven = nil
			local wt = 0
			while not newOven and wt < 5 do
				if not AE_Active then
					AE_Resp = false
					return
				end
				task.wait(0.1)
				wt = wt + 0.1
				for _, obj in ipairs(folder:GetChildren()) do
					if obj.Name == "OvenDarkGray" and not existing[obj] then
						newOven = obj
						break
					end
				end
			end
			if not newOven then
				AE_Resp = false
				return
			end
			newOven.Name = "DestroyExplosive"
			local button = newOven:WaitForChild("ButtonOven", 5)
			if not button then
				AE_Resp = false
				return
			end
			task.spawn(function()
				sno(button)
			end)
			for _, v in ipairs(newOven:GetDescendants()) do
				if v:IsA("BasePart") and v.Name == "SoundPart" then
					v.CanCollide = false
					v.CFrame = CFrame.new(0, 9000000000, 0)
				end
			end
			task.wait(0.1)
			AE_Resp = false
			AE_Ready = true
			AE_StartTPLoop(newOven)
			if AE_Watch then
				AE_Watch:Disconnect()
				AE_Watch = nil
			end
			AE_Watch = newOven.AncestryChanged:Connect(function(_, parent)
				if not AE_Active then
					return
				end
				if parent == nil then
					AE_StopTPLoop()
					AE_Ready = false
					AE_WasGrabbed = false
					if AE_Watch then
						AE_Watch:Disconnect()
						AE_Watch = nil
					end
					AE_Resp = false
					task.wait(0.1)
					if AE_Active then
						task.spawn(AE_SpawnDestroyExplosive)
					end
				end
			end)
		end

		-- ============================================================================
		-- KOZMOZ USER FIX: Unified FTAP Anti Engine (ported 1:1 from uploads/kar.txt)
		-- ============================================================================
		local KozAnti = {}
		tbl12.KozAnti = KozAnti

		do
			-- Helper: spawn a toy cleanly both inside owned houses (PlotItems) and outside
			local function kaFindMyToysFolder()
				return workspace:FindFirstChild(localPlayer.Name .. "SpawnedInToys")
			end

			local function kaSpawnToy(toyName, cf)
				local ok, res = pcall(function()
					return tbl12.SpawnToy(toyName, cf, nil, true)
				end)
				if ok and res and res.Parent then
					return res
				end
				local menuToys = ReplicatedStorage:FindFirstChild("MenuToys")
				local rf = menuToys and menuToys:FindFirstChild("SpawnToyRemoteFunction")
				if not rf then
					return nil
				end
				local folder = kaFindMyToysFolder()
				local before = {}
				if folder then
					for _, c in ipairs(folder:GetChildren()) do
						before[c] = true
					end
				end
				task.spawn(function()
					pcall(function()
						rf:InvokeServer(toyName, cf, Vector3.new(0, 0, 0))
					end)
				end)
				local deadline = os.clock() + 2.5
				while os.clock() < deadline do
					folder = kaFindMyToysFolder()
					if folder then
						for _, c in ipairs(folder:GetChildren()) do
							if not before[c] and c.Name == toyName then
								return c
							end
						end
					end
					if localPlayer:FindFirstChild("InOwnedPlot") and localPlayer.InOwnedPlot.Value and workspace:FindFirstChild("PlotItems") then
						for _, pf in ipairs(workspace.PlotItems:GetChildren()) do
							for _, c in ipairs(pf:GetChildren()) do
								if c.Name == toyName and tbl12.IsNetworkOwner and tbl12.IsNetworkOwner(c:FindFirstChildWhichIsA("BasePart") or c) then
									return c
								end
							end
						end
					end
					task.wait(0.05)
				end
				return nil
			end

			local function kaDestroyToy(toy)
				if not toy or not toy.Parent then
					return
				end
				pcall(function()
					tbl12.DestroyToy(toy)
				end)
				if toy and toy.Parent then
					pcall(function()
						local menuToys = ReplicatedStorage:FindFirstChild("MenuToys")
						local del = menuToys and menuToys:FindFirstChild("DestroyToy")
						if del then
							del:FireServer(toy)
						end
					end)
				end
			end

			local function kaRestoreStickyScriptIfIdle()
				if tbl8.AntiSticky or tbl8.KozAntiStickyLag or (toggles.AntiLag and toggles.AntiLag.Value) then
					return
				end
				pcall(function()
					local ps = localPlayer:FindFirstChild("PlayerScripts")
					if ps then
						local sptd = ps:FindFirstChild("StickyPartsTouchDetection")
						if sptd and sptd:IsA("LocalScript") then
							sptd.Disabled = false
							sptd.Enabled = true
						end
					end
				end)
			end

			-- ------------------------------------------------------------------
			-- 1) Anti Blobman (kar.txt: TruePositionPart + CreatureDrop + Massless)
			-- ------------------------------------------------------------------
			local abHBConn, abCharConn = nil, nil
			local abTruePart, abRealRootAtt, abFakeBool = nil, nil, nil
			local abNextDropScan = 0

			local function abRestoreAttachment()
				local _, hrp = tbl12.Char()
				if abFakeBool and abFakeBool.Parent then
					pcall(function()
						abFakeBool:Destroy()
					end)
				end
				abFakeBool = nil
				if abRealRootAtt and abRealRootAtt.Parent then
					pcall(function()
						if hrp and hrp.Parent then
							abRealRootAtt.Parent = hrp
						else
							abRealRootAtt:Destroy()
						end
					end)
				end
				abRealRootAtt = nil
				if abTruePart and abTruePart.Parent then
					pcall(function()
						abTruePart:Destroy()
					end)
				end
				abTruePart = nil
			end

			local function abEnsureAttachment(hrp)
				if not (hrp and hrp.Parent) then
					return
				end
				if not (abTruePart and abTruePart.Parent) then
					local p = Instance.new("Part")
					p.Name = "TruePositionPart"
					p.Size = Vector3.new(1, 1, 1)
					p.Transparency = 1
					p.Anchored = true
					p.CanCollide = false
					p.CanQuery = false
					p.CanTouch = false
					p.Massless = true
					p.CFrame = hrp.CFrame
					p.Parent = workspace
					abTruePart = p
				else
					abTruePart.CFrame = hrp.CFrame
				end

				if not (abRealRootAtt and abRealRootAtt.Parent == abTruePart) then
					local ra = hrp:FindFirstChild("RootAttachment")
					if ra and ra:IsA("Attachment") then
						abRealRootAtt = ra
						ra.Parent = abTruePart
						local fake = Instance.new("BoolValue")
						fake.Name = "RootAttachment"
						fake.Parent = hrp
						abFakeBool = fake
					end
				end
				if hrp.Massless then
					hrp.Massless = false
				end
			end

			local function abScanBlobmanWelds(char, hrp)
				local function checkModel(m)
					if not (m and m.Name == "CreatureBlobman") then
						return
					end
					local scriptObj = m:FindFirstChild("BlobmanSeatAndOwnerScript")
					local dropRemote = scriptObj and scriptObj:FindFirstChild("CreatureDrop")
					for _, detName in ipairs({ "RightDetector", "LeftDetector" }) do
						local det = m:FindFirstChild(detName)
						if det then
							for _, wName in ipairs({ "RightWeld", "LeftWeld", "AlignOrientation", "AlignPosition" }) do
								local w = det:FindFirstChild(wName)
								if w then
									local hitOurs = false
									pcall(function()
										if (w:IsA("JointInstance") and ((w.Part1 and w.Part1:IsDescendantOf(char)) or (w.Part0 and w.Part0:IsDescendantOf(char))))
											or (w:IsA("Constraint") and w.Attachment0 and w.Attachment0:IsDescendantOf(char))
										then
											hitOurs = true
										end
									end)
									if hitOurs then
										if dropRemote then
											pcall(function()
												dropRemote:FireServer(w, hrp)
											end)
										end
										pcall(function()
											if tbl11 and tbl11.Struggle then
												tbl11.Struggle:FireServer(localPlayer)
											end
										end)
									end
								end
							end
						end
					end
				end

				for _, child in ipairs(workspace:GetChildren()) do
					if child.Name == "CreatureBlobman" then
						checkModel(child)
					elseif child.Name:sub(-13) == "SpawnedInToys" then
						for _, toy in ipairs(child:GetChildren()) do
							if toy.Name == "CreatureBlobman" then
								checkModel(toy)
							end
						end
					end
				end
				local plotItems = workspace:FindFirstChild("PlotItems")
				if plotItems then
					for _, pf in ipairs(plotItems:GetChildren()) do
						for _, toy in ipairs(pf:GetChildren()) do
							if toy.Name == "CreatureBlobman" then
								checkModel(toy)
							end
						end
					end
				end
			end

			KozAnti.SetAntiBlobman = function(on)
				tbl8.AntiBlobman = on and true or false
				if not on then
					for _, c in pairs({ abHBConn, abCharConn }) do
						if c then
							pcall(function()
								c:Disconnect()
							end)
						end
					end
					abHBConn, abCharConn = nil, nil
					abRestoreAttachment()
					return
				end
				if abHBConn then
					return
				end
				abCharConn = localPlayer.CharacterAdded:Connect(function()
					abRealRootAtt, abFakeBool = nil, nil
				end)
				abHBConn = RunService.Heartbeat:Connect(function()
					if flag11 or not tbl8.AntiBlobman then
						KozAnti.SetAntiBlobman(false)
						return
					end
					local char, hrp = tbl12.Char()
					if not (char and hrp) then
						return
					end
					abEnsureAttachment(hrp)
					local now = os.clock()
					if now >= abNextDropScan then
						abNextDropScan = now + 0.12
						pcall(abScanBlobmanWelds, char, hrp)
					end
				end)
			end

			-- ------------------------------------------------------------------
			-- 2) Anti Network Ownership (kar.txt: valid space Hold/Drop loop)
			-- ------------------------------------------------------------------
			local anoToken = 0
			local anoToy = nil
			local anoDummyEGE = nil
			local anoCharConn = nil

			local function anoEnsureDummyEGE(on)
				local ce = ReplicatedStorage:FindFirstChild("CharacterEvents")
				if not ce then
					return
				end
				if on then
					if not (anoDummyEGE and anoDummyEGE.Parent) then
						local existing = ce:FindFirstChild("EndGrabEarly")
						if not existing then
							local bv = Instance.new("BoolValue")
							bv.Name = "EndGrabEarly"
							bv.Parent = ce
							anoDummyEGE = bv
						end
					end
				else
					if anoDummyEGE and anoDummyEGE.Parent then
						pcall(function()
							anoDummyEGE:Destroy()
						end)
					end
					anoDummyEGE = nil
				end
			end

			-- Legacy hand-welded Heart is disabled. Heart now uses the exact
			-- Immortality Totem hold path: FoodHamburger grip + hand-following local skin.
			local handHeartModel = nil
			local handHeartArm = nil
			local handHeartStepConn = nil
			local handHeartCharConn = nil
			local handHeartHiddenMug = nil
			local handHeartHeldMug = nil
			local handHeartScanAt = 0

			local function hhIsHeartSelected()
				if tbl9 and tbl9.AntiInputDisplayType == "Heart" then
					return true
				end
				local dd = options and options.AITSkinDropdown
				return (dd and dd.Value == "Heart") or false
			end

			local function hhSetMugHidden(mug, hide)
				if not mug then
					return
				end
				pcall(function()
					for _, d in ipairs(mug:GetDescendants()) do
						if d:IsA("BasePart") and d.Name ~= "HoldPart" then
							d.Transparency = hide and 1 or 0
						elseif d:IsA("Decal") or d:IsA("Texture") then
							d.Transparency = hide and 1 or 0
						end
					end
				end)
			end

			local function hhFindHeldCupMug(char)
				local leftArm = char and char:FindFirstChild("Left Arm")
				local gripAtt = leftArm and leftArm:FindFirstChild("LeftGripAttachment")
				local function isMugHeld(m)
					if not (m and m.Parent and m.Name == "CupMugBrown") then
						return false
					end
					local hp = m:FindFirstChild("HoldPart")
					local rc = hp and hp:FindFirstChild("RigidConstraint")
					local att1 = rc and rc.Attachment1
					if att1 and ((gripAtt and att1 == gripAtt) or att1:IsDescendantOf(char)) then
						return true
					end
					return false
				end
				if isMugHeld(handHeartHeldMug) then
					return handHeartHeldMug
				end
				if isMugHeld(anoToy) then
					handHeartHeldMug = anoToy
					return anoToy
				end
				local now = os.clock()
				if (now - handHeartScanAt) < 0.15 then
					return nil
				end
				handHeartScanAt = now
				local folder = kaFindMyToysFolder()
				if folder then
					for _, child in ipairs(folder:GetChildren()) do
						if isMugHeld(child) then
							handHeartHeldMug = child
							return child
						end
					end
				end
				handHeartHeldMug = nil
				return nil
			end

			local handHeartLeftMotor, handHeartRightMotor = nil, nil
			local handHeartSavedLeft, handHeartSavedRight = nil, nil

			local function hhResetLeftShoulder()
				pcall(function()
					if handHeartLeftMotor and handHeartLeftMotor.Parent and handHeartSavedLeft then
						handHeartLeftMotor.Transform = handHeartSavedLeft
					end
					if handHeartRightMotor and handHeartRightMotor.Parent and handHeartSavedRight then
						handHeartRightMotor.Transform = handHeartSavedRight
					end
				end)
				handHeartLeftMotor, handHeartRightMotor = nil, nil
				handHeartSavedLeft, handHeartSavedRight = nil, nil
			end

			local function hhPoseBothHands(char)
				local torso = char and (char:FindFirstChild("Torso") or char:FindFirstChild("UpperTorso"))
				local left = torso and torso:FindFirstChild("Left Shoulder")
				local right = torso and torso:FindFirstChild("Right Shoulder")
				if left and left:IsA("Motor6D") then
					if handHeartLeftMotor ~= left then
						handHeartLeftMotor, handHeartSavedLeft = left, left.Transform
					end
					left.Transform = CFrame.Angles(math.rad(70), 0, math.rad(50))
				end
				if right and right:IsA("Motor6D") then
					if handHeartRightMotor ~= right then
						handHeartRightMotor, handHeartSavedRight = right, right.Transform
					end
					right.Transform = CFrame.Angles(math.rad(70), 0, math.rad(-50))
				end
			end

			local function hhDestroyHeart()
				if handHeartModel then
					pcall(function()
						handHeartModel:Destroy()
					end)
					handHeartModel = nil
				end
				handHeartArm = nil
				if handHeartHiddenMug then
					if not (tbl8 and tbl8.AntiInputLag) then
						hhSetMugHidden(handHeartHiddenMug, false)
					end
					handHeartHiddenMug = nil
				end
			end

			local function hhBuild3DPinkHeart(char)
				local arm = char and (char:FindFirstChild("Torso") or char:FindFirstChild("UpperTorso"))
				if not (arm and arm:IsA("BasePart")) then
					return nil
				end
				if handHeartModel and handHeartModel.Parent == char and handHeartArm == arm then
					return handHeartModel
				end
				hhDestroyHeart()

				local mdl = Instance.new("Model")
				mdl.Name = "KozmozHandHeart"

				local root = Instance.new("Part")
				root.Name = "HeartGripRoot"
				root.Size = Vector3.new(0.2, 0.2, 0.2)
				root.Transparency = 1
				root.CanCollide = false
				root.CanTouch = false
				root.CanQuery = false
				root.Massless = true
				root.CastShadow = false
				root.CFrame = arm.CFrame * CFrame.new(0, -0.10, -0.90)
				root.Parent = mdl
				mdl.PrimaryPart = root

				local gripWeld = Instance.new("Weld")
				gripWeld.Name = "HeartHandWeld"
				gripWeld.Part0 = arm
				gripWeld.Part1 = root
				-- Center the heart in front of the torso so both arms can meet around it.
				gripWeld.C0 = CFrame.new(0, -0.10, -0.90)
				gripWeld.Parent = root

				local heartPink = Color3.fromRGB(255, 96, 158)
				local pieces = {
		{ "LeftLobe",    Vector3.new(0.60, 0.56, 0.02), CFrame.new(-0.24,  0.20, 0) * CFrame.Angles(0, 0,  math.rad(18)) },
		{ "RightLobe",   Vector3.new(0.60, 0.56, 0.02), CFrame.new( 0.24,  0.20, 0) * CFrame.Angles(0, 0, -math.rad(18)) },
		{ "CenterCore",  Vector3.new(0.58, 0.54, 0.02), CFrame.new( 0.00,  0.03, 0) },
		{ "LeftCheek",   Vector3.new(0.46, 0.62, 0.02), CFrame.new(-0.17, -0.04, 0) * CFrame.Angles(0, 0,  math.rad(35)) },
		{ "RightCheek",  Vector3.new(0.46, 0.62, 0.02), CFrame.new( 0.17, -0.04, 0) * CFrame.Angles(0, 0, -math.rad(35)) },
		{ "LeftTaper",   Vector3.new(0.30, 0.46, 0.02), CFrame.new(-0.08, -0.23, 0) * CFrame.Angles(0, 0,  math.rad(31)) },
		{ "RightTaper",  Vector3.new(0.30, 0.46, 0.02), CFrame.new( 0.08, -0.23, 0) * CFrame.Angles(0, 0, -math.rad(31)) },
		{ "BottomPoint", Vector3.new(0.20, 0.22, 0.02), CFrame.new( 0.00, -0.39, 0) },
				}

				for _, spec in ipairs(pieces) do
					local p = Instance.new("Part")
					p.Name = spec[1]
					p.Size = spec[2]
					p.Color = heartPink
					p.Material = Enum.Material.SmoothPlastic
					p.Reflectance = 0.14
					p.Transparency = 0
					p.CanCollide = false
					p.CanTouch = false
					p.CanQuery = false
					p.Massless = true
					p.CastShadow = false
					pcall(function()
						p.TopSurface = Enum.SurfaceType.Smooth
						p.BottomSurface = Enum.SurfaceType.Smooth
					end)
					local mesh = Instance.new("SpecialMesh")
					mesh.MeshType = Enum.MeshType.Sphere
					mesh.Parent = p
					p.CFrame = root.CFrame * spec[3]
					p.Parent = mdl

					local w = Instance.new("Weld")
					w.Part0 = root
					w.Part1 = p
					w.C0 = spec[3]
					w.Parent = p
				end

				pcall(function()
					local hl = Instance.new("Highlight")
					hl.Name = "HeartGloss"
					hl.Adornee = mdl
					hl.DepthMode = Enum.HighlightDepthMode.Occluded
					hl.FillColor = Color3.fromRGB(255, 135, 190)
					hl.FillTransparency = 0.84
					hl.OutlineColor = Color3.fromRGB(255, 205, 228)
					hl.OutlineTransparency = 0.62
					hl.Parent = mdl
				end)

				mdl.Parent = char
				handHeartModel = mdl
				handHeartArm = arm
				return mdl
			end

			local handHeartWasHolding = false

			KozAnti.SyncHandHeart = function()
				-- Heart must be held like Immortality Totem. The old torso weld +
				-- forced shoulder Transform made the hand appear behind the body.
				-- Keep this as cleanup only; the visual is handled by SyncNetOwnerVisual.
				if handHeartStepConn then
					pcall(function() handHeartStepConn:Disconnect() end)
					handHeartStepConn = nil
				end
				if handHeartCharConn then
					pcall(function() handHeartCharConn:Disconnect() end)
					handHeartCharConn = nil
				end
				hhDestroyHeart()
				if handHeartWasHolding then
					handHeartWasHolding = false
					hhResetLeftShoulder()
				end
			end

			local function anoResolveToyName()
				local raw = tostring(tbl9.AntiInputType or "FoodHamburger")
				if raw == "Heart" or raw == "Immortality Totem" or raw == "None" or raw == "" or raw == "nil" then
					return "FoodHamburger"
				end
				return raw
			end

			local function anoHideCupIfHeart(toy)
				local disp = tbl9 and tbl9.AntiInputDisplayType
				if disp == nil and options and options.AITSkinDropdown then
					disp = options.AITSkinDropdown.Value
				end
				if not (toy and (disp == "Heart" or disp == "Immortality Totem")) then
					return
				end
				pcall(function()
					for _, d in ipairs(toy:GetDescendants()) do
						if d:IsA("BasePart") then
							d.Transparency = 1
						elseif d:IsA("Decal") or d:IsA("Texture") then
							d.Transparency = 1
						end
					end
				end)
			end

			local function anoFindOrSpawnToy(hrp)
				local wantName = anoResolveToyName()
				if anoToy and anoToy.Parent and anoToy.Name == wantName and anoToy:FindFirstChild("HoldPart") then
					anoHideCupIfHeart(anoToy)
					return anoToy
				end
				if anoToy and anoToy.Parent then
					kaDestroyToy(anoToy)
					anoToy = nil
				end
				local folder = kaFindMyToysFolder()
				local plotItems = workspace:FindFirstChild("PlotItems")
				local plotNum = plotItems and AV_GetMyPlotNumber()
				local plotFolder = plotNum and plotItems:FindFirstChild("Plot" .. plotNum)
				for _, container in ipairs({ folder, plotFolder }) do
					if container then
						for _, t in ipairs(container:GetChildren()) do
							if t.Name == wantName and t:FindFirstChild("HoldPart") then
								anoToy = t
								anoHideCupIfHeart(t)
								return t
							end
						end
					end
				end
				local spawnCF = hrp and (hrp.CFrame * CFrame.new(0, 6, 8)) or CFrame.new(0, 25, 0)
				local spawned = kaSpawnToy(wantName, spawnCF)
				if spawned then
					anoToy = spawned
					anoHideCupIfHeart(spawned)
				end
				return anoToy
			end


