			local function anoSkinDecode64(src)
				local alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
				local map = {}
				for i = 1, #alphabet do map[alphabet:sub(i, i)] = i - 1 end
				local out = {}
				for i = 1, #src, 4 do
					local a, b, c, d = src:sub(i, i), src:sub(i+1, i+1), src:sub(i+2, i+2), src:sub(i+3, i+3)
					local n = (map[a] or 0)*262144 + (map[b] or 0)*4096 + (map[c] or 0)*64 + (map[d] or 0)
					table.insert(out, string.char(math.floor(n/65536)%256))
					if c ~= "=" then table.insert(out, string.char(math.floor(n/256)%256)) end
					if d ~= "=" then table.insert(out, string.char(n%256)) end
				end
				return table.concat(out)
			end
			local function anoGetTotemAsset()
				if anoTotemAttempted then return anoTotemAsset end
				anoTotemAttempted = true
				-- KOZMOZ: DISKE YAZIM YOK. Totem gorseli png olarak yazilmiyor;
				-- oyunun kendi totem gorseli kullanilir (asset = nil -> fallback).
				if anoTotemAsset == nil then anoTotemAsset = false end
				local ok, asset = false, nil
				if ok then anoTotemAsset = asset end
				return anoTotemAsset
			end
