			local anoHeartIconAsset, anoHeartIconAttempted = nil, false
			local function anoGetHeartIconAsset()
				-- KOZMOZ: DISKE YAZIM YOK -> kalp ikonu dosyaya yazilmiyor,
				-- oyunun kendi ikonu kullanilir (nil = fallback).
				return nil
			end
			KozAnti.GetNetOwnerSkinIcon = function(kind)
				if kind == "Heart" then return anoGetHeartIconAsset() end
				if kind == "Immortality Totem" then return anoGetTotemAsset() end
				return nil
			end
			local function anoRemoveSkin()
				if anoSkinStepConn then anoSkinStepConn:Disconnect(); anoSkinStepConn = nil end
				if anoSkinModel then pcall(function() anoSkinModel:Destroy() end) end
				anoSkinModel, anoSkinChar, anoSkinMode = nil, nil, nil
			end
			local function anoSkinPart(name, size, color, localCF, parent, invisible)
				local part = Instance.new("Part")
				part.Name, part.Size = name, size
				part.Color, part.Material = color, Enum.Material.SmoothPlastic
				part.Anchored, part.Massless = true, true
				part.CanCollide, part.CanTouch, part.CanQuery = false, false, false
				part.CastShadow = false
				part.Transparency = invisible and 1 or 0
				part.CFrame = localCF
				part.Parent = parent
				return part
			end
			local function anoBuildWorldHeart(model)
				-- Eight shaded, truly 3D lobes; world size is constant at any camera distance.
				local pieces = {
					{ -.23, .19, -.02, .58, .57, .32, 18 },
					{  .23, .19, -.02, .58, .57, .32,-18 },
					{ 0, .02, .00, .58, .55, .34, 0 },
					{ -.17,-.05, .01, .46, .62, .33, 35 },
					{  .17,-.05, .01, .46, .62, .33,-35 },
					{ -.08,-.25, .02, .30, .47, .29, 31 },
					{  .08,-.25, .02, .30, .47, .29,-31 },
					{ 0,-.39, .03, .23, .25, .25, 0 },
				}
				for i, v in ipairs(pieces) do
					local part = anoSkinPart("RedHeartLobe" .. i,
						Vector3.new(v[4], v[5], v[6]),
						i == 3 and Color3.fromRGB(230, 24, 47) or Color3.fromRGB(240, 35, 56),
						CFrame.new(v[1], v[2], v[3])*CFrame.Angles(0, 0, math.rad(v[7])), model, false)
					local mesh = Instance.new("SpecialMesh")
					mesh.MeshType = Enum.MeshType.Sphere
					mesh.Parent = part
				end
			end
			local function anoDrawTotem(faceGui)
				local asset = anoGetTotemAsset()
				if asset then
					local image = Instance.new("ImageLabel")
					image.Name = "FlatImmortalityTotem"
					image.BackgroundTransparency = 1
					image.Size = UDim2.fromScale(1, 1)
					image.Image = asset
					image.ScaleType = Enum.ScaleType.Fit
					image.Parent = faceGui
					return
				end
				-- Executor without local image loading: a simple 2D totem silhouette.
				local function rect(name, color, x, y, w, h)
					local frame = Instance.new("Frame")
					frame.Name, frame.BackgroundColor3, frame.BorderSizePixel = name, color, 0
					frame.Position, frame.Size = UDim2.fromScale(x, y), UDim2.fromScale(w, h)
					frame.Parent = faceGui
				end
				local gold, dark, green = Color3.fromRGB(217, 177, 71), Color3.fromRGB(112, 79, 41), Color3.fromRGB(68, 117, 60)
				rect("Legs", gold, .38, .66, .24, .23)
				rect("Arms", gold, .20, .36, .60, .29)
				rect("Head", gold, .33, .14, .34, .42)
				rect("Crest", dark, .37, .10, .26, .06)
				rect("LeftEye", green, .37, .29, .09, .14)
				rect("RightEye", green, .54, .29, .09, .14)
				rect("BodyRune", green, .44, .51, .12, .13)
			end
			local function anoBuildWorldTotem(model)
				local flat = anoSkinPart("TotemFlatCanvas", Vector3.new(1.02, 1.13, .025),
					Color3.new(1, 1, 1), CFrame.new(), model, true)
				for _, face in ipairs({ Enum.NormalId.Front, Enum.NormalId.Back }) do
					local surface = Instance.new("SurfaceGui")
					surface.Name = "Totem2D"
					surface.Face = face
					surface.CanvasSize = Vector2.new(147, 160)
					surface.AlwaysOnTop = false
					surface.LightInfluence = 0
					surface.Parent = flat
					anoDrawTotem(surface)
				end
			end
			local function anoHandPosition(char, torso, side)
				local limb = char:FindFirstChild(side .. "Hand") or char:FindFirstChild(side .. " Arm")
				if not (limb and limb:IsA("BasePart")) then return nil end
				local grip = limb:FindFirstChild(side .. "GripAttachment")
				if grip and grip:IsA("Attachment") then return grip.WorldPosition end
				return limb.Position + torso.CFrame:VectorToWorldSpace(Vector3.new(0, -.22, 0))
			end
			local function anoSkinHandCFrame(char, torso, mode)
				local left, right = anoHandPosition(char, torso, "Left"), anoHandPosition(char, torso, "Right")
				local betweenHands = left and right and (left + right) * .5
				local handLocal = betweenHands and torso.CFrame:PointToObjectSpace(betweenHands)
				-- Both visual skins share the same between-the-hands placement; no toy movement.
				local lift = .28
				if not handLocal then
					return torso.CFrame * CFrame.new(0, -.05 + lift, -.73)
				end
				local depth = math.min(handLocal.Z + .08, -.73)
				return torso.CFrame * CFrame.new(
					math.clamp(handLocal.X, -.18, .18),
					math.clamp(handLocal.Y + .18, -.20, .22) + lift,
					depth
				)
			end
			-- Make the real selected toy locally invisible as soon as it appears,
			-- before kaSpawnToy/anoNullify finish. Only render properties are touched.
			local anoQuickToyConn = nil
			local anoQuickContainerConns = {}
			local anoQuickSaved = setmetatable({}, { __mode = "k" })
			local function anoQuickHideDesc(desc, toy)
				if desc:IsA("BasePart") then
					if not anoQuickSaved[desc] then
						anoQuickSaved[desc] = { toy, desc.LocalTransparencyModifier, "part" }
					end
					pcall(function() desc.LocalTransparencyModifier = 1 end)
				elseif desc:IsA("Decal") or desc:IsA("Texture") then
					if not anoQuickSaved[desc] then
						anoQuickSaved[desc] = { toy, desc.Transparency, "image" }
					end
					pcall(function() desc.Transparency = 1 end)
				end
			end
			local function anoQuickOwnedToy(toy)
					if not (toy and toy:IsA("Model") and toy.Name == anoResolveToyName()) then return false end
				local myFolder = workspace:FindFirstChild(localPlayer.Name .. "SpawnedInToys")
				if myFolder and toy.Parent == myFolder then return true end
				local plotItems = workspace:FindFirstChild("PlotItems")
				local plotNum = plotItems and AV_GetMyPlotNumber()
				local myPlot = plotNum and plotItems:FindFirstChild("Plot" .. plotNum)
				return myPlot ~= nil and toy.Parent == myPlot
			end
			local function anoQuickHideToy(toy)
				if not anoQuickOwnedToy(toy) then return end
				for _, desc in ipairs(toy:GetDescendants()) do anoQuickHideDesc(desc, toy) end
			end
			local function anoQuickStop()
				if anoQuickToyConn then anoQuickToyConn:Disconnect(); anoQuickToyConn = nil end
				for container, conn in pairs(anoQuickContainerConns) do
					conn:Disconnect(); anoQuickContainerConns[container] = nil
				end
				for part, original in pairs(anoQuickSaved) do
					-- Keep the active Anti Net-Owner toy hidden until its normal destroy finishes.
					if part.Parent and original[1] ~= anoToy then
						pcall(function()
							if original[3] == "part" then
								part.LocalTransparencyModifier = original[2]
							else
								part.Transparency = original[2]
							end
						end)
					end
					anoQuickSaved[part] = nil
				end
			end
			local function anoQuickWatchContainer(container)
				if not (container and container.Parent) or anoQuickContainerConns[container] then return end
				anoQuickContainerConns[container] = container.DescendantAdded:Connect(function(desc)
					if not tbl8.AntiInputLag then return end
					local toy = desc
					while toy and toy.Parent and toy.Parent ~= container do toy = toy.Parent end
					if not (toy and toy.Parent == container and anoQuickOwnedToy(toy)) then return end
					if toy == desc then anoQuickHideToy(toy) else anoQuickHideDesc(desc, toy) end
				end)
				for _, toy in ipairs(container:GetChildren()) do anoQuickHideToy(toy) end
			end
			local function anoQuickScanContainers()
				if flag11 or not tbl8.AntiInputLag then return end
				anoQuickWatchContainer(workspace:FindFirstChild(localPlayer.Name .. "SpawnedInToys"))
				local plots = workspace:FindFirstChild("PlotItems")
				local plotNum = plots and AV_GetMyPlotNumber()
				anoQuickWatchContainer(plotNum and plots:FindFirstChild("Plot" .. plotNum))
			end
			local function anoQuickSync(mode, eligible)
				if not eligible then anoQuickStop(); return end
				if anoQuickToyConn then return end
				-- Observe only the user's own toy containers, not every part in Workspace.
				anoQuickToyConn = workspace.ChildAdded:Connect(function(child)
					if child.Name == localPlayer.Name .. "SpawnedInToys" or child.Name == "PlotItems" then
						task.defer(anoQuickScanContainers)
					end
				end)
				anoQuickScanContainers()
			end
			KozAnti.SyncNetOwnerVisual = function()
				local mode = anoResolveToyName()
				local active = not flag11 and tbl8 and tbl8.AntiInputLag
				local disp = tbl9 and tbl9.AntiInputDisplayType
				if disp == nil and options and options.AITSkinDropdown then
					disp = options.AITSkinDropdown.Value
				end
				local heartSkin = (disp == "Heart")
				local totemSkin = (disp == "Immortality Totem")
				local eligible = active and (heartSkin or totemSkin)
				local skinKey = (heartSkin and "Heart:" or "Totem:") .. tostring(mode)
				anoQuickSync(mode, eligible)
				if not eligible then
					if anoSkinCharConn then anoSkinCharConn:Disconnect(); anoSkinCharConn = nil end
					anoRemoveSkin()
					return
				end
				if not anoSkinCharConn then
					anoSkinCharConn = localPlayer.CharacterAdded:Connect(function()
						anoRemoveSkin()
						task.wait(.5)
						pcall(KozAnti.SyncNetOwnerVisual)
					end)
				end
				local char = localPlayer.Character
				local torso = char and (char:FindFirstChild("UpperTorso") or char:FindFirstChild("Torso"))
				if not (torso and torso:IsA("BasePart")) then anoRemoveSkin(); return end
				if anoSkinModel and anoSkinModel.Parent and anoSkinStepConn
					and anoSkinChar == char and anoSkinMode == skinKey then return end
			anoRemoveSkin()
			local model = Instance.new("Model")
			model.Name = heartSkin and "Heart" or "Immortality Totem"
			model.WorldPivot = CFrame.new()
			if heartSkin then anoBuildWorldHeart(model) else anoBuildWorldTotem(model) end
			model:ScaleTo(heartSkin and 1.16 or 1.31) -- totem matches the heart's visible size
				-- Client-created anchored parts, not welded to the avatar and not sent to server.
				model.Parent = workspace
				anoSkinModel, anoSkinChar, anoSkinMode = model, char, skinKey
				local lastSkinCF = nil
				local function updateHandSkin()
					if not (model.Parent and char.Parent and torso.Parent) then return end
					local nextCF = anoSkinHandCFrame(char, torso, mode)
					if not lastSkinCF or nextCF ~= lastSkinCF then
						model:PivotTo(nextCF)
						lastSkinCF = nextCF
					end
				end
				updateHandSkin()
				anoSkinStepConn = game:GetService("RunService").RenderStepped:Connect(updateHandSkin)
			end
			lib:OnUnload(function()
				if anoSkinCharConn then anoSkinCharConn:Disconnect(); anoSkinCharConn = nil end
				anoQuickStop()
				anoRemoveSkin()
			end)

			end
			KozAnti.SetupNetOwnerSkin()
			KozAnti.SetupNetOwnerSkin = nil

			-- =============================================================
			-- KOZMOZ FIX ("basinca arkadaki kod calismiyor"):
			-- Yukaridaki SetAnti* fonksiyonlari HICBIR ZAMAN cagrilmiyordu.
			-- Toggle'lar reso'nun generic yolunu kullaniyor:
			--     tbl12.SetRuntimeToggle("AntiX", arg) -> sadece tbl8.AntiX = arg
			-- ama motorlar (Heartbeat / DescendantAdded / dongu) bir kere bile
			-- baslatilmiyordu. Sonuc: toggle aciliyor, kod donmuyor.
			-- Asagidaki tablo toggle ID'sini motor fonksiyonuna baglar; dispatcher
			-- SetRuntimeToggle'dan SONRA cagrilir (tbl8 degeri aynen korunur).
			KozAnti.Handlers = {
				AntiBlobman = function(on) KozAnti.SetAntiBlobman(on) end,
				AntiInputLag = function(on) KozAnti.SetAntiNetworkOwnership(on) end,
				AntiBurn = function(on) KozAnti.SetAntiBurn(on) end,
				AntiVoid = function(on) KozAnti.SetAntiVoid(on) end,
				AntiKick = function(on) KozAnti.SetAntiKick(on) end,
				AntiKick2 = function(on) KozAnti.SetAntiKickBreakPCLD(on) end,
				AntiSnowball = function(on) KozAnti.SetAntiSnowball(on) end,
				-- KOZMOZ FIX (image-58): eskiden hicbir motora baglanmamis 4 toggle
				-- vardi; aciliyorlardi ama arkada hicbir sey calismiyordu.
				AntiBanana = function(on) KozAnti.SetAutoBanana(on) end,
				AntiPaint = function(on) KozAnti.SetAntiPaint(on) end,
				AntiPoison = function(on) KozAnti.SetAntiPoison(on) end,
				AntiExplosion = function(on) KozAnti.SetAntiExplosion(on) end,
				-- AntiSticky / AntiStickyLag / AutoReset: kendi donguleri var, cift
				-- motor olusmasin diye buraya baglanmadi.
			}

			-- KOZMOZ FIX (image-56): AntiLag da AYNI dispatcher'dan gecer.
			-- SetAntiLag "LookFigures acikken kapatma" kuralini kendi icinde
			-- korudugu icin cakisma yok; boylece motor gercekten baslar.
			KozAnti.Handlers.AntiLag = function(on) KozAnti.SetAntiLag(on) end
			-- AntiBox acildiginda / UI hazir oldugunda acik toggle'larin motorunu
			-- tekrar baslat (executor yavas yuklendiyse ilk cagri kacmÄ±ÅŸ olabilir).
			tbl12.KozAntiSyncAll = function()
				for id in pairs(KozAnti.Handlers) do
					local tg = toggles and toggles[id]
					if tg and tg.Value == true then
						pcall(KozAnti.Dispatch, id, true)
					end
				end
			end
			task.delay(3, function()
				if type(tbl12.KozAntiSyncAll) == "function" then
					pcall(tbl12.KozAntiSyncAll)
				end
			end)

			KozAnti.Dispatch = function(id, on)
				local h = KozAnti.Handlers[id]
				if type(h) ~= "function" then
					return false
				end
				local ok, err = pcall(h, on == true)
				if not ok then
					warn("[KOZMOZ Anti] " .. tostring(id) .. " motoru hata verdi: " .. tostring(err))
				end
				return ok
			end
			tbl12.KozAntiDispatch = KozAnti.Dispatch

			-- Toggle acilirsa motoru da baslat.
			tbl12.KozAntiStart = function(id)
				local tg = toggles and toggles[id]
				if tg and tg.Value ~= true then
					return
				end
				KozAnti.Dispatch(id, true)
			end

			KozAnti.SetAntiNetworkOwnership = function(on)
				tbl8.AntiInputLag = on and true or false
				anoToken = anoToken + 1
				local myToken = anoToken
				pcall(KozAnti.SyncHandHeart)
				pcall(KozAnti.SyncNetOwnerVisual)

				if not on then
					if anoCharConn then
						pcall(function()
							anoCharConn:Disconnect()
						end)
						anoCharConn = nil
					end
					anoEnsureDummyEGE(false)
					if anoToy then
						local old = anoToy
						anoToy = nil
						task.spawn(kaDestroyToy, old)
					end
					return
				end

				anoEnsureDummyEGE(true)
				if anoCharConn then
					pcall(function()
						anoCharConn:Disconnect()
					end)
				end
				anoCharConn = localPlayer.CharacterAdded:Connect(function()
					task.wait(0.6)
					if tbl8.AntiInputLag and myToken == anoToken then
						anoEnsureDummyEGE(true)
						pcall(KozAnti.SyncNetOwnerVisual)
					end
				end)

				task.spawn(function()
					-- v27: identical to kar.txt - we never move parts by hand into space
					-- (hand-writing CFrames launched the player because of RigidConstraint).
					-- Order: nullify (massless=false + low density) -> DROP(space) -> HOLD
					local spaceDrops = {
						CFrame.new(800000, 500000, -600000),
						CFrame.new(-750000, 420000, 900000),
						CFrame.new(300000, 980000, 700000),
						CFrame.new(-900000, 300000, -800000),
					}

					local function anoSpaceDrop()
						return spaceDrops[math.random(1, #spaceDrops)]
					end

					local function anoNullify(toy)
						if not (toy and toy.Parent) then
							return
						end
						pcall(function()
							for _, d in ipairs(toy:GetDescendants()) do
								if d:IsA("BasePart") then
									d.Transparency = 1
									pcall(function()
										d.LocalTransparencyModifier = 1
									end)
									pcall(function()
										d.CastShadow = false
									end)
									d.CanCollide = false
									d.CanTouch = false
									d.CanQuery = false
									pcall(function()
										d.Massless = false
									end)
									pcall(function()
										d.Archivable = false
									end)
									pcall(function()
										d.EnableFluidForces = false
									end)
									pcall(function()
										d.CustomPhysicalProperties = PhysicalProperties.new(0.7, 0.3, 0.5, 0.1, 0.1)
									end)
								elseif d:IsA("SurfaceAppearance") or d:IsA("Decal") or d:IsA("Texture") then
									pcall(function()
										d.Transparency = 1
									end)
								else
									pcall(function()
										d.Archivable = false
									end)
									pcall(function()
										d.Enabled = false
									end)
								end
							end
						end)
					end

					-- v30: original FTAP Anti Input Lag rhythm restored: DROP + HOLD are fired TOGETHER
					-- every "Grab & Drop Delay" (0.05 s default). We no longer wait for the drop reply
					-- before holding, so the toy never visibly leaves the hand and the arm stays up.
					-- "Anti Net-Owner Delay" now only sets how often the toy is re-nullified.
					local anoHB = RunService.Heartbeat
					local function anoCycleWait()
						local d = math.clamp(tonumber(tbl9.InputLgDelay) or 0.05, 0, 0.3)
						if d > 0 then
							task.wait(d)
						else
							anoHB:Wait()
						end
					end

					local anoInFlight = 0
					local anoLastNull, anoLastNullToy = -math.huge, nil
					while not flag11 and tbl8.AntiInputLag and myToken == anoToken do
						local char, hrp, hum = tbl12.Char()
						if char and hrp and hum and hum.Health > 0 then
							anoEnsureDummyEGE(true)
							local toy = anoFindOrSpawnToy(hrp)

							if toy and toy.Parent then
								local reNull = math.clamp(tonumber(tbl9.ANOwnerDelay) or 3, 1, 10)
								if toy ~= anoLastNullToy or (os.clock() - anoLastNull) >= reNull then
									anoLastNullToy = toy
									anoLastNull = os.clock()
									pcall(anoNullify, toy)
								end

								local holdPart = toy:FindFirstChild("HoldPart") or toy:WaitForChild("HoldPart", 2)
								local holdRF = holdPart
									and (holdPart:FindFirstChild("HoldItemRemoteFunction") or holdPart:WaitForChild("HoldItemRemoteFunction", 2))
								local dropRF = holdPart
									and (holdPart:FindFirstChild("DropItemRemoteFunction") or holdPart:WaitForChild("DropItemRemoteFunction", 2))

								if holdPart and holdPart.Parent and holdRF and dropRF then
									local holder = holdPart:FindFirstChild("HoldingPlayer")
									if holder and holder.Value and holder.Value ~= localPlayer
										and holder.Value ~= localPlayer.Name then
										-- someone else is holding it -> drop into space and destroy
										task.spawn(function()
											pcall(function()
												dropRF:InvokeServer(toy, anoSpaceDrop(), Vector3.zero)
											end)
										end)
										anoHB:Wait()
										pcall(function()
											toy:Destroy()
										end)
										anoToy = nil
									elseif anoInFlight < 10 then
										-- same frame, drop first then hold (server handles them in order)
										local thisToy, thisChar = toy, char
										anoInFlight += 2
										task.spawn(function()
											pcall(function()
												dropRF:InvokeServer(thisToy, anoSpaceDrop(), Vector3.zero)
											end)
											anoInFlight -= 1
										end)
										task.spawn(function()
											pcall(function()
												holdRF:InvokeServer(thisToy, thisChar)
											end)
											anoInFlight -= 1
										end)
									end
								end
							end
						end
						anoCycleWait()
					end
				end)
			end

			-- ------------------------------------------------------------------
			-- 3) Anti Burn (kar.txt: FactoryIsland / Hole ExtinguishPart + FireDebounce)
			-- ------------------------------------------------------------------
			local aburnHBConn, aburnCharConn = nil, nil
			local aburnExtinguish = nil
			local aburnSaved = nil

			local function aburnFindExtinguishPart()
				if aburnExtinguish and aburnExtinguish.Parent then
					return aburnExtinguish
				end
				local m = workspace:FindFirstChild("Map")
				if m then
					local hole = m:FindFirstChild("Hole")
					local psh = hole and hole:FindFirstChild("PoisonSmallHole")
					local ep = psh and psh:FindFirstChild("ExtinguishPart")
					if ep and ep:IsA("BasePart") then
						aburnExtinguish = ep
						return ep
					end
					for _, d in ipairs(m:GetDescendants()) do
						if d:IsA("BasePart") and d.Name == "ExtinguishPart" then
							aburnExtinguish = d
							return d
						end
					end
				end
				for _, d in ipairs(workspace:GetDescendants()) do
					if d:IsA("BasePart") and d.Name == "ExtinguishPart" then
						aburnExtinguish = d
						return d
					end
				end
				return nil
			end

			local function aburnSetFireScript(disabled)
				pcall(function()
					local ps = localPlayer:FindFirstChild("PlayerScripts")
					local s = ps and ps:FindFirstChild("OnFireAnimationScript")
					if s and s:IsA("LocalScript") then
						s.Disabled = disabled
						s.Enabled = not disabled
					end
				end)
			end

			local function aburnRestorePart()
				if aburnExtinguish and aburnExtinguish.Parent and aburnSaved then
					pcall(function()
						aburnExtinguish.Size = aburnSaved.Size
						aburnExtinguish.CFrame = aburnSaved.CFrame
						aburnExtinguish.CanCollide = aburnSaved.CanCollide
						aburnExtinguish.CanTouch = aburnSaved.CanTouch
						aburnExtinguish.Transparency = aburnSaved.Transparency
					end)
				end
				aburnSaved = nil
			end

			KozAnti.SetAntiBurn = function(on)
				tbl8.AntiBurn = on and true or false
				if not on then
					for _, c in pairs({ aburnHBConn, aburnCharConn }) do
						if c then
							pcall(function()
								c:Disconnect()
							end)
						end
					end
					aburnHBConn, aburnCharConn = nil, nil
					aburnSetFireScript(false)
					aburnRestorePart()
					return
				end
				if aburnHBConn then
					return
				end
				aburnSetFireScript(true)
				aburnCharConn = localPlayer.CharacterAdded:Connect(function()
					task.wait(0.3)
					if tbl8.AntiBurn then
						aburnSetFireScript(true)
					end
				end)
				aburnHBConn = RunService.Heartbeat:Connect(function()
					if flag11 or not tbl8.AntiBurn then
						KozAnti.SetAntiBurn(false)
						return
					end
					local char, hrp, hum = tbl12.Char()
					if not (char and hrp and hum) then
						return
					end
					local onFire = (hum:FindFirstChild("FireDebounce") ~= nil)
						or (hrp:FindFirstChild("FireParticleEmitter") ~= nil)
						or (hrp:FindFirstChild("FireLight") ~= nil)
					if not onFire then
						local firePart = hrp:FindFirstChild("FirePlayerPart")
						if firePart and firePart:FindFirstChild("CanBurn") and firePart.CanBurn.Value then
							onFire = true
						end
					end
					if onFire then
						pcall(function()
							local fl = hrp:FindFirstChild("FireLight")
							if fl then
								fl:Destroy()
							end
							local fpe = hrp:FindFirstChild("FireParticleEmitter")
							if fpe and fpe:IsA("ParticleEmitter") then
								fpe.Enabled = false
							end
							local overlay = playerGui and playerGui:FindFirstChild("ScreenOverlayGui")
							local fade = overlay and overlay:FindFirstChild("FireFade")
							if fade then
								fade.Visible = false
							end
						end)
						local ep = aburnFindExtinguishPart()
						if ep then
							if not aburnSaved then
								aburnSaved = {
									Size = ep.Size,
									CFrame = ep.CFrame,
									CanCollide = ep.CanCollide,
									CanTouch = ep.CanTouch,
									Transparency = ep.Transparency,
								}
							end
							pcall(function()
								if ep:FindFirstChild("Tex") then
									ep.Tex:Destroy()
								end
								ep.Transparency = 1
								ep.CanCollide = false
								ep.CanTouch = true
								ep.Size = Vector3.new(15, 15, 15)
								ep.CFrame = hrp.CFrame
							end)
						end
					elseif aburnSaved and aburnExtinguish and aburnExtinguish.Parent then
						aburnRestorePart()
					end
				end)
			end

			-- ------------------------------------------------------------------
			-- 4) Anti Void (kar.txt: FallenPartsDestroyHeight = -5000 + Spawn TP)
			-- ------------------------------------------------------------------
			local avHBConn = nil
			local avOrigDestroyHeight = nil

			local function avGetSafeSpawnCF()
				local sl = workspace:FindFirstChildOfClass("SpawnLocation")
				if not sl then
					local m = workspace:FindFirstChild("Map")
					sl = m and m:FindFirstChildWhichIsA("SpawnLocation", true)
				end
				if sl then
					return CFrame.new(sl.Position + Vector3.new(0, 5, 0))
				end
				return CFrame.new(0, 20, 0)
			end

			KozAnti.SetAntiVoid = function(on)
				tbl8.AntiVoid = on and true or false
				if not on then
					if avHBConn then
						pcall(function()
							avHBConn:Disconnect()
						end)
						avHBConn = nil
					end
					pcall(function()
						workspace.FallenPartsDestroyHeight = avOrigDestroyHeight or -100
					end)
					return
				end
				if avOrigDestroyHeight == nil then
					pcall(function()
						avOrigDestroyHeight = workspace.FallenPartsDestroyHeight
					end)
				end
				pcall(function()
					workspace.FallenPartsDestroyHeight = -5000
				end)
				if avHBConn then
					return
				end
				avHBConn = RunService.Heartbeat:Connect(function()
					if flag11 or not tbl8.AntiVoid then
						KozAnti.SetAntiVoid(false)
						return
					end
					if tbl8.LoopTP and tbl9.LoopTPType == "VOID" then
						return
					end
					local char, hrp = tbl12.Char()
					if not (char and hrp) then
						return
					end
					local y = hrp.Position.Y
					if y < -120 or y > 15000 then
						local safeCF = avGetSafeSpawnCF()
						pcall(function()
							hrp.AssemblyLinearVelocity = Vector3.zero
							hrp.AssemblyAngularVelocity = Vector3.zero
							if type(char.PivotTo) == "function" then
								char:PivotTo(safeCF)
							else
								hrp.CFrame = safeCF
							end
						end)
					end
				end)
			end

			-- ------------------------------------------------------------------
			-- 5) Anti Kick (kar.txt: NinjaShuriken1 StickyWeld onto FirePlayerPart)
			-- ------------------------------------------------------------------
			local akToken = 0
			local akShuriken = nil
			local akCharConn = nil
			local akHighlight = nil

			local function akSyncHighlight(model)
				local cfg = tbl7 and tbl7.AntiKickSettings
				if not (model and model.Parent and cfg and cfg.Highlight) then
					if akHighlight and akHighlight.Parent then
						pcall(function()
							akHighlight:Destroy()
						end)
					end
					akHighlight = nil
					return
				end
				if not (akHighlight and akHighlight.Parent == model) then
					if akHighlight then
						pcall(function()
							akHighlight:Destroy()
						end)
					end
					local hl = Instance.new("Highlight")
					hl.Name = "KozAKHighlight"
					hl.Adornee = model
					hl.Parent = model
					akHighlight = hl
				end
				pcall(function()
					akHighlight.FillColor = cfg.FillColor or Color3.new(1, 1, 1)
					akHighlight.FillTransparency = cfg.FillTrans or 0.5
					akHighlight.OutlineColor = cfg.OutlineColor or Color3.new(0, 0, 0)
					akHighlight.OutlineTransparency = cfg.OutlineTrans or 0
				end)
			end

			local function akCleanShuriken()
				if akHighlight then
					pcall(function()
						akHighlight:Destroy()
					end)
					akHighlight = nil
				end
				if akShuriken and akShuriken.Parent then
					local old = akShuriken
					akShuriken = nil
					task.spawn(kaDestroyToy, old)
				end
				akShuriken = nil
				local folder = kaFindMyToysFolder()
				if folder then
					for _, c in ipairs(folder:GetChildren()) do
						if c.Name == "NinjaShuriken1" or c:FindFirstChild("IsAntiKickItem") then
							task.spawn(kaDestroyToy, c)
						end
					end
				end
			end

			local function akEnsureShurikenWelded()
				local char, hrp, hum = tbl12.Char()
				if not (char and hrp and hum and hum.Health > 0) then
					return
				end
				local firePart = hrp:FindFirstChild("FirePlayerPart") or hrp
				local stickyEvents = ReplicatedStorage:FindFirstChild("PlayerEvents")
				local stickyEvent = stickyEvents and stickyEvents:FindFirstChild("StickyPartEvent")

				if not (akShuriken and akShuriken.Parent) then
					local folder = kaFindMyToysFolder()
					if folder then
						for _, c in ipairs(folder:GetChildren()) do
							if c.Name == "NinjaShuriken1" or c:FindFirstChild("IsAntiKickItem") then
								akShuriken = c
								break
							end
						end
					end
				end

				if not (akShuriken and akShuriken.Parent) then
					local spawned = kaSpawnToy("NinjaShuriken", hrp.CFrame * CFrame.new(0, 8, 5))
					if not spawned then
						return
					end
					pcall(function()
						spawned.Name = "NinjaShuriken1"
						if not spawned:FindFirstChild("IsAntiKickItem") then
							local tag = Instance.new("BoolValue")
							tag.Name = "IsAntiKickItem"
							tag.Value = true
							tag.Parent = spawned
						end
					end)
					akShuriken = spawned
				end

				local stickyPart = akShuriken:FindFirstChild("StickyPart")
				local stickyWeld = stickyPart and stickyPart:FindFirstChild("StickyWeld")
				if not stickyPart then
					kaDestroyToy(akShuriken)
					akShuriken = nil
					return
				end

				for _, d in ipairs(akShuriken:GetDescendants()) do
					if d:IsA("BasePart") then
						pcall(function()
							d.CanCollide = false
							d.Massless = true
							d.Transparency = (tbl7 and tbl7.AntiKickSettings and tbl7.AntiKickSettings.Highlight) and 0 or 1
						end)
					elseif d:IsA("Decal") or d:IsA("Texture") then
						pcall(function()
							d.Transparency = 1
						end)
					end
				end
				akSyncHighlight(akShuriken)

				local alreadyWelded = stickyWeld and stickyWeld.Part1 and stickyWeld.Part1:IsDescendantOf(char)
				if not alreadyWelded then
					pcall(function()
						tbl12.SNO(stickyPart)
					end)
					if stickyEvent then
						pcall(function()
							stickyEvent:FireServer(
								stickyPart,
								firePart,
								CFrame.new(0, 0, 0) * CFrame.Angles(0, math.rad(90), math.rad(90))
							)
						end)
					end
				end
			end

			KozAnti.SetAntiKick = function(on)
				tbl8.AntiKick = on and true or false
				tbl12.WakeRuntimeGate("PCLDTracking")
				akToken = akToken + 1
				local myToken = akToken

				if not on then
					if akCharConn then
						pcall(function()
							akCharConn:Disconnect()
						end)
						akCharConn = nil
					end
					akCleanShuriken()
					return
				end

				if akCharConn then
					pcall(function()
						akCharConn:Disconnect()
					end)
				end
				akCharConn = localPlayer.CharacterAdded:Connect(function()
					akShuriken = nil
					task.wait(0.8)
					if tbl8.AntiKick and myToken == akToken then
						pcall(akEnsureShurikenWelded)
					end
				end)

				task.spawn(function()
					while not flag11 and tbl8.AntiKick and myToken == akToken do
						pcall(akEnsureShurikenWelded)
						task.wait(0.3)
					end
				end)
			end

			-- ------------------------------------------------------------------
			-- 6) Anti Kick [Break PCLD] (kar.txt: +50,000 Y two-death PCLD break)
			-- ------------------------------------------------------------------
			local pcldRunning = false
			local pcldToken = 0

			local function runBreakPCLDSequence(myToken)
				if pcldRunning or not tbl8.AntiKick2 or flag11 then
					return
				end
				local char, hrp, hum = tbl12.Char()
				if not (char and hrp and hum and hum.Health > 0) then
					return
				end
				if hum:GetAttribute("BrokenPCLD") then
					return
				end
				pcldRunning = true
				local origCF = hrp.CFrame

				-- Death 1/2: teleport +50,000 studs up BEFORE dying so PCLD detaches out of range
				fn18("Breaking PCLD (1/2)...", "Anti Kick [Break PCLD]")
				pcall(function()
					hrp.CFrame = origCF + Vector3.new(0, 50000, 0)
				end)
				task.wait(0.12)
				pcall(function()
					hum:SetStateEnabled(Enum.HumanoidStateType.Dead, true)
					hum:ChangeState(Enum.HumanoidStateType.Dead)
					hum.Health = 0
				end)

				local newChar1 = localPlayer.CharacterAdded:Wait()
				if flag11 or not tbl8.AntiKick2 or myToken ~= pcldToken then
					pcldRunning = false
					return
				end
				local hrp1 = newChar1:WaitForChild("HumanoidRootPart", 8)
				local hum1 = newChar1:WaitForChild("Humanoid", 8)
				task.wait(0.25)

				-- Death 2/2: teleport back to original CFrame BEFORE second death
				if hrp1 and hum1 then
					fn18("Breaking PCLD (2/2)...", "Anti Kick [Break PCLD]")
					pcall(function()
						hrp1.CFrame = origCF
					end)
					task.wait(0.12)
					pcall(function()
						hum1:SetStateEnabled(Enum.HumanoidStateType.Dead, true)
						hum1:ChangeState(Enum.HumanoidStateType.Dead)
						hum1.Health = 0
					end)
				end

				local newChar2 = localPlayer.CharacterAdded:Wait()
				if flag11 or myToken ~= pcldToken then
					pcldRunning = false
					return
				end
				local hrp2 = newChar2:WaitForChild("HumanoidRootPart", 8)
				local hum2 = newChar2:WaitForChild("Humanoid", 8)
				task.wait(0.2)
				if hrp2 then
					pcall(function()
						hrp2.CFrame = origCF
						hrp2.AssemblyLinearVelocity = Vector3.zero
					end)
				end
				if hum2 then
					pcall(function()
						hum2:SetAttribute("BrokenPCLD", true)
					end)
				end
				fn18("PCLD Broken (2/2)!", "Anti Kick [Break PCLD]")
				pcldRunning = false
			end

			KozAnti.SetAntiKickBreakPCLD = function(on)
				tbl8.AntiKick2 = on and true or false
				pcldToken = pcldToken + 1
				local myToken = pcldToken
				if not on then
					pcldRunning = false
					return
				end
				task.spawn(runBreakPCLDSequence, myToken)
			end

			-- ------------------------------------------------------------------
			-- 7) Anti Sticky (kar.txt: StickyPartsTouchDetection + foreign sticky detach)
			-- ------------------------------------------------------------------
			local asToken = 0
			local asCharConn = nil

			local function asDisableStickyScript()
				pcall(function()
					local ps = localPlayer:FindFirstChild("PlayerScripts")
					if ps then
						for _, d in ipairs(ps:GetDescendants()) do
							if d:IsA("LocalScript") and (d.Name == "StickyPartsTouchDetection" or d.Name:lower():find("sticky")) then
								d.Disabled = true
								d.Enabled = false
							end
						end
					end
				end)
			end

			KozAnti.SetAntiSticky = function(on)
				tbl8.AntiSticky = on and true or false
				asToken = asToken + 1
				local myToken = asToken

				if not on then
					if asCharConn then
						pcall(function()
							asCharConn:Disconnect()
						end)
						asCharConn = nil
					end
					kaRestoreStickyScriptIfIdle()
					return
				end

				asDisableStickyScript()
				if asCharConn then
					pcall(function()
						asCharConn:Disconnect()
					end)
				end
				asCharConn = localPlayer.CharacterAdded:Connect(function()
					task.wait(0.4)
					if tbl8.AntiSticky and myToken == asToken then
						asDisableStickyScript()
					end
				end)

				task.spawn(function()
					while not flag11 and tbl8.AntiSticky and myToken == asToken do
						local char = tbl12.Char()
						local myFolder = kaFindMyToysFolder()
						if char then
							for _, limb in ipairs(char:GetChildren()) do
								if limb:IsA("BasePart") then
									local okParts, connected = pcall(function()
										return limb:GetConnectedParts()
									end)
									if okParts and type(connected) == "table" then
										for _, cp in ipairs(connected) do
											local parentModel = cp and cp.Parent
											local isProtectedAK = parentModel and (parentModel.Name == "NinjaShuriken1" or parentModel:FindFirstChild("IsAntiKickItem") ~= nil)
											local isMine = myFolder and cp:IsDescendantOf(myFolder)
											if cp.Name == "StickyPart" and not isProtectedAK and not isMine then
												for _, ch in ipairs(cp:GetChildren()) do
													if ch:IsA("TouchTransmitter") or ch.Name == "TouchInterest" then
														pcall(function()
															ch:Destroy()
														end)
													end
												end
												if parentModel then
													local nice = tbl12.FindNicePart and tbl12.FindNicePart(parentModel) or cp
													if nice then
														pcall(tbl12.SNO, nice)
														pcall(tbl12.Grab, nice)
													end
												end
											end
										end
									end
								end
							end
						end
						task.wait(0.12)
					end
				end)
			end

			-- ------------------------------------------------------------------
			-- 8) Anti Snowball (BallSnowball CanTouch=false + WeldHRP unfreeze)
			-- ------------------------------------------------------------------
			local asbToken = 0
			local asbDescConn = nil
			local asbTouchedParts = setmetatable({}, { __mode = "k" })

			local function asbHandleDesc(inst)
				if not tbl8.AntiSnowball then
					return
				end
				if inst:IsA("BasePart") and inst.Parent and inst.Parent.Name == "BallSnowball" then
					asbTouchedParts[inst] = true
					pcall(function()
						inst.CanTouch = false
					end)
				end
			end

			KozAnti.SetAntiSnowball = function(on)
				tbl8.AntiSnowball = on and true or false
				asbToken = asbToken + 1
				local myToken = asbToken

				if not on then
					if asbDescConn then
						pcall(function()
							asbDescConn:Disconnect()
						end)
						asbDescConn = nil
					end
					for p, _ in pairs(asbTouchedParts) do
						if p and p.Parent then
							pcall(function()
								p.CanTouch = true
							end)
						end
					end
					asbTouchedParts = {}
					local char = tbl12.Char()
					if char then
						pcall(tbl12.ToggleCollisions, char, true)
					end
					return
				end

				for _, d in ipairs(workspace:GetDescendants()) do
					asbHandleDesc(d)
				end
				if asbDescConn then
					pcall(function()
						asbDescConn:Disconnect()
					end)
				end
				asbDescConn = workspace.DescendantAdded:Connect(asbHandleDesc)

				task.spawn(function()
					while not flag11 and tbl8.AntiSnowball and myToken == asbToken do
						if not tbl8.GucciAntiGrab then
							local char, hrp, hum = tbl12.Char()
							local weldHRP = hrp and hrp:FindFirstChild("WeldHRP")
							if char and hrp and hum and hum.Health > 0 and weldHRP then
