			-- ------------------------------------------------------------------
			-- 9) Auto Banana (kar.txt: CamPart->"Right Leg" + banish both legs)
			-- ------------------------------------------------------------------
			local abanToken = 0
			local abanCharConn = nil
			local abanBusy = false

			local function abanStripLegsOnce()
				if abanBusy or not tbl8.AntiBanana or flag11 then
					return
				end
				local char, hrp, hum = tbl12.Char()
				if not (char and hrp and hum and hum.Health > 0) then
					return
				end
				local rLeg = char:FindFirstChild("Right Leg")
				local lLeg = char:FindFirstChild("Left Leg")
				if not rLeg and not lLeg then
					return
				end
				abanBusy = true

				local wasGucci = tbl8.GucciAntiGrab
				local wasAntiRag = tbl8.KozAntiRagdoll
				if wasGucci and toggles.GucciAntiGrab then
					pcall(function()
						if toggles.GucciAntiGrab then toggles.GucciAntiGrab:SetValue(false) end
					end)
					task.wait(0.2)
				end
				if wasAntiRag then
					tbl8.KozAntiRagdoll = false
				end

				pcall(function()
					local camPart = hrp:FindFirstChild("CamPart")
					if camPart then
						camPart.Name = "Right Leg"
					end
				end)

				for _ = 1, 3 do
					pcall(function()
						tbl11.RagdollRemote:FireServer(hrp, 0.45)
					end)
					task.wait(0.06)
				end
				task.wait(0.18)

				for _, legName in ipairs({ "Right Leg", "Left Leg" }) do
					for _, child in ipairs(char:GetChildren()) do
						if child:IsA("BasePart") and child.Name == legName then
							pcall(function()
								tbl12.SNO(child)
								child.CFrame = CFrame.new(0, -100000, 0)
							end)
						end
					end
				end
				task.wait(0.35)

				pcall(function()
					hum.Sit = false
					hum.PlatformStand = false
					hum:ChangeState(Enum.HumanoidStateType.GettingUp)
				end)

				if wasAntiRag then
					tbl8.KozAntiRagdoll = true
				end
				if wasGucci and toggles.GucciAntiGrab then
					pcall(function()
						if toggles.GucciAntiGrab then toggles.GucciAntiGrab:SetValue(true) end
					end)
				end
				abanBusy = false
			end

			KozAnti.SetAutoBanana = function(on)
				tbl8.AntiBanana = on and true or false
				abanToken = abanToken + 1
				local myToken = abanToken

				if not on then
					if abanCharConn then
						pcall(function()
							abanCharConn:Disconnect()
						end)
						abanCharConn = nil
					end
					abanBusy = false
					return
				end

				if abanCharConn then
					pcall(function()
						abanCharConn:Disconnect()
					end)
				end
				abanCharConn = localPlayer.CharacterAdded:Connect(function()
					task.wait(1.1)
					if tbl8.AntiBanana and myToken == abanToken then
						pcall(abanStripLegsOnce)
					end
				end)

				task.spawn(function()
					while not flag11 and tbl8.AntiBanana and myToken == abanToken do
						local char = tbl12.Char()
						if char and (char:FindFirstChild("Right Leg") or char:FindFirstChild("Left Leg")) then
							pcall(abanStripLegsOnce)
						end
						task.wait(0.6)
					end
				end)
			end

			-- ------------------------------------------------------------------
			-- 10) Anti Paint (kar.txt: PaintPlayerPart + BucketPaint/Toilet* guard)
			-- ------------------------------------------------------------------
			local apDescConn = nil
			local apPropConns = setmetatable({}, { __mode = "k" })
			local apModified = setmetatable({}, { __mode = "k" })

			local PAINT_PARENTS = {
				BucketPaint = true,
				ToiletGold = true,
				ToiletWhite = true,
			}

			local function apIsPaintPart(inst)
				if not inst:IsA("BasePart") then
					return false
				end
				if inst.Name == "PaintPlayerPart" then
					return true
				end
				local p = inst.Parent
				if p and PAINT_PARENTS[p.Name] and (inst.Name:lower():find("paint") or inst.Name == "Liquid" or inst.Name == "ColorPart") then
					return true
				end
				return false
			end

			local function apApplyPart(part)
				if not tbl8.AntiPaint or not apIsPaintPart(part) then
					return
				end
				apModified[part] = true
				pcall(function()
					part.CanTouch = false
					part.CanQuery = false
					for _, ch in ipairs(part:GetChildren()) do
						if ch:IsA("TouchTransmitter") or ch.Name == "TouchInterest" then
							ch:Destroy()
						end
					end
				end)
				if not apPropConns[part] then
					pcall(function()
						apPropConns[part] = part:GetPropertyChangedSignal("CanTouch"):Connect(function()
							if tbl8.AntiPaint and part.CanTouch then
								part.CanTouch = false
							end
						end)
					end)
				end
			end

			KozAnti.SetAntiPaint = function(on)
				tbl8.AntiPaint = on and true or false
				if not on then
					if apDescConn then
						pcall(function()
							apDescConn:Disconnect()
						end)
						apDescConn = nil
					end
					for _, c in pairs(apPropConns) do
						pcall(function()
							c:Disconnect()
						end)
					end
					apPropConns = {}
					for part, _ in pairs(apModified) do
						if part and part.Parent then
							pcall(function()
								part.CanTouch = true
								part.CanQuery = true
							end)
						end
					end
					apModified = {}
					return
				end

				for _, d in ipairs(workspace:GetDescendants()) do
					apApplyPart(d)
				end
				if apDescConn then
					pcall(function()
						apDescConn:Disconnect()
					end)
				end
				apDescConn = workspace.DescendantAdded:Connect(apApplyPart)
			end

			-- ------------------------------------------------------------------
			-- 11) Anti Poison (kar.txt: Hole + FactoryIsland poison vats/scripts)
			-- ------------------------------------------------------------------
			local apoisonDescConn = nil
			local apoisonModifiedParts = setmetatable({}, { __mode = "k" })
			local apoisonDisabledScripts = setmetatable({}, { __mode = "k" })

			local function apoisonHandleInst(inst)
				if not tbl8.AntiPoison then
					return
				end
				-- NEVER disable ExtinguishPart so Anti Burn always works!
				if inst.Name == "ExtinguishPart" then
					return
				end
				local m = workspace:FindFirstChild("Map")
				if not m or not inst:IsDescendantOf(m) then
					return
				end
				local hole = m:FindFirstChild("Hole")
				local factory = m:FindFirstChild("FactoryIsland")
				local inPoisonContainer = false
				if hole and inst:IsDescendantOf(hole) then
					inPoisonContainer = true
				elseif factory and inst:IsDescendantOf(factory) then
					local full = inst:GetFullName():lower()
					if full:find("poison") or inst.Name == "PoisonHurtPart" then
						inPoisonContainer = true
					end
				elseif inst.Name:lower():find("poison") then
					inPoisonContainer = true
				end
				if not inPoisonContainer then
					return
				end

				if inst:IsA("BasePart") and (inst.Name == "PoisonHurtPart" or inst.Name == "PaintPlayerPart" or inst.Name:lower():find("poison")) then
					apoisonModifiedParts[inst] = true
					pcall(function()
						inst.CanTouch = false
						inst.CanQuery = false
					end)
				elseif (inst:IsA("Script") or inst:IsA("LocalScript")) and inst.Name:lower():find("poison") then
					apoisonDisabledScripts[inst] = true
					pcall(function()
						inst.Disabled = true
					end)
				end
			end

			KozAnti.SetAntiPoison = function(on)
				if not on then
					tbl8.AntiPoison = false
					if apoisonDescConn then
						pcall(function()
							apoisonDescConn:Disconnect()
						end)
						apoisonDescConn = nil
					end
					for part, _ in pairs(apoisonModifiedParts) do
						if part and part.Parent then
							pcall(function()
								part.CanTouch = true
								part.CanQuery = true
							end)
						end
					end
					for scr, _ in pairs(apoisonDisabledScripts) do
						if scr and scr.Parent then
							pcall(function()
								scr.Disabled = false
							end)
						end
					end
					apoisonModifiedParts = {}
					apoisonDisabledScripts = {}
					return
				end

				tbl8.AntiPoison = true
				local m = workspace:FindFirstChild("Map")
				if m then
					for _, d in ipairs(m:GetDescendants()) do
						apoisonHandleInst(d)
					end
				end
				if apoisonDescConn then
					pcall(function()
						apoisonDescConn:Disconnect()
					end)
				end
				apoisonDescConn = workspace.DescendantAdded:Connect(apoisonHandleInst)
			end

		-- KOZMOZ FIX (image-58/59): Anti Explosion motoru.
		-- Toggle acikken "explosion guard" gercekten baglanir; kapaninca kesilir.
		-- (Bu blok KozAnti tanimlandiktan SONRA gelir; erken tanim crash
		-- veriyordu: "attempt to index nil with 'SetAntiExplosion'".)
		local aeConn = nil
		KozAnti.SetAntiExplosion = function(on)
			tbl8.AntiExplosion = on and true or false
			if aeConn then
				pcall(function() aeConn:Disconnect() end)
				aeConn = nil
			end
			if not on or flag11 then
				if not on then
					pcall(guardExplosionPart)
				end
				return
			end
			aeConn = workspace.ChildAdded:Connect(function(child)
				if not tbl8.AntiExplosion or flag11 then
					return
				end
				if type(explosionPartNear) == "function" and explosionPartNear(child) then
					pcall(guardExplosionPart)
				end
			end)
			task.spawn(function()
				task.wait(0.2)
				if tbl8.AntiExplosion and not flag11 then
					pcall(guardExplosionPart)
				end
			end)
		end
			-- ------------------------------------------------------------------
			-- 12) Anti Lag ported from kar.txt (DefAntiLag / _clearAllGrabParts)
			-- ------------------------------------------------------------------
			local alEnabled = false
			-- KOZMOZ FIX (image-56): Anti Lag artik gercekten bir dongu ile
			-- calisir. Ã–nceden sadece "acilista bir kez temizle" yapiyordu;
			-- sonradan olusan grab cizgileri / sticky weldler temizlenmiyordu.
			-- Artik 0.5 sn'de bir hafif tarama + 2 sn'de bir tam temizlik.
			local alAuto = { on = false, loop = nil, last = 0, lastHeavy = 0 }
			local alCharConn = nil

			local function alClearAllGrabParts()
			    for _, holder in ipairs(workspace:GetDescendants()) do
			        if holder.Name == "GrabParts" then
			            pcall(function()
			                for _, descendant in ipairs(holder:GetDescendants()) do
			                    if descendant:IsA("Beam") then
			                        descendant.Enabled = false
			                    elseif descendant:IsA("BasePart") then
			                        descendant.Transparency = 1
			                        for _, child in ipairs(descendant:GetChildren()) do
			                            if child:IsA("Sound") then child.Volume = 0 end
			                        end
			                    end
			                end
			            end)
			        end
			    end
			end

			local function alSetCharacterAndBeamMove(disabled)
			    local playerScripts = localPlayer:FindFirstChildOfClass("PlayerScripts")
			        or localPlayer:FindFirstChild("PlayerScripts")
			    local characterAndBeamMove = playerScripts and playerScripts:FindFirstChild("CharacterAndBeamMove")
			    if characterAndBeamMove then
			        pcall(function() characterAndBeamMove.Disabled = disabled end)
			    end
			end

			KozAnti.SetAntiLag = function(enabled)
			    local on = enabled == true and not flag11
			    -- Look Figures relies on Anti Lag staying enabled, as in Kozmoz's existing integration.
			    if not on and not flag11 and tbl7.LookFigures and tbl7.LookFigures.Enabled then
			        if toggles.AntiLag and not toggles.AntiLag.Value then
			            toggles.AntiLag:SetValue(true)
			        end
			        return
			    end

			    alEnabled = on
			    if alCharConn then
			        alCharConn:Disconnect()
			        alCharConn = nil
			    end

			    alSetCharacterAndBeamMove(on)
			    if on then
			        alClearAllGrabParts()
			        -- Keep the PlayerScripts switch in effect across respawns in Kozmoz.
			        alCharConn = localPlayer.CharacterAdded:Connect(function()
			            task.defer(function()
			                if alEnabled and not flag11 then alSetCharacterAndBeamMove(true) end
			            end)
			        end)
			    end

			    -- KOZMOZ FIX: gercek motor. Aciksa 0.5 sn'de bir sadece YENI
			    -- eklenen parcalari, 2 sn'de bir de tam listeyi temizler.
			    alAuto.on = on
			    if on then
			        if not alAuto.loop then
			            alAuto.loop = RunService.Heartbeat:Connect(function()
			                if not alAuto.on or flag11 then
									return
								end
			                local nowAl = os.clock()
			                if nowAl - alAuto.last >= 0.5 then
			                    alAuto.last = nowAl
			                    pcall(alClearAllGrabParts)
			                end
			                if nowAl - alAuto.lastHeavy >= 2 then
			                    alAuto.lastHeavy = nowAl
			                    pcall(alClearAllGrabParts)
			                end
			            end)
			        end
			    elseif alAuto.loop then
			        alAuto.loop:Disconnect()
			        alAuto.loop = nil
			    end
			end
		end

		-- KOZMOZ: "AntiGrab" artik reso'nun "Antis" kutusunda (Defanse sag taraf) ve
		-- ayni ID iki yerde olmamali; buradaki kopya kaldirildi.
	-- =====================================================================
		-- v30: global notification guard â€” never show "nil", never spam
		-- =====================================================================
		pcall(function()
			if type(lib) == "table" and type(lib.Notify) == "function" and not lib.__kozGuard then
				local origNotify = lib.Notify
				local lastSeen = {}
				lib.Notify = function(self, data, ...)
					if type(data) ~= "table" then
						return origNotify(self, data, ...)
					end
					local d = {}
					for k, v in pairs(data) do
						d[k] = v
					end
					local title = tostring(d.Title or d.title or "")
					local desc = d.Description or d.desc or d.Content or d.content or ""
					if type(desc) ~= "string" then
						desc = tostring(desc)
					end
					if desc == "nil" or desc == "" then
						desc = ""
					end
					-- dedupe: skip identical title + text within 2 seconds
					local key = title .. "|" .. desc
					local now = os.clock()
					if lastSeen[key] and (now - lastSeen[key]) < 2 then
						return
					end
					lastSeen[key] = now

					d.Description = desc
					if d.Content ~= nil then
						d.Content = desc
					end
					d.Time = d.Time or d.Duration or 3
					return origNotify(self, d, ...)
				end
				lib.__kozGuard = true
			end
		end)

		-- =====================================================================
		-- v28: GUCCI SHIELD â€” soft blue bubble around you, turns red when anyone
		-- sits down nearby (blobman). FPS friendly: single part, no lights,
		-- C-side spatial query instead of GetDescendants scans.
		-- =====================================================================
		do
			local PlayersS = game:GetService("Players")
			local LPs = PlayersS.LocalPlayer

			local SH = {
				Enabled = false,
				Part = nil,
				Char = nil,
				IsRed = false,
				NextScan = 0,
				BaseSize = 12,
				ColBlue = Color3.fromRGB(90, 160, 255),
				ColRed = Color3.fromRGB(255, 65, 65),
			}

			local scanParams = OverlapParams.new()
			scanParams.FilterType = Enum.RaycastFilterType.Exclude
			scanParams.MaxParts = 30

			local function shDestroy()
				if SH.Part then
					pcall(function()
						SH.Part:Destroy()
					end)
					SH.Part = nil
				end
				SH.Char = nil
			end

			local function shBuild()
				local char = LPs.Character
				local hrp = char and (char:FindFirstChild("HumanoidRootPart") or char:FindFirstChild("Torso"))
				if not (char and hrp) then
					return false
				end
				if SH.Part and SH.Part.Parent and SH.Char == char then
					return true
				end
				shDestroy()

				local p = Instance.new("Part")
				p.Name = "KOZMOZ_GucciShield"
				p.Shape = Enum.PartType.Ball
				p.Size = Vector3.new(SH.BaseSize, SH.BaseSize, SH.BaseSize)
				p.Material = Enum.Material.ForceField
				p.Color = SH.ColBlue
				p.Transparency = 0.86
				p.Anchored = false
				p.CanCollide = false
				p.CastShadow = false
				p.Massless = true
				p.Locked = true
				pcall(function()
					p.CanQuery = false
					p.CanTouch = false
					p.CanClimb = false
				end)
				p.CFrame = hrp.CFrame
				p.Parent = workspace

				p.CFrame = hrp.CFrame

				local weld = Instance.new("WeldConstraint")
				weld.Name = "KOZMOZ_ShieldWeld"
				weld.Part0 = hrp
				weld.Part1 = p
				weld.Parent = p

				SH.Part, SH.Char = p, char
				return true
			end

			local function shThreat(hrp)
				local pos = hrp.Position
				-- 1) any player seated nearby
				for _, plr in ipairs(PlayersS:GetPlayers()) do
					if plr ~= LPs and plr.Character then
						local hum = plr.Character:FindFirstChildOfClass("Humanoid")
						local root = plr.Character:FindFirstChild("HumanoidRootPart")
						if hum and root and hum.Health > 0 and hum.SeatPart then
							if (root.Position - pos).Magnitude < 60 then
								return true
							end
						end
					end
				end
				-- 2) occupied seats within 45 studs (fast C-side query)
				scanParams.FilterDescendantsInstances = { LPs.Character }
				local ok, parts = pcall(function()
					return workspace:GetPartBoundsInRadius(pos, 45, scanParams)
				end)
				if ok and parts then
					for _, part in ipairs(parts) do
						if part:IsA("Seat") or part:IsA("VehicleSeat") then
							if part.Occupant then
								return true
							end
						end
					end
				end
				return false
			end

			local function shPaint(red)
				local p = SH.Part
				if not (p and p.Parent) then
					return
				end
				local col = red and SH.ColRed or SH.ColBlue
				pcall(function()
					p.Color = col
					p.Transparency = red and 0.72 or 0.86
					p.Size = Vector3.new(SH.BaseSize, SH.BaseSize, SH.BaseSize)
				end)
			end

			local function shSetEnabled(on)
				SH.Enabled = on and true or false
				if not SH.Enabled then
					shDestroy()
					return
				end
				shBuild()
			end

			getgenv().KOZMOZ_GUCCI_SHIELD = shSetEnabled

			-- build/maintain + follow loop (low cost, 5x/second max)
			task.spawn(function()
				while not flag11 do
					task.wait(0.2)
					if SH.Enabled then
						local char = LPs.Character
						local hrp = char and (char:FindFirstChild("HumanoidRootPart") or char:FindFirstChild("Torso"))
						if hrp then
							if not (SH.Part and SH.Part.Parent and SH.Char == char) then
								shBuild()
							end
							local p = SH.Part
							if p and p.Parent then
								local now = os.clock()
								if now >= SH.NextScan then
									SH.NextScan = now + 0.6
									local red = shThreat(hrp)
									if red ~= SH.IsRed then
										SH.IsRed = red
										shPaint(red)
									end
								end
							end
						end
					end
				end
			end)
		end

		-- apel.txt:6512-6869. Keep Kozmoz option IDs; replace their behavior.
		local apelSitOn = false
		local apelSitThread = nil
		local function apelStopSit()
			apelSitOn = false
			if apelSitThread then pcall(task.cancel, apelSitThread); apelSitThread = nil end
		end
		local function apelStartSit()
			apelStopSit()
			apelSitOn = true
			apelSitThread = task.spawn(function()
				while apelSitOn and not flag11 do
					local myChar = localPlayer.Character
					local myRoot = myChar and myChar:FindFirstChild("HumanoidRootPart")
					if myRoot then
						for _, player in ipairs(Players:GetPlayers()) do
							if player ~= localPlayer then
								local other = player.Character
								local root = other and other:FindFirstChild("HumanoidRootPart")
								local hum = other and other:FindFirstChildOfClass("Humanoid")
								local seat = hum and hum.SeatPart
								if root and seat and seat.Parent and seat.Parent.Name == "CreatureBlobman"
									and (root.Position - myRoot.Position).Magnitude <= 19 then
									pcall(function() tbl11.SetNetworkOwner:FireServer(root, root.CFrame) end)
								end
							end
						end
					end
					task.wait(0.01) -- apel interval
				end
				apelSitThread = nil
			end)
		end
		AntiTab:AddToggle("AntiBlobmanSit", {
			Text = "Anti Blobman Sit", Default = false,
			Callback = function(on) if on then apelStartSit() else apelStopSit() end end,
		})

		local apelRagOn, apelRagSeatConn, apelRagCharConn = false, nil, nil
		local apelRagToken = 0
		local function apelDisconnectRag()
			if apelRagSeatConn then apelRagSeatConn:Disconnect(); apelRagSeatConn = nil end
			if apelRagCharConn then apelRagCharConn:Disconnect(); apelRagCharConn = nil end
		end
		local function apelSetupRag(char, token)
			if apelRagSeatConn then apelRagSeatConn:Disconnect(); apelRagSeatConn = nil end
			local hum = char and char:FindFirstChildOfClass("Humanoid")
			local root = char and char:FindFirstChild("HumanoidRootPart")
			local remote = tbl11.RagdollRemote -- CharacterEvents.RagdollRemote in Kozmoz
			if not (hum and root and remote) then return end
			local busy = false
			apelRagSeatConn = hum:GetPropertyChangedSignal("SeatPart"):Connect(function()
				local seat = hum.SeatPart
				if not (apelRagOn and token == apelRagToken and seat and seat.Parent
					and seat.Parent.Name == "CreatureBlobman") or busy then return end
				busy = true
				task.spawn(function()
					local limit = os.clock() + 1.5
					while apelRagOn and not hum.Sit and os.clock() < limit do task.wait() end
					if not apelRagOn or token ~= apelRagToken or char ~= localPlayer.Character
						or hum.SeatPart ~= seat then busy = false; return end
					pcall(function() remote:FireServer(root, 3) end)
					local timeout = os.clock() + 1.5
					while apelRagOn and hum.Sit and os.clock() < timeout do
						local rag = hum:FindFirstChild("Ragdolled")
						if rag and rag.Value then break end
						task.wait()
					end
					task.wait(0.4)
					if apelRagOn and token == apelRagToken and char == localPlayer.Character then
						pcall(function()
							hum.Sit = false
							if seat.Parent and (seat:IsA("Seat") or seat:IsA("VehicleSeat")) then seat:Sit(hum) end
						end)
						while apelRagOn and token == apelRagToken and char == localPlayer.Character
							and hum.SeatPart and hum.SeatPart.Parent do
							pcall(function() remote:FireServer(root, 1) end)
							task.wait(0.05) -- apel's seated refresh
						end
					end
					busy = false
				end)
			end)
		end
		local apelRagOn, apelRagSeatConn, apelRagCharConn = false, nil, nil
		local apelRagToken = 0
		local function apelDisconnectRag()
			if apelRagSeatConn then apelRagSeatConn:Disconnect(); apelRagSeatConn = nil end
			if apelRagCharConn then apelRagCharConn:Disconnect(); apelRagCharConn = nil end
		end
