		local apelGrabOn, apelGrabToken, apelGrabCharConn = false, 0, nil
		local apelGrabTracked = setmetatable({}, { __mode = "k" })
		local function apelRestoreChar(char)
			local data = char and apelGrabTracked[char]
			if not data then return end
			local root = char:FindFirstChild("HumanoidRootPart")
			local phantom = char:FindFirstChild("TruePositionPart")
			local attachment = data.attachment
			if root and attachment and attachment.Parent == phantom then
				pcall(function() attachment.Parent = root end)
			end
			if phantom and phantom == data.phantom then pcall(function() phantom:Destroy() end) end
			for part, massless in pairs(data.parts) do
				if part and part.Parent then pcall(function() part.Massless = massless end) end
			end
			apelGrabTracked[char] = nil
		end
		local function apelDropFromBlobs(char)
			local root = char and char:FindFirstChild("HumanoidRootPart")
			if not root then return end
			local function drop(toy)
					if toy.Name ~= "CreatureBlobman" then return end
					local scriptObj = toy:FindFirstChild("BlobmanSeatAndOwnerScript")
					local detector = toy:FindFirstChild("RightDetector")
					local remote = scriptObj and scriptObj:FindFirstChild("CreatureDrop")
					local weld = detector and detector:FindFirstChild("RightWeld")
					if remote and weld then
						pcall(function()
							remote:FireServer(weld, root)
							tbl11.Struggle:FireServer(localPlayer)
						end)
					end
				end
			local plotItems = workspace:FindFirstChild("PlotItems")
			if plotItems then
				for _, plot in ipairs(plotItems:GetChildren()) do
					if plot.Name ~= "PlayersInPlots" then
						for _, toy in ipairs(plot:GetChildren()) do drop(toy) end
					end
				end
			end
			for _, player in ipairs(Players:GetPlayers()) do
				local folder = workspace:FindFirstChild(player.Name .. "SpawnedInToys")
				if folder then for _, toy in ipairs(folder:GetChildren()) do drop(toy) end end
			end
		end
		local function apelGrabStep(char, token)
			local root = char and char:FindFirstChild("HumanoidRootPart")
			if not root then return end
			local data = apelGrabTracked[char]
			if not data then
				data = { parts = {}, attachment = root:FindFirstChild("RootAttachment") }
				apelGrabTracked[char] = data
			end
			local phantom = char:FindFirstChild("TruePositionPart")
			if not phantom then
				phantom = Instance.new("Part")
				phantom.Name = "TruePositionPart"
				phantom.Anchored, phantom.CanCollide, phantom.CanTouch = true, false, false
				phantom.Transparency = 1
				phantom.Size = Vector3.new(1, 1, 1)
				phantom.CFrame = CFrame.new(0, -100, 0)
				phantom.Parent = char
				data.phantom = phantom
			end
			local changedMassless = false
			for _, part in ipairs(char:GetChildren()) do
				if part:IsA("BasePart") and part.Massless and part ~= phantom then
					if data.parts[part] == nil then data.parts[part] = true end
					part.Massless = false
					changedMassless = true
				end
			end
			if changedMassless then apelDropFromBlobs(char) end
			local attachment = root:FindFirstChild("RootAttachment")
			if attachment and phantom and not phantom:FindFirstChild("RootAttachment") then
				task.wait(0.2) -- apel attachment move delay
				if apelGrabOn and token == apelGrabToken and char == localPlayer.Character
					and root.Parent and attachment.Parent == root then
					data.attachment = attachment
					attachment.Parent = phantom
				end
			end
		end
		local function apelStopGrab()
			apelGrabOn = false
			apelGrabToken += 1
			if apelGrabCharConn then apelGrabCharConn:Disconnect(); apelGrabCharConn = nil end
			for char in pairs(apelGrabTracked) do apelRestoreChar(char) end
		end
		-- KOZMOZ v39: "AntiBlobmanGrab" taken 1:1 from kuzey.reso.txt (Defanse)
		AntiTab:AddToggle("AntiBlobmanGrab", {
			Text = "Anti Blobman Grab",
			Default = false,
			Tooltip = "Mumus method: hides your RootAttachment inside a TruePositionPart so Blobman can't grab you. Don't use it together with Anti Blobman above.",
			Callback = function(arg)
