					end
					ABG_RestoreRootAttachment()
				end
			end,
		})

		-- KOZMOZ v38: Anti Kick (Item) -- ported 1:1 from apel.txt / kuzey.reso.txt "[ITEM] Anti Kick":
		-- the item's Hitbox is network-owned (SetNetworkOwner) and held ON your
		-- PlayerCharacterLocationDetector (PCLD) with a BodyPosition every frame; the item is renamed
		-- "AntiKickItem", duplicates are removed, it pauses while you are inside a plot.
		-- Kept from v36: Japanese Lantern default, automatic Japanese Lantern fallback + notification
		-- when the chosen toy cannot be spawned, toy-aura reservation, config change swaps the item.
		local AKI = { token = 0, fails = 0, fallback = nil, okNoted = false, lastNote = -math.huge, itemToy = nil, nameCache = {} }
		AKI.FALLBACK_TOY = "JapaneseLantern"
		function AKI.note(msg, force)
			if not force and os.clock() - AKI.lastNote < 8 then
				return
			end
			AKI.lastNote = os.clock()
			pcall(function()
				fn18(msg, "Anti Kick (Item)", nil, 4, true)
			end)
		end
		-- real toy name in this game version (e.g. "SpookyCandle1" vs "SpookyCandle")
		function AKI.resolveName(name)
			if type(name) ~= "string" or name == "" then
				return AKI.FALLBACK_TOY
			end
			local cached = AKI.nameCache[name]
			if cached then
				return cached
			end
			local found, prefixHit = nil, nil
			local base = string.lower((string.gsub(name, "%d+$", "")))
			pcall(function()
				for _, cname in ipairs({ "Toys", "ToyModels", "Items", "Assets", "MenuToys" }) do
					local c = RS:FindFirstChild(cname)
					if c then
						for _, t in ipairs(c:GetChildren()) do
							if t:IsA("Model") or t:IsA("BasePart") or t:IsA("Folder") then
								if t.Name == name then
									found = name
									return
								end
								if not prefixHit and base ~= "" then
									local tb = string.lower((string.gsub(t.Name, "%d+$", "")))
									if tb == base then
										prefixHit = t.Name
									end
								end
							end
						end
					end
				end
			end)
			local res = found or prefixHit or name
			AKI.nameCache[name] = res
			return res
		end
		function AKI.wanted()
			return AKI.fallback or AKI.resolveName(SelectedAntiKickToy)
		end
		function AKI.hitbox(item, waitSec)
			if not item then
				return nil
			end
			local hb = item:FindFirstChild("Hitbox")
			if not hb and waitSec then
				hb = FWD(item, "Hitbox", waitSec)
			end
			if not hb then
				hb = item:FindFirstChild("SoundPart")
			end
			if hb and hb:IsA("BasePart") then
				return hb
			end
			return nil
		end
		function AKI.destroyAll(keep)
			local inv = workspace:FindFirstChild(plr.Name .. "SpawnedInToys")
			local destroyToy = RS:FindFirstChild("MenuToys") and RS.MenuToys:FindFirstChild("DestroyToy")
			if not (inv and destroyToy) then
				return
			end
			for _, v in pairs(inv:GetChildren()) do
				if v.Name == "AntiKickItem" and v ~= keep then
					pcall(function()
						tbl7.ToyAuraReserved[v] = nil
					end)
					pcall(function()
						destroyToy:FireServer(v)
					end)
				end
			end
		end

		AntiTab:AddToggle("AntiKickItem", {
			Text = "Anti Kick (Item)",
			Default = false,
			Tooltip = "Protects you from kick using an interactable item (Config > Anti Kick Item, default Japanese Lantern). The item is held on your PCLD.",
			Callback = function(Val)
				AntiKickItemActive = Val and true or false
				AKI.token += 1
				local token = AKI.token
				if Val then
					AKI.fails = 0
					AKI.okNoted = false
					task.spawn(function()
						local Item, SoundPart
						while AntiKickItemActive and token == AKI.token and not flag11 and task.wait() do
							-- re-check after the wait: the reference loop ran one extra body after OFF
							-- (re-started the PCLD watcher and could spawn one more item)
							if not (AntiKickItemActive and token == AKI.token and not flag11) then
								break
							end
							local char = plr.Character
							local hrp = char and char:FindFirstChild("HumanoidRootPart")
							local hum = char and char:FindFirstChild("Humanoid")
							local inPlot = plr:FindFirstChild("InPlot")
							local inv = workspace:FindFirstChild(plr.Name .. "SpawnedInToys")

							if not hrp or not hum or hum.Health <= 0 or not inv then
								continue
							end
							if inPlot and inPlot.Value then
								continue
							end
							if not MyPCLD and not pcldConn then
								FindPCLD(hrp)
							end

							local want = AKI.wanted()
							Item = inv:FindFirstChild("AntiKickItem")
							SoundPart = AKI.hitbox(Item)
							if Item and AKI.itemToy and AKI.itemToy ~= want then
								-- Config > Anti Kick Item changed -> swap the item
								Item, SoundPart = nil, nil
							end

							if not Item or not SoundPart then
								AKI.destroyAll(nil)

								Item = SpawnToy(want)
								if not AntiKickItemActive or token ~= AKI.token or flag11 then
									if Item then
										pcall(function()
											RS.MenuToys.DestroyToy:FireServer(Item)
										end)
									end
									break
								end
								if not Item then
									AKI.fails += 1
									if AKI.fails >= 3 and want ~= AKI.FALLBACK_TOY then
										AKI.fallback = AKI.FALLBACK_TOY
										AKI.fails = 0
										AKI.note("Could not spawn " .. tostring(want) .. " (not owned?). Using Japanese Lantern instead.", true)
									elseif AKI.fails >= 3 then
										AKI.note("Could not spawn " .. tostring(want) .. " (toy limit / spawn cooldown?). Retrying...")
									end
									task.wait(0.5)
									continue
								end
								AKI.fails = 0

								SoundPart = AKI.hitbox(Item, 0.5)
								if SoundPart then
									sno(SoundPart)
								end

								for _, v in pairs(Item:GetChildren()) do
									if v:IsA("BasePart") then
										v.CanCollide = false
									end
								end

								pcall(function()
									local highlight = Instance.new("Highlight")
									highlight.Name = "AntiKickHighlight"
									highlight.FillTransparency = 1
									highlight.OutlineColor = Color3.fromRGB(255, 255, 255)
									highlight.OutlineTransparency = 0
									highlight.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
									highlight.Adornee = Item
									highlight.Parent = Item
								end)

								if SoundPart then
									local bp = SoundPart:FindFirstChild("AntiKickFollow")
									if not bp then
										bp = Instance.new("BodyPosition")
										bp.Name = "AntiKickFollow"
										bp.MaxForce = Vector3.new(1e5, 1e5, 1e5)
										bp.P = 30000
										bp.D = 500
										bp.Parent = SoundPart
									end
								end

								pcall(function()
									tbl7.ToyAuraReserved[Item] = true
								end)
								Item.Name = "AntiKickItem"
								AKI.itemToy = want
								if not AKI.okNoted then
									AKI.okNoted = true
									AKI.note(tostring(want) .. " is on your PCLD (anti kick active).")
								end
							end

							if Item and Item.Parent then
								AKI.destroyAll(Item)
							end

							if SoundPart and not CheckNetworkOwnerOnPart(SoundPart) then
								sno(SoundPart)
							end

							if SoundPart then
								local targetPart = MyPCLD or hrp:FindFirstChild("FirePlayerPart") or hrp
								if targetPart then
									local bp = SoundPart:FindFirstChild("AntiKickFollow")
									if bp then
										bp.Position = targetPart.Position
									else
										SoundPart.CFrame = targetPart.CFrame
										SoundPart.AssemblyLinearVelocity = Vector3.zero
										SoundPart.AssemblyAngularVelocity = Vector3.zero
									end
								end
							end
						end
					end)
				else
					if pcldConn then
						pcldConn:Disconnect()
						pcldConn = nil
					end
					MyPCLD = nil
					AKI.itemToy = nil
					task.spawn(AKI.destroyAll, nil)
				end
			end,
		})
		lib:OnUnload(function()
			AKI.token += 1
			AntiKickItemActive = false
			pcall(AKI.destroyAll, nil)
		end)

		lib:OnUnload(function()
			apelStopSit()
			apelRagOn = false; apelRagToken += 1; apelDisconnectRag()
			apelStopGrab()
		end)

