    AntiTab:AddToggle("KozAntiStickyLag", {
      Text = "Anti Sticky Lag",
      Default = false,
      Tooltip = "Switches off the sticky touch scripts of the game, so lagging players can not glue themselves to you anymore. Re-applied after every respawn.",
      Callback = function(arg)
        local localPlayer2 = game:GetService("Players").LocalPlayer

        local function setStickyScripts(disabled)
          pcall(function()
            local playerScripts = localPlayer2:FindFirstChild("PlayerScripts")

            if playerScripts then
              for _, descendant in ipairs(playerScripts:GetDescendants()) do
                local isStickyScript = descendant:IsA("LocalScript") and (descendant.Name == "StickyPartsTouchDetection" or descendant.Name:lower():find("sticky") ~= nil or descendant.Name:lower():find("touchdetect") ~= nil)

                if isStickyScript then
                  descendant.Disabled = disabled
                end
              end
            end
          end)
        end

        if kozStickyLagConn then
          pcall(function()
            kozStickyLagConn:Disconnect()
          end)

          kozStickyLagConn = nil
        end

        tbl8.KozAntiStickyLag = arg
        setStickyScripts(arg)

        if arg then
          kozStickyLagConn = localPlayer2.CharacterAdded:Connect(function()
            task.wait(1)

            if tbl8.KozAntiStickyLag then
              setStickyScripts(true)
            end
          end)
        end
      end,
    })
