    AntiTab:AddToggle("KozAntiRagdoll", {
      Text = "Anti Ragdoll",
      Default = false,
      Tooltip = "If the game tries to ragdoll you, the joints are switched back on and you are put back on your feet at the spot you were standing on.",
      Callback = function(arg)
        tbl8.KozAntiRagdoll = arg

        if not arg then
          return
        end

        task.spawn(function()
          local lastCFrame = nil
          while tbl8.KozAntiRagdoll do
            task.wait(0.05)

            local char, root, hum = tbl12.Char()

            if char and root and hum and hum.Health > 0 then
              local ragdolled = false
              if tbl12.IsGucciApplying and tbl12.IsGucciApplying() then
                continue
              end
              local deadFlag = hum:FindFirstChild("Ragdolled") or char:FindFirstChild("Ragdolled") or char:FindFirstChild("Ragdoll")

              if deadFlag and deadFlag:IsA("BoolValue") and deadFlag.Value then
                ragdolled = true
                pcall(function()
                  deadFlag.Value = false
                end)
              end

              if not ragdolled then
                for _, motor in ipairs(char:GetDescendants()) do
                  if motor:IsA("Motor6D") and motor.Name == "RootJoint" and not motor.Enabled then
                    ragdolled = true
                    break
                  end
                end
              end

              if ragdolled then
                tbl12.ToggleMotor6D(char, true)

                if lastCFrame then
                  pcall(function()
                    root.CFrame = lastCFrame
                    root.AssemblyLinearVelocity = Vector3.new(0, 0, 0)
                    root.AssemblyAngularVelocity = Vector3.new(0, 0, 0)
                  end)
                end

                pcall(function()
                  hum:ChangeState(Enum.HumanoidStateType.GettingUp)
                end)
              elseif hum:GetState() ~= Enum.HumanoidStateType.Dead then
                lastCFrame = root.CFrame
              end
            end
          end
        end)
      end,
    })
