    -- =====================================================================
    -- KOZMOZ: kar'daki "FakePosPart" mantigi + Desync ile uyum.
    -- Calisma prensibi:
    --   1) HumanoidRootPart'in TAM ustunde (ayni CFrame, ayni boyut) gorunmez
    --      bir "FakePosPart" yaratilir, WeldConstraint ile gercek koke baglanir.
    --   2) sethiddenproperty(root, "PhysicsRepRootPart", part) -> Roblox fizik
    --      replikasyonu artik ROOT'u degil, bu sahte parcayi bildirir.
    --   3) Boylece sen gercek karakterinle serbestce kosarsin; sunucudaki
    --      kopyan sahte kokun oldugu yerde kalir (klasik fakepos/desync).
    --   4) Her ~1.1 sn'de sahte kok hafifce sifirlanir (takilmasin, "donuk"
    --      gorunmesin) ve sunucu tekrar senkronlanir.
    --   5) Respawn / olum / toggle kapatma -> her sey temiz sekilde geri alinir.
    local fakePosState = {
        active = false,
        part = nil,
        weld = nil,
        conn = nil,
        hb = nil,
        token = 0,
        lastSync = 0,
        holdMode = "Freeze",
    }

    local function fakePosClear()
        fakePosState.token += 1
        fakePosState.active = false
        tbl12.FakePosActive = false
        tbl12.FakePosPart = nil

        if fakePosState.hb then
            pcall(function() fakePosState.hb:Disconnect() end)
            fakePosState.hb = nil
        end
        if fakePosState.conn then
            pcall(function() fakePosState.conn:Disconnect() end)
            fakePosState.conn = nil
        end
        if fakePosState.weld then
            pcall(function() fakePosState.weld:Destroy() end)
            fakePosState.weld = nil
        end
        if fakePosState.part then
            pcall(function() fakePosState.part:Destroy() end)
            fakePosState.part = nil
        end
        -- gercek koku geri ver
        local _, root = tbl12.Char()
        if root then
            if tbl12.DesyncSetRep then
                pcall(tbl12.DesyncSetRep, root, nil)
            elseif type(sethiddenproperty) == "function" then
                pcall(sethiddenproperty, root, "PhysicsRepRootPart", nil)
            elseif type(set_hidden_property) == "function" then
                pcall(set_hidden_property, root, "PhysicsRepRootPart", nil)
            end
        end
    end

    local function fakePosBuild()
        if flag11 or not fakePosState.active then return end
        local char, root = tbl12.Char()
        if not (char and char.Parent and root and root.Parent) then return end

        local myToken = fakePosState.token

        -- eski parca varsa temizle (respawn / tekrar kurulum)
        if fakePosState.weld then pcall(function() fakePosState.weld:Destroy() end) fakePosState.weld = nil end
        if fakePosState.part then pcall(function() fakePosState.part:Destroy() end) fakePosState.part = nil end

        local part = Instance.new("Part")
        part.Name = "FakePosPart"
        part.Size = root.Size
        part.CFrame = root.CFrame
        part.Anchored = false
        part.CanCollide = false
        part.CanTouch = false
        part.CanQuery = false
        part.CastShadow = false
        part.Massless = true
        part.Transparency = 1
        part.Parent = char

        -- sahte kok gercek koke weld'lenir; boylece ayni assembly'de kalir
        local weld = Instance.new("WeldConstraint")
        weld.Name = "FakePosWeld"
        weld.Part0 = root
        weld.Part1 = part
        weld.Parent = part

        fakePosState.part = part
        fakePosState.weld = weld
        tbl12.FakePosPart = part
        tbl12.FakePosActive = true

        -- fizik kokunu sahte parcaya cevir
        local applied
        if tbl12.DesyncSetRep then
            applied = tbl12.DesyncSetRep(root, part)
        elseif type(sethiddenproperty) == "function" then
            applied = pcall(sethiddenproperty, root, "PhysicsRepRootPart", part)
        elseif type(set_hidden_property) == "function" then
            applied = pcall(set_hidden_property, root, "PhysicsRepRootPart", part)
        end
        if not applied then
            -- executor bu ozelligi yazamiyor: bosuna acik birakma
            pcall(function()
                if fn18 then
                    fn18("Fakepos: PhysicsRepRootPart is not writable on this executor.", "Fakepos")
                end
            end)
            task.defer(function()
                local tg = toggles.KozFakepos
                if tg and tg.SetValue then pcall(function() tg:SetValue(false) end) end
            end)
            fakePosClear()
            return
        end

        -- KOZMOZ: hafif "hold" dongusu. Sunucu sahte koku takip ederken uzun
        -- sure ayni noktada kalirsa geri cekme (rubberband) yiyebiliyor. Her
        -- 1.1 sn'de sahte kokun CFrame'ini root'a esitleyip birakiyoruz; bu
        -- sunucuda "kucuk teleport" gibi gorunur ve senkron tazelenir.
        if fakePosState.hb then pcall(function() fakePosState.hb:Disconnect() end) end
        fakePosState.hb = RunService.Heartbeat:Connect(function()
            if flag11 or not fakePosState.active or fakePosState.token ~= myToken then
                return
            end
            if not (char.Parent and root.Parent) then return end
            if os.clock() - fakePosState.lastSync < 1.1 then return end
            fakePosState.lastSync = os.clock()

            local fp = fakePosState.part
            if not (fp and fp.Parent) then return end

            if fakePosState.holdMode == "Freeze" then
                -- sunucuya "yerinde dur" bilgisi: sahte kokun hizini sifirla
                pcall(function()
                    fp.AssemblyLinearVelocity = Vector3.new(0, 0, 0)
                    fp.AssemblyAngularVelocity = Vector3.new(0, 0, 0)
                end)
            else
                -- "Follow": sahte koku root'a yapistir (daha guvenli, daha az bug)
                pcall(function()
                    fp.CFrame = root.CFrame
                end)
            end
        end)

        -- karakter oldu ya da parca silindiyse temiz kapat
        local humanoid = char:FindFirstChildOfClass("Humanoid")
        if humanoid then
            if fakePosState.diedConn then
                pcall(function() fakePosState.diedConn:Disconnect() end)
            end
            fakePosState.diedConn = humanoid.Died:Connect(function()
                if fakePosState.token ~= myToken then return end
                -- KOZMOZ: olumde toggle'i KAPATMA. Parcayi temizle, respawn'da
                -- CharacterAdded baglantisi fakepos'u otomatik yeniden kurar.
                if fakePosState.part then
                    pcall(function() fakePosState.part:Destroy() end)
                    fakePosState.part = nil
                end
                if fakePosState.weld then
                    pcall(function() fakePosState.weld:Destroy() end)
                    fakePosState.weld = nil
                end
                tbl12.FakePosPart = nil
            end)
        end
    end

    AntiTab:AddToggle("KozFakepos", {
        Text = "Fakepos",
        Default = false,
        Tooltip = "kar FakePos: invisible fake physics root welded to your HumanoidRootPart. The server follows the fake root while your real character moves freely. Works together with Desync.",
        Callback = function(on)
            fakePosState.active = on == true
            fakePosState.token += 1
            fakePosState.lastSync = 0

            if not on then
                fakePosClear()
                return
            end

            fakePosBuild()

            -- respawn / karakter degisimi -> otomatik yeniden kur
            if fakePosState.conn then pcall(function() fakePosState.conn:Disconnect() end) end
            fakePosState.conn = localPlayer.CharacterAdded:Connect(function(newChar)
                local myToken = fakePosState.token
                newChar:WaitForChild("HumanoidRootPart", 10)
                task.wait(0.4)
                if fakePosState.active and fakePosState.token == myToken then
                    fakePosBuild()
                end
            end)
        end,
    }):AddKeyPicker("FakeposKey", {
        Default = "None",
        SyncToggleState = true,
        Mode = "Toggle",
        Text = "Fakepos",
        NoUI = false,
    })

    -- KOZMOZ: Fakepos davranis modu. "Freeze" = klasik fakepos (sunucudaki
    -- kopya geride kalir, en guclu desync). "Follow" = sahte kok seni takip
    -- eder (daha az bug, daha az geri cekme). Varsayilan: Freeze.
    -- KOZMOZ FIX (image-43): "attempt to index nil with 'OnChanged'".
    -- Sebep: AddDropdown element'i dondurmuyor / toggles tablosuna kaydoluyor
    -- diye varsayilmisti. Guvenli yol: Callback kullan ve elementi yerel
    -- degiskende tut (dropdown'u yeniden kurmak icin).
    tbl12.KozFakeModeApply = function(value)
        fakePosState.holdMode = tostring(value == "Follow" and "Follow" or "Freeze")
        if fakePosState.active then
            fakePosState.lastSync = 0
            task.defer(fakePosBuild)
        end
    end

    local kozFakeModeDropdown = AntiTab:AddDropdown("KozFakeposMode", {
        Text = "Fakepos Mode",
        Values = { "Freeze", "Follow" },
        Default = "Freeze",
        Tooltip = "Freeze: server copy stays behind (stronger desync). Follow: fake root follows you (safer, less rubberband).",
        Callback = function(value)
            tbl12.KozFakeModeApply(value)
        end,
    })
    tbl12.KozFakeposModeDropdown = function()
        return kozFakeModeDropdown
    end


