		do
			local permRagdollConn = nil
			local permRagdollCharAdded = nil
			ExtraDefenseTab:AddToggle("PermRagdoll", {
				Text = "Perm Ragdoll",
				Default = false,
				Callback = function(v)
					if v then
						if permRagdollConn then permRagdollConn:Disconnect() permRagdollConn = nil end
						if permRagdollCharAdded then permRagdollCharAdded:Disconnect() permRagdollCharAdded = nil end
						local function applyPermRagdoll()
							local char = localPlayer.Character
							if not char then return end
							local hum = char:FindFirstChildOfClass("Humanoid")
							local hrp = char:FindFirstChild("HumanoidRootPart")
							if hum and hrp and hum.Health > 0 then
								hum.BreakJointsOnDeath = false
								pcall(function()
									if tbl11 and tbl11.RagdollRemote then
										tbl11.RagdollRemote:FireServer(hrp, 2)
									end
								end)
							hum.PlatformStand = true
						end
					end
					applyPermRagdoll()
					permRagdollConn = RunService.RenderStepped:Connect(function()
						applyPermRagdoll()
					end)
					permRagdollCharAdded = localPlayer.CharacterAdded:Connect(function()
						task.wait(0.2)
						applyPermRagdoll()
					end)
				else
					if permRagdollConn then permRagdollConn:Disconnect() permRagdollConn = nil end
					if permRagdollCharAdded then permRagdollCharAdded:Disconnect() permRagdollCharAdded = nil end
					local char = localPlayer.Character
					local hum = char and char:FindFirstChildOfClass("Humanoid")
					local hrp = char and char:FindFirstChild("HumanoidRootPart")
					if hum and hrp and hum.Health > 0 then
						pcall(function()
							if tbl11 and tbl11.RagdollRemote then
								tbl11.RagdollRemote:FireServer(hrp, 0)
							end
						end)
						hum.PlatformStand = false
						hum:ChangeState(Enum.HumanoidStateType.GettingUp)
						hrp.AssemblyLinearVelocity = Vector3.zero
						hrp.AssemblyAngularVelocity = Vector3.zero
					end
				end
			end,
		})
	end

