		do
			local posLockConn = nil
			local posLockPos = nil
			ExtraDefenseTab:AddToggle("PosLock", {
				Text = "Pos Lock",
				Default = false,
				Callback = function(Value)
					if Value then
						pcall(function()
							local c = localPlayer.Character
							local root = c and c:FindFirstChild("HumanoidRootPart")
							if root then
								posLockPos = root.CFrame
							end
							posLockConn = RunService.RenderStepped:Connect(function()
								local c2 = localPlayer.Character
								local root2 = c2 and c2:FindFirstChild("HumanoidRootPart")
							if root2 and posLockPos then
								local assembly = root2.AssemblyRootPart or root2
								assembly.AssemblyLinearVelocity = Vector3.zero
								assembly.AssemblyAngularVelocity = Vector3.zero
								local offset = assembly.CFrame:ToObjectSpace(root2.CFrame)
								assembly.CFrame = posLockPos * offset:Inverse()
							end
						end)
					end)
				else
					if posLockConn then
						posLockConn:Disconnect()
						posLockConn = nil
					end
				pcall(function()
						local c2 = localPlayer.Character
						local root2 = c2 and c2:FindFirstChild("HumanoidRootPart")
						if root2 then
							local assembly = root2.AssemblyRootPart or root2
							assembly.AssemblyLinearVelocity = Vector3.zero
							assembly.AssemblyAngularVelocity = Vector3.zero
							if posLockPos then
								root2.CFrame = posLockPos
								posLockPos = nil
							end
						end
					end)
				end
			end,
		})
	end

