		local ALLOWED_LIMBS = {
			["Head"] = true,
			["Torso"] = true,
			["Left Arm"] = true,
			["Right Arm"] = true,
			["Left Leg"] = true,
			["Right Leg"] = true,
			["UpperTorso"] = true,
			["LowerTorso"] = true,
			["LeftUpperArm"] = true,
			["LeftLowerArm"] = true,
