		-- Follow the real animated parts, not an animation running inside the ViewportFrame.
		-- Resolve exact child paths once (duplicate accessory names are supported).
		local function MakeLivePreviewPairs(realChar, clonedChar)
			local realRoot = realChar:FindFirstChild("Torso") or realChar:FindFirstChild("UpperTorso")
				or realChar:FindFirstChild("HumanoidRootPart") or realChar:FindFirstChild("Head")
			local clonedRoot = realRoot and clonedChar:FindFirstChild(realRoot.Name)
			local pairsOut = {}
			if not (realRoot and clonedRoot) then return pairsOut, nil, nil end

			local function ResolveRealPart(clonePart)
				local path = {}
				local node = clonePart
				while node and node ~= clonedChar do
					local parent = node.Parent
					if not parent then return nil end
					local ordinal = 1
					for _, sibling in ipairs(parent:GetChildren()) do
						if sibling == node then break end
						if sibling.Name == node.Name and sibling.ClassName == node.ClassName then
							ordinal += 1
						end
					end
					table.insert(path, 1, { node.Name, node.ClassName, ordinal })
					node = parent
				end
				if node ~= clonedChar then return nil end
				local realNode = realChar
				for _, step in ipairs(path) do
					local found, index = nil, 0
					for _, child in ipairs(realNode:GetChildren()) do
						if child.Name == step[1] and child.ClassName == step[2] then
							index += 1
							if index == step[3] then found = child; break end
						end
					end
					if not found then return nil end
					realNode = found
				end
				return realNode:IsA("BasePart") and realNode or nil
			end

			for _, part in ipairs(clonedChar:GetDescendants()) do
				if #pairsOut >= 128 then break end
				if part:IsA("BasePart") and part ~= clonedRoot then
					local livePart = ResolveRealPart(part)
					if livePart then table.insert(pairsOut, { real = livePart, clone = part }) end
				end
			end
			return pairsOut, realRoot, clonedRoot
		end

		local function KeepSurvivingPairs(pairsIn)
			local result = {}
			for _, pair in ipairs(pairsIn) do
				if pair.real.Parent and pair.clone.Parent then
					table.insert(result, pair)
				end
			end
			return result
		end

		local function Prepare3DCharacter(sourceModel)
			local rootPart = sourceModel:FindFirstChild("Torso")
				or sourceModel:FindFirstChild("UpperTorso")
				or sourceModel:FindFirstChild("HumanoidRootPart")
				or sourceModel:FindFirstChild("Head")
			if not rootPart then return false end

			local rootCF = rootPart.CFrame
			local keepParts = {}

			for _, child in ipairs(sourceModel:GetChildren()) do
				if child:IsA("BasePart") then
					if ALLOWED_LIMBS[child.Name] then
						keepParts[child] = rootCF:ToObjectSpace(child.CFrame)
						for _, sub in ipairs(child:GetDescendants()) do
							if sub:IsA("BasePart") or sub:IsA("Model") or sub:IsA("SelectionBox") or sub:IsA("BoxHandleAdornment") then
								pcall(function() sub:Destroy() end)
							end
						end
					else
						pcall(function() child:Destroy() end)
					end
				elseif child:IsA("Accessory") or child:IsA("Hat") then
					local lowerName = child.Name:lower()
					if child.Name == "TypingKeyboardMyWorld"
						or lowerName:find("keyboard")
						or lowerName:find("campart")
						or lowerName:find("ragdoll")
					then
						pcall(function() child:Destroy() end)
					else
						local handle = child:FindFirstChild("Handle")
						if handle and handle:IsA("BasePart") and (handle.Position - rootCF.Position).Magnitude <= 8 then
							keepParts[handle] = rootCF:ToObjectSpace(handle.CFrame)
							for _, sub in ipairs(child:GetDescendants()) do
								if sub ~= handle and (sub:IsA("BasePart") or sub:IsA("SelectionBox") or sub:IsA("BoxHandleAdornment")) then
									pcall(function() sub:Destroy() end)
								end
							end
						else
							pcall(function() child:Destroy() end)
						end
					end
				elseif child:IsA("Model") or child:IsA("Folder") or child:IsA("Tool") then
					pcall(function() child:Destroy() end)
				end
			end

			local count = 0
			for _ in pairs(keepParts) do count = count + 1 end
			if count == 0 then return false end

			for _, desc in ipairs(sourceModel:GetDescendants()) do
				if desc:IsA("JointInstance")
					or desc:IsA("WeldConstraint")
					or desc:IsA("Constraint")
					or desc:IsA("BodyMover")
					or desc:IsA("BaseScript")
					or desc:IsA("ForceField")
					or desc:IsA("BillboardGui")
					or desc:IsA("Beam")
					or desc:IsA("Highlight")
					or desc:IsA("SelectionBox")
					or desc:IsA("ParticleEmitter")
					or desc:IsA("Trail")
					or desc:IsA("Sound")
				then
					pcall(function() desc:Destroy() end)
				elseif desc:IsA("Humanoid") then
					desc.DisplayDistanceType = Enum.HumanoidDisplayDistanceType.None
					desc.HealthDisplayType = Enum.HumanoidHealthDisplayType.AlwaysOff
				elseif desc:IsA("Decal") or desc:IsA("Texture") then
					desc.Transparency = 0
				end
			end

			for part, relCF in pairs(keepParts) do
				if part and part.Parent then
					part.Anchored = true
					part.CanCollide = false
					part.Massless = true
					part.AssemblyLinearVelocity = Vector3.zero
					part.AssemblyAngularVelocity = Vector3.zero
					part.Transparency = 0
					part.LocalTransparencyModifier = 0
					part.CFrame = CFrame.new(0, 0, 0) * relCF
				end
			end

			return true
		end

		local function Refresh3DAvatar(targetPlayer)
			if not targetPlayer then return end
			currentReqPlr = targetPlayer
			refreshToken += 1
			local token = refreshToken

			task.spawn(function()
				local newModel, newSource, newRoot, newCloneRoot = nil, nil, nil, nil
				local newPairs = {}
				local c = targetPlayer.Character
				if c then
					task.wait(0.2)
					if token ~= refreshToken or c ~= targetPlayer.Character
						or currentReqPlr ~= targetPlayer or flag11 then return end
					local oldArc = c.Archivable
					local okClone, cloned = pcall(function()
						c.Archivable = true
						return c:Clone()
					end)
					pcall(function() c.Archivable = oldArc end)
					if okClone and cloned then
						local okPairs, pairsOut, realHrp, clonedHrp = pcall(MakeLivePreviewPairs, c, cloned)
						if Prepare3DCharacter(cloned) then
							newModel = cloned
							if okPairs and realHrp and clonedHrp and c == targetPlayer.Character then
								newSource, newRoot, newCloneRoot = c, realHrp, clonedHrp
								newPairs = KeepSurvivingPairs(pairsOut)
							end
						else
							pcall(function() cloned:Destroy() end)
						end
					elseif cloned then
						pcall(function() cloned:Destroy() end)
					end
				end

				if not newModel and token == refreshToken and c == targetPlayer.Character then
					local okApi, apiModel = pcall(function()
						return Players:CreateHumanoidModelFromUserId(targetPlayer.UserId)
					end)
					if okApi and apiModel and Prepare3DCharacter(apiModel) then
						newModel = apiModel
					elseif apiModel then
						pcall(function() apiModel:Destroy() end)
					end
				end

				if not newModel then return end
				if token ~= refreshToken or flag11 or c ~= targetPlayer.Character
					or currentReqPlr ~= targetPlayer or not PreviewHolder.Visible or not worldModel.Parent then
					pcall(function() newModel:Destroy() end)
					return
				end

				if currentModel then
					pcall(function() currentModel:Destroy() end)
				end
				currentModel = newModel
				liveSource, liveRoot, cloneRoot = newSource, newRoot, newCloneRoot
				livePairs = newPairs
				previewElapsed = 0
				currentModel.Parent = worldModel
				pcall(function() Immunity:Resize() end)
			end)
		end
		local liveStatConn, lastLiveStat = nil, 0
		local currentPreviewIndex = 1
		local currentSelectedPlayers = {}

		local function UpdatePreview(targetPlr)
			if charAddedConn then
				charAddedConn:Disconnect()
				charAddedConn = nil
			end

			if not targetPlr or not targetPlr.Parent then
				refreshToken += 1
				currentReqPlr, liveSource, liveRoot, cloneRoot = nil, nil, nil, nil
				table.clear(livePairs)
				-- KOZMOZ FIX: kutu acik kalir, sadece "hedef yok" durumuna gecer
				PreviewHolder.Visible = true
				leftArrow.Visible = false
				rightArrow.Visible = false
				if liveStatConn then
					pcall(function() liveStatConn:Disconnect() end)
					liveStatConn = nil
				end
				liveOverlay.Text = ""
				nameOverlay.Text = "No target selected"
				userOverlay.Text = "Pick a player from the Immunity list"
				detailName.Text = "<b>-</b>"
				detailId.Text = "Select a target for the live preview"
				if currentModel then
					pcall(function() currentModel:Destroy() end)
					currentModel = nil
				end
				Immunity:Resize()
				return
			end

			PreviewHolder.Visible = true
			leftArrow.Visible = (#currentSelectedPlayers > 1)
			rightArrow.Visible = (#currentSelectedPlayers > 1)

			nameOverlay.Text = tostring(targetPlr.DisplayName)
			userOverlay.Text = "@" .. tostring(targetPlr.Name)
			detailName.Text = string.format("<b>%s</b> (@%s)", tostring(targetPlr.DisplayName), tostring(targetPlr.Name))
			detailId.Text = string.format('User ID: <font color="#a0a0a0">%d</font>', targetPlr.UserId)

			Refresh3DAvatar(targetPlr)

			-- KOZMOZ: anlik hareket gostergesi (0.15 s aralik, FPS'e etkisi yok)
			local myToken = refreshToken
			if liveStatConn then
				pcall(function() liveStatConn:Disconnect() end)
				liveStatConn = nil
			end
			liveStatConn = RunService.Heartbeat:Connect(function()
				if flag11 or refreshToken ~= myToken or not PreviewHolder.Visible then return end
				local now = os.clock()
				if now - (lastLiveStat or 0) < 0.15 then return end
				lastLiveStat = now

				local lChar = targetPlr.Character
				local lRoot = lChar and lChar:FindFirstChild("HumanoidRootPart")
				local lHum = lChar and lChar:FindFirstChildOfClass("Humanoid")
				if not (lRoot and lHum) then
					liveOverlay.Text = "<font color=\"#ff8a8a\">No character (respawning)</font>"
					return
				end

				local speed = lRoot.AssemblyLinearVelocity.Magnitude
				local tags = {}
				local state = lHum:GetState()
				if state == Enum.HumanoidStateType.Freefall then
					tags[#tags + 1] = "<font color=\"#8ab4ff\">airborne</font>"
				elseif state == Enum.HumanoidStateType.Swimming then
					tags[#tags + 1] = "<font color=\"#8ab4ff\">floating</font>"
				elseif state == Enum.HumanoidStateType.Climbing then
					tags[#tags + 1] = "<font color=\"#8ab4ff\">climbing</font>"
				end
				if lHum.Sit then tags[#tags + 1] = "<font color=\"#ffd479\">sitting</font>" end
				local rag = lChar:FindFirstChild("Ragdolled")
				if rag and rag.Value then tags[#tags + 1] = "<font color=\"#ff8a8a\">ragdoll</font>" end
				if lHum.Health < lHum.MaxHealth then
					tags[#tags + 1] = string.format("<font color=\"#ff9f6b\">HP %d%%</font>", math.floor((lHum.Health / math.max(lHum.MaxHealth, 1)) * 100))
				end

				local moveTxt = speed < 1 and "standing" or (speed < 8 and "walking" or (speed < 22 and "running" or "launched"))
				liveOverlay.Text = string.format("<b>%s</b> Â· %d speed%s", moveTxt, math.floor(speed),
					#tags > 0 and ("  Â·  " .. table.concat(tags, "  Â·  ")) or "  Â·  <font color=\"#a0a0a0\">idle</font>")
			end)

			charAddedConn = targetPlr.CharacterAdded:Connect(function()
				task.wait(0.6)
				if currentSelectedPlayers[currentPreviewIndex] == targetPlr then
					Refresh3DAvatar(targetPlr)
				end
			end)

			Immunity:Resize()
		end

		local function ShowCurrentPlayer()
			if #currentSelectedPlayers == 0 then
				currentPreviewIndex = 1
				UpdatePreview(nil)
			else
				if currentPreviewIndex > #currentSelectedPlayers then
					currentPreviewIndex = 1
				elseif currentPreviewIndex < 1 then
					currentPreviewIndex = #currentSelectedPlayers
				end
				local plrToView = currentSelectedPlayers[currentPreviewIndex]
				UpdatePreview(plrToView)
			end
		end

		leftArrow.MouseButton1Click:Connect(function()
			if #currentSelectedPlayers <= 1 then return end
			currentPreviewIndex = currentPreviewIndex - 1
			if currentPreviewIndex < 1 then
				currentPreviewIndex = #currentSelectedPlayers
			end
			ShowCurrentPlayer()
		end)

		rightArrow.MouseButton1Click:Connect(function()
			if #currentSelectedPlayers <= 1 then return end
			currentPreviewIndex = currentPreviewIndex + 1
			if currentPreviewIndex > #currentSelectedPlayers then
				currentPreviewIndex = 1
			end
			ShowCurrentPlayer()
		end)

		viewport.InputBegan:Connect(function(input)
			if input.UserInputType == Enum.UserInputType.MouseButton1
				or input.UserInputType == Enum.UserInputType.MouseButton2
				or input.UserInputType == Enum.UserInputType.Touch
			then
				isDragging = true
				lastInputPos = input.Position
			end
		end)

		UIS.InputEnded:Connect(function(input)
			if input.UserInputType == Enum.UserInputType.MouseButton1
				or input.UserInputType == Enum.UserInputType.MouseButton2
				or input.UserInputType == Enum.UserInputType.Touch
			then
				isDragging = false
			end
		end)

		UIS.InputChanged:Connect(function(input)
			if not isDragging or not lastInputPos then return end
			if input.UserInputType == Enum.UserInputType.MouseMovement
				or input.UserInputType == Enum.UserInputType.Touch
			then
				local delta = input.Position - lastInputPos
				lastInputPos = input.Position
				yawAngle = yawAngle - delta.X * 0.012
				pitchAngle = math.clamp(pitchAngle + delta.Y * 0.008, -0.45, 0.45)
			end
		end)

		local immunityPreviewConn = RunService.RenderStepped:Connect(function(dt)
			if flag11 or not viewport.Parent or not PreviewHolder.Visible or not viewport.Visible then return end
			local anc = viewport.Parent
			while anc do
				if anc:IsA("GuiObject") and not anc.Visible then return end
				if anc:IsA("ScreenGui") and not anc.Enabled then return end
				anc = anc.Parent
			end
			-- Keep only the displayed selected player's parts in sync; no extra render loop.
			if currentModel and currentModel.Parent and currentReqPlr
				and liveSource == currentReqPlr.Character and liveRoot and liveRoot.Parent
				and cloneRoot and cloneRoot.Parent then
				previewElapsed += dt
				if previewElapsed >= 1 / 30 then
					previewElapsed = 0
					local rootCF = liveRoot.CFrame
					cloneRoot.CFrame = CFrame.new(0, 0, 0)
					for _, pair in ipairs(livePairs) do
						if pair.real.Parent and pair.clone.Parent then
							pair.clone.CFrame = rootCF:ToObjectSpace(pair.real.CFrame)
						end
					end
				end
			else
				previewElapsed = 0
			end
			if not isDragging then
				yawAngle = (yawAngle + dt * 1.15) % (math.pi * 2)
			end
			local offset = CFrame.Angles(0, yawAngle, 0)
				* CFrame.Angles(pitchAngle, 0, 0)
				* Vector3.new(0, 0.1, FIXED_CAMERA_DISTANCE)
			vpCamera.CFrame = CFrame.lookAt(modelCenter + offset, modelCenter)
		end)
		lib:OnUnload(function()
			refreshToken += 1
			if immunityPreviewConn then immunityPreviewConn:Disconnect() end
			if charAddedConn then charAddedConn:Disconnect(); charAddedConn = nil end
			table.clear(livePairs)
			currentReqPlr, liveSource, liveRoot, cloneRoot = nil, nil, nil, nil
		end)

		Players.PlayerRemoving:Connect(function(leavingPlr)
			local foundIdx = table.find(currentSelectedPlayers, leavingPlr)
			if foundIdx then
				table.remove(currentSelectedPlayers, foundIdx)
				if #currentSelectedPlayers == 0 then
					currentPreviewIndex = 1
					UpdatePreview(nil)
				else
					if currentPreviewIndex > #currentSelectedPlayers then
						currentPreviewIndex = 1
					end
					ShowCurrentPlayer()
				end
			end
		end)

		local previousSelectionMap = {}
		local function OnSelectionChanged(arg8)
			local newSelectedList = {}
			local newlyAdded = nil

			if typeof(arg8) == "table" then
				for plrObj, isSel in pairs(arg8) do
					if isSel and typeof(plrObj) == "Instance" and plrObj:IsA("Player") and plrObj.Parent == Players then
						table.insert(newSelectedList, plrObj)
						if not previousSelectionMap[plrObj] then
							newlyAdded = plrObj
						end
					end
				end

				previousSelectionMap = {}
				for _, p in ipairs(newSelectedList) do
					previousSelectionMap[p] = true
				end
			elseif typeof(arg8) == "Instance" and arg8:IsA("Player") and arg8.Parent == Players then
				table.insert(newSelectedList, arg8)
				newlyAdded = arg8
				previousSelectionMap = { [arg8] = true }
			else
				previousSelectionMap = {}
			end

			-- KOZMOZ v27: remember the selection ORDER (Gorilla guards only the first selected player)
			do
				local order = {}
				local inNew = {}
				for _, p in ipairs(newSelectedList) do
					inNew[p] = true
				end
				for _, p in ipairs(type(tbl7.ImmuneOrder) == "table" and tbl7.ImmuneOrder or {}) do
					if inNew[p] and not table.find(order, p) then
						table.insert(order, p)
					end
				end
				for _, p in ipairs(newSelectedList) do
					if not table.find(order, p) then
						table.insert(order, p)
					end
				end
				tbl7.ImmuneOrder = order
			end
			currentSelectedPlayers = newSelectedList

			if #currentSelectedPlayers == 0 then
				currentPreviewIndex = 1
				UpdatePreview(nil)
			else
				if newlyAdded then
					local idx = table.find(currentSelectedPlayers, newlyAdded)
					if idx then
						currentPreviewIndex = idx
					end
				elseif currentPreviewIndex > #currentSelectedPlayers or currentPreviewIndex < 1 then
					currentPreviewIndex = 1
				end
				ShowCurrentPlayer()
			end
		end

