		local syncingImmunityAGMode = false

		-- v26: is Gorilla ready? IsReady() used to be strict (the gState.enabled check
		-- kept it ðŸ”´ even when it was installed). We now scan the scene too.
		local function countGorillaPartsInWorld()
			local n = 0
			pcall(function()
				local slots = getgenv().KOZMOZ_GORILLA_SLOTS
				if type(slots) == "table" then
					for i = 1, 30 do
						local sl = slots[i]
						if sl and sl.Model and sl.Model.Parent then
							n += 1
						end
					end
					if n > 0 then
						return
					end
				end
				for _, obj in ipairs(workspace:GetChildren()) do
					local nm = string.lower(obj.Name)
					if string.find(nm, "gorilla") then
						n += 1
					end
				end
			end)
			return n
		end

		pcall(function()
			getgenv().KOZMOZ_GORILLA_COUNT_PARTS = countGorillaPartsInWorld
		end)

		local function isGorillaReadyForGuard()
			local g = kozPorBridge and kozPorBridge.Gorilla
			if g and g.IsReady then
				local ok, res = pcall(g.IsReady)
				if ok and res == true then
					return true
				end
			end
			-- v26: is it really installed? (partial is enough)
			return countGorillaPartsInWorld() > 0
		end
		local function isBearReadyForGuard()
			local b = kozPorBridge and kozPorBridge.Bear
			if b and b.IsReady then
				local ok, ready = pcall(b.IsReady)
				if ok then return ready == true end
			end
			local fn = getgenv().KOZMOZ_BEAR_COUNT_PARTS
			local ok, n = pcall(function() return type(fn) == "function" and fn() or 0 end)
			return ok and (tonumber(n) or 0) > 0
		end
		local function formatGorillaModeOption(val)
			if val == "Gorilla" then
				return isGorillaReadyForGuard() and "Gorilla ðŸŸ¢" or "Gorilla ðŸ”´"
			elseif val == "Bear" then
				return isBearReadyForGuard() and "Bear ðŸŸ¢" or "Bear ðŸ”´"
			end
			return tostring(val or "")
		end

		UpdateShieldIndicators()
	end



	do
		local EGIP = {
			Selected = {},
			Queue = {},
			Queued = {},
			Processing = false,
			Syncing = false,
			PlotCache = {},
			Controls = {},
			NearestLabels = {},
			NearestName = nil,
			NextRetryAt = {},
		}
		tbl12.EnableGrabInPlotState = EGIP

		local EGIP_Defs = {
			{ Key = "TudorHouse", Label = "1 | TudorHouse", Fallback = "Plot1" },
			{ Key = "PinkRoofHouse", Label = "2 | PinkRoofHouse", Fallback = "Plot2" },
			{ Key = "HauntedHouse", Label = "3 | HauntedHouse", Fallback = "Plot3" },
			{ Key = "JapaneseHouse", Label = "4 | JapaneseHouse", Fallback = "Plot5" },
			{ Key = "BlueHouse", Label = "5 | BlueHouse", Fallback = "Plot4" },
		}
		local EGIP_DefsByKey = {}
		for _, def in ipairs(EGIP_Defs) do
			EGIP_DefsByKey[def.Key] = def
			EGIP.Selected[def.Key] = false
			EGIP.Controls[def.Key] = {}
			EGIP.NextRetryAt[def.Key] = 0
		end

		local function EGIP_Notify(message)
			pcall(function()
				if fn18 then
					fn18(message, "Enable Grab In Plot")
				end
			end)
		end

		local function EGIP_InstancePosition(inst)
			if not inst then
				return nil
			end
			local pos = nil
			pcall(function()
				if inst:IsA("BasePart") then
					pos = inst.Position
				elseif inst:IsA("Attachment") then
					pos = inst.WorldPosition
				elseif inst:IsA("Model") then
					pos = inst:GetPivot().Position
				else
					local part = inst:FindFirstChildWhichIsA("BasePart", true)
					if part then
						pos = part.Position
					end
				end
			end)
			if pos and pos.Magnitude < 100000 then
				return pos
			end
			return nil
		end

		local function EGIP_PlotPosition(plot)
			if not plot then
				return nil
			end
			local pos = EGIP_InstancePosition(plot:FindFirstChild("PlotArea"))
			if pos then
				return pos
			end
			pos = EGIP_InstancePosition(plot:FindFirstChild("PlotSign"))
			if pos then
				return pos
			end
			return EGIP_InstancePosition(plot)
		end

		local function EGIP_ResolvePlots()
			local plotsFolder = workspace:FindFirstChild("Plots")
			if not plotsFolder then
				return
			end
			local used = {}
			for key, plot in pairs(EGIP.PlotCache) do
				if plot and plot.Parent then
					used[plot] = true
				else
					EGIP.PlotCache[key] = nil
				end
			end
			local waypoints = workspace:FindFirstChild("Waypoints")
			for _, def in ipairs(EGIP_Defs) do
				if not EGIP.PlotCache[def.Key] then
					local chosen = nil
					local waypoint = waypoints and waypoints:FindFirstChild(def.Key)
					local waypointPos = EGIP_InstancePosition(waypoint)
					if waypointPos then
						local bestDist = math.huge
						for _, plot in ipairs(plotsFolder:GetChildren()) do
							if not used[plot] then
								local plotPos = EGIP_PlotPosition(plot)
								if plotPos then
									local dist = (plotPos - waypointPos).Magnitude
									if dist < bestDist then
										bestDist = dist
										chosen = plot
									end
								end
							end
						end
						if bestDist > 350 then
							chosen = nil
						end
					end
					if not chosen then
						local fallback = plotsFolder:FindFirstChild(def.Fallback)
						if fallback and not used[fallback] then
							chosen = fallback
						end
					end
					if chosen then
						EGIP.PlotCache[def.Key] = chosen
						used[chosen] = true
					end
				end
			end
		end

		local function EGIP_GetPlot(def)
			local cached = EGIP.PlotCache[def.Key]
			if cached and cached.Parent then
				return cached
			end
			EGIP.PlotCache[def.Key] = nil
			EGIP_ResolvePlots()
			return EGIP.PlotCache[def.Key]
		end

		local function EGIP_IsBroken(plot)
			return plot and tbl7.BrokenPlots and tbl7.BrokenPlots[plot.Name] ~= nil
		end

		local function EGIP_FixPlot(plot)
			if not plot then
				return true
			end
			local brokenToy = tbl7.BrokenPlots and tbl7.BrokenPlots[plot.Name]
			if not brokenToy then
				return true
			end
			if typeof(brokenToy) ~= "Instance" then
				return false
			end
			pcall(function()
				tbl12.DestroyToy(brokenToy)
			end)
			local started = tick()
			while tick() - started < 0.6 do
				if not brokenToy.Parent or tbl7.BrokenPlots[plot.Name] ~= brokenToy then
					return true
				end
				task.wait()
			end
			return tbl7.BrokenPlots[plot.Name] ~= brokenToy
		end

		local EGIP_StartProcessor

		local function EGIP_ProcessEntry(entry)
			local key = entry.Key
			local def = EGIP_DefsByKey[key]
			if not def then
				return
			end
			local plot = EGIP_GetPlot(def)
			if not plot then
				EGIP.NextRetryAt[key] = tick() + 5
				if entry.Manual then
					EGIP_Notify("Could not find the plot for " .. def.Key .. ".")
				end
				return
			end
			if EGIP.Selected[key] then
				local attempts = 0
				while not flag11 and EGIP.Selected[key] and not EGIP_IsBroken(plot) and attempts < 3 do
					attempts = attempts + 1
					local ok, result = pcall(tbl12.BreakPlot, plot)
					if (not ok or not result) and EGIP.Selected[key] and not EGIP_IsBroken(plot) then
						task.wait(0.15)
					end
				end
				if EGIP.Selected[key] and not EGIP_IsBroken(plot) then
					EGIP.NextRetryAt[key] = tick() + 5
					if entry.Manual then
						EGIP_Notify("Could not disable the safe zone for " .. def.Key .. " yet. It will keep retrying.")
					end
				elseif EGIP.Selected[key] then
					EGIP.NextRetryAt[key] = 0
				end
			else
				local attempts = 0
				while not flag11 and not EGIP.Selected[key] and EGIP_IsBroken(plot) and attempts < 3 do
					attempts = attempts + 1
					if EGIP_FixPlot(plot) then
						break
					end
					task.wait(0.1)
				end
				if not EGIP.Selected[key] and EGIP_IsBroken(plot) then
					EGIP.NextRetryAt[key] = tick() + 5
					if entry.Manual then
						EGIP_Notify("Could not restore the safe zone for " .. def.Key .. " yet.")
					end
				elseif not EGIP.Selected[key] then
					EGIP.NextRetryAt[key] = 0
				end
			end
		end

		local function EGIP_Enqueue(key, manual)
			if flag11 then
				return
			end
			local entry = EGIP.Queued[key]
			if entry then
				entry.Manual = entry.Manual or manual == true
				return
			end
			entry = { Key = key, Manual = manual == true }
			EGIP.Queued[key] = entry
			table.insert(EGIP.Queue, entry)
			if EGIP_StartProcessor then
				EGIP_StartProcessor()
			end
		end

		EGIP_StartProcessor = function()
			if EGIP.Processing then
				return
			end
			EGIP.Processing = true
			task.spawn(function()
				while not flag11 and #EGIP.Queue > 0 do
					local entry = table.remove(EGIP.Queue, 1)
					EGIP.Queued[entry.Key] = nil
					pcall(EGIP_ProcessEntry, entry)
				end
				EGIP.Processing = false
				if not flag11 and #EGIP.Queue > 0 then
					EGIP_StartProcessor()
				end
			end)
		end

		local function EGIP_SetSelected(key, value, sourceId)
			value = value == true
			EGIP.Selected[key] = value
			EGIP.NextRetryAt[key] = 0
			if not EGIP.Syncing then
				EGIP.Syncing = true
				for _, toggleId in ipairs(EGIP.Controls[key] or {}) do
					if toggleId ~= sourceId then
						local toggle = toggles and toggles[toggleId]
						if toggle and toggle.Value ~= value then
							pcall(function()
								toggle:SetValue(value)
							end)
						end
					end
				end
				EGIP.Syncing = false
			end
			EGIP_Enqueue(key, true)
		end

		local function EGIP_UpdateNearest()
			if #EGIP.NearestLabels == 0 then
				return
			end
			local char = localPlayer and localPlayer.Character
			local hrp = char and (char:FindFirstChild("HumanoidRootPart") or char:FindFirstChild("Torso"))
			if not hrp then
				return
			end
			local waypoints = workspace:FindFirstChild("Waypoints")
			if not waypoints then
				return
			end
			local nearestName = nil
			local nearestDist = math.huge
			for _, child in ipairs(waypoints:GetChildren()) do
				if child.Name ~= "CharacterWaypoint" then
					local pos = EGIP_InstancePosition(child)
					if pos then
						local dist = (pos - hrp.Position).Magnitude
						if dist < nearestDist then
							nearestDist = dist
							nearestName = child.Name
						end
					end
				end
			end
			if nearestName and nearestName ~= EGIP.NearestName then
				EGIP.NearestName = nearestName
				local text = "Nearest Location: " .. nearestName
				for _, label in ipairs(EGIP.NearestLabels) do
					pcall(function()
						label:SetText(text)
					end)
				end
			end
		end

		local function EGIP_MaintainSelected()
			for _, def in ipairs(EGIP_Defs) do
				local key = def.Key
				if EGIP.Selected[key] and tick() >= (EGIP.NextRetryAt[key] or 0) then
					local plot = EGIP_GetPlot(def)
					if plot and not EGIP_IsBroken(plot) then
						EGIP_Enqueue(key, false)
					end
				end
			end
		end

		tbl12.CreateEnableGrabInPlotGroup = function(tab, prefix)
			local group = tab:AddLeftGroupbox("Enable Grab In Plot", "fence")
			group:AddLabel("Disables Selected Safe Zones!", true)
			group:AddDivider("Plots")
			for _, def in ipairs(EGIP_Defs) do
				local key = def.Key
				local toggleId = prefix .. key
				table.insert(EGIP.Controls[key], toggleId)
				group:AddToggle(toggleId, {
					Text = def.Label,
					Default = EGIP.Selected[key] == true,
					Tooltip = "Checked: disables this plot's safe zone so players inside can be grabbed. Unchecked: restores the safe zone.",
					Callback = function(value)
						EGIP_SetSelected(key, value, toggleId)
					end,
				})
			end
			group:AddDivider()
			local nearestLabel = group:AddLabel("Nearest Location: ...", true)
			table.insert(EGIP.NearestLabels, nearestLabel)
			EGIP.NearestName = nil
			EGIP_UpdateNearest()
			return group
		end

		-- Plot lookup runs on demand when a safe-zone action is selected.

		task.spawn(function()
			while not flag11 do
				EGIP_UpdateNearest()
				EGIP_MaintainSelected()
				task.wait(0.75)
			end
		end)
	end

