	-- KOZMOZ USER FEATURE: the Spin method (mogg's circle spin), ported to KOZMOZ's helpers.
	-- The victim is pinned in the air with a BodyPosition/BodyGyro pair while YOUR character is
	-- pushed around them on a circle; when the grab line is destroyed at the right moment the game
	-- throws them. Radius/speed: Target > Method Settings > Spin Settings. Nothing here touches
	-- the Kick loop: if a player is already pinned by it (KickAP), Spin leaves them alone.
	local SPIN_DESTROY_DELAY = 0.01 -- mogg's "Destroy Line Lag Delay", fixed on purpose (no slider)
	local SPIN_ONCE_SECONDS = 1.2 -- one "Apply Method Selected" press keeps them spinning this long
	local SPIN_HOLD_SNAP = 1.5 -- they must be this close to the hold point before the line is cut
	local SPIN_REACH = 33 -- how close you have to be to hold them at all
	local SPIN_LOST_FRAMES = 10 -- losing physics ownership this often resets the circle
	local SPIN_HOLD = { "KozmozSpinHold", "KozmozSpinHoldGyro" }
	local SPIN_MOVE = { "KozmozSpinMove", "KozmozSpinMoveGyro" }
	local SPIN_LIMBS = {
		"Head",
		"Torso",
		"UpperTorso",
		"LowerTorso",
		"Left Arm",
		"Right Arm",
		"Left Leg",
		"Right Leg",
		"HumanoidRootPart",
	}
	local spinStates = {}
	local playersSvc2 = game:GetService("Players")
	local me2 = playersSvc2.LocalPlayer

	local function spinClear(part, names)
		if not (part and part.Parent) then
			return
		end

		for _, name in ipairs(names) do
			local obj = part:FindFirstChild(name)

			if obj then
				pcall(function()
					obj:Destroy()
				end)
			end
		end
	end

	local function spinHold(part, targetPos, lookVec)
		-- same numbers as mogg: P 50000, D 100
		if not (part and part.Parent) then
			return
		end

		local bp = part:FindFirstChild(SPIN_HOLD[1])

		if not bp then
			bp = Instance.new("BodyPosition")
			bp.Name = SPIN_HOLD[1]
			bp.MaxForce = Vector3.new(math.huge, math.huge, math.huge)
			bp.Parent = part
		end

		bp.P = 50000
		bp.D = 100
		bp.Position = targetPos

		local bg = part:FindFirstChild(SPIN_HOLD[2])

		if not bg then
			bg = Instance.new("BodyGyro")
			bg.Name = SPIN_HOLD[2]
			bg.MaxTorque = Vector3.new(math.huge, math.huge, math.huge)
			bg.P = 50000
			bg.D = 100
			bg.Parent = part
		end

		bg.CFrame = CFrame.new(part.Position, part.Position + lookVec)
	end

	local function spinMove(part, pos, lookPos)
		-- mogg: BodyPosition P 10000 D 500, BodyGyro P 50000 D 500
		if not (part and part.Parent) then
			return
		end

		local bp = part:FindFirstChild(SPIN_MOVE[1])

		if not bp then
			bp = Instance.new("BodyPosition")
			bp.Name = SPIN_MOVE[1]
			bp.MaxForce = Vector3.new(math.huge, math.huge, math.huge)
			bp.P = 10000
			bp.D = 500
			bp.Parent = part
		end

		bp.Position = pos

		local bg = part:FindFirstChild(SPIN_MOVE[2])

		if not bg then
			bg = Instance.new("BodyGyro")
			bg.Name = SPIN_MOVE[2]
			bg.MaxTorque = Vector3.new(math.huge, math.huge, math.huge)
			bg.P = 50000
			bg.D = 500
			bg.Parent = part
		end

		bg.CFrame = CFrame.new(pos, lookPos)
	end

	local function spinRelease(plr)
		local state = spinStates[plr]

		if not state then
			return
		end

		spinStates[plr] = nil
		spinClear(state.root, SPIN_HOLD)

		if state.root and state.root.Parent then
			tbl12.ResetVelocity(state.root)

			local weld = state.root:FindFirstChild("WeldHRP")

			if weld and state.humanoid and state.humanoid:FindFirstChild("Ragdolled") and state.humanoid.Ragdolled.Value then
				weld.Enabled = true
			end
		end

		if state.char and state.char.Parent then
			for _, name in ipairs(SPIN_LIMBS) do
				local part = state.char:FindFirstChild(name)

				if part then
					pcall(function()
						part.CanCollide = true
						part.CanTouch = true
					end)
				end
			end
		end

		local myChar, myRoot = tbl12.Char()

		if next(spinStates) == nil then
			if myRoot and myRoot.Parent then
				spinClear(myRoot, SPIN_MOVE)
				tbl12.ResetVelocity(myRoot)
			end

			if myChar and myChar.Parent then
				tbl12.ResetVelocity(myChar:FindFirstChild("HumanoidRootPart") or myRoot)
			end
		end
	end

	local function spinKeep(plr, seconds)
		local state = spinStates[plr]

		if not state then
			state = {
				["angle"] = 0,
				["keepUntil"] = 0,
				["lost"] = 0,
			}
			spinStates[plr] = state
		end

		if seconds > 0 then
			state.keepUntil = math.max(state.keepUntil or 0, os.clock() + seconds)
		end

		return state
	end

	local function spinInPlot()
		local flag = me2 and me2:FindFirstChild("InPlot")
		return flag ~= nil and flag.Value == true
	end

	local function spinTargets(server, wanted)
		if server then
			for _, plr in ipairs(playersSvc2:GetPlayers()) do
				if plr ~= me2 and plr.Parent and not tbl12.IsProtectedPlayer(plr) then
					wanted[plr] = true
				end
			end
		else
			for plr in pairs(tbl7.SelectedPlayers) do
				if plr and plr.Parent and not tbl12.IsProtectedPlayer(plr) then
					wanted[plr] = true
				end
			end
		end
	end

	local spinDt = 1 / 60

	local function spinStep(plr, state)
		local myChar, myRoot, myHum = tbl12.Char()

		if not (myChar and myRoot and myHum and myHum.Health > 0) then
			spinRelease(plr)
			return
		end

		local char, root, hum = tbl12.Char(plr)

		if not (char and root and hum and hum.Health > 0) then
			-- they died or left: drop everything we put on them
			spinRelease(plr)
			return
		end

		state.char, state.root, state.humanoid = char, root, hum

		-- KOZMOZ USER: Kick + Spin run together; clean stale Kick movers and keep spinning
		if root:FindFirstChild("KickAP") or root:FindFirstChild("KickAO") then
			spinClear(root, { "KickAP", "KickAO" })
		end

		-- they must not stand on the ground while they are being spun
		for _, name in ipairs(SPIN_LIMBS) do
			local part = char:FindFirstChild(name)

			if part then
				pcall(function()
					tbl12.ResetVelocity(part)
					part.CanCollide = false
					part.CanTouch = false
				end)
			end
		end

		local weld = root:FindFirstChild("WeldHRP")

		if weld then
			weld.Enabled = false
		end

		-- mogg watches a PartOwner StringValue; KOZMOZ has a helper for the same question
		if state.started then
			if tbl12.IsNetworkOwner and root and tbl12.IsNetworkOwner(root) then
				state.lost = 0
			else
				state.lost = (state.lost or 0) + 1

				if state.lost > SPIN_LOST_FRAMES then
					state.lost = 0
					state.started = nil
					state.groundY = nil
				end
			end
		end

		local radius = math.max(tonumber(tbl9.SpinRadius) or 15, 1)
		local speed = math.max(tonumber(tbl9.SpinSpeed) or 2, 0.1)
		local height = tonumber(tbl9.NKOffset) or 15

		if not state.groundY then
			local ok, params = pcall(RaycastParams.new)

			if ok then
				params.FilterType = Enum.RaycastFilterType.Exclude
				params.FilterDescendantsInstances = { myChar }
				params.IgnoreWater = true
			end

			local hit = ok and workspace:Raycast(myRoot.Position, Vector3.new(0, -2000, 0), params) or nil
			state.groundY = hit and hit.Position.Y or myRoot.Position.Y
			if not state.anchor then
				state.anchor = Vector3.new(myRoot.Position.X, 0, myRoot.Position.Z)
				state.angle = 0
			end
		elseif myRoot.Position.Y < state.groundY - 1 then
			state.groundY = myRoot.Position.Y
		end

		local curXZ = Vector3.new(myRoot.Position.X, 0, myRoot.Position.Z)

		if (curXZ - state.anchor).Magnitude > radius * 5 then
			-- we drifted too far for the circle to make sense: re-centre it
			state.anchor = curXZ
			state.angle = 0
		end

		state.angle = (state.angle + speed * math.pi * 2 * spinDt) % (math.pi * 2)

		local y = state.groundY + height
		local holdPos = Vector3.new(state.anchor.X, y, state.anchor.Z)
		local orbitPos = Vector3.new(
			state.anchor.X + math.cos(state.angle) * radius,
			y,
			state.anchor.Z + math.sin(state.angle) * radius
		)

		spinMove(myRoot, orbitPos, holdPos)
		spinHold(root, holdPos, (holdPos - orbitPos).Unit)

		state.holdPos = holdPos
		state.started = true

		if tbl12.GetMagnitude(myRoot, root) <= SPIN_REACH then
			-- keep the server convinced we are holding them
			tbl12.Grab(root)
		end

		if (root.Position - holdPos).Magnitude <= SPIN_HOLD_SNAP and (root.Position - myRoot.Position).Magnitude < SPIN_REACH then
			local now = os.clock()

			if now - (state.lastCut or 0) >= SPIN_DESTROY_DELAY then
				state.lastCut = now
				-- cut the line while they are pinned: that is what throws them
				tbl12.RNO(root)
			end
		end
	end

	task.spawn(function()
		local last = os.clock()

		while task.wait() do
			if flag11 then
				for plr in pairs(spinStates) do
					spinRelease(plr)
				end

				return
			end

			local methods = tbl7.TargetMethods
			local loopSel = tbl8.LoopApplyMethodT
			local loopServ = tbl8.LoopApplyMethodTServer
			local allow = methods and methods.Spin == true and not spinInPlot()
			local looping = allow and (loopSel or loopServ)
			if not looping and next(spinStates) == nil then
				last = os.clock()
				continue
			end

			local now = os.clock()
			spinDt = math.min(math.max(now - last, 0.001), 0.2)
			last = now
			local wanted = {}

			if looping then
				-- the Server loop grabs everybody, the Selected loop only the picked players
				spinTargets(loopServ == true, wanted)
			end

			if allow then
				-- an "Apply Method Selected" press keeps spinning that player for a short while
				for plr, state in pairs(spinStates) do
					if (state.keepUntil or 0) >= now then
						wanted[plr] = true
					end
				end
			end

			for plr in pairs(spinStates) do
				if wanted[plr] ~= true then
					spinRelease(plr)
				end
			end

			for plr in pairs(wanted) do
				if plr ~= me2 and not tbl12.IsProtectedPlayer(plr) then
					spinStep(plr, spinKeep(plr, 0))
				end
			end
		end
	end)

	tbl12.BeginSpinKick = function(plr)
		if plr and plr ~= me2 and not tbl12.IsProtectedPlayer(plr) then
			if tbl7.TargetMethods and tbl7.TargetMethods.Kick and tbl12.Void and not tbl8.LoopApplyMethodT and not tbl8.LoopApplyMethodTServer then
				task.delay(SPIN_ONCE_SECONDS, function()
					if tbl7.TargetMethods and tbl7.TargetMethods.Kick then
						pcall(tbl12.Void, plr)
					end
				end)
			end
			spinKeep(plr, SPIN_ONCE_SECONDS)
		end
	end


