	do
		-- =====================================================================
		-- HOUSE BARRIER - ported 1:1 from kar.txt (ocarina + campfire trick)
		-- =====================================================================
		local Barrier = tbl15.Toys:AddRightGroupbox("House Barrier", "house")
		pcall(function()
			Barrier:SetDescription("House Functions")
		end)

		local HB_WS = workspace
		local HB_LP = localPlayer
		local HB_RS = game:GetService("ReplicatedStorage")
		local hbAuto = false
		local hbToys = nil
		local hbSpawnToy = nil
		local hbDeleteToy = nil

		task.spawn(function()
			pcall(function()
				hbToys = HB_RS:WaitForChild("MenuToys", 10)
				hbSpawnToy = hbToys and hbToys:WaitForChild("SpawnToyRemoteFunction", 10)
				hbDeleteToy = hbToys and hbToys:WaitForChild("DestroyToy", 10)
			end)
		end)

		local function hbMyToys()
			return HB_WS:FindFirstChild(HB_LP.Name .. "SpawnedInToys")
		end

		local hbPlots = nil
		local function hbPlotsFolder()
			if not hbPlots or not hbPlots.Parent then
				hbPlots = HB_WS:FindFirstChild("Plots") or HB_WS:WaitForChild("Plots", 5)
			end
			return hbPlots
		end

		local hbWatched = {}
		local hbConns = {}
		local hbApply = nil

		-- true when no solid barrier is standing any more
		local function hbIsBroken()
			local folder = hbPlotsFolder()
			if not folder then
				return false
			end
			local plots = {}
			for _, child in ipairs(folder:GetChildren()) do
				if child.Name:find("Plot") or child:FindFirstChild("PlotSign") or child:FindFirstChild("Barrier") then
					table.insert(plots, child)
				end
			end
			if #plots == 0 then
				return false
			end

			local overlapParams = OverlapParams.new()
			overlapParams.FilterType = Enum.RaycastFilterType.Include
			overlapParams.FilterDescendantsInstances = { HB_WS:FindFirstChild("Map") or HB_WS, folder }
			local found = {}
			pcall(function()
				found = HB_WS:GetPartBoundsInRadius(Vector3.new(304.06, 25.77, 488.54), 12, overlapParams)
			end)
			local solidNearby = false
			for _, part in ipairs(found) do
				if part:IsA("BasePart") and part.Anchored and part.Position.Y > 0 then
					solidNearby = true
					break
				end
			end
			if #found == 0 or not solidNearby then
				return true
			end

			local brokenCount = 0
			local standingCount = 0
			for _, plot in ipairs(plots) do
				local barrier = plot:FindFirstChild("Barrier") or plot:FindFirstChild("PlotBarrier") or plot:FindFirstChild("HouseBarrier")
				if not barrier then
					brokenCount += 1
				else
					local parts = {}
					for _, desc in ipairs(barrier:GetDescendants()) do
						if desc:IsA("BasePart") then
							table.insert(parts, desc)
						end
					end
					if #parts == 0 then
						brokenCount += 1
					else
						local pivot = plot:GetPivot().Position
						local broken = false
						for _, part in ipairs(parts) do
							if not part.CanCollide then
								broken = true
								break
							elseif part.Position.Y < -50 then
								broken = true
								break
							elseif (part.Position - pivot).Magnitude > 250 then
								broken = true
								break
							end
						end
						if broken then
							brokenCount += 1
						else
							standingCount += 1
						end
					end
				end
			end
			if brokenCount > 0 or standingCount == 0 then
				return true
			end
			return false
		end

		-- re-apply the break whenever the game restores a barrier part
		local function hbWatch()
			for _, conn in ipairs(hbConns) do
				pcall(function()
					conn:Disconnect()
				end)
			end
			hbConns = {}
			hbWatched = {}
			local folder = hbPlotsFolder()
			if not folder then
				return
			end
			for _, child in ipairs(folder:GetChildren()) do
				local barrier = child:FindFirstChild("Barrier") or child:FindFirstChild("PlotBarrier") or child:FindFirstChild("HouseBarrier")
				if barrier then
					for _, desc in ipairs(barrier:GetDescendants()) do
						if desc:IsA("BasePart") and not hbWatched[desc] then
							hbWatched[desc] = true
							local conn = desc:GetPropertyChangedSignal("CanCollide"):Connect(function()
								if hbApply then
									hbApply()
								end
							end)
							table.insert(hbConns, conn)
						end
					end
				end
			end
		end

		-- kar.txt trick: hold the ocarina, teleport through the barrier, drop it,
		-- then place a campfire sound part so the server marks the plot as raided.
		-- v37: the break body is a normal (blocking) function so Toys Pet can wait for it;
		-- hbBreak() keeps the old behaviour (background, 6s delay).
		local hbRunning = false
		local function hbBreakBody()
			if not hbIsBroken() and hbAuto then
				-- re-run handled by the loop below; nothing to do here
			end
			local character = HB_LP.Character
			local hrp
			if character then
				hrp = character:FindFirstChild("saviHRP") or character:FindFirstChild("HumanoidRootPart")
			end
			if not hrp then
				return
			end
			local savedCF = hrp.CFrame
			pcall(function()
				if hbSpawnToy then
					hbSpawnToy:InvokeServer(
						"InstrumentWoodwindOcarina",
						CFrame.new(184.148834, -5.54824972, 498.136749, 0.829037189, -0.214714944, 0.516328275, 0, 0.923344612, 0.383972496, -0.559193552, -0.318327487, 0.765486956),
						Vector3.new(0, 34, 0)
					)
				end
			end)
			task.wait(0.3)
			local myToys = hbMyToys()
			local ocarina = myToys and myToys:FindFirstChild("InstrumentWoodwindOcarina")
			if ocarina and ocarina:FindFirstChild("HoldPart") and character then
				pcall(function()
					ocarina.HoldPart.HoldItemRemoteFunction:InvokeServer(ocarina, character)
				end)
			end
			task.wait(0.3)
			hrp.CFrame = CFrame.new(304.06, 25.77, 488.54)
			task.wait(0.15)
			if ocarina and ocarina.Parent and hbDeleteToy then
				pcall(function()
					hbDeleteToy:FireServer(ocarina)
				end)
			end
			task.wait(0.15)
			hrp.CFrame = savedCF
			local folder = hbPlotsFolder()
			if folder then
				for _, child in ipairs(folder:GetChildren()) do
					local barrier = child:FindFirstChild("Barrier")
					if barrier then
						for _, part in ipairs(barrier:GetChildren()) do
							if part:IsA("BasePart") then
								part.CanCollide = false
							end
						end
					end
				end
			end
			task.wait(0.5)
			pcall(function()
				if hbSpawnToy then
					hbSpawnToy:InvokeServer("Campfire", hrp.CFrame, Vector3.zero)
				end
			end)
			task.wait(0.2)
			local campfire = hbMyToys()
			campfire = campfire and campfire:FindFirstChild("Campfire")
			if campfire and campfire:FindFirstChild("SoundPart") then
				pcall(function()
					campfire.SoundPart.CFrame = CFrame.new(304, 25, 488)
				end)
				task.wait(2)
				if hbDeleteToy then
					pcall(function()
						hbDeleteToy:FireServer(campfire)
					end)
				end
			end
		end
		local function hbBreakRun(delaySec)
			if (delaySec or 0) > 0 then
				task.wait(delaySec)
			end
			if hbRunning then
				-- another break is already running: just wait for it
				local w0 = os.clock()
				while hbRunning and os.clock() - w0 < 6 do
					task.wait(0.1)
				end
				return
			end
			hbRunning = true
			local okRun, errRun = pcall(hbBreakBody)
			hbRunning = false
			if not okRun then
				warn("[KOZMOZ House Barrier] " .. tostring(errRun))
			end
		end
		local function hbBreak()
			task.spawn(hbBreakRun, 6)
		end
		-- v37: shared with Toys Pet (break the barrier first, then build the pet)
		tbl12.HouseBarrier = {
			IsBroken = function()
				return hbIsBroken()
			end,
			BreakNow = function()
				pcall(hbWatch)
				hbBreakRun(0)
			end,
		}

		hbApply = function()
			if not hbAuto then
				return
			end
			if not hbIsBroken() then
				hbBreak()
			end
		end

		Barrier:AddCheckbox("AutoBreakHB", {
