			Default = false,
			Callback = function(on)
				hbAuto = on
				if on then
					hbWatch()
					task.spawn(function()
						hbBreak()
						while hbAuto do
							task.wait(6)
							if not hbIsBroken() then
								hbBreak()
							end
						end
					end)
				end
			end,
		})

		Barrier:AddButton({
