		local kzLocalPlayer = kzPlayers.LocalPlayer

		lib.Items = lib.Items or {}
		lib.LucideIcons = lib.LucideIcons or {}
		local Library = setmetatable({
			Items = lib.Items,
			LucideIcons = lib.LucideIcons,
			Notify = function(_, opts, ...)
				if type(opts) == "table" then
					return lib:Notify({
						Title = opts.Title or "Toy Builds",
						Description = opts.Description or opts.Content or opts.Text or "",
						Time = opts.Time or opts.Duration or 3,
					})
				end
				return lib:Notify(opts, ...)
			end,
		}, { __index = lib })

		local function kzWrapItem(elem)
			if not elem then return nil end
			return {
				Set = function(v)
					if elem.SetValue then
						pcall(function() elem:SetValue(v) end)
					end
				end,
				Get = function()
					return elem.Value
				end,
				Element = elem,
			}
		end

		-- Bind defense (2).txt ANONIM_DF_* flags into Library.Items so cross-references work seamlessly
		pcall(function()
			local dfMap = {
				ANONIM_DF_AntiGrab = toggles and toggles.AntiGrab,
				ANONIM_DF_GucciType = options and options.GTDropdown,
				ANONIM_DF_CfgGucciType = options and options.GTDropdown,
				ANONIM_DF_AntiGucci = toggles and toggles.GucciAntiGrab,
				ANONIM_DF_AntiGucci_K = options and options.GucciKey,
				ANONIM_DF_AntiInputLag = toggles and toggles.AntiInputLag,
				ANONIM_DF_AntiInputLag_K = options and options.AntiNetK,
				ANONIM_DF_AntiExp = toggles and toggles.AntiExplosion,
				ANONIM_DF_AntiBurn = toggles and toggles.AntiBurn,
				ANONIM_DF_AntiVoid = toggles and toggles.AntiVoid,
				ANONIM_DF_AntiKick = toggles and toggles.AntiKick,
				ANONIM_DF_AntiKick2 = toggles and toggles.AntiKick2,
				ANONIM_DF_AntiSticky = toggles and toggles.AntiSticky,
				ANONIM_DF_AntiSnowball = toggles and toggles.AntiSnowball,
				ANONIM_DF_AntiBanana = toggles and toggles.AntiBanana,
				ANONIM_DF_AntiPaint = toggles and toggles.AntiPaint,
				ANONIM_DF_AntiPoison = toggles and toggles.AntiPoison,
				ANONIM_DF_AntiLag = toggles and toggles.AntiLag,
				ANONIM_DF_AntiLag_K = options and options.AntiLagK,
				ANONIM_DF_AutoAntiLag = toggles and toggles.AutoAntiLag,
				ANONIM_DF_AntiInvis = toggles and toggles.AntiInvis,
				ANONIM_DF_AutoReset = toggles and toggles.AutoReset,
				ANONIM_DF_LoopTP = toggles and toggles.LoopTP,
			}
			for flag, el in pairs(dfMap) do
				if el then
					Library.Items[flag] = kzWrapItem(el)
				end
			end
		end)

		local function kzInfo(cfg, map)
			local out = {}
			if type(cfg) == "table" then
				for k, v in pairs(cfg) do
					out[map[k] or k] = v
				end
			end
			return out
		end

		local function kzRegister(flag, element)
			if flag and element then
				Library.Items[flag] = kzWrapItem(element)
			end
			return element
		end

		local function kzLabel(lbl, initialText)
			local inner = Instance.new("TextLabel")
			inner.Text = tostring(initialText or (lbl and lbl.Text) or "")
			local f = Instance.new("Frame")
			inner.Parent = f
			inner:GetPropertyChangedSignal("Text"):Connect(function()
				if lbl and lbl.SetText then
					pcall(function()
						lbl:SetText(inner.Text)
					end)
				end
			end)
			return f
		end

		local kzIdCounter = 0
		local function kzNextFlag(prefix, c)
			if type(c) == "table" and type(c.Flag) == "string" and c.Flag ~= "" then
				return c.Flag
			end
			kzIdCounter += 1
			local base = (type(c) == "table" and (c.Name or c.Text)) or prefix
			return tostring(base) .. "_" .. tostring(kzIdCounter)
		end

		local function kzCreateBlock(targetTab, opts)
			opts = type(opts) == "table" and opts or { Name = tostring(opts or "Block") }
			local name = opts.Name or opts.Text or "Toy Builds"
			local side = string.lower(tostring(opts.Side or "left"))
			local icon = opts.Icon or "bot"
			if icon == "bot" then
				icon = "blocks"
			end
			local tabObj = targetTab or tbl15.ToysBuilds or tbl15.Toys
			local box
			if side == "right" then
				box = tabObj:AddRightGroupbox(name, icon)
			else
				box = tabObj:AddLeftGroupbox(name, icon)
			end
			local B = { _box = box }

			function B:CreateToggle(c)
				local flag = kzNextFlag("Toggle", c)
				local t = box:AddToggle(flag, kzInfo(c, {
					Name = "Text",
					Default = "Default",
					Callback = "Callback",
					Tooltip = "Tooltip",
				}))
				return kzRegister(c and c.Flag, t)
			end

			function B:CreateSlider(c)
				local flag = kzNextFlag("Slider", c)
				local s = box:AddSlider(flag, kzInfo(c, {
					Name = "Text",
					Default = "Default",
					Min = "Min",
					Max = "Max",
					Rounding = "Rounding",
					Callback = "Callback",
					Tooltip = "Tooltip",
					Suffix = "Suffix",
				}))
				return kzRegister(c and c.Flag, s)
			end

			function B:CreateDropdown(c)
				local flag = kzNextFlag("Dropdown", c)
				local info = kzInfo(c, {
					Name = "Text",
					Options = "Values",
					Items = "Values",
					Values = "Values",
					Default = "Default",
					Multi = "Multi",
					Callback = "Callback",
					Tooltip = "Tooltip",
				})
				local d = box:AddDropdown(flag, info)
				if type(c) == "table" and type(c.UpdateList) == "function" then
					-- KOZMOZ FIX: player lists (Follow Target / Target ...) are now
					-- refreshed on join, on leave AND on a slow heartbeat, and the
					-- dropdown is only rewritten when the list really changed.
					-- Before, a dropdown built while the server was still loading
					-- stayed stuck on "Me" until somebody joined.
					local lastSig = nil
					local function refreshValues()
						if flag11 then return end
						local ok, list = pcall(c.UpdateList)
						if not (ok and type(list) == "table" and d and d.SetValues) then return end
						local sig = table.concat(list, "|")
						if sig == lastSig then return end
						lastSig = sig
						pcall(function() d:SetValues(list) end)
					end
					local c1 = kzPlayers.PlayerAdded:Connect(function()
						task.defer(refreshValues)
					end)
					local c2 = kzPlayers.PlayerRemoving:Connect(function()
						task.delay(0.5, refreshValues)
					end)
					task.spawn(function()
						task.wait(0.5)
						while not flag11 do
							pcall(refreshValues)
							task.wait(2)
						end
					end)
					lib:OnUnload(function()
						pcall(function() c1:Disconnect() end)
						pcall(function() c2:Disconnect() end)
					end)
				end
				return kzRegister(c and c.Flag, d)
			end

			function B:CreateButton(c)
				return box:AddButton(kzInfo(c, {
					Name = "Text",
					Callback = "Func",
					Tooltip = "Tooltip",
				}))
			end

			function B:CreateLabel(c)
				local text = type(c) == "table" and (c.Text or c.Name) or tostring(c or "")
				local l = box:AddLabel(text, true)
				return kzLabel(l, text)
			end

			function B:CreateDivider(c)
				return box:AddDivider(c)
			end

			function B:CreateKeybind(c)
				local name = (type(c) == "table" and (c.Name or c.Text)) or "Keybind"
				local flag = kzNextFlag("Keybind", c)
				local def = type(c) == "table" and c.Default or "None"
				if type(def) == "table" then
					def = def.Name or "None"
				end
				if def == nil or def == "" then
					def = "None"
				end
				local lbl = box:AddLabel(name)
				lbl:AddKeyPicker(flag, {
					Text = name,
					Default = def,
					Mode = "Press",
					NoUI = false,
					Callback = type(c) == "table" and c.Callback or nil,
					ChangedCallback = type(c) == "table" and c.ChangedCallback or nil,
				})
				local kp = (options and options[flag]) or lbl
				return kzRegister(c and c.Flag, kp)
			end
			B.CreateKeyPicker = B.CreateKeybind

			return B
		end

		local function ANONIM_MakeTabbox(Block, tabs, opts)
			local box = Block and Block._box
			if not box or not box.Container or type(tabs) ~= "table" or #tabs == 0 then
				return nil
			end
			local pages = {}
			local buttons = {}
			local activeKey = (opts and opts.Active) or (tabs[1] and tabs[1].Key) or "Robot"
			local TB
			local iconMap = {
				Robot = "bot",
				Pet = "dog",
				Slap = "hand",
			}

			local function updateTabVisuals()
				pcall(function()
					for key, btn in pairs(buttons) do
						local isAct = (TB and TB.Active == key)
						if btn.Label then
							btn.Label.TextColor3 = isAct and lib.Scheme.AccentColor or lib.Scheme.FontColor
							btn.Label.TextTransparency = isAct and 0 or 0.35
							if lib.Registry and lib.Registry[btn.Label] then
								lib.Registry[btn.Label].TextColor3 = isAct and "AccentColor" or "FontColor"
							end
						end
						if btn.IconImage then
							btn.IconImage.ImageColor3 = isAct and lib.Scheme.AccentColor or lib.Scheme.FontColor
							btn.IconImage.ImageTransparency = isAct and 0 or 0.35
							if lib.Registry and lib.Registry[btn.IconImage] then
								lib.Registry[btn.IconImage].ImageColor3 = isAct and "AccentColor" or "FontColor"
							end
						end
						if btn.Stroke then
							btn.Stroke.Color = isAct and lib.Scheme.AccentColor or lib.Scheme.OutlineColor
							if lib.Registry and lib.Registry[btn.Stroke] then
								lib.Registry[btn.Stroke].Color = isAct and "AccentColor" or "OutlineColor"
							end
						end
					end
				end)
			end

			local mainBtn = nil
			for i, tabInfo in ipairs(tabs) do
				local key = tabInfo.Key or tostring(i)
				local label = tabInfo.Label or tabInfo.Title or key
				pages[key] = {}
				local btnSpec = {
					Text = label,
					Icon = iconMap[key],
					Func = function()
						if TB and TB.Select then
							TB.Select(key)
						end
					end,
				}
				local btn
				if not mainBtn then
					mainBtn = box:AddButton(btnSpec)
					btn = mainBtn
				else
					btn = mainBtn:AddButton(btnSpec)
				end
				buttons[key] = btn
				if btn and btn.Base then
					btn.Base.MouseLeave:Connect(function()
						task.defer(updateTabVisuals)
					end)
				end
			end
			box:AddDivider()

			TB = {
				Cont = box.Container,
				Pages = pages,
				Active = activeKey,
				Buttons = buttons,
				Select = function(key)
					if not key or not pages[key] then return end
					TB.Active = key
					updateTabVisuals()
					task.defer(function()
						pcall(function() box:Resize() end)
					end)
				end,
				Proxy = function(key)
					pages[key] = pages[key] or {}
					return Block
				end,
				SetBlockIcon = function() end,
			}
			updateTabVisuals()
			return TB
		end

		local Tabs = {
			Toy = {
				CreateBlock = function(_, opts)
					return kzCreateBlock(tbl15.ToysBuilds or tbl15.Toys, opts)
				end,
			},
			Defense = {
				CreateBlock = function(_, opts)
					return kzCreateBlock(tbl15.ToysBuilds or tbl15.Invincibility, opts)
				end,
			},
		}

		local function ANONIM_IsWL(p)
			if not p then return false end
			local ok, res = pcall(function()
				return tbl12.IsProtectedPlayer(p, true)
			end)
			return ok and res == true
		end

		-- KOZMOZ FIX: target dropdowns (Pet / Robot / Slap ...) used to hide every
		-- player that was flagged as whitelisted, so the list often showed nothing
		-- but "Me". Now every other player in the server is listed.
		local ANONIM_ShowAllTargets = true

		local ANONIM_MobileActions = {}
		local ANONIM_MobileBtnAPI = {
			Buttons = {},
			Short = {},
			Create = function(name)
				local existing = ANONIM_MobileBtnAPI.Buttons and ANONIM_MobileBtnAPI.Buttons[name]
				if existing and existing.Parent then
					return existing
				end
				if type(lib) == "table" and type(lib.AddDraggableButton) == "function" then
					local ok, drag = pcall(function()
						return lib:AddDraggableButton(name, function()
							local fn = ANONIM_MobileActions and ANONIM_MobileActions[name]
							if type(fn) == "function" then
								pcall(fn)
							end
						end)
					end)
					local btn = ok and drag and (drag.Button or drag)
					if btn then
						ANONIM_MobileBtnAPI.Buttons[name] = btn
						return btn
					end
				end
				return nil
			end,
		}

		local function ParseTarget(v)
			if type(v) == "string" and v ~= "Me" and v ~= "None" and v ~= "" then
				return v:match("%(@([^%)]+)%)$") or v
			end
			return nil
		end

		local kzRT = {}
		kzRT.Char = function(p)
			return tbl12.Char(p)
		end
		kzRT.ResetVelocity = function(part)
			return tbl12.ResetVelocity(part)
		end
		kzRT.FindNicePart = function(model)
			return tbl12.FindNicePart(model)
		end
		kzRT.BreakHoldable = function(model, ...)
			return tbl12.BreakHoldable(model, ...)
		end
		kzRT.IsPartOwner = function(part)
			if not (part and part.Parent and part:IsA("BasePart")) then
				return false
			end
			local ok, res = pcall(tbl12.IsPartOwner, part)
			if ok and res == true then
				return true
			end
			local po = part:FindFirstChild("PartOwner") or (part.Parent and part.Parent:FindFirstChild("PartOwner", true))
			if po and po.Value == kzLocalPlayer.Name then
				return true
			end
			local rp = part.AssemblyRootPart or part
			if rp and not rp.Anchored and rp.ReceiveAge == 0 then
				return true
			end
			return false
		end
		kzRT.Grab = function(part, cf, isPlotClaim)
			if not (part and part.Parent and part:IsA("BasePart")) then
				return false
			end
			pcall(function()
				if tbl11 and tbl11.CreateGrabLine then
					tbl11.CreateGrabLine:FireServer(part, part.CFrame)
				end
			end)
			pcall(function()
				local _, hrp = tbl12.Char()
				local cam = workspace.CurrentCamera
				local sendCF = cf or (hrp and (hrp.CFrame * CFrame.new(0, 1.593, 0))) or (cam and cam.CFrame) or part.CFrame
				if tbl11 and tbl11.SetNetworkOwner then
					tbl11.SetNetworkOwner:FireServer(part, sendCF)
				end
			end)
			pcall(tbl12.Grab, part, cf)
			return true
		end
		kzRT.SNO = function(part, timeout, checkFn)
			if not (part and part.Parent and part:IsA("BasePart")) then
				return false
			end
			if kzRT.IsPartOwner(part) then
				return true
			end
			kzRT.Grab(part)
			local ok, res = pcall(tbl12.SNO, part, timeout or 0.5, checkFn)
			if ok and res == true then
				return true
			end
			if kzRT.IsPartOwner(part) then
				return true
			end
			local t0 = tick()
			local limit = math.min(tonumber(timeout) or 0.4, 0.5)
			while part.Parent and tick() - t0 < limit and not flag11 do
				kzRT.Grab(part)
				if kzRT.IsPartOwner(part) then
					return true
				end
				game:GetService("RunService").Heartbeat:Wait()
			end
			return part.Parent ~= nil
		end
		kzRT.SpawnToy = function(toyName, cf, priority, reserve)
			if type(toyName) ~= "string" or toyName == "" then
				return nil
			end
			pcall(function()
				local plots = workspace:FindFirstChild("Plots")
				if plots then
					for _, pl in ipairs(plots:GetChildren()) do
						local barrier = pl:FindFirstChild("Barrier")
						if barrier then
							for _, bp in ipairs(barrier:GetChildren()) do
								if bp:IsA("BasePart") and bp.Name == "PlotBarrier" then
									bp.CanCollide = false
								end
							end
						end
					end
				end
			end)
			pcall(function()
				if tbl7 and tbl7.FailedToys then
					tbl7.FailedToys[toyName] = nil
				end
			end)
			local okSpawn, spawned = pcall(tbl12.SpawnToy, toyName, cf, priority or 1, reserve ~= false)
			if okSpawn and spawned and spawned.Parent then
				pcall(function()
					if tbl7 and tbl7.ToyAuraReserved then
						tbl7.ToyAuraReserved[spawned] = true
					end
				end)
				return spawned
			end
			local _, hrp = tbl12.Char()
			if not hrp then
				return nil
			end
			local canSpawn = kzLocalPlayer:FindFirstChild("CanSpawnToy")
			if canSpawn and not canSpawn.Value then
				local w0 = tick()
				while not canSpawn.Value and tick() - w0 < 3.5 and not flag11 do
					game:GetService("RunService").Heartbeat:Wait()
				end
			end
			local inv = workspace:FindFirstChild(kzLocalPlayer.Name .. "SpawnedInToys")
			local ownedPlot = tbl12.OwnedPlot and tbl12.OwnedPlot(kzLocalPlayer)
			local plotItems = workspace:FindFirstChild("PlotItems")
			local myPlotFolder = ownedPlot and plotItems and plotItems:FindFirstChild(ownedPlot.Name)
			local inOwned = kzLocalPlayer:FindFirstChild("InOwnedPlot")
			local spawnCF = cf
			if not spawnCF then
				if inOwned and inOwned.Value and ownedPlot and ownedPlot:FindFirstChild("PlotArea") then
					local pa = ownedPlot.PlotArea
					local rel = pa.CFrame:PointToObjectSpace(hrp.Position + hrp.CFrame.LookVector * 4)
					local hx, hz = pa.Size.X * 0.35, pa.Size.Z * 0.35
					spawnCF = CFrame.new((pa.CFrame * CFrame.new(math.clamp(rel.X, -hx, hx), 3.5, math.clamp(rel.Z, -hz, hz))).Position)
				else
					spawnCF = CFrame.new(hrp.Position + Vector3.new(0, 15, 20))
				end
			end
			local rot = workspace:FindFirstChild("RotateOrientPart") and workspace.RotateOrientPart.Rotation or Vector3.zero
			local found = nil
			local c1, c2
			local function onChild(ch)
				if ch.Name == toyName and not found then
					found = ch
					pcall(function()
						if tbl7 and tbl7.ToyAuraReserved then
							tbl7.ToyAuraReserved[ch] = true
						end
					end)
				end
			end
			if inv then c1 = inv.ChildAdded:Connect(onChild) end
			if myPlotFolder then c2 = myPlotFolder.ChildAdded:Connect(onChild) end
			task.spawn(function()
				pcall(function()
					tbl11.SpawnToy:InvokeServer(toyName, spawnCF, rot)
				end)
			end)
			local t0 = tick()
			while not found and tick() - t0 < 2.0 and not flag11 do
				game:GetService("RunService").Heartbeat:Wait()
			end
			if c1 then c1:Disconnect() end
			if c2 then c2:Disconnect() end
			return found
		end
		kzRT.DestroyToy = function(model)
			if not model then return end
			pcall(function()
				if tbl7 and tbl7.ToyAuraReserved then
					tbl7.ToyAuraReserved[model] = nil
				end
			end)
			pcall(tbl12.DestroyToy, model)
		end
		setmetatable(kzRT, { __index = tbl12 })
		kzRT.RT = kzRT
		local ANONIM_ToysShared = kzRT
		pcall(function() _G.ANONIM_ToysShared = kzRT end)

		_G.ANONIM_UNLOADED = false
		lib:OnUnload(function()
			_G.ANONIM_UNLOADED = true
		end)

do
    local okPB, errPB = pcall(function()
        local Players = game:GetService("Players")
        local RunService = game:GetService("RunService")
        local ReplicatedStorage = game:GetService("ReplicatedStorage")
        local LP = Players.LocalPlayer

        local UP = Vector3.new(0, 1, 0)
        local DEFAULT_TOY = "PalletLightBrown"
        local PB = {Builds = {}, ExtraToys = {}}
        local AO = {Enabled = false, Flags = {}, Syncing = false, Label = nil}

        local function Shared()
            local s = ANONIM_ToysShared
            return s and s.RT
        end
        local function CharParts()
            local RT = Shared()
            if not RT then return nil, nil, nil end
            return RT.Char()
        end
        local function UNL()
            return _G.ANONIM_UNLOADED == true
        end
        local function Notify(title, text, dur)
            pcall(function()
                Library:Notify({Title = title, Content = text, Duration = dur or 3})
            end)
        end

        local function PlotsFolder()
            return workspace:FindFirstChild("Plots")
        end

        local function PlotOwners(plot)
            local sign = plot and plot:FindFirstChild("PlotSign")
            return sign and sign:FindFirstChild("ThisPlotsOwners")
        end

        local function MyPlot()
            local plots = PlotsFolder()
            if not plots then return nil end
            for _, plot in ipairs(plots:GetChildren()) do
                local owners = PlotOwners(plot)
                if owners then
                    for _, v in ipairs(owners:GetChildren()) do
                        if v:IsA("StringValue") and v.Value == LP.Name then
                            return plot
                        end
                    end
                end
            end
            return nil
        end

        local function PlusPart(plot)
            local sign = plot and plot:FindFirstChild("PlotSign")
            local s2 = sign and sign:FindFirstChild("Sign")
            local plus = s2 and s2:FindFirstChild("Plus")
            return plus and plus:FindFirstChild("PlusGrabPart")
        end

        local function PlotHasOwner(plot)
            local owners = PlotOwners(plot)
            if not owners then return true end
            for _, v in ipairs(owners:GetChildren()) do
                if v:IsA("StringValue") and v.Value ~= "" then
                    return true
                end
            end
            return false
        end

        local function PlotOccupied(plot)
            local area = plot:FindFirstChild("PlotArea")
            if not area then return false end
            local ok, parts = pcall(function() return workspace:GetPartsInPart(area) end)
            if not ok or not parts then return false end
            for _, p in ipairs(parts) do
                local pl = Players:GetPlayerFromCharacter(p.Parent)
                if pl and pl ~= LP then return true end
            end
            return false
        end

        local function FindEmptyPlot()
            local plots = PlotsFolder()
            if not plots then return nil end
            local RT = Shared()
            local _, root = CharParts()
            local best, bestD = nil, math.huge
            for _, plot in ipairs(plots:GetChildren()) do
                local plus = PlusPart(plot)
                if plus and not PlotHasOwner(plot) and not PlotOccupied(plot) then
                    local d = root and (root.Position - plus.Position).Magnitude or 0
                    if d < bestD then
                        best, bestD = plot, d
                    end
                end
            end
            return best
        end

        local function Teleport(cf)
            local RT = Shared()
            local _, root = CharParts()
            if not root then return false end
            root.AssemblyLinearVelocity = Vector3.zero
            root.CFrame = cf
            return true
        end

        local function ClaimPlot(plot)
            local RT = Shared()
            local plus = PlusPart(plot)
            if not (RT and plus) then return false end
            Teleport(CFrame.new(plus.Position + Vector3.new(0, 4, 0)))
            task.wait(0.25)
            local t0 = tick()
            while tick() - t0 < 4 and not UNL() do
                if MyPlot() == plot then return true end
                if PlotHasOwner(plot) then break end
                pcall(RT.Grab, plus, nil, true)
                RunService.Heartbeat:Wait()
            end
            return MyPlot() == plot
        end

        local function InOwnedPlot()
            local v = LP:FindFirstChild("InOwnedPlot")
            return v and v.Value == true
        end

        local function GoInside(plot)
            local RT = Shared()
            local char, root = CharParts()
            local area = plot and plot:FindFirstChild("PlotArea")
            if not (root and area) then return false end
            local params = RaycastParams.new()
            params.FilterType = Enum.RaycastFilterType.Exclude
            params.FilterDescendantsInstances = {char, area}
            local origin = area.Position + Vector3.new(0, 2, 0)
            local hit = workspace:Raycast(origin, Vector3.new(0, -(area.Size.Y + 60), 0), params)
            local pos = hit and (hit.Position + Vector3.new(0, 3.5, 0)) or area.Position
            Teleport(CFrame.new(pos))
            local t0 = tick()
            repeat task.wait(0.1) until InOwnedPlot() or tick() - t0 > 3 or UNL()
            if not InOwnedPlot() then
                Teleport(CFrame.new(area.Position))
                t0 = tick()
                repeat task.wait(0.1) until InOwnedPlot() or tick() - t0 > 2 or UNL()
            end
            return InOwnedPlot()
        end

        AO.Interval = 60
        AO.LastInside = os.clock()
        AO.Busy = false
        AO.HasPass = nil
        task.spawn(function()
            local MPS = game:GetService("MarketplaceService")
            for _ = 1, 3 do
                local ok, owns = pcall(function() return MPS:UserOwnsGamePassAsync(LP.UserId, 51538260) end)
                if ok then
                    AO.HasPass = owns and true or false
                    return
                end
                task.wait(3)
            end
            AO.HasPass = false
        end)
        AO.Set = function(v, src)
            v = v and true or false
            AO.Enabled = v
            AO.LastInside = os.clock()
            if AO.Syncing then return end
            AO.Syncing = true
            for _, f in ipairs(AO.Flags) do
                if f ~= src then
                    local item = Library.Items and Library.Items[f]
                    if item and item.Set then pcall(item.Set, v) end
                end
            end
            AO.Syncing = false
        end
        AO.Status = function(text)
            if not AO.Label then return end
            for _, d in ipairs(AO.Label:GetDescendants()) do
                if d:IsA("TextLabel") then
                    if d.Text ~= "Status: " .. text then d.Text = "Status: " .. text end
                    break
                end
            end
        end
        AO.Refresh = function(plot)
            local _, root, hum = CharParts()
            if not (root and hum and hum.Health > 0) then return end
            local back = root.CFrame
            GoInside(plot)
            task.wait(0.3)
            Teleport(back)
        end
        AO.Tick = function()
            local now = os.clock()
            if not AO.Enabled then
                AO.LastInside = now
                AO.Status("Off")
                return
            end
            if AO.HasPass then
                AO.LastInside = now
                AO.Status("Infinite House Time gamepass (not needed)")
                return
            end
            local plot = MyPlot()
            if not plot then
                AO.LastInside = now
                AO.Status("No house owned")
                return
            end
            if InOwnedPlot() then
                AO.LastInside = now
                AO.Status("In house")
                return
            end
            local out = now - AO.LastInside
            if out >= AO.Interval and not AO.Busy then
                AO.Busy = true
                AO.Status("Refreshing house...")
                pcall(AO.Refresh, plot)
                AO.Busy = false
                AO.LastInside = os.clock()
            else
                AO.Status(string.format("Outside %ds / %ds", math.floor(out), math.floor(AO.Interval)))
            end
        end
        task.spawn(function()
            while not UNL() do
                task.wait(0.5)
                pcall(AO.Tick)
            end
        end)

        local function ComputeAlign(model, rootPart)
            local inv = rootPart.CFrame:Inverse()
            local minV = Vector3.new(math.huge, math.huge, math.huge)
            local maxV = -minV
            for _, p in ipairs(model:GetDescendants()) do
                if p:IsA("BasePart") then
                    local h = p.Size / 2
                    for _, sx in ipairs({-1, 1}) do
                        for _, sy in ipairs({-1, 1}) do
                            for _, sz in ipairs({-1, 1}) do
                                local c = inv * (p.CFrame * Vector3.new(h.X * sx, h.Y * sy, h.Z * sz))
                                minV = minV:Min(c)
                                maxV = maxV:Max(c)
                            end
                        end
                    end
                end
            end
            local size = maxV - minV
            local center = (maxV + minV) / 2
            local dims = {size.X, size.Y, size.Z}
            local order = {1, 2, 3}
            table.sort(order, function(a, b) return dims[a] > dims[b] end)
            local L, M, T = order[1], order[2], order[3]
            local cols = {}
            cols[L] = Vector3.new(0, 1, 0)
            cols[M] = Vector3.new(1, 0, 0)
            cols[T] = Vector3.new(0, 0, 1)
            if cols[1]:Dot(cols[2]:Cross(cols[3])) < 0 then
                cols[M] = -cols[M]
            end
            local rot = CFrame.fromMatrix(Vector3.zero, cols[1], cols[2], cols[3])
            return rot * CFrame.new(-center), (dims[L] + dims[M]) / 2, dims[T]
        end

        local function ListToys()
            local names, seen = {DEFAULT_TOY}, {[DEFAULT_TOY] = true}
            local function add(n)
                if type(n) == "string" and not seen[n] and n:match("^%u[%w]+$") then
                    seen[n] = true
                    names[#names + 1] = n
                end
            end
            pcall(function()
                local gui = LP:FindFirstChild("PlayerGui")
                local menu = gui and gui:FindFirstChild("MenuGui")
                if menu then
                    for _, d in ipairs(menu:GetDescendants()) do
                        if d.Name == "ViewItemButton" and d.Parent then add(d.Parent.Name) end
                    end
                end
            end)
            pcall(function()
                local inv = workspace:FindFirstChild(LP.Name .. "SpawnedInToys")
                if inv then
                    for _, m in ipairs(inv:GetChildren()) do add(m.Name) end
                end
            end)
            for n in pairs(PB.ExtraToys) do add(n) end
            local first = table.remove(names, 1)
            table.sort(names)
            table.insert(names, 1, first)
            return names
        end

        local function FrameCF(center, yAxis, zAxis)
            local y = yAxis.Magnitude > 1e-4 and yAxis.Unit or UP
            local z = zAxis - y * zAxis:Dot(y)
            if z.Magnitude < 1e-4 then
                z = Vector3.new(1, 0, 0) - y * y.X
                if z.Magnitude < 1e-4 then z = Vector3.new(0, 0, 1) - y * y.Z end
            end
            z = z.Unit
            return CFrame.fromMatrix(center, y:Cross(z), y, z)
        end

        local function SegCF(a, b)
            local d = b - a
            local n = d:Cross(UP)
            if n.Magnitude < 1e-3 then n = Vector3.new(1, 0, 0) end
            return FrameCF((a + b) / 2, d, n)
        end

        local function FlatLook(cf)
            local lv = cf.LookVector
            local f = Vector3.new(lv.X, 0, lv.Z)
            if f.Magnitude < 1e-3 then return Vector3.new(0, 0, -1) end
            return f.Unit
        end

        local function GroundY(pos, exclude, fallback)
            local params = RaycastParams.new()
            params.FilterType = Enum.RaycastFilterType.Exclude
            params.FilterDescendantsInstances = exclude
            local hit = workspace:Raycast(pos + Vector3.new(0, 4, 0), Vector3.new(0, -80, 0), params)
            return hit and hit.Position.Y or fallback
        end

        local function Count(b) return b.Def.Count(b) end
        local function ToyFor(b, i)
            return b.ToyName or DEFAULT_TOY
        end

        local function CountSlots(b)
            local n = 0
            for i = 1, Count(b) do
                local s = b.Slots[i]
                if s and s.Model and s.Model.Parent then n = n + 1 end
            end
            return n
        end

        local function UpdateLabel(b, extra)
            if not b.Label then return end
            local text = tostring(CountSlots(b)) .. "/" .. tostring(Count(b)) .. " toys"
            if extra then text = text .. " | " .. extra end
            for _, d in ipairs(b.Label:GetDescendants()) do
                if d:IsA("TextLabel") then
                    d.Text = text
                    break
                end
            end
        end

        local function DestroyAll(b)
            local RT = Shared()
            for i, s in pairs(b.Slots) do
                if s and s.Model and RT and not s.Foreign then pcall(RT.DestroyToy, s.Model) end
                b.Slots[i] = nil
            end
            table.clear(b.Acq)
            if b.Def.Reset then pcall(b.Def.Reset, b) end
            UpdateLabel(b)
        end

        local function StopLoop(b)
            if b.Conn then
                pcall(function() b.Conn:Disconnect() end)
                b.Conn = nil
            end
        end

        local function TargetLabel(p)
            -- KOZMOZ FIX: never return nil, fall back to UserId when names are missing
            local dn = tostring(p.DisplayName or "")
            local un = tostring(p.Name or "")
            if un == "" then un = "Player" .. tostring(p.UserId or "?") end
            if dn == "" then dn = un end
            return dn .. " (@" .. un .. ")"
        end
        local function ListTargets()
            -- KOZMOZ FIX: list EVERY player except yourself (no whitelist filter),
            -- sorted alphabetically so the list is stable between refreshes.
            local out = {"Me"}
            local rows = {}
            for _, p in ipairs(Players:GetPlayers()) do
                if p ~= LP and p.Parent then
                    rows[#rows + 1] = p
                end
            end
            table.sort(rows, function(a, b)
                local an = tostring(a.Name or ""):lower()
                local bn = tostring(b.Name or ""):lower()
                if an == bn then return tostring(a.DisplayName or "") < tostring(b.DisplayName or "") end
                return an < bn
            end)
            for _, p in ipairs(rows) do
                local ok, label = pcall(TargetLabel, p)
                if ok and type(label) == "string" and #label > 0 then
                    out[#out + 1] = label
                end
            end
            return out
        end
        local function ResetTarget(b, msg)
            b.Target = nil
            if b.Def.Reset then pcall(b.Def.Reset, b) end
            if msg then Notify(b.Name, msg, 3) end
            local flag = b.TargetFlag
            task.spawn(function()
                local item = flag and Library.Items and Library.Items[flag]
                if item and item.Set then pcall(item.Set, "Me") end
            end)
        end
        local function FollowParts(b, myChar, myRoot, myHum)
            local name = b.Target
            if not name then return myChar, myRoot, myHum end
            local p = Players:FindFirstChild(name)
            if not (p and p:IsA("Player")) then
                ResetTarget(b, "Target left the game. Following you again.")
                return myChar, myRoot, myHum
            end
            -- KOZMOZ FIX: following a whitelisted player is allowed again.
            if ANONIM_ShowAllTargets ~= true and ANONIM_IsWL and ANONIM_IsWL(p) then
                ResetTarget(b, "Target is whitelisted. Following you again.")
                return myChar, myRoot, myHum
            end
            local c = p.Character
            local r = c and c:FindFirstChild("HumanoidRootPart")
            local h = c and c:FindFirstChildOfClass("Humanoid")
            if r and h and h.Health > 0 then return c, r, h end
            return nil
        end

        local function RepairWanted(b)
            return b.AutoRepair == true or (b.Outside and b.AutoRepair ~= false)
        end

        local function Step(b, dt)
            if UNL() or not b.Enabled then return end
            local RT = Shared()
            if not RT then return end
            local char, root, hum = RT.Char()
            if not (char and root and hum and hum.Health > 0) then return end
            local myPos = root.Position
            char, root, hum = FollowParts(b, char, root, hum)
            if not char then return end
            local ctx = b.Def.Frame(b, char, root, hum, dt)
            if not ctx then return end
            for i = 1, Count(b) do
                local s = b.Slots[i]
                if s and s.Model and s.Model.Parent and s.Root and s.Root.Parent then
                    if RT.IsPartOwner(s.Owner) then
                        s.LostT = nil
                        local cf = b.Def.Place(b, i, ctx)
                        if cf then
                            s.Root.CFrame = cf * s.Align
                            RT.ResetVelocity(s.Root)
                            if b.Def.SafeSelf and s.Solid and s.Parts then
                                local near = (s.Root.Position - myPos).Magnitude < b.Unit * 1.6 + 6
                                if near ~= s.NoCol then
                                    s.NoCol = near
                                    for _, pp in ipairs(s.Parts) do pp.CanCollide = not near end
                                end
                            end
                            if b.Def.Vel then
                                local v = b.Def.Vel(b, i, ctx)
                                if v then s.Root.AssemblyLinearVelocity = v end
                            end
                        end
                    else
                        local lost = false
                        if RepairWanted(b) then
                            s.LostT = s.LostT or os.clock()
                            if os.clock() - s.LostT > 1.5 then
                                lost = true
                                b.Slots[i] = nil
                                b.NeedFill = true
                                if not s.Foreign then
                                    local m = s.Model
                                    task.spawn(function() pcall(RT.DestroyToy, m) end)
                                end
                            end
                        end
                        if not lost and not b.Acq[i] then
                            b.Acq[i] = true
                            task.spawn(function()
                                pcall(RT.SNO, s.Owner, 0.3)
                                b.Acq[i] = nil
                            end)
                        end
                    end
                elseif s then
                    b.Slots[i] = nil
                    if RepairWanted(b) then b.NeedFill = true end
                elseif b.AutoRepair then
                    b.NeedFill = true
                end
            end
            if RepairWanted(b) and b.NeedFill and not b.Building and PB.FillAsync and os.clock() >= (b.NextAuto or 0) then
                b.NeedFill = false
                b.NextAuto = os.clock() + (b.AutoRepair and 3 or 1)
                PB.FillAsync(b, true)
            end
        end

        local function StartLoop(b)
            StopLoop(b)
            b.Conn = RunService.Heartbeat:Connect(function(dt)
                local ok, err = pcall(Step, b, dt)
                if not ok then warn("[ANONIM] " .. b.Name .. ": " .. tostring(err)) end
            end)
        end

        local function PrepSlot(b, model, owner, index, name, foreign)
            local rootPart = owner.AssemblyRootPart or owner
            local solid = b.Def.Solid and b.Def.Solid(b, index)
            local parts = {}
            for _, p in ipairs(model:GetDescendants()) do
                if p:IsA("BasePart") then
                    p.CanCollide = solid and true or false
                    p.CanTouch = false
                    p.CanQuery = false
                    parts[#parts + 1] = p
                end
            end
            local align, unit, thick = ComputeAlign(model, rootPart)
            if not foreign then
                if unit and unit > 0.3 and unit < 40 then b.Unit = unit end
                if thick and thick > 0 and thick < 10 then b.Thick = thick end
            end
            return {Model = model, Owner = owner, Root = rootPart, Align = align, Toy = name,
                Parts = parts, Solid = solid and true or false, Foreign = foreign}
        end

        local function SpawnToy(b, gen, index)
            local RT = Shared()
            if not RT then return nil end
            local name = ToyFor(b, index)
            local model = RT.SpawnToy(name, nil, 1, true)
            if not model then return nil end
            if model:FindFirstChild("HoldPart") then
                pcall(RT.BreakHoldable, model)
            end
            local owner = model:FindFirstChild("SoundPart") or model:WaitForChild("SoundPart", 0.5) or RT.FindNicePart(model)
            if not owner or not RT.SNO(owner, 0.8) or gen ~= b.Gen or not b.Enabled then
                RT.DestroyToy(model)
                return nil
            end
            return PrepSlot(b, model, owner, index, name, false)
        end

        local function ToyLimit()
            if PB.Limit then return PB.Limit end
            local ok, owns = pcall(function()
                return game:GetService("MarketplaceService"):UserOwnsGamePassAsync(LP.UserId, 39635504)
            end)
            if ok then PB.Limit = owns and 200 or 100 end
            return PB.Limit or 100
        end
        local function InvCount()
            local inv = workspace:FindFirstChild(LP.Name .. "SpawnedInToys")
            return inv and #inv:GetChildren() or 0
        end
        local function PlotAreas()
            local out = {}
            local plots = PlotsFolder()
            if plots then
                for _, plot in ipairs(plots:GetChildren()) do
                    local ar = plot:FindFirstChild("PlotArea")
                    if ar and ar:IsA("BasePart") then out[#out + 1] = ar end
                end
            end
            return out
        end
        local function InAnyPlot(pos, areas)
            for _, ar in ipairs(areas) do
                local rel = ar.CFrame:PointToObjectSpace(pos)
                local h = ar.Size / 2
                if math.abs(rel.X) <= h.X and math.abs(rel.Z) <= h.Z and rel.Y > -h.Y - 10 and rel.Y < h.Y + 80 then
                    return true
                end
            end
            return false
        end
        local function MapCandidates(name)
            local used = {}
            for _, bb in ipairs(PB.Builds) do
                for _, sl in pairs(bb.Slots) do
                    if sl and sl.Model then used[sl.Model] = true end
                end
            end
            local myInv = workspace:FindFirstChild(LP.Name .. "SpawnedInToys")
            local areas = PlotAreas()
            local _, root = CharParts()
            local list = {}
            for _, m in ipairs(workspace:GetDescendants()) do
                if m.Name == name and m:IsA("Model") and not used[m] and m.Parent ~= myInv then
                    local okOwner = true
                    local folder = m.Parent
                    if folder and folder.Name:sub(-13) == "SpawnedInToys" then
                        local pl = Players:FindFirstChild(folder.Name:sub(1, -14))
                        if pl and ANONIM_IsWL and ANONIM_IsWL(pl) then okOwner = false end
                    end
                    if okOwner then
                        local part = m:FindFirstChild("SoundPart") or m.PrimaryPart or m:FindFirstChildWhichIsA("BasePart", true)
                        if part and not part.Anchored and not InAnyPlot(part.Position, areas) then
                            list[#list + 1] = {M = m, D = root and (part.Position - root.Position).Magnitude or 0}
                        end
                    end
                end
            end
            table.sort(list, function(x, y) return x.D < y.D end)
            return list
        end
        local function ClaimMapToy(b, gen, index)
            local RT = Shared()
            if not RT then return nil end
            local name = ToyFor(b, index)
            local now = os.clock()
            if not b.MapList or b.MapName ~= name or now - (b.MapListT or 0) > 3 then
                b.MapList, b.MapName, b.MapListT = MapCandidates(name), name, now
            end
            while #b.MapList > 0 do
                local m = table.remove(b.MapList, 1).M
                if m.Parent then
                    local owner = m:FindFirstChild("SoundPart") or RT.FindNicePart(m)
                    if owner and RT.SNO(owner, 0.8) then
                        if gen ~= b.Gen or not b.Enabled then return nil end
                        return PrepSlot(b, m, owner, index, name, true)
                    end
                end
            end
            return nil
        end

        local function Fill(b, gen, quiet)
            local fails, streak, made = 0, 0, 0
            for i = 1, Count(b) do
                if gen ~= b.Gen or not b.Enabled or UNL() then return end
                local s = b.Slots[i]
                if not (s and s.Model and s.Model.Parent) then
                    local slot = nil
                    while not slot and fails < 60 and gen == b.Gen and b.Enabled and not UNL() do
                        if b.UseMap and InvCount() >= ToyLimit() then
                            slot = ClaimMapToy(b, gen, i)
                            if not slot then
                                if not quiet then Notify(b.Name, "Toy limit full and no free " .. ToyFor(b, i) .. " on the map.", 4) end
                                return
                            end
                        else
                            slot = SpawnToy(b, gen, i)
                            if not slot and b.UseMap and streak >= 2 then
                                slot = ClaimMapToy(b, gen, i)
                            end
                        end
                        if not slot then
                            fails = fails + 1
                            streak = streak + 1
                            if made == 0 and streak >= 8 then
                                if not quiet then Notify(b.Name, "Could not spawn " .. ToyFor(b, i) .. ". Do you own this toy?", 5) end
                                return
                            end
                            task.wait(0.4)
                        end
                    end
                    if not slot then return end
                    if i > Count(b) or slot.Toy ~= ToyFor(b, i) then
                        if not slot.Foreign then pcall(Shared().DestroyToy, slot.Model) end
                        return
                    end
                    streak = 0
                    made = made + 1
                    b.Slots[i] = slot
                    UpdateLabel(b, "building")
                end
            end
        end

        local function FillAsync(b, quiet)
            if not b.Enabled or b.Building then return end
            b.Building = true
            local gen = b.Gen
            task.spawn(function()
                pcall(Fill, b, gen, quiet)
                if gen == b.Gen and b.Enabled then
                    local full = CountSlots(b) == Count(b)
                    UpdateLabel(b, full and "ready" or "incomplete")
                    if quiet and not full then
                        b.NeedFill = true
                        b.NextAuto = os.clock() + 5
                    end
                end
                b.Building = false
            end)
        end
        PB.FillAsync = FillAsync

        local function Reshape(b)
            local n = Count(b)
            local RT = Shared()
            local pools = {}
            for i, s in pairs(b.Slots) do
                if s and s.Model and s.Model.Parent then
                    pools[s.Toy] = pools[s.Toy] or {}
                    table.insert(pools[s.Toy], s)
                end
                b.Slots[i] = nil
            end
            table.clear(b.Acq)
            local missing = 0
            for i = 1, n do
                local pool = pools[ToyFor(b, i)]
                if pool and #pool > 0 then
                    b.Slots[i] = table.remove(pool)
                else
                    missing = missing + 1
                end
            end
            for _, pool in pairs(pools) do
                for _, s in ipairs(pool) do
                    if RT and not s.Foreign then pcall(RT.DestroyToy, s.Model) end
                end
            end
            if b.Def.Reset then pcall(b.Def.Reset, b) end
            UpdateLabel(b)
            if missing > 0 then FillAsync(b) end
        end

        local function EnsureHouse(b, gen)
            if not b.UseHouse or InOwnedPlot() then return end
            local plot = MyPlot()
            if not plot then
                UpdateLabel(b, "finding house")
                Notify(b.Name, "Searching for an empty house...", 2)
                local empty = FindEmptyPlot()
                if empty and ClaimPlot(empty) then
                    plot = empty
                    Notify(b.Name, "House claimed: " .. empty.Name, 3)
                elseif empty then
                    Notify(b.Name, "Could not claim the house, spawning here.", 4)
                else
                    Notify(b.Name, "No empty house found, spawning here.", 4)
                end
            end
            if plot and gen == b.Gen and b.Enabled then
                UpdateLabel(b, "entering house")
                if not GoInside(plot) then
                    Notify(b.Name, "Could not enter the house, spawning here.", 4)
                end
            end
        end

        local function Build(b)
            if b.Building then return end
            b.Building = true
            b.Gen = b.Gen + 1
            local gen = b.Gen
            task.spawn(function()
                local ok, err = pcall(function()
                    if not Shared() then
                        Notify(b.Name, "Toys system is not loaded.", 4)
                        return
                    end
                    if not CharParts() then return end
                    if PB.Preflight then PB.Preflight(b) end
                    EnsureHouse(b, gen)
                    if b.Outside then
                        local inPlot = LP:FindFirstChild("InPlot")
                        if inPlot and inPlot.Value then
                            Notify(b.Name, "Leave the house: this build is made outside.", 4)
                            UpdateLabel(b, "leave the house")
                            repeat task.wait(0.3) until not inPlot.Value or gen ~= b.Gen or not b.Enabled or UNL()
                        end
                    end
                    if gen ~= b.Gen or not b.Enabled then return end
                    if b.Def.Reset then pcall(b.Def.Reset, b) end
                    if b.Def.OnStart then pcall(b.Def.OnStart, b) end
                    UpdateLabel(b, "building")
                    StartLoop(b)
                    Fill(b, gen)
                    if gen == b.Gen and b.Enabled then
                        local n, total = CountSlots(b), Count(b)
                        UpdateLabel(b, n == total and "ready" or "incomplete")
                        if n == total then
                            Notify(b.Name, b.Name .. " is ready!", 3)
                        elseif n > 0 then
                            Notify(b.Name, "Built with " .. n .. "/" .. total .. " toys (toy limit or cooldown).", 5)
                        end
                    end
                end)
                if not ok then warn("[ANONIM] " .. b.Name .. " build: " .. tostring(err)) end
                b.Building = false
            end)
        end

        local function SetEnabled(b, v)
            b.ToggleTicket = (b.ToggleTicket or 0) + 1
            local ticket = b.ToggleTicket
            b.Enabled = v and true or false
            if b.Enabled then
                if b.UseHouse and not AO.Enabled and not AO.HasPass then
                    AO.Set(true)
                    Notify("Auto Owner", "Auto Owner enabled: your house will be kept.", 3)
                end
                if b.Building then
                    task.spawn(function()
                        while b.Building and b.Enabled and not UNL() and ticket == b.ToggleTicket do task.wait(0.05) end
                        if b.Enabled and not UNL() and ticket == b.ToggleTicket then Build(b) end
                    end)
                else
                    Build(b)
                end
            else
                b.Gen = b.Gen + 1
                StopLoop(b)
                DestroyAll(b)
            end
        end

        local function NewBuild(name, def, extra)
            local b = {Name = name, Def = def, Enabled = false, Building = false, Gen = 0,
                Slots = {}, Acq = {}, Conn = nil, Label = nil, UseHouse = true,
                Unit = 4.3, Thick = 0.5, ToyName = DEFAULT_TOY}
            for k, v in pairs(extra or {}) do b[k] = v end
            PB.Builds[#PB.Builds + 1] = b
            return b
        end

        local HALF_PI = math.pi / 2
        local ROT_FB = CFrame.new()
        local ROT_SIDE = CFrame.Angles(0, HALF_PI, 0)
        local ROT_TOP = CFrame.Angles(HALF_PI, 0, 0)
        local function Face(list, limb, x, y, z, nx, ny, nz)
            local rot = ROT_FB
            if nx ~= 0 then rot = ROT_SIDE elseif ny ~= 0 then rot = ROT_TOP end
            list[#list + 1] = {Limb = limb, Off = Vector3.new(x, y, z), N = Vector3.new(nx, ny, nz), Rot = rot}
        end

        local P3 = {}
        Face(P3, "Head", 0, 0, -0.5, 0, 0, -1)
        Face(P3, "Head", 0, 0, 0.5, 0, 0, 1)
        Face(P3, "Head", -0.5, 0, 0, -1, 0, 0)
        Face(P3, "Head", 0.5, 0, 0, 1, 0, 0)
        Face(P3, "Head", 0, 0.5, 0, 0, 1, 0)
        for _, y in ipairs({0.5, -0.5}) do
            for _, x in ipairs({-0.5, 0.5}) do
                Face(P3, "Torso", x, y, -0.5, 0, 0, -1)
                Face(P3, "Torso", x, y, 0.5, 0, 0, 1)
            end
            Face(P3, "Torso", -1, y, 0, -1, 0, 0)
            Face(P3, "Torso", 1, y, 0, 1, 0, 0)
        end
        Face(P3, "Torso", -0.5, 1, 0, 0, 1, 0)
        Face(P3, "Torso", 0.5, 1, 0, 0, 1, 0)
        for _, limb in ipairs({"Left Arm", "Right Arm", "Left Leg", "Right Leg"}) do
            for _, y in ipairs({0.5, -0.5}) do
                Face(P3, limb, 0, y, -0.5, 0, 0, -1)
                Face(P3, limb, 0, y, 0.5, 0, 0, 1)
                Face(P3, limb, -0.5, y, 0, -1, 0, 0)
                Face(P3, limb, 0.5, y, 0, 1, 0, 0)
            end
        end
local UX = {Limit = 100, LimitNext = 0}

        function UX.Text(label, text)
            if not label then return end
            for _, item in ipairs(label:GetDescendants()) do
                if item:IsA("TextLabel") then
                    if item.Text ~= text then item.Text = text end
                    break
                end
            end
        end
        function UX.Flag(flag, value)
            local item = Library.Items and Library.Items[flag]
            if item and item.Set then pcall(item.Set, value) end
        end
        function UX.Target(b)
            local c, r, h = CharParts()
            if not c then return nil, nil, nil end
            return FollowParts(b, c, r, h)
        end
        function UX.Params(b, char)
            local params = RaycastParams.new()
            params.FilterType = Enum.RaycastFilterType.Exclude
            pcall(function() params.RespectCanCollide = true end)
            local list = {}
            if char then list[#list + 1] = char end
            if LP.Character and LP.Character ~= char then list[#list + 1] = LP.Character end
            for _, build in ipairs(PB.Builds) do
                for _, slot in pairs(build.Slots) do
                    if slot and slot.Model and slot.Model.Parent then list[#list + 1] = slot.Model end
                end
            end
            params.FilterDescendantsInstances = list
            return params
        end
        function UX.Reconfigure(b)
            b.ConfigTicket = (b.ConfigTicket or 0) + 1
            local ticket = b.ConfigTicket
            if not b.Enabled then
                if b.Def.Prepare then b.Def.Prepare(b) end
                if b.Def.Reset then b.Def.Reset(b) end
                UpdateLabel(b)
                return
            end
            b.Gen = b.Gen + 1
            b.NeedFill = false
            task.spawn(function()
                while b.Building and b.Enabled and not UNL() and ticket == b.ConfigTicket do task.wait(0.05) end
                if UNL() or not b.Enabled or ticket ~= b.ConfigTicket then return end
                if b.Def.Prepare then b.Def.Prepare(b) end
                Reshape(b)
                if not b.Conn then StartLoop(b) end
                if b.AutoRepair then b.NeedFill, b.NextAuto = true, 0 end
            end)
        end
        function UX.GetLimit()
            if PB.Limit then UX.Limit = PB.Limit end
            if os.clock() >= UX.LimitNext then
                UX.LimitNext = os.clock() + 30
                task.spawn(function()
                    local ok, value = pcall(ToyLimit)
                    if ok and tonumber(value) then UX.Limit = value end
                end)
            end
            return UX.Limit
        end
        function UX.Available(b)
            local reserved, trackedInventory = 0, 0
            for _, other in ipairs(PB.Builds) do
                if other ~= b and other.Enabled then reserved = reserved + Count(other) end
                for _, slot in pairs(other.Slots) do
                    local model = slot and slot.Model
                    if model and model.Parent and model.Parent.Name == LP.Name .. "SpawnedInToys" then
                        trackedInventory = trackedInventory + 1
                    end
                end
            end
            local external = math.max(0, InvCount() - trackedInventory)
            return math.max(0, UX.GetLimit() - reserved - external)
        end
        function UX.Preflight(b)
            if b.Def.Prepare then b.Def.Prepare(b) end
            local available, needed = UX.Available(b), Count(b)
            if needed > available then
                Notify("Build Budget", b.Name .. " requests " .. needed .. " toys; estimated free budget is " .. available .. ". House rules may differ.", 5)
            end
        end
        PB.Preflight = UX.Preflight

        
        function UX.CollapseBudget()
            local content = UX.BudgetLabel and UX.BudgetLabel.Parent
            local frame = content and content.Parent
            local original = frame and frame:FindFirstChild("BlockHeader")
            if not original or not original:IsA("GuiButton") then return false end
            
            
            local header = original:Clone()
            if not header then return false end
            for _, child in ipairs(header:GetChildren()) do child:Destroy() end
            for _, child in ipairs(original:GetChildren()) do child.Parent = header end
            header.Name = "BlockHeader"
            original:Destroy()
            header.Parent = frame
            local separator = frame:FindFirstChild("BlockSep")
            local chevron = header:FindFirstChild("Chevron")
            local function apply(collapsed)
                frame:SetAttribute("Collapsed", collapsed)
                content.Visible = not collapsed
                if separator then separator.Visible = not collapsed end
                if chevron then chevron.Rotation = collapsed and -90 or 0 end
            end
            if UX.BudgetHeaderConn then UX.BudgetHeaderConn:Disconnect() end
            UX.BudgetHeaderConn = header.MouseButton1Click:Connect(function()
                if not UNL() then apply(frame:GetAttribute("Collapsed") ~= true) end
            end)
            apply(true)
            return true
        end

        function UX.BudgetUI()
            local B = Tabs.Toy:CreateBlock({Name = "Build Budget", Side = "Right", Icon = "layers"})
            UX.BudgetLabel = B:CreateLabel({Text = "Reserved: 0 / 100 toys"})
            B:CreateLabel({Text = "Estimated shared budget. House rules may differ."})
            B:CreateButton({Name = "Optimize Active Builds", Callback = function()
                for _, b in ipairs(PB.Builds) do
                    if b.Enabled and b.Def.Prepare then UX.Reconfigure(b) end
                end
                Notify("Build Budget", "Active layouts will be optimized for the current toy budget.", 3)
            end})
            pcall(UX.CollapseBudget)
            task.spawn(function()
                while not UNL() do
                    local reserved, existing = 0, 0
                    for _, b in ipairs(PB.Builds) do
                        if b.Enabled then reserved = reserved + Count(b) end
                        existing = existing + CountSlots(b)
                    end
                    local limit = UX.GetLimit()
                    UX.Text(UX.BudgetLabel, string.format("Reserved: %d / %d | Built: %d%s", reserved, limit, existing, reserved > limit and " | OVER BUDGET" or ""))
                    task.wait(0.5)
                end
                if UX.BudgetHeaderConn then UX.BudgetHeaderConn:Disconnect() UX.BudgetHeaderConn = nil end
            end)
        end

        
        local RG = {
            R6 = {"Head", "Torso", "Left Arm", "Right Arm", "Left Leg", "Right Leg"},
        }
        function RG.Layout()
            local out = {}
            for _, piece in ipairs(P3) do
                local copy = {}
                for k, v in pairs(piece) do copy[k] = v end
                out[#out + 1] = copy
            end
            return out
        end
        function RG.Prepare(b, char)
            b.Pieces = RG.Layout()
        end
        function RG.Reset(b)
            b.LastBase = nil
        end
        function RG.Live(b, char, root)
            local inverse, limbs = root.CFrame:Inverse(), {}
            for _, name in ipairs(RG.R6) do
                local part = char:FindFirstChild(name)
                if part and part:IsA("BasePart") then
                    limbs[name] = inverse * part.CFrame
                end
            end
            return limbs
        end
        function RG.Mirror(cf)
            local x,y,z,a,b,c,d,e,f,g,h,i = cf:GetComponents()
            return CFrame.fromMatrix(Vector3.new(-x,y,z), Vector3.new(a,-d,-g), Vector3.new(-b,e,h), Vector3.new(-c,f,i))
        end
        function RG.Base(b, root, char, scale, dt)
            local forward = FlatLook(root.CFrame)
            local right = forward:Cross(UP)
            local distance = b.Distance or 15
            local offset = right * distance
            if b.Placement == "Left" then offset = -right * distance
            elseif b.Placement == "Front" then offset = forward * distance
            elseif b.Placement == "Behind" then offset = -forward * distance
            elseif b.Placement == "Custom" then offset = Vector3.zero
            end
            local anchor = root.Position + offset
            local facing, offsetForward, offsetRight = forward, forward, right
            if b.Mode == "Mirror (Face Target)" then
                anchor, facing = root.Position + forward * (distance + 10), -forward
            elseif b.Mode == "Stay Here" then
                b.StayAnchor = b.StayAnchor or root.Position + offset
                b.StayAxis = b.StayAxis or forward
                anchor = b.StayAnchor
                offsetForward, offsetRight = b.StayAxis, b.StayAxis:Cross(UP)
                if b.LockFacing then b.StayLook = b.StayLook or forward facing = b.StayLook end
            end
            anchor = anchor + offsetRight * (b.OffsetX or 0) - offsetForward * (b.OffsetZ or 0)
            local y = anchor.Y + (scale - 1) * 3 + (b.OffsetY or 0)
            if b.GroundAlign then
                local ground = GroundY(anchor, UX.Params(b,char).FilterDescendantsInstances, anchor.Y - 3)
                y = ground + scale * 3 + (b.OffsetY or 0)
            end
            local pos = Vector3.new(anchor.X,y,anchor.Z)
            local base = CFrame.lookAt(pos,pos+facing)
            if b.LastBase then base = b.LastBase:Lerp(base, 1 - math.exp(-12 * dt)) end
            b.LastBase = base
            return base
        end

        local Robot = NewBuild("Pallet Robot", {
            Count = function(b) return #b.Pieces end,
            Prepare = RG.Prepare,
            Reset = RG.Reset,
            OnStart = function(b) RG.Prepare(b) end,
            Frame = function(b, char, root, hum, dt)
                dt = math.clamp(dt,0.001,0.1)
                local live = RG.Live(b,char,root)
                local scale = b.Unit * b.Size
                return {S=scale,Base=RG.Base(b,root,char,scale,dt),Limbs=live,Mirror=b.Mode=="Mirror (Face Target)"}
            end,
            Place = function(b,index,ctx)
                local piece = b.Pieces[index]
                local limb = piece and ctx.Limbs[piece.Limb]
                if not limb then return nil end
                local off = piece.Off or Vector3.zero
                local localCF = CFrame.new(limb.Position*ctx.S) * limb.Rotation
                    * CFrame.new(off*ctx.S-piece.N*(b.Thick/2)) * piece.Rot
                if ctx.Mirror then localCF = RG.Mirror(localCF) end
                return ctx.Base * localCF
            end,
        }, {Pieces=P3,Mode="Follow Me",Size=1,
            Distance=15,Side=15,Back=0,MirrorDist=25,Placement="Right",OffsetX=0,OffsetY=0,OffsetZ=0,
            LockFacing=true,GroundAlign=true,AutoRepair=true})

        local PET_COUNT = {Spider = 19, Dog = 15, Cat = 18, Rabbit = 17, Turtle = 15, Parrot = 14, Snake = 14,
            Butterfly = 11, Penguin = 13, Ghost = 8, Fish = 12}
        local PET_TYPES = {"Spider", "Dog", "Cat", "Rabbit", "Turtle", "Parrot", "Snake",
            "Butterfly", "Penguin", "Ghost", "Fish"}
        local PET_MATERIALS = {
            "JapaneseLantern", "NormalDesk", "NinjaKunai", "NinjaShuriken",
            "BallBasketball", "BallMagicLight", "BellSmall", "FactoryDesk",
            "TableWoodFourLegsBrown",
        }
        local PG = {
            DefaultMat = {Dog = "JapaneseLantern", Ghost = "JapaneseLantern", Fish = "NinjaShuriken"},
            Height = {Spider = 0.8, Dog = 1.5, Cat = 1.2, Rabbit = 1.2, Turtle = 0.7, Parrot = 0.7, Snake = 0.3,
                Butterfly = 0.4, Penguin = 0.95, Ghost = 1.2, Fish = 0.7},
            Step = {Spider = 1.2, Dog = 0.9, Cat = 1.0, Rabbit = 0.45, Turtle = 0.7, Parrot = 1.0, Snake = 1.0,
                Butterfly = 1.0, Penguin = 1.1, Ghost = 1.0, Fish = 1.0},
            Rate = {Turtle = 2.5},
            FWD = Vector3.new(0, 0, -1),
            BACK = Vector3.new(0, 0, 1),
            RIGHT = Vector3.new(1, 0, 0),
            LEFT = Vector3.new(-1, 0, 0),
        }

        function PG.Body6(B, i, hx, ty, hz)
            local zz = (i % 2 == 1) and -hz * 0.5 or hz * 0.5
            if i <= 2 then return B * FrameCF(Vector3.new(-hx, 0, zz), UP, PG.LEFT) end
            if i <= 4 then return B * FrameCF(Vector3.new(hx, 0, zz), UP, PG.RIGHT) end
            return B * FrameCF(Vector3.new(0, ty, zz), PG.FWD, UP)
        end

        function PG.Head4(H, k, r)
            if k == 1 then return H * FrameCF(Vector3.new(0, 0, -r), UP, PG.FWD) end
            if k == 2 then return H * FrameCF(Vector3.new(-r, 0, 0), UP, PG.LEFT) end
            if k == 3 then return H * FrameCF(Vector3.new(r, 0, 0), UP, PG.RIGHT) end
            return H * FrameCF(Vector3.new(0, r, 0), PG.FWD, UP)
        end

        function PG.Cat(b, i, ctx)
            local U, cf, sit = ctx.U, ctx.CF, ctx.Sit
            local Bl = CFrame.new(0, -0.3 * U * sit, 0.6 * U) * CFrame.Angles(0.45 * sit, 0, 0) * CFrame.new(0, 0, -0.6 * U)
            if i <= 6 then return PG.Body6(cf * Bl, i, 0.4 * U, 0.4 * U, 0.9 * U) end
            if i <= 12 then
                local yawn = sit * math.max(0, math.sin(ctx.T * 0.7)) ^ 12
                local Hd = cf * Bl * CFrame.new(0, 0.55 * U, -1.2 * U) * CFrame.Angles(0.5 * yawn, 0, 0)
                if i <= 10 then return PG.Head4(Hd, i - 6, 0.4 * U) end
                local sx = (i == 11) and -1 or 1
                return Hd * SegCF(Vector3.new(sx * 0.25 * U, 0.35 * U, 0), Vector3.new(sx * 0.32 * U, 0.85 * U, 0.08 * U))
            end
            if i <= 16 then
                local li = i - 12
                local sx = (li == 1 or li == 3) and -1 or 1
                local front = li <= 2
                local sz = front and -1 or 1
                local ph = ctx.Walk + ((sx * sz > 0) and 0 or math.pi)
                local a = 0.55 * math.sin(ph) * ctx.Amp
                local hip = Bl * Vector3.new(sx * 0.3 * U, -0.35 * U, sz * 0.6 * U)
                local L = math.max(0.4 * U, hip.Y + ctx.H)
                local dir = Vector3.new(0, -math.cos(a), math.sin(a))
                if not front then
                    dir = dir:Lerp(Vector3.new(0, -0.3, -0.95), sit).Unit
                    L = 0.8 * U
                end
                return cf * SegCF(hip, hip + dir * L)
            end
            local sw = math.sin(ctx.T * 2.2) * 0.5 * (ctx.Sit + 0.25 * ctx.Amp)
            local base = Bl * Vector3.new(0, 0.25 * U, 0.95 * U)
            local d1 = Vector3.new(math.sin(sw) * 0.3, 0.55, 0.8):Lerp(Vector3.new(0.6, -0.5, 0.6), sit).Unit
            local p1 = base + d1 * 0.8 * U
            if i == 17 then return cf * SegCF(base, p1) end
            local d2 = Vector3.new(math.sin(sw * 1.4) * 0.5, 0.95, 0.2):Lerp(Vector3.new(0.9, -0.1, -0.4), sit).Unit
            return cf * SegCF(p1, p1 + d2 * 0.8 * U)
        end

        function PG.Rabbit(b, i, ctx)
            local U, cf = ctx.U, ctx.CF
            local ph = ctx.Walk
            local air = math.abs(math.sin(ph)) * ctx.Amp
            local hop = air * 0.9 * U
            local Bl = CFrame.new(0, hop, 0) * CFrame.Angles(-0.3 * math.cos(ph) * ctx.Amp, 0, 0)
            if i <= 6 then return PG.Body6(cf * Bl, i, 0.4 * U, 0.45 * U, 0.8 * U) end
            if i <= 12 then
                local Hd = cf * Bl * CFrame.new(0, 0.65 * U, -1.0 * U)
                if i <= 10 then return PG.Head4(Hd, i - 6, 0.38 * U) end
                local sx = (i == 11) and -1 or 1
                local tw = (ctx.Sit > 0.5 and math.sin(ctx.T * 3 + sx) > 0.85) and 0.35 or 0
                local tip = Vector3.new(sx * (0.25 + tw * 0.5) * U, 1.35 * U, (0.25 + tw) * U)
                return Hd * SegCF(Vector3.new(sx * 0.18 * U, 0.38 * U, 0.05 * U), tip)
            end
            if i <= 14 then
                local sx = (i == 13) and -1 or 1
                local sh = Bl * Vector3.new(sx * 0.25 * U, -0.4 * U, -0.4 * U)
                local a = 0.6 * math.sin(ph) * ctx.Amp
                local L = math.max(0.4 * U, sh.Y + ctx.H)
                return cf * SegCF(sh, sh + Vector3.new(0, -math.cos(a), -math.sin(a)) * L)
            end
            if i <= 16 then
                local sx = (i == 15) and -1 or 1
                local hip = Bl * Vector3.new(sx * 0.42 * U, -0.2 * U, 0.5 * U)
                local dir = Vector3.new(0, -0.6, -0.8):Lerp(Vector3.new(0, -0.5, 0.85), math.min(1, air * 1.5)).Unit
                return cf * SegCF(hip, hip + dir * 0.9 * U)
            end
            return cf * Bl * FrameCF(Vector3.new(0, 0.2 * U, 0.95 * U), UP, PG.BACK)
        end

        function PG.Turtle(b, i, ctx)
            local U, cf = ctx.U, ctx.CF
            local Bl = CFrame.new(0, math.sin(ctx.Walk * 2) * 0.04 * U * ctx.Amp, 0)
            local B = cf * Bl
            if i <= 8 then
                if i <= 2 then
                    local zz = (i == 1) and -0.5 * U or 0.5 * U
                    return B * FrameCF(Vector3.new(0, 0.45 * U, zz), PG.FWD, UP)
                end
                if i <= 6 then
                    local sx = (i <= 4) and -1 or 1
                    local zz = (i % 2 == 1) and -0.5 * U or 0.5 * U
                    return B * FrameCF(Vector3.new(sx * 0.75 * U, 0.1 * U, zz), PG.FWD, Vector3.new(sx * 0.7, 0.7, 0))
                end
                local sz = (i == 7) and -1 or 1
                return B * FrameCF(Vector3.new(0, 0.1 * U, sz * 1.1 * U), PG.RIGHT, Vector3.new(0, 0.7, sz * 0.7))
            end
            if i <= 10 then
                local look = math.sin(ctx.T * 0.5) * 0.5 * ctx.Sit
                local neckBase = Vector3.new(0, -0.1 * U, -1.1 * U)
                local Nk = Bl * CFrame.new(neckBase) * CFrame.Angles(0, look, 0)
                local bob = math.sin(ctx.T * 1.5) * 0.08 * U * ctx.Sit
                local tip = Vector3.new(0, 0.2 * U + bob, -0.8 * U)
                if i == 9 then return cf * Nk * SegCF(Vector3.new(), tip) end
                return cf * Nk * FrameCF(tip + Vector3.new(0, 0.05 * U, -0.4 * U), PG.FWD, UP)
            end
            if i <= 14 then
                local li = i - 10
                local sx = (li == 1 or li == 3) and -1 or 1
                local sz = (li <= 2) and -1 or 1
                local ph = ctx.Walk + ((sx * sz > 0) and 0 or math.pi)
                local a = 0.5 * math.sin(ph) * ctx.Amp
                local hip = Vector3.new(sx * 0.7 * U, -0.2 * U, sz * 0.6 * U)
                local dir = Vector3.new(sx * 0.6, -0.5, sz * 0.3 + a).Unit
                return B * SegCF(hip, hip + dir * 0.7 * U)
            end
            local sway = math.sin(ctx.T * 2) * 0.15 * U * ctx.Motion
            return B * SegCF(Vector3.new(0, -0.1 * U, 1.1 * U), Vector3.new(sway, -0.3 * U, 1.6 * U))
        end

        function PG.Parrot(b, i, ctx)
            local U, cf = ctx.U, ctx.CF
            local perch = ctx.Perch
            local Bl = CFrame.Angles(-0.35 * (1 - perch), 0, 0)
            local B = cf * Bl
            if i <= 4 then
                if i == 1 then return B * FrameCF(Vector3.new(0, 0, -0.35 * U), UP, PG.FWD) end
                if i == 2 then return B * FrameCF(Vector3.new(0, 0, 0.35 * U), UP, PG.BACK) end
                if i == 3 then return B * FrameCF(Vector3.new(-0.35 * U, 0, 0), UP, PG.LEFT) end
                return B * FrameCF(Vector3.new(0.35 * U, 0, 0), UP, PG.RIGHT)
            end
            if i == 5 then return B * FrameCF(Vector3.new(0, 0.75 * U, -0.15 * U), PG.FWD, UP) end
            if i == 6 then return B * FrameCF(Vector3.new(0, 0.5 * U, -0.5 * U), UP, PG.FWD) end
            if i == 7 then return B * SegCF(Vector3.new(0, 0.45 * U, -0.6 * U), Vector3.new(0, 0.2 * U, -1.0 * U)) end
            if i == 8 then return B * SegCF(Vector3.new(0, 0.8 * U, 0), Vector3.new(0, 1.3 * U, 0.3 * U)) end
            if i <= 12 then
                local sx = (i <= 10) and -1 or 1
                local outer = (i % 2 == 0)
                local a = math.sin(ctx.T * 12) * 0.7 * ctx.Flight
                local sh = Vector3.new(sx * 0.35 * U, 0.3 * U, 0)
                local d1 = Vector3.new(sx * math.cos(a), math.sin(a), 0):Lerp(Vector3.new(sx * 0.15, -0.6, 0.8), perch).Unit
                local e1 = sh + d1 * 0.9 * U
                local d = d1
                local from, to = sh, e1
                if outer then
                    d = Vector3.new(sx * math.cos(a * 1.3), math.sin(a * 1.3), 0):Lerp(Vector3.new(sx * 0.05, -0.5, 0.85), perch).Unit
                    from, to = e1, e1 + d * 0.9 * U
                end
                local n = d:Cross(PG.BACK)
                if n.Magnitude < 1e-3 then n = UP end
                return B * FrameCF((from + to) / 2, d, n)
            end
            local sx = (i == 13) and -0.15 or 0.15
            return B * SegCF(Vector3.new(sx * U, -0.4 * U, 0.3 * U), Vector3.new(sx * 1.6 * U, -1.2 * U, 0.9 * U))
        end

        function PG.SnakePoints(b, center, fwd, U, now, amp, reset)
            local tr = b.Trail
            if reset or not tr or (tr[1] and (tr[1] - center).Magnitude > 12 * U) then
                tr = {}
                b.Trail = tr
            end
            if not tr[1] or (center - tr[1]).Magnitude > 0.2 * U then
                table.insert(tr, 1, center)
            end
            while #tr > 120 do table.remove(tr) end
            local S = 0.8 * U
            local pts = {center}
            local prev, acc, k = center, 0, 1
            while #pts < 14 and k <= #tr do
                local q = tr[k]
                local seg = (q - prev).Magnitude
                if seg > 1e-4 and acc + seg >= S then
                    local p = prev:Lerp(q, (S - acc) / seg)
                    pts[#pts + 1] = p
                    prev, acc = p, 0
                else
                    acc = acc + seg
                    prev = q
                    k = k + 1
                end
            end
            local back = -fwd
            if #pts >= 2 then
                local d = pts[#pts] - pts[#pts - 1]
                d = Vector3.new(d.X, 0, d.Z)
                if d.Magnitude > 1e-3 then back = d.Unit end
            end
            while #pts < 14 do pts[#pts + 1] = pts[#pts] + back * S end
            local out = {pts[1]}
            local wave = (b.IdleAnimations == false) and amp or (0.25 + 0.75 * amp)
            local A = 0.28 * U * wave
            for j = 2, 14 do
                local d = pts[j - 1] - pts[j]
                d = Vector3.new(d.X, 0, d.Z)
                local side = (d.Magnitude > 1e-3) and d.Unit:Cross(UP) or Vector3.new()
                out[j] = pts[j] + side * (math.sin(j * 0.9 - now * 5) * A * math.min(1, j / 4))
            end
            return out
        end

        function PG.Snake(b, i, ctx)
            local U, P = ctx.U, ctx.Pts
            if i == 1 then
                local d = P[1] - P[2]
                d = Vector3.new(d.X, 0, d.Z)
                if d.Magnitude < 1e-3 then d = ctx.CF.LookVector end
                d = d.Unit
                local sway = math.sin(ctx.T * 1.5) * 0.4 * ctx.Sit
                d = CFrame.Angles(0, sway, 0) * d
                local raise = (0.3 * ctx.Amp + 0.5 * ctx.Sit) * U
                return FrameCF(P[1] + d * 0.45 * U + Vector3.new(0, raise, 0), d + Vector3.new(0, 0.35, 0), UP)
            end
            local a, c = P[i - 1], P[i]
            return FrameCF((a + c) / 2, a - c, UP)
        end


        function PG.Dog(b, i, ctx)
            local U, cf, sit = ctx.U, ctx.CF, ctx.Sit
            local Bl = CFrame.new(0, -0.28 * U * sit, 0.65 * U)
                * CFrame.Angles(0.42 * sit, 0, 0) * CFrame.new(0, 0, -0.65 * U)
            local B = cf * Bl
            if i <= 6 then return PG.Body6(B, i, 0.5 * U, 0.5 * U, U) end
            if i <= 10 then
                local Hd = B * CFrame.new(0, 0.7 * U, -1.4 * U)
                    * CFrame.Angles(-0.12 * sit, math.sin(ctx.T * 0.8) * 0.12 * sit, 0)
                return PG.Head4(Hd, i - 6, 0.5 * U)
            end
            if i <= 14 then
                local li = i - 10
                local sx = (li == 1 or li == 3) and -1 or 1
                local front = li <= 2
                local sz = front and -1 or 1
                local phase = ctx.Walk + ((sx * sz > 0) and 0 or math.pi)
                local a = 0.55 * math.sin(phase) * ctx.Amp
                local hip = Bl * Vector3.new(sx * 0.35 * U, -0.5 * U, sz * 0.7 * U)
                local dir = Vector3.new(0, -math.cos(a), math.sin(a))
                local length = math.max(0.4 * U, hip.Y + ctx.H)
                if not front then
                    dir = dir:Lerp(Vector3.new(0, -0.3, -0.95), sit).Unit
                    length = length * (1 - 0.25 * sit)
                end
                return cf * SegCF(hip, hip + dir * length)
            end
            local wag = math.sin(ctx.T * 8) * 0.6 * ctx.Motion
            local base = Bl * Vector3.new(0, 0.4 * U, U)
            local dir = Vector3.new(math.sin(wag) * 0.8, 0.6, math.cos(wag) * 0.8)
            return cf * SegCF(base, base + dir * U)
        end

        function PG.Spider(b, i, ctx)
            local U, cf = ctx.U, ctx.CF
            if i == 1 then return cf * FrameCF(Vector3.new(0, 0.15 * U, 0), PG.FWD, UP) end
            if i == 2 then return cf * FrameCF(Vector3.new(0, -0.15 * U, 0), PG.FWD, UP) end
            if i == 3 then return cf * FrameCF(Vector3.new(0, 0, -0.6 * U), UP, PG.FWD) end
            local li = math.floor((i - 4) / 2)
            local upper = ((i - 4) % 2) == 0
            local sx = (li < 4) and 1 or -1
            local j = li % 4
            local phase = ctx.Walk + (((j % 2 == 0) == (sx > 0)) and 0 or math.pi)
            local yaw = 0.35 * math.sin(phase) * ctx.Amp
            local lift = math.max(0, math.cos(phase)) * 0.3 * U * ctx.Amp
            local out = Vector3.new(sx, 0, (j - 1.5) * 0.5).Unit
            out = CFrame.Angles(0, yaw, 0) * out
            local hip = Vector3.new(sx * 0.45 * U, 0, (-0.45 + j * 0.3) * U)
            local knee = hip + out * 0.9 * U + Vector3.new(0, 0.6 * U + lift, 0)
            local foot = hip + out * 1.7 * U + Vector3.new(0, -ctx.H + lift * 0.5, 0)
            return cf * (upper and SegCF(hip, knee) or SegCF(knee, foot))
        end

        function PG.Butterfly(b, i, ctx)
            local U, cf = ctx.U, ctx.CF
            if i <= 2 then
                return cf * FrameCF(Vector3.new(0, 0, (i == 1 and 0.35 or -0.35) * U), PG.FWD, UP)
            end
            if i == 3 then return cf * FrameCF(Vector3.new(0, 0.12 * U, -0.95 * U), UP, PG.FWD) end
            if i <= 5 then
                local sx = i == 4 and -1 or 1
                return cf * SegCF(Vector3.new(sx * 0.15 * U, 0.2 * U, -0.9 * U),
                    Vector3.new(sx * 0.55 * U, 0.8 * U, -1.3 * U))
            end
            local k = i - 6
            local sx, part = k < 3 and -1 or 1, k % 3
            local flight = ctx.Flight
            local flap = 0.2 + math.sin(ctx.T * 13) * 0.95
            local a = flap * flight + (1 - flight) * 1.38
            local z = (-0.55 + part * 0.55) * U
            local base = Vector3.new(sx * 0.15 * U, 0, z)
            local length = (part == 1 and 1.55 or 1.2) * U
            local d = Vector3.new(sx * math.cos(a), math.sin(a), part == 0 and -0.15 or 0.15).Unit
            return cf * FrameCF(base + d * length * 0.5, d, d:Cross(PG.BACK))
        end

        function PG.Penguin(b, i, ctx)
            local U, cf, slide = ctx.U, ctx.CF, ctx.Slide
            local waddle = math.sin(ctx.Walk * 1.5) * 0.15 * ctx.Amp * (1 - slide)
            local B = cf * CFrame.new(0, -0.32 * U * slide - 0.15 * U * ctx.Sit, 0)
                * CFrame.Angles(-1.3 * slide, 0, waddle)
            if i == 1 then return B * FrameCF(Vector3.new(0, 0, -0.4 * U), UP, PG.FWD) end
            if i == 2 then return B * FrameCF(Vector3.new(0, 0, 0.4 * U), UP, PG.BACK) end
            if i == 3 then return B * FrameCF(Vector3.new(-0.4 * U, 0, 0), UP, PG.LEFT) end
            if i == 4 then return B * FrameCF(Vector3.new(0.4 * U, 0, 0), UP, PG.RIGHT) end
            local head = B * CFrame.new(0, 0.85 * U, -0.08 * U)
            if i <= 8 then return PG.Head4(head, i - 4, 0.4 * U) end
            if i == 9 then return head * SegCF(Vector3.new(0, -0.05 * U, -0.35 * U), Vector3.new(0, -0.13 * U, -0.9 * U)) end
            if i <= 11 then
                local sx = i == 10 and -1 or 1
                local flap = math.sin(ctx.Walk * 1.5 + sx) * 0.25 * ctx.Amp
                local base = Vector3.new(sx * 0.4 * U, 0.3 * U, 0)
                local d = Vector3.new(sx * (0.25 + 0.65 * slide), -0.85 + flap, 0.25).Unit
                return B * SegCF(base, base + d * 1.05 * U)
            end
            local sx = i == 12 and -1 or 1
            local step = math.sin(ctx.Walk * 1.5 + (sx > 0 and math.pi or 0)) * 0.2 * U * ctx.Amp
            return B * FrameCF(Vector3.new(sx * 0.3 * U, -0.75 * U, -0.28 * U + step), PG.FWD, UP)
        end

        function PG.Ghost(b, i, ctx)
            -- floating lantern sheet head to tail, two drifting arms, slow sway
            local U = ctx.U
            local sway = math.sin(ctx.T * 0.8) * 0.06
            local B = ctx.CF * CFrame.Angles(-0.08 * ctx.Flight + sway * 0.4, 0, sway)
            if i == 1 then return B * FrameCF(Vector3.new(0, 0.75 * U, 0), PG.FWD, UP) end
            if i <= 3 then
                local w = i == 2 and 1.0 or 1.35
                return B * FrameCF(Vector3.new(0, (0.95 + 1.05 - i * 0.47) * U * 0.7, 0),
                    Vector3.new(0, 0, -1).Unit, UP) -- sheet discs
            end
            if i == 4 then
                local curl = Vector3.new(math.sin(ctx.T * 1.3) * 0.3, -0.85, 0.25).Unit
                return B * SegCF(Vector3.new(0, 0.05 * U, 0), Vector3.new(0, 0.05 * U, 0) + curl * 1.3 * U)
            end
            if i <= 6 then
                local sx = i == 5 and -1 or 1
                local wave = math.sin(ctx.T * 1.7 + sx) * 0.25
                local d = Vector3.new(sx * 0.9, 0.25 + wave, -0.3).Unit
                local root = Vector3.new(sx * 0.3 * U, 0.55 * U, -0.05 * U)
                return B * SegCF(root, root + d * 0.9 * U)
            end
            local sx = i == 7 and -1 or 1
            -- spooky eyes glow
            return B * FrameCF(Vector3.new(sx * 0.17 * U, 0.85 * U, -0.42 * U), PG.FWD, UP)
        end

        function PG.Fish(b, i, ctx)
            -- airborne swimmer: flowing body line, wagging tail, fins
            local U = ctx.U
            local wag = math.sin(ctx.T * 6)
            local wag2 = math.sin(ctx.T * 6 - 0.9)
            local B = ctx.CF * CFrame.Angles(0, wag * 0.12, wag * 0.06)
            if i <= 3 then
                local z = (i - 2) * 0.62
                local slim = 2 - math.abs(i - 2)
                local dir = Vector3.new(wag * 0.12 * (i == 3 and 2 or i == 1 and -2 or 0), 0, -1).Unit
                return B * FrameCF(Vector3.new(wag * 0.08 * (i - 2) * U, 0, (z - 0.6) * U), dir, UP)
            end
            if i <= 5 then
                local k = i - 4
                local root = Vector3.new(-wag2 * 0.1 * U, wag2 * 0.05 * U, 0.75 * U)
                local d = (k == 1) and Vector3.new(wag2 * 0.5, 0.7, 0.7).Unit or Vector3.new(wag2 * 0.5, -0.7, 0.7).Unit
                return B * SegCF(root, root + d * 1.0 * U)
            end
            if i == 6 then
                return B * SegCF(Vector3.new(0, 0.28 * U, -0.15 * U), Vector3.new(0, 0.85 * U, 0.35 * U))
            end
            if i <= 8 then
                local sx = i == 7 and -1 or 1
                local flap = math.sin(ctx.T * 6 + sx) * 0.2
                local d = Vector3.new(sx * 0.85, -0.2 + flap, 0.45).Unit
                local root = Vector3.new(sx * 0.18 * U, -0.1 * U, 0)
                return B * SegCF(root, root + d * 0.7 * U)
            end
            if i <= 10 then
                local sx = i == 9 and -1 or 1
                return B * FrameCF(Vector3.new(sx * 0.16 * U, 0.14 * U, -0.55 * U), PG.FWD, UP)
            end
            local root = Vector3.new(0, -0.18 * U, -0.1 * U)
            return B * SegCF(root, root + Vector3.new(0, -0.6, 0.75).Unit * 0.6 * U)
        end

                PG.Flying = {Parrot = true, Butterfly = true, Ghost = true, Fish = true}
        PG.SpeedFactor = {Turtle = 0.45, Snake = 0.85, Penguin = 0.85, Butterfly = 0.9, Ghost = 0.65, Fish = 0.85}
        PG.Movements = {Follow = true, Stay = true, Wander = true}
        PG.Pathfinding = game:GetService("PathfindingService")

        function PG.Flat(v)
            return Vector3.new(v.X, 0, v.Z)
        end

        function PG.PetNumber(b)
            return math.clamp(math.floor(tonumber(b.PetCount) or 1), 1, 3)
        end

        function PG.Blend(value, goal, rate, dt)
            return value + (goal - value) * (1 - math.exp(-rate * dt))
        end

        function PG.ClearRoute(a)
            a.NavTicket = (a.NavTicket or 0) + 1
            a.NavBusy, a.NavPath, a.NavGoal = false, nil, nil
            a.NavIndex, a.NextPath = 1, 0
        end

        function PG.SetMovement(b, mode)
            if not PG.Movements[mode] then mode = "Follow" end
            b.MoveMode = mode
            for _, a in pairs(b.Pets or {}) do
                a.StayPos = mode == "Stay" and a.Pos or nil
                a.StayFlightY = mode == "Stay" and a.FlightY or nil
                a.WanderGoal, a.WanderWait = nil, nil
                PG.ClearRoute(a)
            end
        end

        function PG.ResetPets(b)
            for _, a in pairs(b.Pets or {}) do PG.ClearRoute(a) end
            b.Pets, b.PetPos = {}, nil
            b.PetParams = nil
        end

        function PG.Reconfigure(b)
            b.PetConfigVersion = (b.PetConfigVersion or 0) + 1
            local version = b.PetConfigVersion
            if not b.Enabled then
                PG.ResetPets(b)
                UpdateLabel(b)
                return
            end
            b.Gen = b.Gen + 1
            b.NeedFill = false
            task.spawn(function()
                while b.Building and b.Enabled and not UNL() and version == b.PetConfigVersion do
                    task.wait(0.05)
                end
                if not b.Enabled or UNL() or version ~= b.PetConfigVersion then return end
                Reshape(b)
                if not b.Conn then StartLoop(b) end
                if b.AutoRepair then b.NeedFill = true end
            end)
        end

        function PG.FormationOffset(b, index, U)
            local n = PG.PetNumber(b)
            if n == 1 then return Vector3.zero end
            local gap = math.max(tonumber(b.PetSpacing) or 12, U * 2.4)
            if b.Formation == "Circle" then
                local angle = (index - 1) * math.pi * 2 / n
                return Vector3.new(math.cos(angle) * gap * 0.7, 0, math.sin(angle) * gap * 0.7)
            end
            if b.Formation == "V" and n == 3 then
                if index == 1 then return Vector3.new(0, 0, -gap * 0.25) end
                return Vector3.new((index == 2 and -1 or 1) * gap * 0.8, 0, gap * 0.65)
            end
            return Vector3.new((index - (n + 1) / 2) * gap, 0, 0)
        end

        function PG.RayParams(b, char)
            local params = b.PetParams
            if not params then
                params = RaycastParams.new()
                params.FilterType = Enum.RaycastFilterType.Exclude
                pcall(function() params.RespectCanCollide = true end)
                b.PetParams = params
            end
            local exclude = {char}
            if LP.Character and LP.Character ~= char then exclude[#exclude + 1] = LP.Character end
            for _, slot in pairs(b.Slots) do
                if slot and slot.Model and slot.Model.Parent then exclude[#exclude + 1] = slot.Model end
            end
            params.FilterDescendantsInstances = exclude
            return params
        end

        function PG.GroundAt(pos, params, fallback)
            local hit = workspace:Raycast(pos + UP * 4, Vector3.new(0, -100, 0), params)
            return hit and hit.Position.Y or fallback, hit ~= nil
        end

        function PG.Probe(a, from, to, U, params, flying, ground)
            local delta = PG.Flat(to - from)
            if delta.Magnitude < 0.001 then return nil end
            if delta.Magnitude > 500 then delta = delta.Unit * 500 end
            local radius = math.clamp(U * 0.42, 0.75, 4)
            local y = flying and (a.FlightY or (ground + U * 2.5)) or (ground + radius + 0.7)
            local origin = Vector3.new(from.X, y, from.Z)
            if PG.HasSpherecast ~= false then
                local ok, hit = pcall(function() return workspace:Spherecast(origin, radius, delta, params) end)
                if ok then PG.HasSpherecast = true return hit end
                PG.HasSpherecast = false
            end
            return workspace:Raycast(origin, delta, params)
        end

        function PG.RequestPath(b, a, goal, U, params, now)
            if a.NavBusy and now - (a.NavStarted or now) > 4 then PG.ClearRoute(a) end
            if a.NavBusy or now < (a.NextPath or 0) then return end
            a.NavBusy, a.NavStarted, a.NextPath = true, now, now + 1.5
            a.NavTicket = (a.NavTicket or 0) + 1
            local ticket = a.NavTicket
            local start = a.Pos
            a.NavGoal = goal
            local startGround = PG.GroundAt(start, params, a.Ground or start.Y - 3)
            local goalGround = PG.GroundAt(goal, params, goal.Y - 3)
            task.spawn(function()
                local path
                local ok, waypoints = pcall(function()
                    path = PG.Pathfinding:CreatePath({
                        AgentRadius = math.clamp(U * 0.55, 1, 5),
                        AgentHeight = math.clamp(U * 1.7, 3, 14),
                        AgentCanJump = false, AgentCanClimb = false,
                        WaypointSpacing = math.max(3, U * 0.7),
                    })
                    path:ComputeAsync(Vector3.new(start.X, startGround + 2, start.Z),
                        Vector3.new(goal.X, goalGround + 2, goal.Z))
                    if path.Status ~= Enum.PathStatus.Success then return nil end
                    local points = {}
                    for _, waypoint in ipairs(path:GetWaypoints()) do
                        if waypoint.Action == Enum.PathWaypointAction.Jump then return nil end
                        points[#points + 1] = waypoint.Position
                    end
                    return #points >= 2 and points or nil
                end)
                if path then pcall(function() path:Destroy() end) end
                if UNL() or not b.Enabled or not b.Pets or b.Pets[a.Index] ~= a or ticket ~= a.NavTicket then return end
                a.NavBusy = false
                if ok and waypoints then
                    a.NavPath, a.NavIndex = waypoints, 2
                else
                    a.NavPath, a.NavIndex, a.NextPath = nil, 1, os.clock() + 2
                end
            end)
        end

        function PG.SafeGroundStep(a, nextPos, U, params, flying)
            local y, exists = PG.GroundAt(nextPos, params, a.Ground or nextPos.Y - 3)
            if not flying and (not exists or math.abs(y - (a.Ground or y)) > math.max(3.5, U * 0.85)) then
                return nil
            end
            return Vector3.new(nextPos.X, y + 3, nextPos.Z)
        end

        function PG.Navigate(b, a, goal, U, params, dt, now, flying)
            local pos = a.Pos
            local delta = PG.Flat(goal - pos)
            local deadzone = math.max(0.35, U * 0.1)
            if delta.Magnitude <= deadzone then
                a.Blocked, a.Stuck = false, 0
                return pos
            end
            local speed = math.clamp(tonumber(b.FollowSpeed) or 18, 2, 50) * (PG.SpeedFactor[b.Type] or 1)
            local direction = delta.Unit
            local step = math.min(speed * dt, delta.Magnitude)
            if b.AvoidObstacles == false then
                a.Blocked, a.Stuck = false, 0
                return pos + direction * step
            end
            local ground = a.Ground or (pos.Y - 3)
            local hit = PG.Probe(a, pos, goal, U, params, flying, ground)
            if hit then
                if a.NavGoal and PG.Flat(a.NavGoal - goal).Magnitude > math.max(6, U * 2) then PG.ClearRoute(a) end
                PG.RequestPath(b, a, goal, U, params, now)
                if a.NavPath then
                    local waypoint = a.NavPath[a.NavIndex or 2]
                    while waypoint and PG.Flat(waypoint - pos).Magnitude < math.max(1.2, U * 0.3) do
                        a.NavIndex = (a.NavIndex or 2) + 1
                        waypoint = a.NavPath[a.NavIndex]
                    end
                    if waypoint then
                        local toward = PG.Flat(waypoint - pos)
                        if toward.Magnitude > 0.001 then
                            direction, step = toward.Unit, math.min(speed * dt, toward.Magnitude)
                        end
                    else
                        a.NavPath = nil
                    end
                end
            elseif a.NavPath then
                a.NavPath = nil
            end
            local candidate = pos + direction * step
            local blocked = PG.Probe(a, pos, candidate, U, params, flying, ground)
            if not blocked then
                local safe = PG.SafeGroundStep(a, candidate, U, params, flying)
                if safe then a.Blocked, a.Stuck = false, 0 return safe end
            else
                local normal = PG.Flat(blocked.Normal)
                if normal.Magnitude > 0.001 then
                    normal = normal.Unit
                    local slide = direction - normal * direction:Dot(normal)
                    if slide.Magnitude < 0.05 then slide = Vector3.new(-normal.Z, 0, normal.X) end
                    slide = slide.Unit
                    if slide:Dot(delta) < 0 then slide = -slide end
                    for side = 1, 2 do
                        local tangent = side == 1 and slide or -slide
                        local nextPos = pos + tangent * step
                        if not PG.Probe(a, pos, nextPos, U, params, flying, ground) then
                            local safe = PG.SafeGroundStep(a, nextPos, U, params, flying)
                            if safe then
                                a.Blocked, a.Stuck = true, (a.Stuck or 0) + dt
                                return safe
                            end
                        end
                    end
                end
            end
            a.Blocked, a.Stuck = true, (a.Stuck or 0) + dt
            return pos
        end

        function PG.Turn(fwd, desired, degreesPerSecond, dt)
            desired = PG.Flat(desired)
            if desired.Magnitude < 0.001 then return fwd end
            desired = desired.Unit
            local from, to = math.atan2(fwd.Z, fwd.X), math.atan2(desired.Z, desired.X)
            local difference = math.atan2(math.sin(to - from), math.cos(to - from))
            local maximum = math.rad(degreesPerSecond) * dt
            local angle = from + math.clamp(difference, -maximum, maximum)
            return Vector3.new(math.cos(angle), 0, math.sin(angle))
        end

        function PG.Goal(b, a, root, U, now)
            local rp, mode = root.Position, b.MoveMode or "Follow"
            local rootForward = FlatLook(root.CFrame)
            local right = rootForward:Cross(UP)
            local offset = PG.FormationOffset(b, a.Index, U)
            local worldOffset = right * offset.X - rootForward * offset.Z
            if mode == "Stay" then
                a.StayPos = a.StayPos or a.Pos
                return a.StayPos
            end
            if mode == "Wander" then
                local radius = math.clamp(tonumber(b.WanderRadius) or 18, 6, 50)
                local farAway = a.WanderGoal and PG.Flat(a.WanderGoal - rp).Magnitude > radius * 1.8
                if farAway or (a.Stuck or 0) > 3 then
                    a.WanderGoal, a.WanderWait, a.Stuck = nil, nil, 0
                    PG.ClearRoute(a)
                end
                if a.WanderGoal and PG.Flat(a.WanderGoal - a.Pos).Magnitude < math.max(0.7, U * 0.2) then
                    a.WanderGoal = nil
                    a.WanderWait = now + 1.5 + math.random() * 2.5
                end
                if not a.WanderGoal and now >= (a.WanderWait or 0) then
                    local angle = math.random() * math.pi * 2
                    local distance = radius * (0.3 + math.random() * 0.7)
                    a.WanderGoal = rp + Vector3.new(math.cos(angle) * distance, 0, math.sin(angle) * distance)
                    a.WanderWait = nil
                end
                return a.WanderGoal or a.Pos
            end
            return rp - rootForward * math.max(6, tonumber(b.Dist) or 12) + worldOffset
        end

        function PG.ActorFrame(b, a, char, root, hum, dt, now, params)
            local U, T, rp = b.Unit, b.Type, root.Position
            local mode = b.MoveMode or "Follow"
            local forward = FlatLook(root.CFrame)
            local reset = false
            if not a.Pos then
                local offset = PG.FormationOffset(b, a.Index, U)
                a.Pos = rp - forward * math.max(6, tonumber(b.Dist) or 12)
                    + forward:Cross(UP) * offset.X - forward * offset.Z
                a.Fwd, a.Ground = forward, rp.Y - 3
                a.FlightV = PG.Flying[T] and 1 or 0
                reset = true
            elseif mode ~= "Stay" and (a.Pos - rp).Magnitude > 150 then
                local offset = PG.FormationOffset(b, a.Index, U)
                a.Pos = rp - forward * math.max(6, tonumber(b.Dist) or 12)
                    + forward:Cross(UP) * offset.X - forward * offset.Z
                a.Ground, a.StayPos, a.WanderGoal, a.WanderWait = rp.Y - 3, nil, nil, nil
                PG.ClearRoute(a)
                reset = true
            end
            local old = a.Pos
            a.Ground = PG.GroundAt(old, params, a.Ground or rp.Y - 3)
            local goal = PG.Goal(b, a, root, U, now)
            local flying = PG.Flying[T] and (a.FlightV or 0) > 0.5
            a.Pos = PG.Navigate(b, a, goal, U, params, dt, now, flying)
            a.Ground = PG.GroundAt(a.Pos, params, a.Ground or rp.Y - 3)
            a.Pos = Vector3.new(a.Pos.X, a.Ground + 3, a.Pos.Z)
            local moved = PG.Flat(a.Pos - old)
            local speed = moved.Magnitude / math.max(dt, 0.001)
            local amp = math.clamp(speed / 10, 0, 1)
            local desired = moved
            if moved.Magnitude < 0.005 then desired = PG.Flat(rp - a.Pos) end
            a.Fwd = PG.Turn(a.Fwd or forward, desired, math.clamp(tonumber(b.TurnSpeed) or 240, 30, 540), dt)
            a.Walk = (a.Walk or 0) + moved.Magnitude * (PG.Step[T] or 1) / math.max(U * 0.3, 0.5)
            if speed < 1.5 then a.Idle = (a.Idle or 0) + dt else a.Idle = 0 end
            local idleEnabled = b.IdleAnimations ~= false
            local sitGoal = (idleEnabled and a.Idle > 1.5) and 1 or 0
            a.SitV = PG.Blend(a.SitV or 0, sitGoal, 3, dt)
            local canFly = PG.Flying[T] == true
            local flightGoal = canFly and 1 or 0
            if T ~= "Parrot" and idleEnabled and a.Idle > 3 then flightGoal = 0 end
            a.FlightV = PG.Blend(a.FlightV or 0, flightGoal, 3, dt)
            local perchGoal = (T == "Parrot" and mode == "Follow" and idleEnabled and a.Idle > 3) and 1 or 0
            local perchSide = a.Index % 2 == 1 and 1 or -1
            local perchPosition = (root.CFrame * CFrame.new(perchSide * (1.2 + math.floor((a.Index - 1) / 2) * 0.8) * U, 1.1 * U, 0.2 * U)).Position
            if perchGoal == 1 and b.AvoidObstacles ~= false then
                if PG.Probe(a, a.Pos, perchPosition, U, params, true, a.Ground) then perchGoal = 0 end
            end
            a.PerchV = PG.Blend(a.PerchV or 0, perchGoal, 2.5, dt)
            local motion = idleEnabled and 1 or amp
            if motion > 0.01 or (canFly and a.FlightV > 0.05 and a.PerchV < 0.95) then
                a.AnimTime = (a.AnimTime or a.Index * 0.37) + dt
            end
            local animationTime = a.AnimTime or 0
            local H = (PG.Height[T] or 0.8) * U
            if T == "Spider" or T == "Turtle" then
                H = H - 0.15 * U * a.SitV
            end
            local center = Vector3.new(a.Pos.X, a.Ground + H, a.Pos.Z)
            if canFly then
                local bob = math.sin(animationTime * 2.2 + a.Index) * 0.18 * U
                local flyHeight = math.max(a.Ground + 1.8 * U, rp.Y + 0.7 * U)
                if mode == "Stay" then
                    a.StayFlightY = a.StayFlightY or a.FlightY or flyHeight
                    flyHeight = a.StayFlightY
                end
                local fly = Vector3.new(a.Pos.X, flyHeight + bob * math.max(amp, idleEnabled and 1 or 0), a.Pos.Z)
                center = center:Lerp(fly, a.FlightV)
                if T == "Parrot" then center = center:Lerp(perchPosition, a.PerchV) end
            end
            a.FlightY = center.Y
            local look = a.Fwd
            if T == "Parrot" then
                look = look:Lerp(forward, a.PerchV)
                if look.Magnitude < 0.001 then look = forward end
                look = look.Unit
            end
            local cf = CFrame.lookAt(center, center + look)
            a.SlideV = PG.Blend(a.SlideV or 0, (T == "Penguin" and speed > 11) and 1 or 0, 4, dt)
            local ctx = {
                CF = cf, U = U, H = H, Walk = a.Walk or 0, Amp = amp,
                T = animationTime, Sit = a.SitV, Perch = math.max(a.PerchV, 1 - a.FlightV),
                Flight = a.FlightV, Motion = motion, Slide = a.SlideV,
                PetIndex = a.Index,
            }
            if T == "Snake" then
                a.IdleAnimations = b.IdleAnimations
                ctx.Pts = PG.SnakePoints(a, center, a.Fwd, U, animationTime, amp, reset)
            end
            return ctx
        end

        local Pet = NewBuild("Pallet Pet", {
            Count = function(b) return (PET_COUNT[b.Type] or 19) * PG.PetNumber(b) end,
            Reset = PG.ResetPets,
            Frame = function(b, char, root, hum, dt)
                dt = math.clamp(tonumber(dt) or 1 / 60, 0.001, 0.1)
                local now = os.clock()
                b.Pets = b.Pets or {}
                local contexts = {}
                local params = PG.RayParams(b, char)
                for index = 1, PG.PetNumber(b) do
                    local a = b.Pets[index]
                    if not a then a = {Index = index} b.Pets[index] = a end
                    contexts[index] = PG.ActorFrame(b, a, char, root, hum, dt, now, params)
                end
                b.PetPos = b.Pets[1] and b.Pets[1].Pos or nil
                return {Actors = contexts, PerPet = PET_COUNT[b.Type] or 19}
            end,
            Place = function(b, index, ctx)
                local perPet = ctx.PerPet
                local actorIndex = math.floor((index - 1) / perPet) + 1
                local pieceIndex = (index - 1) % perPet + 1
                local actorContext = ctx.Actors[actorIndex]
                local shape = PG[b.Type]
                if not actorContext or type(shape) ~= "function" then return nil end
                return shape(b, pieceIndex, actorContext)
            end,
        }, {
            Type = "Spider", Dist = 12, ToyName = "NormalDesk", MoveMode = "Follow", IdleAnimations = true,
