        function CX.Rule(page, method, config)
            local rules = CX.Rules[page] or {}
            if method == "CreateDivider" then
                local title = type(config) == "table" and (config.Text or config.Name) or config
                return rules.Dividers and rules.Dividers[title]
            end
            if type(config) ~= "table" then return nil end
            if config.VisibleWhen then return config.VisibleWhen end
            if config.Flag and rules.Flags then return rules.Flags[config.Flag] end
            if config.ContextKey and rules.Labels then return rules.Labels[config.ContextKey] end
            if method == "CreateButton" and rules.Buttons then return rules.Buttons[config.Name] end
            return nil
        end
        function CX.Wanted(entry)
            if CX.Cleaned or UNL() then return false end
            if CX.Tabbed and TB.Active ~= entry.Page then return false end
            local state = CX.States[entry.Page]
            if entry.Rule then
                local ok, value = pcall(entry.Rule, state)
                if not ok then
                    if not entry.Warned then entry.Warned = true warn("[Toy Builds UI] A visibility rule could not be evaluated.") end
                    return false
                end
                return value and true or false
            end
            return true
        end
        function CX.Filtering()
            return CX.SearchInput and CX.SearchInput.Parent and CX.SearchInput.Text:gsub("%s", "") ~= ""
        end
        function CX.Apply(entry, allowShow)
            local frame = entry.Frame
            if not frame or not frame.Parent then return end
            local wanted = CX.Wanted(entry)
            if not wanted then
                if frame.Visible then frame.Visible = false end
            elseif allowShow and not frame.Visible then
                frame.Visible = true
            end
        end
        function CX.Refresh()
            if CX.Cleaned or CX.Refreshing then return end
            CX.Refreshing = true
            local allowShow = not CX.Filtering()
            for _, entry in ipairs(CX.Entries) do CX.Apply(entry, allowShow) end
            CX.Refreshing = false
            if Block and Block._box and Block._box.Resize then
                pcall(function() Block._box:Resize() end)
            end
        end
        UX.RefreshContext = CX.Refresh
        function CX.Register(frame, page, rule, config, method)
            if not frame or not frame.Parent or CX.Seen[frame] then return end
            local entry = {Frame = frame, Page = page, Rule = rule, Method = method,
                Flag = type(config) == "table" and config.Flag or nil,
                Name = type(config) == "table" and (config.ContextKey or config.Name or config.Text) or config}
            CX.Seen[frame] = entry
            CX.Entries[#CX.Entries + 1] = entry
            
            local connection = frame:GetPropertyChangedSignal("Visible"):Connect(function()
                if frame.Visible then CX.Apply(entry, false) end
            end)
            CX.Connections[#CX.Connections + 1] = connection
            CX.Apply(entry, true)
        end
        function CX.Snapshot()
            local before = {}
            if CX.Container then for _, frame in ipairs(CX.Container:GetChildren()) do before[frame] = true end end
            return before
        end
        function CX.Wrap(page, base, state)
            CX.States[page] = state
            return setmetatable({}, {__index = function(_, method)
                local create = base[method]
                if type(create) ~= "function" then return create end
                if method:sub(1, 6) ~= "Create" then
                    return function(_, ...) return create(base, ...) end
                end
                return function(_, config, ...)
                    local rule = CX.Rule(page, method, config)
                    local args = table.pack(...)
                    local before = CX.Snapshot()
                    local pageRows = TB and TB.Pages and TB.Pages[page]
                    local first = pageRows and #pageRows or 0
                    local passed = config
                    if type(config) == "table" then
                        passed = {}
                        for k, v in pairs(config) do passed[k] = v end
                        local callback = config.Callback
                        if callback then
                            passed.Callback = function(...)
                                local result = table.pack(callback(...))
                                CX.Refresh()
                                return table.unpack(result, 1, result.n)
                            end
                        end
                    end
                    local result = table.pack(create(base, passed, table.unpack(args, 1, args.n)))
                    if pageRows then
                        for i = first + 1, #pageRows do CX.Register(pageRows[i], page, rule, config, method) end
                    end
                    if CX.Container then
                        for _, frame in ipairs(CX.Container:GetChildren()) do
                            if not before[frame] and frame:IsA("GuiObject") then CX.Register(frame, page, rule, config, method) end
                        end
                    end
                    CX.Refresh()
                    return table.unpack(result, 1, result.n)
                end
            end})
        end
        if TB and TB.Select then
            local selectPage = TB.Select
            TB.Select = function(key)
                selectPage(key)
                CX.Refresh()
            end
        end
        
        pcall(function()
