        local function CommonTop(B, b, toggleName, flag, opts)
            opts = opts or {}
            if opts.outside then
                b.Outside, b.UseHouse, b.UseMap = true, false, true
            end
            B:CreateToggle({
                Name = toggleName, Flag = flag, Default = false,
                Callback = function(v)
                    SetEnabled(b, v)
                    if b.OnToggle then pcall(b.OnToggle, v) end
                end,
            })
            if not opts.noTarget then
                b.TargetFlag = flag .. "Target"
                B:CreateDropdown({
                    Name = opts.targetName or "Follow", Flag = b.TargetFlag,
                    Items = ListTargets(), Default = "Me",
                    UpdateList = ListTargets,
                    Callback = function(v)
                        local name = nil
                        if type(v) == "string" and v ~= "Me" then
                            name = v:match("%(@([^%)]+)%)$")
                        end
                        if name ~= b.Target then
                            b.Target = name
                            if b.Def.Reset then pcall(b.Def.Reset, b) end
                        end
                    end,
                })
            end
            if not opts.noMaterial then
                local function MaterialList()
                    return opts.materials or ListToys()
                end
                B:CreateDropdown({
                    Name = "Material", Flag = flag .. "Material",
                    Items = MaterialList(), Default = opts.defaultMaterial or b.ToyName or DEFAULT_TOY,
                    UpdateList = MaterialList,
                    Callback = function(v)
                        if type(v) == "string" and v ~= "" and v ~= b.ToyName then
                            b.ToyName = v
                            if opts.onMaterialChange then opts.onMaterialChange(b) else Reshape(b) end
                        end
                    end,
                })
            end
        end

