        local ZAX, XAX, YAX = Vector3.new(0, 0, 1), Vector3.new(1, 0, 0), Vector3.new(0, 1, 0)
        do 
            local HX = {Gestures={Slap=true,Wave=true,["Thumbs Up"]=true,Victory=true,Fist=true,["Open Palm"]=true,["High Five"]=true,Clap=true}}
            function HX.CanAnimate(b)
                return b.Gesture=="Slap" or b.Gesture=="Wave" or b.Gesture=="High Five" or b.Gesture=="Clap"
            end
            function HX.Duration(b)
                if b.Gesture~="Slap" then return b.ActionDuration or 1.12 end
                return (b.Windup or 0.4)+(b.Swing or 0.22)+(b.ReturnTime or 0.5)
            end
            function HX.Victim(b)
                local name=b.Victim
                if not name then return nil,"NO TARGET" end
                local p=Players:FindFirstChild(name)
                -- KOZMOZ FIX: whitelisted players are valid targets again
                if not p or not p:IsA("Player") or p==LP then return nil,"INVALID TARGET" end
                if ANONIM_ShowAllTargets ~= true and ANONIM_IsWL and ANONIM_IsWL(p) then return nil,"INVALID TARGET" end
                local c=p.Character
                local r=c and c:FindFirstChild("HumanoidRootPart")
                local h=c and c:FindFirstChildOfClass("Humanoid")
                if not r or not h or h.Health<=0 then return nil,"WAITING FOR TARGET" end
                return r,"READY"
            end
            function HX.Check(b,root)
                if b.Gesture~="Slap" or b.Ghost then return true,nil,"READY" end
                local victim,status=HX.Victim(b)
                if not victim then return false,nil,status end
                if (victim.Position-root.Position).Magnitude>(b.MaxRange or 60) then return false,victim,"OUT OF RANGE" end
                return true,victim,"READY"
            end
            function HX.Collision(b)
                local solid=b.Gesture=="Slap" and not b.Ghost
                for _,slot in pairs(b.Slots) do
                    if slot then
                        slot.Solid,slot.NoCol=solid,nil
                        for _,part in ipairs(slot.Parts or {}) do if part.Parent then part.CanCollide=solid end end
                    end
                end
            end
            function HX.Reset(b) b.ActionT0,b.SlapT0,b.SlapDir=nil,nil,nil b.NextAction=0 HX.Collision(b) end
            function HX.Start(b,quiet)
                if UNL() then return false end
                if not b.Enabled then if not quiet then Notify("Hand Action","Turn on Slap Hand first.",2) end return false end
                if not HX.CanAnimate(b) then
                    if not quiet then Notify("Hand Action","This gesture is a static pose. Select Slap, Wave, High Five or Clap to play an action.",3) end
                    return false
                end
                local _,root=CharParts()
                if not root then return false end
                local ready,_,status=HX.Check(b,root)
                if not ready then if not quiet then Notify("Hand Action",status=="OUT OF RANGE" and "The target is outside the allowed range." or "Select a valid target or enable Ghost Preview.",3) end return false end
                local now=os.clock()
                if b.ActionT0 or now<(b.NextAction or 0) then
                    if not quiet then Notify("Hand Action",string.format("Action is cooling down: %.1f sec.",math.max(0,(b.NextAction or now)-now)),2) end
                    return false
                end
                b.ActionT0,b.SlapT0,b.SlapDir=now,now,nil
                b.NextAction=now+HX.Duration(b)+(b.Interval or 1)
                return true
            end
            function HX.Arc(b,vpos,away,angle)
                local r=CFrame.Angles(0,angle,0)*(-away)
                local tangent=UP:Cross(r)
                local fingers=(r+UP*0.25).Unit
                local pos=vpos+away*(b.ArmRadius or 14)+r*(b.ArmRadius or 14)
                return CFrame.fromMatrix(pos,fingers:Cross(tangent).Unit,fingers,tangent),tangent
            end
            function HX.Frame(b,char,root,hum,dt)
                local now=os.clock()
                if b.Victim and not Players:FindFirstChild(b.Victim) then
                    b.Victim,b.ActionT0,b.SlapT0=nil,nil,nil
                    UX.Flag("ANONIM_PBSlapVictim","None")
                    Notify("Hand Action","The target left. Target selection was cleared.",3)
                end
                local ready,victim,status=HX.Check(b,root)
                if b.Auto and HX.CanAnimate(b) and not b.ActionT0 and now>=(b.NextAction or 0) and ready then HX.Start(b,true) end
                local fwd=FlatLook(root.CFrame)
                local right=fwd:Cross(UP)
                local origin=root.Position+right*(b.Side or 10)+fwd*(b.Forward or 0)+UP*(b.Height or 4)
                local normal=fwd
                local idle=CFrame.fromMatrix(origin,UP:Cross(normal),UP,normal)
                local cf,velocity=idle,nil
                local phase=b.ActionT0 and (now-b.ActionT0) or 0
                local active=b.ActionT0~=nil
                if active and phase>=HX.Duration(b) then b.ActionT0,b.SlapT0,b.SlapDir=nil,nil,nil active=false end
                local progress=active and math.clamp(phase/HX.Duration(b),0,1) or 0
                if b.Gesture=="Slap" and active then
                    if not ready then b.ActionT0,b.SlapT0,b.SlapDir=nil,nil,nil active=false
                    else
                        local destination=victim and victim.Position or root.Position+fwd*math.max(10,(b.ArmRadius or 14)) + UP*(b.Height or 4)
                        if not b.SlapDir then
                            local away=Vector3.new(origin.X-destination.X,0,origin.Z-destination.Z)
                            b.SlapDir=away.Magnitude>0.1 and away.Unit or right
                        end
                        local angle=math.rad(b.ArcAngle or 72)
                        local windup,swing,back=b.Windup or 0.4,b.Swing or 0.22,b.ReturnTime or 0.5
                        local function ease(x)return x*x*(3-2*x)end
                        if phase<windup then cf=idle:Lerp(HX.Arc(b,destination,b.SlapDir,-angle),ease(phase/windup))
                        elseif phase<windup+swing then
                            local a=(phase-windup)/swing
                            local pose,tangent=HX.Arc(b,destination,b.SlapDir,-angle+2*angle*a)
                            cf=pose
                            if not b.Ghost then velocity=(tangent+UP*0.35).Unit*(150*(b.Power or 6)) end
                        else cf=HX.Arc(b,destination,b.SlapDir,angle):Lerp(idle,ease(math.clamp((phase-windup-swing)/back,0,1))) end
                    end
                elseif b.Gesture=="Wave" then
                    cf=idle*CFrame.Angles(0,0,math.sin(now*(active and 7 or 3))*0.45)
                elseif b.Gesture=="Thumbs Up" then cf=idle*CFrame.Angles(0,0,-math.pi/2*(b.HandSide=="Left" and -1 or 1))
                elseif b.Gesture=="High Five" and active then cf=idle*CFrame.new(0,math.sin(progress*math.pi)*b.Unit,math.sin(progress*math.pi)*b.Unit*2)
                end
                local second
                if b.Gesture=="Clap" then
                    local center=root.Position+fwd*math.max(8,b.Forward or 8)+UP*(b.Height or 4)
                    local spacing=active and (0.05+math.abs(math.cos(progress*math.pi*2))*2.5) or 3.2
                    cf=CFrame.fromMatrix(center-right*spacing*b.Unit,UP:Cross(right),UP,right)
                    second=CFrame.fromMatrix(center+right*spacing*b.Unit,UP:Cross(-right),UP,-right)
                end
                local remaining=math.max(0,(b.NextAction or 0)-now)
                local displayStatus=active and "PLAYING" or remaining>0 and string.format("COOLDOWN %.1fs",remaining) or status
                UX.Text(b.StatusLabel,b.Gesture.." | "..displayStatus..(b.Gesture=="Slap" and b.Ghost and " | GHOST PREVIEW" or ""))
                return {CF=cf,Second=second,Vel=velocity,U=b.Unit*(b.Size or 1),Active=active,Progress=progress,Gesture=b.Gesture,Time=now}
            end
            function HX.Piece(b,index,ctx)
                local hand=math.floor((index-1)/15)+1
                local i=(index-1)%15+1
                local cf=hand==2 and ctx.Second or ctx.CF
                if not cf then return nil end
                local U=ctx.U
                local mirror=b.HandSide=="Left" and -1 or 1
                if b.Gesture=="Clap" then mirror=hand==1 and 1 or -1 end
                local curl=0.12
                if ctx.Gesture=="Fist" or ctx.Gesture=="Thumbs Up" then curl=1.5 end
                if i<=4 then
                    local x=(i%2==1 and -0.5 or 0.5)*mirror
                    local y=i<=2 and 0.5 or -0.5
                    return cf*FrameCF(Vector3.new(x*U,y*U,0),YAX,ZAX)
                elseif i<=12 then
                    local finger=math.floor((i-5)/2)
                    local seg=(i-5)%2
                    if ctx.Gesture=="Victory" then curl=(finger==0 or finger==1) and 0 or 1.5 end
                    local x=(-0.75+finger*0.5)*U*mirror
                    if seg==0 then
                        local d=Vector3.new(0,math.cos(curl*0.45),math.sin(curl*0.45))
                        return cf*FrameCF(Vector3.new(x,U,0)+d*0.5*U,d,XAX)
                    end
                    local base=Vector3.new(x,U,0)+Vector3.new(0,math.cos(curl*0.45),math.sin(curl*0.45))*U
                    local d=Vector3.new(0,math.cos(curl),math.sin(curl))
                    return cf*FrameCF(base+d*0.5*U,d,XAX)
                elseif i<=14 then
                    local base=Vector3.new(-U*mirror,-0.1*U,0)
                    local d=Vector3.new(-0.6*mirror,0.8,ctx.Gesture=="Fist" and 0.9 or 0.15).Unit
                    return cf*FrameCF(base+d*(i==13 and 0.5 or 1.5)*U,d,ZAX)
                end
                return cf*FrameCF(Vector3.new(0,-1.5*U,0),YAX,ZAX)
            end
            local Slap=NewBuild("Slap Hand",{
                Count=function(b)return b.Gesture=="Clap" and 30 or 15 end,
                Solid=function(b)return b.Gesture=="Slap" and not b.Ghost end,SafeSelf=true,
                Reset=HX.Reset,Frame=HX.Frame,Place=HX.Piece,Vel=function(b,index,ctx)return ctx.Vel end,
            },{Gesture="Slap",Ghost=true,HandSide="Right",Side=10,Forward=0,Height=4,Size=1,Power=6,Interval=1,Auto=false,
                MaxRange=60,Windup=0.4,Swing=0.22,ReturnTime=0.5,ActionDuration=1.12,ArcAngle=72,ArmRadius=14,AutoRepair=true})
            local function ListVictims()
                local list=ListTargets()
                list[1]="None"
                return list
            end
            local function ToggleHand()if not UNL() then UX.Flag("ANONIM_PBSlap",not Slap.Enabled) end end
            local function Action()HX.Start(Slap,false)end
            function HX.Mobile(b,which,value)
                b.MobileWanted=b.MobileWanted or {}
                b.MobileWanted[which]=value and true or false
                local function update()
                    local api=ANONIM_MobileBtnAPI
                    if not api or not api.Create or not api.Buttons then return false end
                    local name=which=="Toggle" and "Slap Hand" or "Hand Action"
                    api.Short=api.Short or {} api.Short["Hand Action"]="HAND\nACTION"
                    local existing=api.Buttons[name]
                    if not (existing and existing.Parent) and value then pcall(api.Create,name) end
                    local button=api.Buttons[name]
                    if button then
                        button.Visible=b.MobileWanted[which] and (which~="Action" or HX.CanAnimate(b))
                        if which=="Toggle" then button.Text=b.Enabled and "HAND\nON" or "HAND\nOFF" end
                    end
                    return true
                end
                if update() or not value then return end
                task.spawn(function()
                    for _=1,300 do
                        if UNL() or not b.MobileWanted[which] then return end
                        task.wait(0.2)
                        if update() then return end
                    end
                    if not UNL() and b.MobileWanted[which] then
                        Notify("Mobile Controls","The mobile button service is not ready. Toggle this option again after the interface finishes loading.",5)
                    end
                end)
            end
            Slap.OnToggle=function()
                if Slap.MobileWanted then for which,value in pairs(Slap.MobileWanted) do HX.Mobile(Slap,which,value) end end
            end
            ANONIM_MobileActions=ANONIM_MobileActions or {}
            ANONIM_MobileActions["Slap Hand"]=ToggleHand
            ANONIM_MobileActions["Hand Action"]=Action

            local B=Page("Slap", Slap)
            CommonTop(B,Slap,"Slap Hand","ANONIM_PBSlap",{outside=true,noTarget=true,noMaterial=true})
            B:CreateDropdown({Name="Gesture",Flag="ANONIM_PBHandGesture",Items={"Slap","Wave","Thumbs Up","Victory","Fist","Open Palm","High Five","Clap"},Default="Slap",
                Callback=function(v) if HX.Gestures[v] and v~=Slap.Gesture then Slap.Gesture=v HX.Reset(Slap) UX.Reconfigure(Slap) if Slap.OnToggle then Slap.OnToggle() end end end})
            B:CreateToggle({Name="Ghost Preview",Flag="ANONIM_PBHandGhost",Default=true,
                Callback=function(v) Slap.Ghost=v and true or false Slap.ActionT0,Slap.SlapT0=nil,nil HX.Collision(Slap) end})
            B:CreateLabel({Text="Preview has no target, collision or impact.",ContextKey="GhostHelp"})
            B:CreateDropdown({Name="Hand",Flag="ANONIM_PBHandSide",Items={"Right","Left"},Default="Right",Callback=function(v) Slap.HandSide=v or "Right" end})
            B:CreateDropdown({Name="Target",Flag="ANONIM_PBSlapVictim",Items=ListVictims(),Default="None",UpdateList=ListVictims,
                Callback=function(v) Slap.Victim=ParseTarget(v) Slap.ActionT0,Slap.SlapT0=nil,nil end})
            B:CreateSlider({Name="Maximum Range",Flag="ANONIM_PBHandRange",Min=10,Max=200,Default=60,Rounding=0,Callback=function(v) Slap.MaxRange=tonumber(v) or 60 end})
            B:CreateSlider({Name="Power",Flag="ANONIM_PBSlapPower",Min=1,Max=10,Default=6,Rounding=1,Callback=function(v) Slap.Power=tonumber(v) or 6 end})
            B:CreateDivider("Action")
            B:CreateButton({Name="Play Hand Action",Callback=Action})
            B:CreateKeybind({Name="Action Key",Flag="ANONIM_PBSlapActionKey",Default={Name="None"},Callback=Action})
            B:CreateToggle({Name="Auto Action",Flag="ANONIM_PBSlapAuto",Default=false,Callback=function(v) Slap.Auto=v and true or false end})
            B:CreateSlider({Name="Action Cooldown (sec)",Flag="ANONIM_PBHandInterval",Min=0.2,Max=10,Default=1,Rounding=1,Callback=function(v) Slap.Interval=tonumber(v) or 1 end})
            B:CreateSlider({Name="Action Duration (sec)",Flag="ANONIM_PBHandActionDuration",Min=0.3,Max=5,Default=1.12,Rounding=2,Callback=function(v) Slap.ActionDuration=tonumber(v) or 1.12 end})
            B:CreateSlider({Name="Windup Time (sec)",Flag="ANONIM_PBHandWindup",Min=0.1,Max=1.5,Default=0.4,Rounding=2,Callback=function(v) Slap.Windup=tonumber(v) or 0.4 end})
            B:CreateSlider({Name="Swing Time (sec)",Flag="ANONIM_PBHandSwing",Min=0.1,Max=1,Default=0.22,Rounding=2,Callback=function(v) Slap.Swing=tonumber(v) or 0.22 end})
            B:CreateSlider({Name="Return Time (sec)",Flag="ANONIM_PBHandReturn",Min=0.1,Max=2,Default=0.5,Rounding=2,Callback=function(v) Slap.ReturnTime=tonumber(v) or 0.5 end})
            B:CreateSlider({Name="Arc Angle (deg)",Flag="ANONIM_PBHandArc",Min=15,Max=100,Default=72,Rounding=0,Callback=function(v) Slap.ArcAngle=tonumber(v) or 72 end})
            B:CreateSlider({Name="Arm Radius",Flag="ANONIM_PBHandArm",Min=6,Max=30,Default=14,Rounding=0,Callback=function(v) Slap.ArmRadius=tonumber(v) or 14 end})
            B:CreateDivider("Placement")
            B:CreateSlider({Name="Distance (Left/Right)",Flag="ANONIM_PBSlapSide",Min=-40,Max=40,Default=10,Rounding=0,Callback=function(v) Slap.Side=tonumber(v) or 10 end})
            B:CreateSlider({Name="Forward Offset",Flag="ANONIM_PBHandForward",Min=-30,Max=30,Default=0,Rounding=0,Callback=function(v) Slap.Forward=tonumber(v) or 0 end})
            B:CreateSlider({Name="Height",Flag="ANONIM_PBHandHeight",Min=0,Max=30,Default=4,Rounding=0,Callback=function(v) Slap.Height=tonumber(v) or 4 end})
            B:CreateSlider({Name="Size",Flag="ANONIM_PBHandSize",Min=0.6,Max=1.5,Default=1,Rounding=1,Callback=function(v) Slap.Size=tonumber(v) or 1 end})
            B:CreateDivider("Mobile and Maintenance")
            B:CreateKeybind({Name="Slap Hand Key",Flag="ANONIM_PBSlapKey",Default={Name="None"},Callback=ToggleHand})
            B:CreateToggle({Name="Show Mobile Toggle",Flag="ANONIM_PBSlapMobile",Default=false,Callback=function(v) HX.Mobile(Slap,"Toggle",v) end})
            B:CreateToggle({Name="Show Mobile Action",Flag="ANONIM_PBHandMobileAction",Default=false,Callback=function(v) HX.Mobile(Slap,"Action",v) end})
            B:CreateToggle({Name="Auto Repair",Flag="ANONIM_PBHandRepair",Default=true,Callback=function(v) Slap.AutoRepair=v and true or false if v then Slap.NeedFill=true end end})
            Slap.StatusLabel=B:CreateLabel({Text="Slap | READY | GHOST PREVIEW"})
            CommonBottom(B,Slap,"ANONIM_PBSlap")
        end

        CX.Refresh()
        UX.BudgetUI()

        pcall(function()
            local D = Tabs.Defense:CreateBlock({Name = "Auto Owner", Side = "Right", Icon = "home"})
            AO.Flags[#AO.Flags + 1] = "ANONIM_AutoOwner"
            D:CreateToggle({
                Name = "Auto Owner (Keep House)", Flag = "ANONIM_AutoOwner", Default = false,
                Callback = function(v) AO.Set(v, "ANONIM_AutoOwner") end,
            })
            D:CreateSlider({
                Name = "Refresh Every (sec)", Flag = "ANONIM_AutoOwnerInterval",
                Min = 20, Max = 85, Default = 60, Rounding = 0,
                Callback = function(v) AO.Interval = tonumber(v) or 60 end,
            })
            D:CreateButton({
                Name = "Refresh House Now",
                Callback = function()
                    if AO.Busy then return end
                    if AO.HasPass then
                        Notify("Auto Owner", "You have Infinite House Time, no need.", 3)
                        return
                    end
                    local plot = MyPlot()
                    if not plot then
                        Notify("Auto Owner", "You do not own a house.", 3)
                        return
                    end
                    task.spawn(function()
                        AO.Busy = true
                        pcall(AO.Refresh, plot)
                        AO.Busy = false
                        AO.LastInside = os.clock()
                    end)
                end,
            })
            AO.Label = D:CreateLabel({Text = "Status: Off"})
            D:CreateLabel({Text = "Quick TP into your house and back before the timer ends."})
        end)

        task.spawn(function()
            while not UNL() do
                task.wait(0.5)
            end
            for _, b in ipairs(PB.Builds) do
                b.Enabled = false
                b.Gen = b.Gen + 1
                StopLoop(b)
                pcall(DestroyAll, b)
            end
        end)
    end)
    if not okPB then
        warn("[ANONIM] Pallet Builds failed to load: " .. tostring(errPB))
    end
end
