				obj[stickyWeld] = nil
				tbl12.UntrackBrokenPart(v20, stickyWeld)
				tbl12.SetRuntimeConnection(str5, nil, false)
				tbl12.SetRuntimeConnection(str5 .. "Cleanup", nil, false)
			end)

			local v21 = enabled
