		local FTAPRGBSpeed = 2.8
		local FTAPCrosshairTransparency = 0
		local FTAPCrosshairScale = 1.3
		local FTAPRGBCrosshairConn = nil
		local CustomCursorColorEnabled = false
		local FTAPRGBEnabled = false
		local FTAPOriginalSizes = {}
		local FTAPOriginalColors = {}

		local function CacheFTAPOriginal()
			local lp = game:GetService("Players").LocalPlayer
			if not (lp and lp.PlayerGui and lp.PlayerGui:FindFirstChild("Crosshairs")) then
				return
			end

			FTAPOriginalColors = {}
			FTAPOriginalSizes = {}

			for _, parent in ipairs({
				lp.PlayerGui.Crosshairs:FindFirstChild("CrosshairsFrame"),
				lp.PlayerGui.Crosshairs:FindFirstChild("Dot"),
			}) do
				if parent then
					for _, f in ipairs(parent:GetChildren()) do
						if f:IsA("Frame") then
							FTAPOriginalColors[f] = f.BackgroundColor3
							FTAPOriginalSizes[f] = f.Size
						end
					end
				end
			end
		end

		local function ApplyToFTAPCrosshairs(color)
			local lp = game:GetService("Players").LocalPlayer
			if not (lp and lp.PlayerGui and lp.PlayerGui:FindFirstChild("Crosshairs")) then
				return
			end

			for _, parent in ipairs({
				lp.PlayerGui.Crosshairs:FindFirstChild("CrosshairsFrame"),
				lp.PlayerGui.Crosshairs:FindFirstChild("Dot"),
			}) do
				if parent then
					for _, f in ipairs(parent:GetChildren()) do
						if f:IsA("Frame") then
							if color then
								f.BackgroundColor3 = color
							end
							f.BackgroundTransparency = FTAPCrosshairTransparency
						end
					end
				end
			end
		end

		local function RestoreFTAPOriginalColors()
			local lp = game:GetService("Players").LocalPlayer
			if not (lp and lp.PlayerGui and lp.PlayerGui:FindFirstChild("Crosshairs")) then
				return
			end

			for f, c in pairs(FTAPOriginalColors) do
				if f and f.Parent then
					f.BackgroundColor3 = c
					f.BackgroundTransparency = FTAPCrosshairTransparency
				end
			end
		end

		local function ApplyFTAPScale()
			local lp = game:GetService("Players").LocalPlayer
			if not (lp and lp.PlayerGui and lp.PlayerGui:FindFirstChild("Crosshairs")) then
				return
			end

			for _, parent in ipairs({
				lp.PlayerGui.Crosshairs:FindFirstChild("CrosshairsFrame"),
				lp.PlayerGui.Crosshairs:FindFirstChild("Dot"),
			}) do
				if parent then
					for _, f in ipairs(parent:GetChildren()) do
						if f:IsA("Frame") and FTAPOriginalSizes[f] then
							f.Size = UDim2.new(
								FTAPOriginalSizes[f].X.Scale * FTAPCrosshairScale,
								FTAPOriginalSizes[f].X.Offset * FTAPCrosshairScale,
								FTAPOriginalSizes[f].Y.Scale * FTAPCrosshairScale,
								FTAPOriginalSizes[f].Y.Offset * FTAPCrosshairScale
							)
						end
					end
				end
			end
		end

		local function RefreshFTAPCrosshair()
			if FTAPRGBCrosshairConn then
				FTAPRGBCrosshairConn:Disconnect()
				FTAPRGBCrosshairConn = nil
			end
			if FTAPRGBEnabled then
				FTAPRGBCrosshairConn = game:GetService("RunService").Heartbeat:Connect(function()
					local t = tick() * FTAPRGBSpeed
					local color = Color3.fromRGB(math.sin(t) * 127 + 128, math.sin(t + 2) * 127 + 128, math.sin(t + 4) * 127 + 128)
					ApplyToFTAPCrosshairs(color)
				end)
			elseif CustomCursorColorEnabled then
				ApplyToFTAPCrosshairs(FTAPCrosshairColor)
			else
				RestoreFTAPOriginalColors()
			end
		end

		task.spawn(function()
			task.wait(0.5)
			CacheFTAPOriginal()
		end)

