				local fakeBlackholes = {}
		local fakeBHSettings = {
			FakeBHDuration = 6,
			FakeBHSize = 10,
			FakeBHSpinSpeed = 2,
			FakeBHInnerSpinSpeed = 4,
			FakeBHExpandTime = 2,
			FakeBHShrinkTime = 1.5,
			FakeBHShowName = false,
		}

		local function spawnFakeBlackhole(position, fakeName)
			local container = Instance.new("Folder")
			container.Name = "FakeBlackhole"
			container.Parent = workspace
			table.insert(fakeBlackholes, container)

			local hole = Instance.new("Part")
			hole.Name = "BlackHole"
			hole.Shape = Enum.PartType.Ball
			hole.Material = Enum.Material.Neon
			hole.Color = tbl9.CustomBHColor or Color3.new(0, 0, 0)
			hole.Size = Vector3.new(0.05, 0.05, 0.05)
			hole.Position = position
			hole.Anchored = true
			hole.CanCollide = false
			hole.CanTouch = false
			hole.CanQuery = false
			hole.CastShadow = false
			hole.Parent = container

			local swirlGui = Instance.new("BillboardGui")
			swirlGui.Name = "SwirlGui"
			swirlGui.Adornee = hole
			swirlGui.Size = UDim2.new(0, 0, 0, 0)
			swirlGui.AlwaysOnTop = false
			swirlGui.LightInfluence = 0
			swirlGui.Parent = hole

			local function makeSwirl(scale)
				local lbl = Instance.new("ImageLabel")
				lbl.Size = UDim2.new(scale, 0, scale, 0)
				lbl.AnchorPoint = Vector2.new(0.5, 0.5)
				lbl.Position = UDim2.new(0.5, 0, 0.5, 0)
				lbl.BackgroundTransparency = 1
				lbl.Image = "rbxassetid://95669290540702"
				lbl.ImageColor3 = tbl9.CustomBHColor or Color3.new(0, 0, 0)
				lbl.ImageTransparency = 0
				lbl.Parent = swirlGui
				return lbl
			end

			local outerSwirl = makeSwirl(1)
			local midSwirl = makeSwirl(0.75)
			local innerSwirl = makeSwirl(0.5)

			if fakeName and fakeName ~= "" then
				local nameBillboard = Instance.new("BillboardGui")
				nameBillboard.Name = "NameGui"
				nameBillboard.Adornee = hole
				nameBillboard.Size = UDim2.fromOffset(280, 36)
				nameBillboard.AlwaysOnTop = true
				nameBillboard.LightInfluence = 0
				nameBillboard.MaxDistance = 50
				nameBillboard.Parent = hole

				local frame = Instance.new("Frame")
				frame.Size = UDim2.fromScale(1, 1)
				frame.BackgroundTransparency = 1
				frame.Parent = nameBillboard

				local nameLabel = Instance.new("TextLabel")
				nameLabel.Size = UDim2.fromScale(1, 1)
				nameLabel.BackgroundTransparency = 1
				nameLabel.Text = fakeName
				nameLabel.TextColor3 = Color3.new(1, 1, 1)
				nameLabel.Font = Enum.Font.BuilderSans
				nameLabel.TextSize = 17
				nameLabel.TextScaled = false
				nameLabel.TextXAlignment = Enum.TextXAlignment.Center
				nameLabel.TextYAlignment = Enum.TextYAlignment.Center
				nameLabel.Parent = frame

				local running = true
				task.spawn(function()
					while running and hole.Parent and nameBillboard.Parent do
						local char = game:GetService("Players").LocalPlayer.Character
						local root = char and char:FindFirstChild("HumanoidRootPart")
						if root then
							nameBillboard.Enabled = (root.Position - hole.Position).Magnitude < 50
						end
						task.wait(0.25)
					end
				end)
				hole.AncestryChanged:Connect(function(_, parent)
					if not parent then running = false end
				end)
			end

			local finalSize = fakeBHSettings.FakeBHSize
			local expandInfo = TweenInfo.new(fakeBHSettings.FakeBHExpandTime, Enum.EasingStyle.Quart, Enum.EasingDirection.Out)
			local shrinkInfo = TweenInfo.new(fakeBHSettings.FakeBHShrinkTime, Enum.EasingStyle.Back, Enum.EasingDirection.In)

			game:GetService("TweenService"):Create(hole, expandInfo, {
				Size = Vector3.new(finalSize, finalSize, finalSize),
			}):Play()
			game:GetService("TweenService"):Create(swirlGui, expandInfo, {
				Size = UDim2.new(finalSize * 1.8, 0, finalSize * 1.8, 0),
			}):Play()

			local spinning = true
			task.spawn(function()
				while spinning and hole.Parent do
					outerSwirl.Rotation = outerSwirl.Rotation + fakeBHSettings.FakeBHSpinSpeed
					midSwirl.Rotation = midSwirl.Rotation - (fakeBHSettings.FakeBHSpinSpeed * 1.5)
					innerSwirl.Rotation = innerSwirl.Rotation + (fakeBHSettings.FakeBHInnerSpinSpeed * 2)
					task.wait(0.03)
				end
			end)

			task.delay(fakeBHSettings.FakeBHDuration, function()
				spinning = false
				local shrinkHole = game:GetService("TweenService"):Create(hole, shrinkInfo, {
					Size = Vector3.new(0.05, 0.05, 0.05),
				})
				local shrinkGui = game:GetService("TweenService"):Create(swirlGui, shrinkInfo, {
					Size = UDim2.new(0, 0, 0, 0),
				})
				shrinkHole:Play()
				shrinkGui:Play()
				shrinkHole.Completed:Once(function()
					if container and container.Parent then
						container:Destroy()
					end
					for i, v in ipairs(fakeBlackholes) do
						if v == container then
							table.remove(fakeBlackholes, i)
							break
						end
					end
				end)
			end)

			return container
		end

		-- v24: Fake Kick paneli kullanabilsin
		pcall(function()
			getgenv().KOZMOZ_FAKE_BH = spawnFakeBlackhole
			getgenv().KOZMOZ_FAKE_BH_SETTINGS = fakeBHSettings
		end)

