		-- v25: spawn the selected blackhole model once (for fake kick)
		pcall(function()
			getgenv().KOZMOZ_SPAWN_SELECTED_BH = function(pos)
					local sel = CosmicBlackhole.Selected
					if not sel or sel == "None" then
						return false
					end
					if sel == "Random" then
						local choices = { "Void", "Dark Void", "Sand Storm", "Elite Purple", "Realistic Blackhole" }
						sel = choices[math.random(1, #choices)]
					end
					local option = CosmicBlackhole.Options[sel]
				if not option then
					return false
				end
				local assetId = option.Id
				local model = nil
				pcall(function()
					local ok, res = pcall(function()
						return game:GetObjects(assetId)[1]
					end)
					if ok and res then
						model = res
					end
				end)
				if not model then
					pcall(function()
						local cleanId = tonumber((assetId:gsub("rbxassetid://", "")))
						if cleanId then
							local ok, res = pcall(function()
								return game:GetService("InsertService"):LoadAsset(cleanId)
							end)
							if ok and res then
								model = res:GetChildren()[1]
							end
						end
					end)
				end
				if not model then
					return false
				end
				local holder = Instance.new("Part")
				holder.Name = "KOZMOZ_FakeKickBH"
				holder.Anchored = true
				holder.CanCollide = false
				holder.CanQuery = false
				holder.CanTouch = false
				holder.Transparency = 1
				holder.Size = Vector3.new(1, 1, 1)
				holder.CFrame = CFrame.new(pos)
				holder.Parent = workspace

				model.Name = "CosmicMesh"
				model.Parent = holder
				pcall(function()
					for _, desc in ipairs(model:GetDescendants()) do
						if desc:IsA("AnimationController") or desc:IsA("Animator") or desc:IsA("Animation") then
							desc:Destroy()
						end
					end
				end)
				pcall(function()
					if model:IsA("Model") then
						model:PivotTo(CFrame.new(pos) * CFrame.Angles(math.rad(-90), 0, 0))
						if model.ScaleTo then
							model:ScaleTo(model:GetScale() * (option.Scale or 1))
						end
					end
				end)
				task.spawn(function()
					local t0 = os.clock()
					while holder.Parent and os.clock() - t0 < 8 do
						if model and model.Parent and model:IsA("Model") then
							pcall(function()
								model:PivotTo(model:GetPivot() * CFrame.Angles(0, math.rad(4), 0))
							end)
						end
						task.wait(0.05)
					end
					pcall(function()
						holder:Destroy()
					end)
				end)
				return true
			end
		end)

		local function CosmicBlackholeWipeOriginal(bh)
			if not bh then return end
			for _, desc in ipairs(bh:GetDescendants()) do
				if desc:IsA("BasePart") or desc:IsA("MeshPart") or desc:IsA("UnionOperation") then
					desc.Transparency = 1
					desc.CastShadow = false
				elseif desc:IsA("ParticleEmitter") or desc:IsA("Trail") or desc:IsA("Beam") or desc:IsA("Smoke") or desc:IsA("Fire") or desc:IsA("Sparkles") then
					desc.Enabled = false
				elseif desc:IsA("PointLight") or desc:IsA("SpotLight") or desc:IsA("SurfaceLight") then
					desc.Enabled = false
				elseif desc:IsA("Decal") or desc:IsA("Texture") then
					desc.Transparency = 1
				elseif desc:IsA("BillboardGui") or desc:IsA("SurfaceGui") then
					desc.Enabled = false
				end
			end
			if bh:IsA("BasePart") then
				bh.Transparency = 1
			end
			if bh:IsA("Model") and bh.PrimaryPart then
				bh.PrimaryPart.Transparency = 1
			end
		end

		local function CosmicBlackholeRestoreOriginal(bh)
			if not bh then return end
			for _, desc in ipairs(bh:GetDescendants()) do
				if desc:IsA("BasePart") or desc:IsA("MeshPart") or desc:IsA("UnionOperation") then
					desc.Transparency = 0
				elseif desc:IsA("ParticleEmitter") or desc:IsA("Trail") or desc:IsA("Beam") or desc:IsA("Smoke") or desc:IsA("Fire") or desc:IsA("Sparkles") then
					desc.Enabled = true
				elseif desc:IsA("PointLight") or desc:IsA("SpotLight") or desc:IsA("SurfaceLight") then
					desc.Enabled = true
				elseif desc:IsA("Decal") or desc:IsA("Texture") then
					desc.Transparency = 0
				elseif desc:IsA("BillboardGui") or desc:IsA("SurfaceGui") then
					desc.Enabled = true
				end
			end
			if bh:IsA("BasePart") then
				bh.Transparency = 0
			end
			if bh:IsA("Model") and bh.PrimaryPart then
				bh.PrimaryPart.Transparency = 0
			end
		end

		local function CosmicBlackholeCleanup(bh)
			if not bh then return end
			local data = CosmicBlackhole.Active[bh]
			if not data then return end
			if data.Anim then
				pcall(function() data.Anim:Disconnect() end)
			end
			if data.Model then
				pcall(function() data.Model:Destroy() end)
			end
			CosmicBlackholeRestoreOriginal(bh)
			CosmicBlackhole.Active[bh] = nil
		end

		local function CosmicBlackholeBuild(bh)
			if not bh or not bh.Parent then return end
			if CosmicBlackhole.Active[bh] then return end

				local hole = bh:FindFirstChild("Hole") or bh:FindFirstChildWhichIsA("BasePart")
				if not hole then return end

				CosmicBlackholeWipeOriginal(bh)

				local selectedName = CosmicBlackhole.Selected
				if selectedName == "Random" then
					local choices = { "Void", "Dark Void", "Sand Storm", "Elite Purple", "Realistic Blackhole" }
					selectedName = choices[math.random(1, #choices)]
				end
				local option = CosmicBlackhole.Options[selectedName] or CosmicBlackhole.Options["Space Blackhole"]
				if not option then return end
				local offsetY = option.OffsetY or 0
				local pos = hole.Position + Vector3.new(0, offsetY, 0)

			local data = {
				Time = 0,
				Hole = hole,
				Anim = nil,
				Model = nil,
				SpinSpeed = 0.8,
					Scale = option.Scale,
					OffsetY = offsetY,
					StartTime = tick(),
			}

			local assetId = option.Id
			local model = nil
			local success, result = pcall(function()
				return game:GetObjects(assetId)[1]
			end)
			if success and result then
				model = result
			end
			if not model then
				local cleanId = tonumber((assetId:gsub("rbxassetid://", "")))
				if cleanId then
					success, result = pcall(function()
						return game:GetService("InsertService"):LoadAsset(cleanId)
					end)
					if success and result then
						model = result:GetChildren()[1]
					end
				end
			end
			if not model then
				CosmicBlackholeRestoreOriginal(bh)
				return
			end

			model.Parent = bh
			model.Name = "CosmicMesh"

			for _, desc in ipairs(model:GetDescendants()) do
				if desc:IsA("AnimationController") or desc:IsA("Animator") or desc:IsA("Animation") then
					desc:Destroy()
				end
			end

			if model:IsA("Model") then
				for _, part in ipairs(model:GetDescendants()) do
					if part:IsA("BasePart") or part:IsA("MeshPart") then
						part.Anchored = true
						part.CanCollide = false
						part.CastShadow = false
						part.Size = part.Size * 0.01
					end
					if part:IsA("Smoke") or part:IsA("ParticleEmitter") then
						if part.Name:lower():find("smog") or part.Name:lower():find("fog") or part.Name:lower():find("mist") or part.Name:lower():find("haze") or part.Name:lower():find("cloud") then
							part:Destroy()
						end
					end
				end

				local offset = Vector3.zero
				if model.PrimaryPart then
					offset = pos - model.PrimaryPart.Position
					model:SetPrimaryPartCFrame(model.PrimaryPart.CFrame + offset)
				else
					local firstPart = nil
					for _, part in ipairs(model:GetDescendants()) do
						if part:IsA("BasePart") then
							firstPart = part
							break
						end
					end
					if firstPart then
						offset = pos - firstPart.Position
						for _, part in ipairs(model:GetDescendants()) do
							if part:IsA("BasePart") then
								part.CFrame = part.CFrame + offset
							end
						end
					end
				end

				data.Model = model
				data.Anim = game:GetService("RunService").Heartbeat:Connect(function(dt)
					if not bh or not bh.Parent then
						CosmicBlackholeCleanup(bh)
						return
					end
					local currentPos = hole.Position + Vector3.new(0, data.OffsetY or 0, 0)
					data.Time = data.Time + dt * data.SpinSpeed
					if data.Model then
						if data.Model:IsA("Model") then
							if data.Model.PrimaryPart then
								data.Model:SetPrimaryPartCFrame(CFrame.new(currentPos) * CFrame.Angles(0, data.Time, 0))
							else
								for _, part in ipairs(data.Model:GetDescendants()) do
									if part:IsA("BasePart") then
										part.CFrame = CFrame.new(currentPos) * CFrame.Angles(0, data.Time, 0)
									end
								end
							end
							for _, part in ipairs(data.Model:GetDescendants()) do
								if part:IsA("BasePart") or part:IsA("MeshPart") then
									if not part:GetAttribute("BaseSize") then
										part:SetAttribute("BaseSize", part.Size / 0.01)
									end
									local baseSize = part:GetAttribute("BaseSize")
									part.Size = baseSize * data.Scale
								end
							end
						elseif data.Model:IsA("BasePart") then
							data.Model.CFrame = CFrame.new(currentPos) * CFrame.Angles(0, data.Time, 0)
							if not data.Model:GetAttribute("BaseSize") then
								data.Model:SetAttribute("BaseSize", data.Model.Size / 0.01)
							end
							data.Model.Size = data.Model:GetAttribute("BaseSize") * data.Scale
						end
					end
				end)
			elseif model:IsA("BasePart") then
				model.Anchored = true
				model.CanCollide = false
				model.CastShadow = false
				model.Size = model.Size * 0.01
				model.CFrame = CFrame.new(pos)
				data.Model = model
				data.Anim = game:GetService("RunService").Heartbeat:Connect(function(dt)
					if not bh or not bh.Parent then
						CosmicBlackholeCleanup(bh)
						return
					end
					local currentPos = hole.Position + Vector3.new(0, data.OffsetY or 0, 0)
					data.Time = data.Time + dt * data.SpinSpeed
					if data.Model then
						data.Model.CFrame = CFrame.new(currentPos) * CFrame.Angles(0, data.Time, 0)
						if not data.Model:GetAttribute("BaseSize") then
							data.Model:SetAttribute("BaseSize", data.Model.Size / 0.01)
						end
						data.Model.Size = data.Model:GetAttribute("BaseSize") * data.Scale
					end
				end)
			end

			bh.AncestryChanged:Connect(function()
				if not bh.Parent then
					CosmicBlackholeCleanup(bh)
				end
			end)

			CosmicBlackhole.Active[bh] = data
		end

		local function CosmicBlackholeStartSystem()
			if CosmicBlackhole.Connection then return end
			CosmicBlackhole.Connection = workspace.ChildAdded:Connect(function(obj)
				if not CosmicBlackhole.Enabled then return end
				if obj.Name:lower():find("blackhole") then
					task.wait(0.2)
					CosmicBlackholeBuild(obj)
				end
			end)
		end

