		local function fn21(arg)
			for _, v25 in tbl18, nil, nil do
				local v26 = toggles[v25[1]]
				if v26 and v26.Value and v25[3](arg) then
					return v25
				end
			end

			return false
		end

		local function fn22(arg)
			if not arg:IsA("Sound") then
				return
			end
			local v25 = fn21(arg)
			local v26 = tbl17[arg]

			if v25 then
				if not v26 then
					local tbl19 = { arg.Volume }
					tbl17[arg] = tbl19

					if v25[4] then
						tbl19[2] = arg:GetPropertyChangedSignal("Volume"):Connect(function()
							if fn21(arg) and arg.Volume ~= 0 then
								arg.Volume = 0
							end
						end)
					end
				end

				arg.Volume = 0
			elseif v26 then
				tbl17[arg] = nil

				if v26[2] then
					v26[2]:Disconnect()
				end

				if arg.Parent then
					arg.Volume = v26[1]
				end
			end
		end

		local function fn23(arg)
			local flag12 = false

			for _, v25 in tbl18, nil, nil do
				flag12 = flag12 or toggles[v25[1]].Value
			end

			tbl12.SetRuntimeConnection("MutedSounds", workspace.DescendantAdded, flag12, fn22)

			for k in tbl17, nil, nil do
				fn22(k)
			end

			if arg then
				for _, v25 in workspace:QueryDescendants("Sound") do
					fn22(v25)
				end
			end
		end

		tbl12.ClearMutedSounds = function()
			tbl12.SetRuntimeConnection("MutedSounds", nil, false)

			for k, v25 in tbl17, nil, nil do
				if v25[2] then
					v25[2]:Disconnect()
				end

				if k.Parent then
					k.Volume = v25[1]
				end
			end

			table.clear(tbl17)
		end

		for _, v25 in tbl18, nil, nil do
			v24:AddToggle(v25[1], {
				Text = v25[2],
				Default = false,
				Callback = function(arg)
					fn23(arg)
				end,
			})
		end
	end

	do
		-- KOZMOZ FIX: do NOT touch the game's Lighting/Sky at startup.
		-- The weather stays exactly as the game set it (no forced daytime / night).
		local Sky = tbl15.Visual:AddLeftGroupbox("Sky", "cloud-sun")
		local sky = Lighting:FindFirstChildOfClass("Sky")
		local weather = getgenv().KozmozOriginalWeather
		local tbl16 = { Created = false, ClockTime = weather and weather.ClockTime or Lighting.ClockTime }

		if sky then
			tbl16.Instance = sky
			tbl16.SunAngularSize = sky.SunAngularSize
			tbl16.SkyboxBk = sky.SkyboxBk
			tbl16.SkyboxDn = sky.SkyboxDn
			tbl16.SkyboxFt = sky.SkyboxFt
			tbl16.SkyboxLf = sky.SkyboxLf
			tbl16.SkyboxRt = sky.SkyboxRt
			tbl16.SkyboxUp = sky.SkyboxUp
		else
			tbl16.SunAngularSize = 21
			tbl16.SkyboxBk = ""
			tbl16.SkyboxDn = ""
			tbl16.SkyboxFt = ""
			tbl16.SkyboxLf = ""
			tbl16.SkyboxRt = ""
			tbl16.SkyboxUp = ""
		end

		local function RestoreOriginalSkybox()
			local target = tbl16.Instance or Lighting:FindFirstChildOfClass("Sky")
			if not (target and target.Parent) then return end
			local w = getgenv().KozmozOriginalWeather
			local saved = w and w.Sky
			for _, prop in ipairs({ "SkyboxBk", "SkyboxDn", "SkyboxFt", "SkyboxLf", "SkyboxRt", "SkyboxUp" }) do
				local value = saved and saved[prop]
				if value == nil then value = tbl16[prop] end
				if value ~= nil then
					pcall(function() target[prop] = value end)
				end
			end
			if tbl16.SunAngularSize then
				pcall(function() target.SunAngularSize = tbl16.SunAngularSize end)
			end
		end

		local function fn21()
			if sky and sky.Parent == Lighting then
				return sky
			end
			local foundSky = Lighting:FindFirstChildOfClass("Sky")
			if not foundSky then
				foundSky = Instance.new("Sky")
				foundSky.Name = "KozmozSky"
				foundSky:SetAttribute("KozmozCreatedSky", true)
				foundSky.Parent = Lighting
				tbl16.Created = true
			else
				tbl16.Created = false
				if not tbl16.Instance then tbl16.Instance = foundSky end
			end
			sky = foundSky
			return sky
		end

		local function fn22(arg)
			if not arg or arg == "" then
				-- KOZMOZ FIX: only remove Sky instances this script created.
				-- Never destroy the game's own Sky (that was turning the sky dark/night).
				for _, child in ipairs(Lighting:GetChildren()) do
					if child:IsA("Sky") and child:GetAttribute("KozmozCreatedSky") then
						pcall(function() child:Destroy() end)
					end
				end
				sky = tbl16.Instance or Lighting:FindFirstChildOfClass("Sky")
				tbl16.Created = false
				RestoreOriginalSkybox()
				return
			end

			local v20 = fn21()
			local tbl17 = {
				SkyboxBk = arg,
				SkyboxDn = arg,
				SkyboxFt = arg,
				SkyboxLf = arg,
				SkyboxRt = arg,
				SkyboxUp = arg,
			}

			for k, v21 in pairs(tbl17) do
				v20[k] = v21
			end
		end

