		local SkyboxPresetEnabled = false
		local SelectedSkyboxPreset = "Black Cloudy Rain" -- KOZMOZ USER DEFAULT

		local function ApplySkyboxPreset()
			if not SkyboxPresetEnabled then
				return
			end
			local data = SkyboxPresets[SelectedSkyboxPreset]
			if not data then
				return
			end
			local currentSky = fn21()
			if not currentSky then
				return
			end
			currentSky.SkyboxBk = data.Bk
			currentSky.SkyboxDn = data.Dn
			currentSky.SkyboxFt = data.Ft
			currentSky.SkyboxLf = data.Lf
			currentSky.SkyboxRt = data.Rt
			currentSky.SkyboxUp = data.Up
		end

		local function RemoveSkyboxPreset()
			fn22()
		end

		Sky:AddDropdown("SkyboxPresetSelect", {
			Values = SkyboxPresetNames,
			Default = "Black Cloudy Rain", -- KOZMOZ USER DEFAULT
			Multi = false,
