				end
			end,
		})

		-- KOZMOZ USER DEFAULT: re-open with the sky/weather dialled in in this tab instead of
		-- snapping back to whatever the map had. Runs while Visual > Sky >
		-- "Normal Daytime Weather" is OFF, which is now the default.
		tbl12.ApplyKozmozSkyDefaults = function()
			pcall(function()
				Lighting.ClockTime = 9
				-- same guard the "Sun Size" slider uses: never create a Sky, just adjust it
				if sky and sky.Parent == Lighting then
					sky.SunAngularSize = 13
				end
				if clouds and clouds.Parent and not tbl16.CloudsCreated then
					clouds.Enabled = true
					clouds.Density = 0.134
					clouds.Cover = 0.543
				end
				if SkyboxPresetEnabled then
					ApplySkyboxPreset()
				end
			end)
		end

		tbl12.RestoreSkySettings = function()
			pcall(function()
				-- KOZMOZ FIX: never force day/night here, just restore the game's weather.
				if tbl12.RestoreDefaultWeather then
					tbl12.RestoreDefaultWeather()
				end

				local w = getgenv().KozmozOriginalWeather
				if tbl16.CloudsCreated then
					if clouds and clouds.Parent and clouds:GetAttribute("KozmozCreatedClouds") then
						clouds:Destroy()
					end
				elseif clouds and clouds.Parent then
					clouds.Color = tbl16.CloudColor
					clouds.Density = tbl16.CloudDensity
					clouds.Cover = tbl16.CloudCover
					clouds.Enabled = tbl16.CloudsEnabled
					if w and w.Clouds and w.Clouds.Instance == clouds then
						clouds.Color = w.Clouds.Color
						clouds.Density = w.Clouds.Density
						clouds.Cover = w.Clouds.Cover
						clouds.Enabled = w.Clouds.Enabled
					end
				end
			end)
		end

		-- KOZMOZ FIX: restore the exact weather the game had before this script ran.
		-- Used after an autoload config is applied and when the script unloads.
		tbl12.RestoreDefaultWeather = function()
			pcall(function()
				local w = getgenv().KozmozOriginalWeather
				if not w then return end

				if toggles.ShadersT and toggles.ShadersT.Value then
					pcall(function() toggles.ShadersT:SetValue(false) end)
				end
				if toggles.BoostFPS and toggles.BoostFPS.Value then
					pcall(function() toggles.BoostFPS:SetValue(false) end)
				end
				if toggles.CustomSkyboxT and toggles.CustomSkyboxT.Value then
					pcall(function() toggles.CustomSkyboxT:SetValue(false) end)
				end
				if toggles.SkyboxPresetToggle and toggles.SkyboxPresetToggle.Value then
					pcall(function() toggles.SkyboxPresetToggle:SetValue(false) end)
				end

				for _, child in ipairs(Lighting:GetChildren()) do
					if child:IsA("Sky") and child:GetAttribute("KozmozCreatedSky") then
						pcall(function() child:Destroy() end)
					elseif (child:IsA("BloomEffect") or child:IsA("BlurEffect") or child:IsA("ColorCorrectionEffect") or child:IsA("SunRaysEffect"))
						and (child:GetAttribute("RSC") or child.Name == "RSC") then
						pcall(function() child:Destroy() end)
					end
				end

				-- Sync the UI slider first; its callback may write ClockTime again.
				if options and options.TimeOfDay then
					pcall(function() options.TimeOfDay:SetValue(w.ClockTime) end)
				end

				for _, prop in ipairs({
					"Ambient", "OutdoorAmbient", "ColorShift_Bottom", "ColorShift_Top",
					"ExposureCompensation", "FogColor", "FogStart", "FogEnd",
					"ShadowSoftness", "GlobalShadows", "Brightness", "ClockTime",
				}) do
					if w[prop] ~= nil then
						pcall(function() Lighting[prop] = w[prop] end)
					end
				end

				if w.Sky and w.Sky.Instance and w.Sky.Instance.Parent then
					local s = w.Sky.Instance
					for _, prop in ipairs({ "SkyboxBk", "SkyboxDn", "SkyboxFt", "SkyboxLf", "SkyboxRt", "SkyboxUp", "SunAngularSize" }) do
						if w.Sky[prop] ~= nil then
							pcall(function() s[prop] = w.Sky[prop] end)
						end
					end
				end

				if w.Clouds and w.Clouds.Instance and w.Clouds.Instance.Parent then
					local c = w.Clouds.Instance
					for _, prop in ipairs({ "Color", "Density", "Cover", "Enabled" }) do
						if w.Clouds[prop] ~= nil then
							pcall(function() c[prop] = w.Clouds[prop] end)
						end
					end
				else
					for _, c in ipairs(workspace.Terrain:GetChildren()) do
						if c:IsA("Clouds") and c:GetAttribute("KozmozCreatedClouds") then
							pcall(function() c:Destroy() end)
						end
					end
				end
			end)
		end

		-- KOZMOZ FIX: never allow night. If the game's own weather was night when the script
		-- started, open with a normal daytime. If the game's weather is already daytime,
		-- the game's weather is left exactly as it is.
		tbl12.EnsureNormalDaytime = function()
			pcall(function()
				if tbl9.NormalWeather == false then
					return
				end
				local w = getgenv().KozmozOriginalWeather
				if not w then
					return
				end
				local original = w.ClockTime or 0
				local isNight = original < 6.5 or original > 17.5
				if not isNight then
					-- The game already starts in daytime: keep its weather untouched.
					return
				end
				if toggles.ShadersT and toggles.ShadersT.Value then
					pcall(function() toggles.ShadersT:SetValue(false) end)
				end
				if options and options.TimeOfDay then
					pcall(function() options.TimeOfDay:SetValue(14) end)
				end
				Lighting.ClockTime = 14
				if Lighting.Brightness < 1 then
					Lighting.Brightness = w.Brightness > 1 and w.Brightness or 1
				end
				if Lighting.GlobalShadows == false then
					Lighting.GlobalShadows = true
				end
			end)
		end
	end

	do
