				tbl9.AutoClickerOffset = CFrame.new(autoClickerOffset.X, arg, autoClickerOffset.Z)
			end,
		})

		Config:AddSlider("ACCSecZO", {
			Text = "Z Offset",
			Default = -5,
			Min = -10,
