					tbl18[1] = num3
					tbl18[2] = num4

					do
						local values = table.pack(v24(format2("%.1f", z2)))
						table.move(values, 1, values.n, 3, tbl18)
					end

					tbl17[k] = tbl18
				end

				for k, v23 in tbl7.ACOffset, nil, nil do
					local limbOffsets = tbl17.LimbOffsets
					local tbl18 = {}
					local num3 = tonumber(string.format("%.1f", v23.X))
