	do
		local Whitelist = tbl15.Lists:AddLeftGroupbox("Whitelist", "user-check")
		local v20 = tbl12.CreatePlayerDropdown(Whitelist, "Whitelist", tbl7.Whitelisted)

		v20:OnChanged(function()
			if tbl8.SilentAim then
				tbl12.RefreshSilentAim()
			end
		end)

		local tbl16 = {}
		local friendStatusChanged = nil

		pcall(function()
			friendStatusChanged = localPlayer.FriendStatusChanged
		end)

		local function fn21(arg, arg2)
			if flag11 or not tbl8.AutoWhitelistFriends or arg == localPlayer or arg.Parent ~= Players or tbl12.IsProtectedPlayer(arg) then
				return
			end
			local flag12 = v20.Value[arg] == true

			if arg2 then
				if flag12 then
					return
				end
				tbl16[arg.UserId] = true
			else
				if not tbl16[arg.UserId] then
					return
				end
				tbl16[arg.UserId] = nil
				if not flag12 then
					return
				end
			end

			local tbl17 = {}

			for k, v21 in v20.Value, nil, nil do
				if k ~= arg then
					tbl17[k] = v21
				end
			end

			if arg2 then
				tbl17[arg] = true
			end

			v20:SetValue(tbl17)
		end

		local function fn22(arg)
			if arg == localPlayer or arg.Parent ~= Players or not tbl8.AutoWhitelistFriends then
				return
			end
			local ok, result = pcall(localPlayer.IsFriendsWith, localPlayer, arg.UserId)

			if ok then
				fn21(arg, result)
			end
		end

		Whitelist:AddDivider("Settings")

		Whitelist:AddToggle("AutoWhitelistFriends", {
			Text = "Auto Whitelist Friends",
			Default = false,
			Tooltip = "Adds your friends to the whitelist",
			Callback = function(autoWhitelistFriends)
				if tbl8.AutoWhitelistFriends == autoWhitelistFriends then
					return
				end
				tbl8.AutoWhitelistFriends = autoWhitelistFriends
				tbl12.SetRuntimeConnection("AutoWhitelistFriends", Players.PlayerAdded, autoWhitelistFriends, fn22)

				if friendStatusChanged then
					pcall(tbl12.SetRuntimeConnection, "AutoWhitelistStatus", friendStatusChanged, autoWhitelistFriends, function(arg, arg2)
						if arg2 == Enum.FriendStatus.Friend or arg2 == Enum.FriendStatus.NotFriend then
							fn21(arg, arg2 == Enum.FriendStatus.Friend)
						end
					end)
				end

				if not autoWhitelistFriends then
					return
				end

				task.spawn(function()
					for _, v21 in Players:GetPlayers() do
						if flag11 or not tbl8.AutoWhitelistFriends then
							return
						end
						fn22(v21)
					end
				end)
			end,
		})

		Whitelist:AddToggle("WhitelistToggle", {
			Text = "Toggle Whitelist",
			Default = false,
			Tooltip = "Prevents server-wide features from affecting people in the list above",
			Callback = function(whitelistedBypass)
				tbl8.WhitelistedBypass = whitelistedBypass

				if tbl8.SilentAim then
					tbl12.RefreshSilentAim()
				end
			end,
		})
	end

	toggles.WhitelistToggle:SetValue(true)
	toggles.AutoWhitelistFriends:SetValue(true)

	do
		-- KOZMOZ USER FEATURE: blacklist. Pick someone from the server or type their name.
		-- When a listed player joins - or the moment you switch an action on while they are
		-- already in here - you get a notification and they can be kicked or killed with the
		-- Blobman. Whitelisted / immune players are never touched, nothing else changes.
		local Blacklist = tbl15.Lists:AddRightGroupbox("Blacklist", "user-x")
		local playersSvc = game:GetService("Players")
		local me = playersSvc.LocalPlayer
		local selected = tbl7.Blacklisted
		local names = tbl7.BlacklistNames
		local listFile = "KOZMOZ/Blacklist.txt"
		local acted = {} -- keyed by player name; cleared when they leave
		local JOIN_DELAY = 2

		-- KOZMOZ: Target > Method Settings > Methods kutusuna iki yoldan da ulasabilmek
		-- icin kutuphanenin kendi Options kaydini da sakla (referans yoksa yedek yol).
		tbl12.LibraryOptions = (type(options) == "table" and options) or (lib and lib.Options) or nil

		local statusLabel = nil
		local dropdown = nil
		local refresh = nil
		local startDrive, stopDrive = nil, nil -- KOZMOZ: Blobman drive (assigned below)

		local function keyOf(name)
			return tostring(name or ""):lower():gsub("^@", ""):gsub("%s", "")
		end

		local function countListed()
			local n = 0
			for _ in pairs(names) do
				n += 1
			end
			return n
		end

		--==== KOZMOZ: WHITELIST DISKE YAZILMIYOR ====--
		-- Eskiden KOZMOZ/list.txt olusturulup yaziliyordu. Artik liste oturum
		-- boyunca bellekte tutulur (diske tek dosya yazilmaz).
		local function save()
			return true
		end

		local function load()
			-- KOZMOZ: dosyadan okuma YOK (whitelist diske yazilmadigi icin)
			return true
		end


		refresh = function()
			if statusLabel and statusLabel.SetText then
				pcall(statusLabel.SetText, statusLabel, ("Blacklisted: %d player(s)"):format(countListed()))
			end

			if dropdown then
				local wanted = {}

				for _, player in playersSvc:GetPlayers() do
					if player ~= me and names[keyOf(player.Name)] and not tbl12.IsProtectedPlayer(player) then
						wanted[player] = true
					end
				end

				local changed = false

				for player in pairs(wanted) do
					if not selected[player] then
						selected[player] = true
						changed = true
					end
				end

				if changed then
					pcall(dropdown.SetValue, dropdown, wanted)
				end
			end
		end

		local function isListed(player)
			if not player then
				return false
			end

			if selected[player] then
				return true
			end

			return names[keyOf(player.Name)] ~= nil
		end

		-- the dropdown and the typed names are one list: whoever is in the server follows the
		-- selection, everyone who left stays in the file until you remove them
		local function syncNames(fromDropdown)
			local keep = {}
			local here = {}

			for _, player in playersSvc:GetPlayers() do
				if player ~= me then
					here[keyOf(player.Name)] = player
				end
			end

			for key, entry in pairs(names) do
				if not here[key] or tbl12.IsProtectedPlayer(here[key]) then
					keep[key] = entry
				end
			end

			for player in pairs(fromDropdown) do
				local key = keyOf(player and player.Name)

				if key ~= "" and key ~= keyOf(me and me.Name) then
					keep[key] = { UserId = player.UserId, Added = os.time() }
				end
			end

			table.clear(names)

			for key, entry in pairs(keep) do
				names[key] = entry
			end

			save()
			refresh()
		end

		-- KOZMOZ USER FEATURE: the drive now runs through the TARGET tab (not the Blobman).
		-- The listed player is written into Target > Targets, Methods is set to Kick/Kill and,
		-- for Kick, "Loop Apply Method Selected" is kept on so the server loop keeps kicking them
		-- while they are in the server. The loop/method the user had before is restored when the
		-- drive stops.
		local drive = { on = false, loop = nil, method = nil, sel = nil, freed = nil }

		local function driveReady()
			return type(tbl12) == "table"
				and type(tbl12.RunTargetDrive) == "function"
				and type(tbl12.SetTargetLoopKick) == "function"
				and type(toggles) == "table"
				and type(options) == "table"
				and type(options.MethodSettingsTargets) == "table"
		end

		local function driveWanted()
			local want = {}

			if flag11 or not (tbl8.BlacklistAutoKick or tbl8.BlacklistAutoKill) then
				return want
			end

			for _, player in playersSvc:GetPlayers() do
				if player ~= me and isListed(player) and not (tbl12.IsProtectedPlayer and tbl12.IsProtectedPlayer(player)) then
					want[player] = true
				end
			end

			return want
		end

		-- KOZMOZ: resoda Kill'in sunucu dongusu yok; Kill secilince kendimiz
		-- tekrar tekrar uygulariz (oyuncu sunucudan gidene kadar).
		local killLoopToken = 0

		local function killLoopStop()
			killLoopToken += 1
		end

		local function killLoopStart()
			killLoopToken += 1
			local token = killLoopToken

			task.spawn(function()
				while not flag11 and drive.on and killLoopToken == token do
					local want = driveWanted()

					for player in pairs(want) do
						if player and player.Parent then
							pcall(tbl12.RunTargetOnce, player, "Kill")
						end
					end

					task.wait(1.5)
				end
			end)
		end

		-- KOZMOZ: drive artik TARGET tarafinda calisir (Blobman degil).
		-- Kick  -> Methods = {Kick} + "Loop Apply Method Selected" acik (sunucu dongusu)
		-- Kill  -> Methods = {Kill} + kendi kill dongumuz (killLoopStart)
		stopDrive = function()
			if not drive.on then
				killLoopStop()
				return
			end

			drive.on = false
			killLoopStop()

			-- KOZMOZ: blacklist yuzunden acilan Kick dongusunu kapat
			if tbl12.SetTargetLoopKick then
				pcall(tbl12.SetTargetLoopKick, false)
			end

			-- KOZMOZ: blacklist yuzunden eklenen isimleri Target kutusundan cikar
			-- (kullanicinin kendi sectigi isimler korunur)
			if drive.freed and options and options.TargetDropdown then
				local keep = {}

				for player in pairs(drive.freed) do
					if player and player.Parent and player ~= me then
						keep[player] = true
					end
				end

				pcall(options.TargetDropdown.SetValue, options.TargetDropdown, keep)
				drive.freed = nil
			end


			if drive.method ~= nil and options.MethodSettingsTargets.Value ~= drive.method then
				pcall(options.MethodSettingsTargets.SetValue, options.MethodSettingsTargets, drive.method)
			end

			-- NOT: Target kutusundaki isaret KALIR. Loop Apply Method Selected
			-- kapaninca sunucudaki dongu durur; isaret geri alinirsa tekrar
			-- acildiginda hicbir sey yapilmaz. Kullanici kendisi kaldirabilir.
			drive.sel = nil

			drive.loop, drive.method = nil, nil
		end

		startDrive = function()
			if not driveReady() then
				return false
			end

			local want = driveWanted()

			if next(want) == nil then
				stopDrive()
				return false
			end

			if not drive.on then
				drive.on = true
				drive.loop = (toggles.LoopApplyMethodT and toggles.LoopApplyMethodT.Value) == true
				drive.method = options.MethodSettingsTargets.Value
				drive.freed = {}

				-- kullanicinin onceden sectigi isimler: kapatinca bunlar kalir
				for player in pairs(tbl7.SelectedPlayers) do
					if player and player.Parent then
						drive.freed[player] = true
					end
				end
			end

			local method = tbl8.BlacklistAutoKick and "Kick" or "Kill"

			if tbl12.RunTargetDrive(want, method) ~= true then
				return false
			end

			if method == "Kill" then
				killLoopStart()
			else
				killLoopStop()
			end

			return true
		end


		local function act(player)
			if flag11 or not (player and player.Parent) or acted[keyOf(player.Name)] then
				return
			end

			acted[keyOf(player.Name)] = true

			if tbl8.BlacklistNotify then
				tbl12.NotifyEvent("Blacklist Join", { blacklistPlayer = tbl12.FormatPlayer(player) }, "Blacklist")
			end

			if not (tbl8.BlacklistAutoKick or tbl8.BlacklistAutoKill) then
				return
			end

			if tbl12.IsProtectedPlayer and tbl12.IsProtectedPlayer(player) then
				return
			end

			-- the drive keeps working on them while they are in the server
			if startDrive() then
				return
			end

			-- the Target UI is not there (yet): a single direct attempt instead
			task.delay(JOIN_DELAY, function()
				if flag11 or not (player and player.Parent) then
					return
				end

				-- KOZMOZ: dogrudan hedefe uygula (Blobman degil, Target)
				if tbl8.BlacklistAutoKick and tbl12.RunTargetOnce then
					pcall(tbl12.RunTargetOnce, player, "Kick")
				end

				if tbl8.BlacklistAutoKill and tbl12.RunTargetOnce then
					pcall(tbl12.RunTargetOnce, player, "Kill")
				end
			end)
		end

		local function scanServer()
			for _, player in playersSvc:GetPlayers() do
				if player ~= me and isListed(player) then
					act(player)
				end
			end

			if startDrive then
				pcall(startDrive)
			end
		end

		local nameInput = Blacklist:AddInput("BlacklistName", {
			Text = "Username",
			Placeholder = "player name",
			Default = "",
			Finished = false,
			ClearTextOnFocus = false,
			Callback = function() end,
		})

		Blacklist:AddButton({
			Text = "Add To Blacklist",
			Func = function()
				local name = tostring(nameInput and nameInput.Value or "")
				local key = keyOf(name)

				if key == "" then
					fn18("Type a username first.")
					return
				end

				if key == keyOf(me and me.Name) then
					fn18("You cannot blacklist yourself.")
					return
				end

				names[key] = { UserId = nil, Added = os.time() }
				save()
				refresh()
				scanServer()
				fn18(("Added %s to the blacklist (%d in total)."):format(name, countListed()))
			end,
		})

		Blacklist:AddButton({
			Text = "Remove From Blacklist",
			Func = function()
				local key = keyOf(nameInput and nameInput.Value)

				if not names[key] then
					fn18("That name is not in the blacklist.")
					return
				end

				names[key] = nil

				for player in pairs(selected) do
					if keyOf(player and player.Name) == key then
						selected[player] = nil
					end
				end

				save()
				refresh()

				if startDrive then
					pcall(startDrive)
				end

				fn18("Removed from the blacklist.")
			end,
		})

		Blacklist:AddButton({
			Text = "Clear Blacklist",
			Func = function()
				table.clear(names)
				table.clear(selected)
				save()
				refresh()

				if startDrive then
					pcall(startDrive)
				end

				fn18("Blacklist cleared.")
			end,
		})

		Blacklist:AddDivider("Actions")

		statusLabel = Blacklist:AddLabel("Blacklisted: 0 player(s)")

		Blacklist:AddToggle("BlacklistAutoKick", {
			Text = "Auto Kick With Target",
			Default = false,
			Tooltip = ("Uses the Target tab: Methods = Kick, they are added to Targets and Loop Apply Method Selected is kept on, so the server keeps kicking them while they are here (%d s join delay)."):format(JOIN_DELAY),
			Callback = function(arg)
				tbl12.SetRuntimeToggle("BlacklistAutoKick", arg)

				if arg then
					task.spawn(scanServer)
				else
					task.spawn(stopDrive)
				end
			end,
		})

		Blacklist:AddToggle("BlacklistAutoKill", {
			Text = "Auto Kill With Target",
			Default = false,
			Tooltip = ("Uses the Target tab: Methods = Kill and they are added to Targets, then reso's Kill runs on them %d seconds after they join."):format(JOIN_DELAY),
			Callback = function(arg)
				tbl12.SetRuntimeToggle("BlacklistAutoKill", arg)

				if arg then
					task.spawn(scanServer)
				else
					task.spawn(stopDrive)
				end
			end,
		})

		Blacklist:AddToggle("BlacklistNotify", {
			Text = "Notify When They Join",
			Default = true,
			Tooltip = "Uses the side you picked in Settings > Notifications",
			Callback = function(arg)
				tbl12.SetRuntimeToggle("BlacklistNotify", arg)
			end,
		})

		Blacklist:AddLabel("Anyone you list is handled in this server too, not only on join.", true)

		dropdown = tbl12.CreatePlayerDropdown(Blacklist, "Blacklist", selected, true, true, function(arg)
			syncNames(arg)

			if startDrive then
				pcall(startDrive)
			end
		end, "Players In Server")

		tbl12.SetRuntimeConnection("BlacklistPlayerAdded", playersSvc.PlayerAdded, true, function(player)
			if isListed(player) then
				act(player)
			end
		end)

		tbl12.SetRuntimeConnection("BlacklistPlayerRemoving", playersSvc.PlayerRemoving, true, function(player)
			acted[keyOf(player and player.Name)] = nil -- a rejoin must be handled again
			task.defer(startDrive)
		end)

		load()
		refresh()
	end



	do
		local Menu = tbl15.Settings:AddLeftGroupbox("Menu", "app-window")
		Menu:AddLabel("Menu Keybind"):AddKeyPicker("menukey", { Text = "Menu Keybind", Mode = "Toggle", Default = "RightShift", NoUI = false })
		lib.ToggleKeybind = options.menukey

		Menu:AddToggle("WatermarkT", {
			Default = true,
			Text = "Watermark",
			Callback = function(arg)
				Watermark:SetVisible(arg)
			end,
		})

		Menu:AddDivider("Keybind Menu")

		Menu:AddToggle("KeybindMenuOpen", {
			Default = false,
