		Display:AddSlider("UICornerSlider", {
			Text = "Corner Radius",
			Default = 13,
			Min = 0,
			Max = 20,
			Rounding = 0,
			Callback = function(arg)
				v19:SetCornerRadius(arg)
			end,
		})

		Display:AddSlider("GUITransparencySlider", {
			Text = "GUI Transparency",
			Default = (Library and Library.CurrentThemeName == "Hello Kitty") and 0 or 46, -- KOZMOZ USER DEFAULT
			Min = 0,
			Max = 100,
			Rounding = 0,
			HideMax = true,
			Color = Color3.fromRGB(255, 0, 255),
			Callback = function(val)
				if v19 and v19.SetGUITransparency then
					v19:SetGUITransparency(val)
				else
					local trans = math.clamp(val / 100, 0, 1)
					if v19 and v19.MainFrame then
						v19.MainFrame.BackgroundTransparency = trans
						for _, desc in ipairs(v19.MainFrame:GetDescendants()) do
							if desc:IsA("Frame") or desc:IsA("ScrollingFrame") then
								if desc.Name == "Container" or desc.Name == "Tabs" or desc.Name == "BottomBackground" then
									desc.BackgroundTransparency = trans
								end
							end
						end
					end
					if lib and lib.Tabs then
						for _, Tab in pairs(lib.Tabs) do
							if Tab.Groupboxes then
								for _, Groupbox in pairs(Tab.Groupboxes) do
									if Groupbox.Holder then
										Groupbox.Holder.BackgroundTransparency = math.clamp(trans, 0, 0.95)
									end
								end
							end
						end
					end
				end
			end,
		})
	end

	do
		local Notifications = tbl15.Settings:AddRightGroupbox("Notifications", "bell-dot")

		local tbl16 = {
			Default = 97643101798871,
			Pop = 124815381429574,
			["Bubble Pop"] = 106994752352532,
			Steam = 18317665126,
			Loaded = 71450094482101,
		}

		Notifications:AddToggle("NotificationMaster", {
			Text = "Master Switch",
			Default = true,
			Tooltip = "Enables or disables every KOZMOZ notification",
			Callback = function(enabled)
				tbl7.NotificationSettings.Enabled = enabled
			end,
		})

		Notifications:AddDropdown("NotificationReceivers", {
			Text = "Event Notifications",
			Values = { "Kicked Player", "Player Left", "Player Rejoined", "Blacklist Join" },
			Default = { "Kicked Player", "Player Left", "Player Rejoined", "Blacklist Join" },
			Multi = true,
			AllowNull = true,
			Callback = function(arg)
				for k in pairs(tbl7.NotificationSettings.Events) do
					tbl7.NotificationSettings.Events[k] = arg[k] == true
				end
			end,
