		end)

		Players.PlayerAdded:Connect(function(player)
			local v20 = tbl16[player.UserId]
			if not v20 or flag11 or not getgenv().KozmozRunning then
				return
			end
			tbl16[player.UserId] = nil

			for _, v21 in ipairs(v20) do
				if not table.find(v21.Dropdown.Values, player) then
					v21.Dropdown:AddValues({ player })
				end

				if v21.Multi == false then
					v21.Dropdown:SetValue(player)
					table.clear(v21.Values)
					v21.Values[player] = true
					table.clear(v21.Selected)
					v21.Selected[player] = true
				else
					local tbl17 = {}

					for k, v22 in pairs(v21.Selected) do
						tbl17[k] = v22
					end

					tbl17[player] = true
					v21.Dropdown:SetValue(tbl17)
					table.clear(v21.Values)

					for k, v22 in pairs(tbl17) do
						v21.Values[k] = v22
					end

					v21.Selected[player] = true
				end
			end

			tbl12.NotifyEvent("Player Rejoined", { rejoinedPlayer = tbl12.FormatPlayer(player), listCount = #v20 }, "Player Rejoined")
		end)
	end

	fn18("Script loaded in " .. math.round((tick() - getgenv().LoadTime) * 100) / 100 .. " seconds", "KOZMOZ", 71450094482101)
	getgenv().LoadTime = nil

	task.spawn(function()
		task.wait(0.4)
		if tbl8.KozmozGroundLogo and tbl12.SetKozmozGroundLogo then
			pcall(tbl12.SetKozmozGroundLogo, true)
		end
		-- KOZMOZ FIX: Anti Lag stays off, Auto Anti Lag stays on at startup.
		tbl8.AutoAntiLag = true
		if toggles.AutoAntiLag and not toggles.AutoAntiLag.Value then
			toggles.AutoAntiLag:SetValue(true)
		end
		if toggles.AntiLag and toggles.AntiLag.Value then
			toggles.AntiLag:SetValue(false)
		end
		if tbl12.EnsureNormalDaytime then
			pcall(tbl12.EnsureNormalDaytime)
		end
		if tbl12.ResetLineColorsAndPalette then
			pcall(tbl12.ResetLineColorsAndPalette, true)
		end
	end)



	return {
		copyright = "Copyright (c) 2026 KOZMOZ. All rights reserved.",
	}
end
]====]
sources.Bootstrap = [====[
local sources = ...
local env = getgenv and getgenv() or _G

-- =====================================================================
-- KOZMOZ FIX (image-51): "KOZMOZ is already running or starting"
-- Eski davranis: bayrak bir kere true kaldiysa (script coktu, executor
-- durdurdu, unload calismadi) script bir daha ASLA acilmiyordu; tek care
-- oyundan cikmakti. Yeni davranis:
--   1) Onceki baslatma yarim kaldiysa (KozmozStarting >15 sn eski) temizle.
--   2) Onceki ornek gercekten canliysa once onu UNLOAD et, sonra devam et.
--   3) Unload edilemiyorsa (cok eski surum) net mesaj ver ve dur.
-- Boylece "tekrar calistir" her zaman calisir, cift UI olusmaz.
-- =====================================================================
env.KozmozStartAt = env.KozmozStartAt or 0

if env.KozmozRunning or env.KozmozStarting then
    local age = os.clock() - (tonumber(env.KozmozStartAt) or 0)

    if env.KozmozStarting and not env.KozmozRunning and age > 15 then
        warn("KOZMOZ: previous start hung, restarting cleanly")
        env.KozmozStarting = false
    elseif type(env.KozmozUnload) == "function" then
        warn("KOZMOZ: unloading the previous instance and restarting")
        pcall(env.KozmozUnload)
        task.wait(0.25)
        env.KozmozRunning = false
        env.KozmozStarting = false
        env.KozmozUnload = nil
    else
        warn("KOZMOZ is already running or starting (Unload it first, then run again)")
        return
    end
end

assert(type(loadstring) == "function", "This executor does not support loadstring")
assert(type(getgenv) == "function", "This executor does not support getgenv")
env.KozmozStarting = true
env.KozmozStartAt = os.clock()
-- First launch should have the same clear daylight as a warm re-open.
-- This is client-side lighting only and runs before expensive module setup.
pcall(function()
    local light = game:GetService("Lighting")
    if light.ClockTime < 6.5 or light.ClockTime > 17.5 then
        light.ClockTime = 9
    end
    if light.Brightness < 1 then light.Brightness = 1 end
end)
local cleanup
local function registerCleanup(fn)
    cleanup = fn
    -- KOZMOZ FIX: bir sonraki calistirma onceki ornegi kapatabilsin.
    env.KozmozUnload = function()
        if type(fn) == "function" then
            pcall(fn)
        end
        env.KozmozRunning = false
        env.KozmozStarting = false
    end
end
local cache = {}
local loading = {}
local function requireModule(name)
    if cache[name] then return cache[name] end
    assert(not loading[name], "Circular module dependency: " .. tostring(name))
    assert(type(sources[name]) == "string", "Missing module: " .. tostring(name))
    loading[name] = true
    local chunk, message = loadstring(sources[name], "@KOZMOZ/" .. name)
    assert(chunk, message)
    local ok, result = pcall(chunk, requireModule)
    loading[name] = nil
    assert(ok, result)
    assert(type(result) == "table", "Invalid module: " .. name)
    cache[name] = result
    return result
end
local reloadPath
local ok, result = xpcall(function()
    -- KOZMOZ: Key gate removed; continue directly to hub startup.
    -- KOZMOZ: INTRO EKRANI KALDIRILDI (bar/progress + KOZMOZ yazisi).
    -- Acilista dogrudan KEY PANELI gelir; key dogrulanmadan hile baslamaz.
    -- Intro modulu dosyada duruyor (silinmedi), sadece cagrilmiyor.
    -- Tekrar acmak istersen: asagidaki iki satirin basindaki "--" isaretini kaldir.
    -- local introOk, introError = pcall(function()
    --     local played, message = requireModule("Intro").Play()
    --     assert(played, message)
    -- end)
    -- if not introOk then warn("KOZMOZ intro: " .. tostring(introError)) end
    --==== KOZMOZ (kullanici istegi): WORKSPACE'E KOD YAZMA YOK ====--
    -- Eskiden her acilista tum moduller (~2.4 MB) "KozmozRestored.lua" olarak
    -- calisma klasorune yaziliyordu (rejoin sonrasi otomatik calistirma icin).
    -- Bu yazma KALDIRILDI: artik diske hicbir sey yazilmiyor.
    -- "Join with script" icin kaynak: KozmozSource/Kozmoz.txt (senin koydugun dosya).
    -- Dosya yoksa o secenek kendini kapatir ve uyarir.
    pcall(function()
        if type(isfile) == "function" and isfile("KozmozRestored.lua") and type(delfile) == "function" then
            pcall(delfile, "KozmozRestored.lua")
            warn("[KOZMOZ] Eski KozmozRestored.lua silindi (artik kod workspace'e yazilmiyor)")
        end
    end)
    do
        local candidates = { "KozmozSource/Kozmoz.txt", "KozmozSource/kozmoz.txt", "Kozmoz.txt" }
        if type(isfile) == "function" then
            for _, path in ipairs(candidates) do
                local has = false
                pcall(function() has = (isfile(path) == true) end)
                if has then
                    reloadPath = path
                    warn("[KOZMOZ] Join with script kaynagi: " .. path)
                    break
                end
            end
        end
    end
    local chunk, message = loadstring(sources.Main, "@KOZMOZ/Main")
    assert(chunk, message)
    return chunk(requireModule, reloadPath, registerCleanup)
end, function(message)
    if debug and debug.traceback then return debug.traceback(tostring(message), 2) end
    return tostring(message)
end)
env.KozmozStarting = false
if not ok then
    if cleanup then pcall(cleanup) end
    env.KozmozRunning = false
    warn("KOZMOZ initialization failed: " .. tostring(result))
    return nil, result
end
return result
]====]
